    #[cfg(feature = "websocket")]
    async fn websocket_upgrade(
        cx: &Cx,
        address: std::net::SocketAddr,
        request: &[u8],
    ) -> Result<(AsyncTcpStream, Vec<u8>), String> {
        use asupersync::io::{AsyncReadExt, AsyncWriteExt};

        let deadline = cx.now().saturating_add_nanos(LIVE_HTTP_TEST_TIMEOUT_NANOS);
        let mut stream = asupersync::time::timeout_at(deadline, AsyncTcpStream::connect(address))
            .await
            .map_err(|_| "WebSocket client connect timed out".to_owned())?
            .map_err(|error| format!("WebSocket client connect failed: {error}"))?;
        asupersync::time::timeout_at(deadline, stream.write_all(request))
            .await
            .map_err(|_| "WebSocket handshake write timed out".to_owned())?
            .map_err(|error| format!("WebSocket handshake write failed: {error}"))?;
        asupersync::time::timeout_at(deadline, stream.flush())
            .await
            .map_err(|_| "WebSocket handshake flush timed out".to_owned())?
            .map_err(|error| format!("WebSocket handshake flush failed: {error}"))?;

        let mut received = Vec::new();
        while !received.windows(4).any(|window| window == b"\r\n\r\n") {
            let mut chunk = [0_u8; 512];
            let read = asupersync::time::timeout_at(deadline, stream.read(&mut chunk))
                .await
                .map_err(|_| "WebSocket handshake response timed out".to_owned())?
                .map_err(|error| format!("WebSocket handshake response failed: {error}"))?;
            if read == 0 {
                break;
            }
            received.extend_from_slice(&chunk[..read]);
        }
        Ok((stream, received))
    }

    #[cfg(feature = "websocket")]
    #[test]
    fn live_websocket_successful_child_reports_quiescent_before_shutdown_cleanup() {
        run_live_http_test(|cx| async move {
            use asupersync::io::{AsyncReadExt, AsyncWriteExt};

            let peer_closed = Arc::new(AtomicBool::new(false));
            let cleanup_after_peer_close = Arc::new(AtomicBool::new(false));
            let shutdown_calls = Arc::new(AtomicUsize::new(0));
            let observed_peer_close = Arc::clone(&peer_closed);
            let observed_cleanup = Arc::clone(&cleanup_after_peer_close);
            let observed_shutdown_calls = Arc::clone(&shutdown_calls);
            let listener = Server::new("live-websocket-successful-child", "1.0.0")
                .protocol_policy(ProtocolPolicy::ModernOnly)
                .expect("modern-only policy is available")
                .on_shutdown(move || {
                    observed_shutdown_calls.fetch_add(1, Ordering::AcqRel);
                    observed_cleanup.store(
                        observed_peer_close.load(Ordering::Acquire),
                        Ordering::Release,
                    );
                })
                .build()
                .bind_websocket(&cx, "127.0.0.1:0")
                .await
                .map_err(|error| format!("successful-child WebSocket bind failed: {error}"))?;
            let address = listener
                .local_addr()
                .map_err(|error| format!("successful-child WebSocket address failed: {error}"))?;
            let scope = cx.scope();
            let mut listener_task = cx
                .spawn_in(&scope, move |listener_cx| async move {
                    listener.serve(&listener_cx).await
                })
                .map_err(|error| {
                    format!("successful-child WebSocket listener admission failed: {error}")
                })?;
            let opening = concat!(
                "GET /mcp HTTP/1.1\r\nHost: localhost\r\nUpgrade: websocket\r\n",
                "Connection: Upgrade\r\nSec-WebSocket-Version: 13\r\n",
                "Sec-WebSocket-Key: dGhlIHNhbXBsZSBub25jZQ==\r\n\r\n"
            );
            let (mut client, accepted) =
                websocket_upgrade(&cx, address, opening.as_bytes()).await?;
            if !accepted.starts_with(b"HTTP/1.1 101") {
                return Err("successful WebSocket child was not upgraded".to_owned());
            }
            client
                .write_all(&masked_websocket_frame(0x08, &[]))
                .await
                .map_err(|error| format!("successful WebSocket close write failed: {error}"))?;
            client
                .flush()
                .await
                .map_err(|error| format!("successful WebSocket close flush failed: {error}"))?;
            let deadline = cx.now().saturating_add_nanos(LIVE_HTTP_TEST_TIMEOUT_NANOS);
            let mut close_reply = [0_u8; 32];
            let close_read = asupersync::time::timeout_at(deadline, client.read(&mut close_reply))
                .await
                .map_err(|_| "successful WebSocket close reply timed out".to_owned())?
                .map_err(|error| format!("successful WebSocket close reply failed: {error}"))?;
            if close_read < 2 || close_reply[0] & 0x0f != 0x08 {
                return Err("successful WebSocket child did not complete a close reply".to_owned());
            }
            peer_closed.store(true, Ordering::Release);
            drop(client);
            listener_task.abort();
            let join_cx = Cx::for_testing();
            let shutdown = listener_task
                .join(&join_cx)
                .await
                .map_err(|error| format!("successful WebSocket listener join failed: {error:?}"))?
                .map_err(|error| format!("successful WebSocket listener failed: {error}"))?;
            if !matches!(shutdown, WebSocketServerShutdown::Quiescent)
                || shutdown_calls.load(Ordering::Acquire) != 1
                || !cleanup_after_peer_close.load(Ordering::Acquire)
            {
                return Err(
                    "successful WebSocket child did not settle before quiescent cleanup".to_owned(),
                );
            }
            Ok(())
        });
    }

    #[cfg(feature = "websocket")]
    #[test]
    fn rh5_websocket_rejects_server_notification_without_dispatch_or_connection_loss() {
        run_live_http_test(|cx| async move {
            use asupersync::io::{AsyncReadExt, AsyncWriteExt};

            let handler_calls = Arc::new(AtomicUsize::new(0));
            let middleware_calls = Arc::new(AtomicUsize::new(0));
            let saw_credential = Arc::new(AtomicBool::new(false));
            let listener = Server::new("websocket-wrong-direction-notification", "1.0.0")
                .protocol_policy(ProtocolPolicy::ModernOnly)
                .expect("modern-only policy is available")
                .middleware(ModernHttpAuthMiddleware {
                    calls: Arc::clone(&middleware_calls),
                    saw_credential: Arc::clone(&saw_credential),
                })
                .tool(ModernHttpAuthCounterTool {
                    calls: Arc::clone(&handler_calls),
                })
                .build()
                .bind_websocket(&cx, "127.0.0.1:0")
                .await
                .map_err(|error| format!("wrong-direction WebSocket bind failed: {error}"))?;
            let address = listener
                .local_addr()
                .map_err(|error| format!("wrong-direction WebSocket address failed: {error}"))?;
            let scope = cx.scope();
            let mut listener_task = cx
                .spawn_in(&scope, move |listener_cx| async move {
                    listener.serve(&listener_cx).await
                })
                .map_err(|error| {
                    format!("wrong-direction WebSocket listener admission failed: {error}")
                })?;
            let opening = concat!(
                "GET /mcp HTTP/1.1\r\nHost: localhost\r\nUpgrade: websocket\r\n",
                "Connection: Upgrade\r\nSec-WebSocket-Version: 13\r\n",
                "Sec-WebSocket-Key: dGhlIHNhbXBsZSBub25jZQ==\r\n\r\n"
            );
            let (mut client, accepted) =
                websocket_upgrade(&cx, address, opening.as_bytes()).await?;
            if !accepted.starts_with(b"HTTP/1.1 101") {
                return Err("wrong-direction WebSocket was not upgraded".to_owned());
            }
            let server_notification = JsonRpcMessage::Request(JsonRpcRequest::notification(
                "notifications/progress",
                Some(serde_json::json!({
                    "progressToken": "server-only",
                    "progress": 1,
                    "_meta": {
                        MODERN_PROTOCOL_VERSION_METADATA_KEY: MODERN_PROTOCOL_VERSION,
                    },
                })),
            ));
            let resumed_client_request = JsonRpcMessage::Request(JsonRpcRequest::new(
                "tools/call",
                Some(serde_json::json!({
                    "name": "modern_http_auth_counter",
                    "arguments": {},
                    "_meta": {
                        MODERN_PROTOCOL_VERSION_METADATA_KEY: MODERN_PROTOCOL_VERSION,
                        FINAL_CLIENT_CAPABILITIES_META_KEY: {},
                    },
                })),
                7_402_i64,
            ));
            let mut frames = masked_websocket_message(modern_discovery_request(7_401));
            frames.extend(masked_websocket_message(server_notification));
            frames.extend(masked_websocket_message(resumed_client_request));
            client
                .write_all(&frames)
                .await
                .map_err(|error| format!("wrong-direction WebSocket write failed: {error}"))?;
            client
                .flush()
                .await
                .map_err(|error| format!("wrong-direction WebSocket flush failed: {error}"))?;

            let deadline = cx.now().saturating_add_nanos(LIVE_HTTP_TEST_TIMEOUT_NANOS);
            let mut responses = Vec::new();
            while !(responses
                .windows(b"serverInfo".len())
                .any(|window| window == b"serverInfo")
                && responses
                    .windows(b"authenticated modern HTTP dispatch".len())
                    .any(|window| window == b"authenticated modern HTTP dispatch"))
            {
                let mut chunk = [0_u8; 1024];
                let read = asupersync::time::timeout_at(deadline, client.read(&mut chunk))
                    .await
                    .map_err(|_| "wrong-direction WebSocket response timed out".to_owned())?
                    .map_err(|error| {
                        format!("wrong-direction WebSocket response failed: {error}")
                    })?;
                if read == 0 {
                    return Err(
                        "wrong-direction notification closed the WebSocket connection".to_owned(),
                    );
                }
                responses.extend_from_slice(&chunk[..read]);
            }
            if handler_calls.load(Ordering::Acquire) != 1
                || middleware_calls.load(Ordering::Acquire) != 2
                || saw_credential.load(Ordering::Acquire)
            {
                return Err(
                    "wrong-direction notification reached middleware or handler before the resumed request"
                        .to_owned(),
                );
            }

            client
                .write_all(&masked_websocket_frame(0x08, &[]))
                .await
                .map_err(|error| {
                    format!("wrong-direction WebSocket close write failed: {error}")
                })?;
            client.flush().await.map_err(|error| {
                format!("wrong-direction WebSocket close flush failed: {error}")
            })?;
            drop(client);
            listener_task.abort();
            let join_cx = Cx::for_testing();
            let shutdown = listener_task
                .join(&join_cx)
                .await
                .map_err(|error| {
                    format!("wrong-direction WebSocket listener join failed: {error:?}")
                })?
                .map_err(|error| format!("wrong-direction WebSocket listener failed: {error}"))?;
            if !matches!(shutdown, WebSocketServerShutdown::Quiescent) {
                return Err("wrong-direction WebSocket listener did not quiesce".to_owned());
            }
            Ok(())
        });
    }

    #[cfg(feature = "websocket")]
    #[test]
    fn live_websocket_failing_child_is_reported_after_cleanup_observes_terminal_peer() {
        run_live_http_test(|cx| async move {
            use asupersync::io::{AsyncReadExt, AsyncWriteExt};

            let peer_terminal = Arc::new(AtomicBool::new(false));
            let cleanup_after_peer_terminal = Arc::new(AtomicBool::new(false));
            let shutdown_calls = Arc::new(AtomicUsize::new(0));
            let observed_peer_terminal = Arc::clone(&peer_terminal);
            let observed_cleanup = Arc::clone(&cleanup_after_peer_terminal);
            let observed_shutdown_calls = Arc::clone(&shutdown_calls);
            let listener = Server::new("live-websocket-failing-child", "1.0.0")
                .protocol_policy(ProtocolPolicy::ModernOnly)
                .expect("modern-only policy is available")
                .on_shutdown(move || {
                    observed_shutdown_calls.fetch_add(1, Ordering::AcqRel);
                    observed_cleanup.store(
                        observed_peer_terminal.load(Ordering::Acquire),
                        Ordering::Release,
                    );
                })
                .build()
                .bind_websocket(&cx, "127.0.0.1:0")
                .await
                .map_err(|error| format!("failing-child WebSocket bind failed: {error}"))?;
            let address = listener
                .local_addr()
                .map_err(|error| format!("failing-child WebSocket address failed: {error}"))?;
            let scope = cx.scope();
            let mut listener_task = cx
                .spawn_in(&scope, move |listener_cx| async move {
                    listener.serve(&listener_cx).await
                })
                .map_err(|error| {
                    format!("failing-child WebSocket listener admission failed: {error}")
                })?;
            let opening = concat!(
                "GET /mcp HTTP/1.1\r\nHost: localhost\r\nUpgrade: websocket\r\n",
                "Connection: Upgrade\r\nSec-WebSocket-Version: 13\r\n",
                "Sec-WebSocket-Key: dGhlIHNhbXBsZSBub25jZQ==\r\n\r\n"
            );
            let (mut client, accepted) =
                websocket_upgrade(&cx, address, opening.as_bytes()).await?;
            if !accepted.starts_with(b"HTTP/1.1 101") {
                return Err("failing WebSocket child was not upgraded".to_owned());
            }
            // Reserved opcode 0x03 is a decoded-frame failure, not a clean
            // peer close. The real connection child must return that failure
            // to the listener-owned TaskHandle.
            client
                .write_all(&masked_websocket_frame(0x03, &[]))
                .await
                .map_err(|error| format!("failing WebSocket frame write failed: {error}"))?;
            client
                .flush()
                .await
                .map_err(|error| format!("failing WebSocket frame flush failed: {error}"))?;
            let deadline = cx.now().saturating_add_nanos(LIVE_HTTP_TEST_TIMEOUT_NANOS);
            let mut terminal = [0_u8; 32];
            let terminal_read = asupersync::time::timeout_at(deadline, client.read(&mut terminal))
                .await
                .map_err(|_| "failing WebSocket terminal response timed out".to_owned())?
                .map_err(|error| format!("failing WebSocket terminal response failed: {error}"))?;
            if terminal_read != 0 && (terminal_read < 2 || terminal[0] & 0x0f != 0x08) {
                return Err(
                    "failing WebSocket child did not terminate the invalid frame".to_owned(),
                );
            }
            peer_terminal.store(true, Ordering::Release);
            drop(client);

            // A second accepted socket makes the listener reap the first
            // terminal child on its real accept-loop path before shutdown.
            let reaper_trigger = opening.replace("Connection: Upgrade", "Connection: keep-alive");
            let (_trigger, rejected) =
                websocket_upgrade(&cx, address, reaper_trigger.as_bytes()).await?;
            if !rejected.starts_with(b"HTTP/1.1 400") {
                return Err("failing-child reaper trigger did not reach the listener".to_owned());
            }
            listener_task.abort();
            let join_cx = Cx::for_testing();
            let listener_result = listener_task
                .join(&join_cx)
                .await
                .map_err(|error| format!("failing WebSocket listener join failed: {error:?}"))?;
            let error = match listener_result {
                Err(error) => error,
                Ok(_) => {
                    return Err(
                        "failing WebSocket child unexpectedly produced a quiescent success result"
                            .to_owned(),
                    );
                }
            };
            if !error
                .message
                .contains("WebSocket connection child settlement failure")
                || shutdown_calls.load(Ordering::Acquire) != 1
                || !cleanup_after_peer_terminal.load(Ordering::Acquire)
            {
                return Err(
                    "failing WebSocket child was hidden or cleanup preceded terminal settlement"
                        .to_owned(),
                );
            }
            Ok(())
        });
    }

    #[cfg(feature = "websocket")]
    #[test]
    fn live_websocket_upgrade_owns_connection_teardown_and_preserves_peer_isolation() {
        run_live_http_test(|cx| async move {
            use asupersync::io::{AsyncReadExt, AsyncWriteExt};

            let listener = Server::new("live-websocket", "1.0.0")
                .protocol_policy(ProtocolPolicy::ModernOnly)
                .expect("modern-only policy is available")
                .http_config(HttpServerConfig::new().mcp_path("/qualified/mcp"))
                .build()
                .bind_websocket(&cx, "127.0.0.1:0")
                .await
                .map_err(|error| format!("WebSocket bind failed: {error}"))?;
            let address = listener
                .local_addr()
                .map_err(|error| format!("WebSocket local address failed: {error}"))?;
            let scope = cx.scope();
            let mut listener_task = cx
                .spawn_in(&scope, move |listener_cx| async move {
                    listener.serve(&listener_cx).await
                })
                .map_err(|error| format!("WebSocket listener task admission failed: {error}"))?;

            let valid = concat!(
                "GET /qualified/mcp?ignored=query HTTP/1.1\r\n",
                "Host: localhost\r\n",
                "Upgrade: websocket\r\n",
                "Connection: Upgrade\r\n",
                "Sec-WebSocket-Version: 13\r\n",
                "Sec-WebSocket-Key: dGhlIHNhbXBsZSBub25jZQ==\r\n\r\n"
            );
            // The opening frame intentionally shares the Upgrade write. This
            // proves that HTTP header parsing hands pre-read WebSocket bytes
            // to the server-role frame decoder instead of losing them.
            let mut opening = valid.as_bytes().to_vec();
            opening.extend_from_slice(&masked_websocket_message(modern_discovery_request(7_101)));
            let (mut client, accepted) = websocket_upgrade(&cx, address, &opening).await?;
            if !accepted.starts_with(b"HTTP/1.1 101") {
                return Err(format!(
                    "valid WebSocket upgrade was not accepted: {accepted:?}"
                ));
            }
            let deadline = cx.now().saturating_add_nanos(LIVE_HTTP_TEST_TIMEOUT_NANOS);
            let header_end = accepted
                .windows(4)
                .position(|window| window == b"\r\n\r\n")
                .map_or(accepted.len(), |position| position + 4);
            let mut response = accepted[header_end..].to_vec();
            while !response.windows(10).any(|window| window == b"serverInfo") {
                let mut chunk = [0_u8; 1024];
                let read = asupersync::time::timeout_at(deadline, client.read(&mut chunk))
                    .await
                    .map_err(|_| "modern WebSocket response timed out".to_owned())?
                    .map_err(|error| format!("modern WebSocket response failed: {error}"))?;
                if read == 0 {
                    return Err("modern WebSocket closed before its response".to_owned());
                }
                response.extend_from_slice(&chunk[..read]);
            }
            client
                .write_all(&masked_websocket_frame(0x08, &[]))
                .await
                .map_err(|error| format!("WebSocket close write failed: {error}"))?;
            client
                .flush()
                .await
                .map_err(|error| format!("WebSocket close flush failed: {error}"))?;
            let mut close_reply = [0_u8; 32];
            let close_read = asupersync::time::timeout_at(deadline, client.read(&mut close_reply))
                .await
                .map_err(|_| "WebSocket close reply timed out".to_owned())?
                .map_err(|error| format!("WebSocket close reply failed: {error}"))?;
            if close_read < 2 || close_reply[0] & 0x0f != 0x08 || close_reply[1] & 0x80 != 0 {
                return Err("server did not return an unmasked WebSocket close reply".to_owned());
            }

            let malformed_header = valid.replace("Connection: Upgrade", "Connection: keep-alive");
            let (_bad_client, rejected) =
                websocket_upgrade(&cx, address, malformed_header.as_bytes()).await?;
            if !rejected.starts_with(b"HTTP/1.1 400") {
                return Err(format!("bad Upgrade header was not rejected: {rejected:?}"));
            }

            let (mut era_client, era_accepted) =
                websocket_upgrade(&cx, address, valid.as_bytes()).await?;
            if !era_accepted.starts_with(b"HTTP/1.1 101") {
                return Err("era-negative WebSocket handshake was not accepted".to_owned());
            }
            era_client
                .write_all(&masked_websocket_message(exact_legacy_initialize_request(
                    7_102,
                    serde_json::json!("1.0.0"),
                )))
                .await
                .map_err(|error| format!("legacy-era WebSocket frame write failed: {error}"))?;
            era_client
                .flush()
                .await
                .map_err(|error| format!("legacy-era WebSocket frame flush failed: {error}"))?;
            let mut rejection = [0_u8; 1024];
            let read = asupersync::time::timeout_at(deadline, era_client.read(&mut rejection))
                .await
                .map_err(|_| "legacy-era WebSocket rejection timed out".to_owned())?
                .map_err(|error| format!("legacy-era WebSocket rejection failed: {error}"))?;
            if read == 0
                || !rejection[..read]
                    .windows(5)
                    .any(|window| window == b"error")
            {
                return Err("wrong-era frame did not receive a JSON-RPC refusal".to_owned());
            }

            // RH-5 negative neighbor: a rejected legacy opening must not
            // poison independent modern state or terminate its listener.
            let (mut independent_client, independent_accepted) =
                websocket_upgrade(&cx, address, valid.as_bytes()).await?;
            if !independent_accepted.starts_with(b"HTTP/1.1 101") {
                return Err("wrong-era peer changed listener admission state".to_owned());
            }
            independent_client
                .write_all(&masked_websocket_message(modern_discovery_request(7_103)))
                .await
                .map_err(|error| format!("isolated modern frame write failed: {error}"))?;
            independent_client
                .flush()
                .await
                .map_err(|error| format!("isolated modern frame flush failed: {error}"))?;
            let mut independent_response = Vec::new();
            while !independent_response
                .windows(10)
                .any(|window| window == b"serverInfo")
            {
                let mut chunk = [0_u8; 1024];
                let read =
                    asupersync::time::timeout_at(deadline, independent_client.read(&mut chunk))
                        .await
                        .map_err(|_| "isolated modern WebSocket response timed out".to_owned())?
                        .map_err(|error| {
                            format!("isolated modern WebSocket response failed: {error}")
                        })?;
                if read == 0 {
                    return Err("wrong-era peer closed an independent modern connection".to_owned());
                }
                independent_response.extend_from_slice(&chunk[..read]);
            }
            independent_client
                .write_all(&masked_websocket_frame(0x08, &[]))
                .await
                .map_err(|error| format!("isolated WebSocket close write failed: {error}"))?;
            drop(era_client);

            // TaskHandle::abort requests cooperative cancellation; the
            // serving future still owns child settlement and returns its
            // first-class shutdown result.
            listener_task.abort();
            let join_cx = Cx::for_testing();
            let shutdown = listener_task
                .join(&join_cx)
                .await
                .map_err(|error| format!("WebSocket listener join failed: {error:?}"))?
                .map_err(|error| format!("WebSocket listener failed: {error}"))?;
            if !matches!(shutdown, WebSocketServerShutdown::Quiescent) {
                return Err("cooperative WebSocket shutdown retained a child".to_owned());
            }
            Ok(())
        });
    }

    #[cfg(all(feature = "websocket", feature = "legacy-2024-11-05"))]
    #[test]
    fn live_websocket_auto_accepts_fresh_eras_and_fences_cross_era_traffic() {
        run_live_http_test(|cx| async move {
            use asupersync::io::{AsyncReadExt, AsyncWriteExt};

            fn contains_bytes(haystack: &[u8], needle: &[u8]) -> bool {
                haystack
                    .windows(needle.len())
                    .any(|window| window == needle)
            }

            let handler_calls = Arc::new(AtomicUsize::new(0));
            let listener = Server::new("live-websocket-auto-era-isolation", "1.0.0")
                .protocol_policy(ProtocolPolicy::Auto)
                .expect("Auto policy is available to the public WebSocket listener")
                .tool(ModernHttpAuthCounterTool {
                    calls: Arc::clone(&handler_calls),
                })
                .build()
                .bind_websocket(&cx, "127.0.0.1:0")
                .await
                .map_err(|error| format!("Auto WebSocket bind failed: {error}"))?;
            let address = listener
                .local_addr()
                .map_err(|error| format!("Auto WebSocket address failed: {error}"))?;
            let scope = cx.scope();
            let mut listener_task = cx
                .spawn_in(&scope, move |listener_cx| async move {
                    listener.serve(&listener_cx).await
                })
                .map_err(|error| format!("Auto WebSocket listener admission failed: {error}"))?;
            let opening = concat!(
                "GET /mcp HTTP/1.1\r\nHost: localhost\r\nUpgrade: websocket\r\n",
                "Connection: Upgrade\r\nSec-WebSocket-Version: 13\r\n",
                "Sec-WebSocket-Key: dGhlIHNhbXBsZSBub25jZQ==\r\n\r\n"
            );
            let deadline = cx.now().saturating_add_nanos(LIVE_HTTP_TEST_TIMEOUT_NANOS);

            // Positive: a final-era client selects final routing on its own
            // fresh public WebSocket connection.
            let (mut modern, modern_upgrade) =
                websocket_upgrade(&cx, address, opening.as_bytes()).await?;
            if !modern_upgrade.starts_with(b"HTTP/1.1 101") {
                return Err("Auto WebSocket did not accept the final-era client".to_owned());
            }
            modern
                .write_all(&masked_websocket_message(modern_discovery_request(7_201)))
                .await
                .map_err(|error| format!("Auto final-era discovery write failed: {error}"))?;
            modern
                .flush()
                .await
                .map_err(|error| format!("Auto final-era discovery flush failed: {error}"))?;
            let mut modern_response = Vec::new();
            while !contains_bytes(&modern_response, b"serverInfo") {
                let mut chunk = [0_u8; 1024];
                let read = asupersync::time::timeout_at(deadline, modern.read(&mut chunk))
                    .await
                    .map_err(|_| "Auto final-era discovery timed out".to_owned())?
                    .map_err(|error| format!("Auto final-era discovery read failed: {error}"))?;
                if read == 0 {
                    return Err("Auto final-era client closed before discovery response".to_owned());
                }
                modern_response.extend_from_slice(&chunk[..read]);
            }
            modern
                .write_all(&masked_websocket_frame(0x08, &[]))
                .await
                .map_err(|error| format!("Auto final-era close write failed: {error}"))?;
            modern
                .flush()
                .await
                .map_err(|error| format!("Auto final-era close flush failed: {error}"))?;
            drop(modern);

            // Positive: a separate exact-2024 peer may initialize, confirm
            // initialization, and make an ordinary request on the same public
            // listener without sharing the final-era connection namespace.
            let (mut legacy, legacy_upgrade) =
                websocket_upgrade(&cx, address, opening.as_bytes()).await?;
            if !legacy_upgrade.starts_with(b"HTTP/1.1 101") {
                return Err("Auto WebSocket did not accept the exact-2024 client".to_owned());
            }
            let legacy_initialize =
                exact_legacy_initialize_request(7_202, serde_json::json!("1.0.0"));
            let legacy_initialized = JsonRpcMessage::Request(JsonRpcRequest::notification(
                "notifications/initialized",
                None,
            ));
            let legacy_list = JsonRpcMessage::Request(JsonRpcRequest::new(
                "tools/list",
                Some(serde_json::json!({})),
                7_203_i64,
            ));
            let mut legacy_frames = masked_websocket_message(legacy_initialize);
            legacy_frames.extend(masked_websocket_message(legacy_initialized));
            legacy_frames.extend(masked_websocket_message(legacy_list));
            legacy
                .write_all(&legacy_frames)
                .await
                .map_err(|error| format!("Auto exact-2024 transcript write failed: {error}"))?;
            legacy
                .flush()
                .await
                .map_err(|error| format!("Auto exact-2024 transcript flush failed: {error}"))?;
            let mut legacy_response = Vec::new();
            while !(contains_bytes(&legacy_response, b"\"id\":7202")
                && contains_bytes(&legacy_response, b"\"id\":7203")
                && contains_bytes(&legacy_response, b"\"tools\""))
            {
                let mut chunk = [0_u8; 1024];
                let read = asupersync::time::timeout_at(deadline, legacy.read(&mut chunk))
                    .await
                    .map_err(|_| "Auto exact-2024 transcript timed out".to_owned())?
                    .map_err(|error| format!("Auto exact-2024 transcript read failed: {error}"))?;
                if read == 0 {
                    return Err(
                        "Auto exact-2024 client closed before its ordinary response".to_owned()
                    );
                }
                legacy_response.extend_from_slice(&chunk[..read]);
            }
            legacy
                .write_all(&masked_websocket_frame(0x08, &[]))
                .await
                .map_err(|error| format!("Auto exact-2024 close write failed: {error}"))?;
            legacy
                .flush()
                .await
                .map_err(|error| format!("Auto exact-2024 close flush failed: {error}"))?;
            drop(legacy);

            // RH-5 neighbor: the only changed dimension is a legacy opening
            // after this peer already selected final routing. Its refusal is
            // connection-local and cannot poison a later independent final
            // client on the listener.
            let (mut mixed, mixed_upgrade) =
                websocket_upgrade(&cx, address, opening.as_bytes()).await?;
            if !mixed_upgrade.starts_with(b"HTTP/1.1 101") {
                return Err("Auto WebSocket did not admit the cross-era probe peer".to_owned());
            }
            let mut mixed_frames = masked_websocket_message(modern_discovery_request(7_204));
            mixed_frames.extend(masked_websocket_message(exact_legacy_initialize_request(
                7_205,
                serde_json::json!("1.0.0"),
            )));
            mixed
                .write_all(&mixed_frames)
                .await
                .map_err(|error| format!("Auto cross-era frame write failed: {error}"))?;
            mixed
                .flush()
                .await
                .map_err(|error| format!("Auto cross-era frame flush failed: {error}"))?;
            let mut mixed_response = Vec::new();
            while !(contains_bytes(&mixed_response, b"\"id\":7205")
                && contains_bytes(&mixed_response, b"\"error\""))
            {
                let mut chunk = [0_u8; 1024];
                let read = asupersync::time::timeout_at(deadline, mixed.read(&mut chunk))
                    .await
                    .map_err(|_| "Auto cross-era refusal timed out".to_owned())?
                    .map_err(|error| format!("Auto cross-era refusal read failed: {error}"))?;
                if read == 0 {
                    return Err("Auto cross-era peer closed before its refusal".to_owned());
                }
                mixed_response.extend_from_slice(&chunk[..read]);
            }

            if handler_calls.load(Ordering::Acquire) != 0 {
                return Err(
                    "cross-era refusal dispatched a handler before closing the offending peer"
                        .to_owned(),
                );
            }
            loop {
                let mut terminal = [0_u8; 64];
                let read = asupersync::time::timeout_at(deadline, mixed.read(&mut terminal))
                    .await
                    .map_err(|_| "Auto cross-era peer close timed out".to_owned())?
                    .map_err(|error| format!("Auto cross-era peer close failed: {error}"))?;
                if read == 0 {
                    break;
                }
            }
            drop(mixed);

            let (mut isolated, isolated_upgrade) =
                websocket_upgrade(&cx, address, opening.as_bytes()).await?;
            if !isolated_upgrade.starts_with(b"HTTP/1.1 101") {
                return Err("cross-era probe poisoned later listener admission".to_owned());
            }
            isolated
                .write_all(&masked_websocket_message(modern_discovery_request(7_206)))
                .await
                .map_err(|error| format!("isolated final-era discovery write failed: {error}"))?;
            isolated
                .flush()
                .await
                .map_err(|error| format!("isolated final-era discovery flush failed: {error}"))?;
            let mut isolated_response = Vec::new();
            while !contains_bytes(&isolated_response, b"serverInfo") {
                let mut chunk = [0_u8; 1024];
                let read = asupersync::time::timeout_at(deadline, isolated.read(&mut chunk))
                    .await
                    .map_err(|_| "isolated final-era discovery timed out".to_owned())?
                    .map_err(|error| {
                        format!("isolated final-era discovery read failed: {error}")
                    })?;
                if read == 0 {
                    return Err("cross-era probe poisoned later final-era traffic".to_owned());
                }
                isolated_response.extend_from_slice(&chunk[..read]);
            }
            isolated
                .write_all(&masked_websocket_frame(0x08, &[]))
                .await
                .map_err(|error| format!("isolated final-era close write failed: {error}"))?;
            isolated
                .flush()
                .await
                .map_err(|error| format!("isolated final-era close flush failed: {error}"))?;
            drop(isolated);

            listener_task.abort();
            let join_cx = Cx::for_testing();
            let shutdown = listener_task
                .join(&join_cx)
                .await
                .map_err(|error| format!("Auto WebSocket listener join failed: {error:?}"))?
                .map_err(|error| format!("Auto WebSocket listener failed: {error}"))?;
            if !matches!(shutdown, WebSocketServerShutdown::Quiescent) {
                return Err("Auto WebSocket listener retained a child after era proof".to_owned());
            }
            Ok(())
        });
    }

    #[cfg(feature = "websocket")]
    #[test]
    fn live_websocket_connection_limit_rejects_before_child_and_releases_its_permit() {
        run_live_http_test(|cx| async move {
            let listener = Server::new("live-websocket-limit", "1.0.0")
                .protocol_policy(ProtocolPolicy::ModernOnly)
                .expect("modern-only policy is available")
                .http_config(HttpServerConfig::new().max_connections(1))
                .build()
                .bind_websocket(&cx, "127.0.0.1:0")
                .await
                .map_err(|error| format!("limited WebSocket bind failed: {error}"))?;
            let address = listener
                .local_addr()
                .map_err(|error| format!("limited WebSocket address failed: {error}"))?;
            let scope = cx.scope();
            let mut listener_task = cx
                .spawn_in(&scope, move |listener_cx| async move {
                    listener.serve(&listener_cx).await
                })
                .map_err(|error| format!("limited WebSocket listener admission failed: {error}"))?;
            let opening = concat!(
                "GET /mcp HTTP/1.1\r\n",
                "Host: localhost\r\n",
                "Upgrade: websocket\r\n",
                "Connection: Upgrade\r\n",
                "Sec-WebSocket-Version: 13\r\n",
                "Sec-WebSocket-Key: dGhlIHNhbXBsZSBub25jZQ==\r\n\r\n"
            );
            let (first, accepted) = websocket_upgrade(&cx, address, opening.as_bytes()).await?;
            if !accepted.starts_with(b"HTTP/1.1 101") {
                return Err("the first limited WebSocket connection was not accepted".to_owned());
            }
            let (_overflow, rejected) = websocket_upgrade(&cx, address, opening.as_bytes()).await?;
            if rejected.starts_with(b"HTTP/1.1 101") {
                return Err(
                    "N+1 WebSocket connection created a child despite the limiter".to_owned(),
                );
            }
            drop(first);
            // The permit belongs to the accepted child's full lifetime.  A
            // later handshake proves it was released when that child ended.
            let deadline = cx.now().saturating_add_nanos(LIVE_HTTP_TEST_TIMEOUT_NANOS);
            let mut replacement = None;
            while cx.now() < deadline {
                let (stream, response) =
                    websocket_upgrade(&cx, address, opening.as_bytes()).await?;
                if response.starts_with(b"HTTP/1.1 101") {
                    replacement = Some(stream);
                    break;
                }
                asupersync::time::sleep(cx.now(), Duration::from_millis(1)).await;
            }
            drop(replacement.ok_or_else(|| {
                "WebSocket permit did not release with its connection child".to_owned()
            })?);
            listener_task.abort();
            let join_cx = Cx::for_testing();
            let shutdown = listener_task
                .join(&join_cx)
                .await
                .map_err(|error| format!("limited WebSocket listener join failed: {error:?}"))?
                .map_err(|error| format!("limited WebSocket listener failed: {error}"))?;
            if !matches!(shutdown, WebSocketServerShutdown::Quiescent) {
                return Err("limited WebSocket shutdown retained a child".to_owned());
            }
            Ok(())
        });
    }

    #[cfg(feature = "websocket")]
    #[test]
    fn live_websocket_upgrade_authentication_rejects_before_101_and_allows_bearer() {
        run_live_http_test(|cx| async move {
            use asupersync::io::{AsyncReadExt, AsyncWriteExt};

            let provider_calls = Arc::new(AtomicUsize::new(0));
            let handler_calls = Arc::new(AtomicUsize::new(0));
            let middleware_calls = Arc::new(AtomicUsize::new(0));
            let saw_credential = Arc::new(AtomicBool::new(false));
            let listener = Server::new("live-websocket-auth", "1.0.0")
                .protocol_policy(ProtocolPolicy::ModernOnly)
                .expect("modern-only policy is available")
                .auth_provider(OneShotNativeAuthProvider {
                    calls: Arc::clone(&provider_calls),
                })
                .middleware(ModernHttpAuthMiddleware {
                    calls: Arc::clone(&middleware_calls),
                    saw_credential: Arc::clone(&saw_credential),
                })
                .tool(ModernHttpAuthCounterTool {
                    calls: Arc::clone(&handler_calls),
                })
                .build()
                .bind_websocket(&cx, "127.0.0.1:0")
                .await
                .map_err(|error| format!("WebSocket auth bind failed: {error}"))?;
            let address = listener
                .local_addr()
                .map_err(|error| format!("WebSocket auth address failed: {error}"))?;
            let scope = cx.scope();
            let mut listener_task = cx
                .spawn_in(&scope, move |listener_cx| async move {
                    listener.serve(&listener_cx).await
                })
                .map_err(|error| format!("WebSocket auth listener admission failed: {error}"))?;
            let unsigned = concat!(
                "GET /mcp HTTP/1.1\r\nHost: localhost\r\nUpgrade: websocket\r\n",
                "Connection: Upgrade\r\nSec-WebSocket-Version: 13\r\n",
                "Sec-WebSocket-Key: dGhlIHNhbXBsZSBub25jZQ==\r\n\r\n"
            );
            let (_missing, missing) = websocket_upgrade(&cx, address, unsigned.as_bytes()).await?;
            if !missing.starts_with(b"HTTP/1.1 401")
                || !String::from_utf8_lossy(&missing)
                    .to_ascii_lowercase()
                    .contains("www-authenticate: bearer")
            {
                return Err(
                    "missing WebSocket bearer committed a 101 or omitted challenge".to_owned(),
                );
            }
            let duplicate = unsigned.replace(
                "\r\n\r\n",
                "\r\nAuthorization: Bearer alpha\r\naUtHoRiZaTiOn: Bearer beta\r\n\r\n",
            );
            let (_duplicate, duplicate_response) =
                websocket_upgrade(&cx, address, duplicate.as_bytes()).await?;
            if !duplicate_response.starts_with(b"HTTP/1.1 401")
                || !String::from_utf8_lossy(&duplicate_response)
                    .to_ascii_lowercase()
                    .contains("www-authenticate: bearer")
            {
                return Err(
                    "duplicate WebSocket Authorization did not receive 401 before 101".to_owned(),
                );
            }
            for malformed in [
                unsigned.replace("\r\n\r\n", "\r\nAuthorization Bearer alpha\r\n\r\n"),
                unsigned.replace("\r\n\r\n", "\r\nAuthorization : Bearer alpha\r\n\r\n"),
            ] {
                let (_malformed, response) =
                    websocket_upgrade(&cx, address, malformed.as_bytes()).await?;
                if !response.starts_with(b"HTTP/1.1 401")
                    || !String::from_utf8_lossy(&response)
                        .to_ascii_lowercase()
                        .contains("www-authenticate: bearer")
                {
                    return Err(
                        "malformed Authorization intent did not receive the bounded challenge"
                            .to_owned(),
                    );
                }
            }
            let unrelated_malformed = unsigned.replace("\r\n\r\n", "\r\nX-Test malformed\r\n\r\n");
            let (_unrelated, unrelated_response) =
                websocket_upgrade(&cx, address, unrelated_malformed.as_bytes()).await?;
            if !unrelated_response.starts_with(b"HTTP/1.1 400") {
                return Err("unrelated malformed Upgrade header was not retained as 400".to_owned());
            }
            if provider_calls.load(Ordering::Acquire) != 0
                || handler_calls.load(Ordering::Acquire) != 0
                || middleware_calls.load(Ordering::Acquire) != 0
            {
                return Err(
                    "pre-101 missing, duplicate, or malformed admission evaluated provider or dispatch"
                        .to_owned(),
                );
            }
            let valid = unsigned.replace("\r\n\r\n", "\r\nAuthorization: Bearer alpha\r\n\r\n");
            let (mut accepted, response) =
                websocket_upgrade(&cx, address, valid.as_bytes()).await?;
            if !response.starts_with(b"HTTP/1.1 101") {
                return Err("valid WebSocket bearer did not pass Upgrade admission".to_owned());
            }
            let request = JsonRpcRequest::new(
                "tools/call",
                Some(serde_json::json!({
                    "name": "modern_http_auth_counter",
                    "arguments": {},
                    "_meta": {
                        MODERN_PROTOCOL_VERSION_METADATA_KEY: MODERN_PROTOCOL_VERSION,
                        FINAL_CLIENT_CAPABILITIES_META_KEY: {},
                    },
                })),
                7_104_i64,
            );
            accepted
                .write_all(&masked_websocket_message(JsonRpcMessage::Request(request)))
                .await
                .map_err(|error| format!("valid WebSocket tool write failed: {error}"))?;
            accepted
                .flush()
                .await
                .map_err(|error| format!("valid WebSocket tool flush failed: {error}"))?;
            let deadline = cx.now().saturating_add_nanos(LIVE_HTTP_TEST_TIMEOUT_NANOS);
            let mut response = Vec::new();
            while !response
                .windows("authenticated modern HTTP dispatch".len())
                .any(|window| window == b"authenticated modern HTTP dispatch")
            {
                let mut chunk = [0_u8; 1024];
                let read = asupersync::time::timeout_at(deadline, accepted.read(&mut chunk))
                    .await
                    .map_err(|_| "valid WebSocket tool response timed out".to_owned())?
                    .map_err(|error| format!("valid WebSocket tool response failed: {error}"))?;
                if read == 0 {
                    return Err("valid WebSocket bearer closed before handler dispatch".to_owned());
                }
                response.extend_from_slice(&chunk[..read]);
            }
            if handler_calls.load(Ordering::Acquire) != 1
                || provider_calls.load(Ordering::Acquire) != 1
                || middleware_calls.load(Ordering::Acquire) != 1
                || saw_credential.load(Ordering::Acquire)
            {
                return Err(
                    "valid WebSocket bearer did not consume exactly one custody evaluation"
                        .to_owned(),
                );
            }
            // The first provider evaluation above was the accepted bearer.
            // This second evaluation must be counted and denied before 101;
            // it must not produce another custody or dispatch mutation.
            let invalid = unsigned.replace(
                "\r\n\r\n",
                "\r\nAuthorization: Bearer invalid-never-echo\r\n\r\n",
            );
            let (_invalid, invalid_response) =
                websocket_upgrade(&cx, address, invalid.as_bytes()).await?;
            if !invalid_response.starts_with(b"HTTP/1.1 401")
                || String::from_utf8_lossy(&invalid_response).contains("invalid-never-echo")
                || provider_calls.load(Ordering::Acquire) != 2
                || handler_calls.load(Ordering::Acquire) != 1
                || middleware_calls.load(Ordering::Acquire) != 1
            {
                return Err(
                    "second provider evaluation did not reject invalid WebSocket bearer before 101"
                        .to_owned(),
                );
            }
            let mixed = JsonRpcRequest::new(
                "tools/call",
                Some(serde_json::json!({
                    "authorization": "Bearer never-log-or-handle",
                    "name": "modern_http_auth_counter",
                    "arguments": {},
                    "_meta": {
                        MODERN_PROTOCOL_VERSION_METADATA_KEY: MODERN_PROTOCOL_VERSION,
                        FINAL_CLIENT_CAPABILITIES_META_KEY: {},
                    },
                })),
                7_105_i64,
            );
            accepted
                .write_all(&masked_websocket_message(JsonRpcMessage::Request(mixed)))
                .await
                .map_err(|error| format!("mixed WebSocket credential write failed: {error}"))?;
            accepted
                .flush()
                .await
                .map_err(|error| format!("mixed WebSocket credential flush failed: {error}"))?;
            let mut rejection = [0_u8; 1024];
            let rejected = asupersync::time::timeout_at(deadline, accepted.read(&mut rejection))
                .await
                .map_err(|_| "mixed WebSocket credential response timed out".to_owned())?
                .map_err(|error| format!("mixed WebSocket credential response failed: {error}"))?;
            if rejected == 0
                || !rejection[..rejected]
                    .windows(5)
                    .any(|window| window == b"error")
                || String::from_utf8_lossy(&rejection[..rejected]).contains("never-log-or-handle")
                || handler_calls.load(Ordering::Acquire) != 1
                || provider_calls.load(Ordering::Acquire) != 2
                || middleware_calls.load(Ordering::Acquire) != 1
                || saw_credential.load(Ordering::Acquire)
            {
                return Err(
                    "mixed WebSocket credential escaped custody or reached dispatch".to_owned(),
                );
            }
            drop(accepted);
            listener_task.abort();
            let join_cx = Cx::for_testing();
            let shutdown = listener_task
                .join(&join_cx)
                .await
                .map_err(|error| format!("WebSocket auth listener join failed: {error:?}"))?
                .map_err(|error| format!("WebSocket auth listener failed: {error}"))?;
            if !matches!(shutdown, WebSocketServerShutdown::Quiescent) {
                return Err("WebSocket authentication shutdown retained a child".to_owned());
            }
            Ok(())
        });
    }

    #[cfg(feature = "websocket")]
    #[test]
    fn websocket_nonquiescent_settle_for_drains_successful_retained_child_once() {
        run_live_http_test(|cx| async move {
            let shutdown_calls = Arc::new(AtomicUsize::new(0));
            let shutdown_observer = Arc::clone(&shutdown_calls);
            let server = Arc::new(
                Server::new("websocket-settlement-success", "1.0.0")
                    .on_shutdown(move || {
                        shutdown_observer.fetch_add(1, Ordering::AcqRel);
                    })
                    .build(),
            );
            let release_child = Arc::new(AtomicBool::new(false));
            let child_release = Arc::clone(&release_child);
            let child_started = Arc::new(AtomicBool::new(false));
            let child_started_observer = Arc::clone(&child_started);
            let scope = cx.scope();
            let child = cx
                .spawn_in(&scope, move |_child_cx| async move {
                    child_started_observer.store(true, Ordering::Release);
                    while !child_release.load(Ordering::Acquire) {
                        asupersync::runtime::yield_now().await;
                    }
                    Ok(())
                })
                .map_err(|error| format!("successful retained child admission failed: {error}"))?;
            let deadline = Instant::now() + Duration::from_secs(1);
            while !child_started.load(Ordering::Acquire) && Instant::now() < deadline {
                asupersync::runtime::yield_now().await;
            }
            if !child_started.load(Ordering::Acquire) {
                return Err("successful retained child did not begin".to_owned());
            }
            let mut retained = WebSocketNonquiescentShutdown {
                children: WebSocketConnectionChildren {
                    tasks: vec![child],
                    terminal_failure: Arc::default(),
                },
                server,
                listener_error: None,
                shutdown_complete: false,
            };
            if retained.remaining_connections() != 1 {
                return Err("successful retained child was not caller-owned".to_owned());
            }
            release_child.store(true, Ordering::Release);
            if !retained
                .settle_for(Duration::from_secs(1))
                .await
                .map_err(|error| format!("successful retained child settlement failed: {error}"))?
                || retained.remaining_connections() != 0
                || shutdown_calls.load(Ordering::Acquire) != 1
            {
                return Err(
                    "successful retained child did not drain to one cleanup-backed settlement"
                        .to_owned(),
                );
            }
            Ok(())
        });
    }

    #[cfg(feature = "websocket")]
    #[test]
    fn websocket_nonquiescent_settle_for_retains_abort_race_and_reaped_panic() {
        run_live_http_test(|cx| async move {
            let shutdown_calls = Arc::new(AtomicUsize::new(0));
            let shutdown_observer = Arc::clone(&shutdown_calls);
            let server = Arc::new(
                Server::new("websocket-settlement-drain", "1.0.0")
                    .on_shutdown(move || {
                        shutdown_observer.fetch_add(1, Ordering::AcqRel);
                    })
                    .build(),
            );
            let scope = cx.scope();
            let release_live_child = Arc::new(AtomicBool::new(false));
            let live_child_release = Arc::clone(&release_live_child);
            let live_child_started = Arc::new(AtomicBool::new(false));
            let live_child_started_observer = Arc::clone(&live_child_started);
            let retained_live = cx
                .spawn_in(&scope, move |_child_cx| async move {
                    live_child_started_observer.store(true, Ordering::Release);
                    while !live_child_release.load(Ordering::Acquire) {
                        // Deliberately ignore the child Cx cancellation. This
                        // is the shutdown-debt shape that must remain caller
                        // owned after the listener aborts its child.
                        asupersync::runtime::yield_now().await;
                    }
                    Ok(())
                })
                .map_err(|error| format!("retained WebSocket child admission failed: {error}"))?;
            let started_deadline = Instant::now() + Duration::from_secs(1);
            while !live_child_started.load(Ordering::Acquire) && Instant::now() < started_deadline {
                asupersync::runtime::yield_now().await;
            }
            if !live_child_started.load(Ordering::Acquire) {
                return Err("WebSocket retained child did not begin before abort".to_owned());
            }
            let failed = cx
                .spawn_in(&scope, move |_child_cx| async move {
                    panic!("forced WebSocket child failure")
                })
                .map_err(|error| format!("failed WebSocket child admission failed: {error}"))?;
            retained_live.abort();
            let mut children = WebSocketConnectionChildren {
                tasks: vec![retained_live, failed],
                terminal_failure: Arc::default(),
            };
            let deadline = Instant::now() + Duration::from_secs(1);
            while !children.has_terminal_failure() && Instant::now() < deadline {
                children.reap_finished();
                if !children.has_terminal_failure() {
                    asupersync::runtime::yield_now().await;
                }
            }
            if !children.has_terminal_failure() {
                return Err("WebSocket child reaper did not retain the forced panic".to_owned());
            }
            let retained = WebSocketServerShutdown::Nonquiescent(WebSocketNonquiescentShutdown {
                children,
                server,
                listener_error: None,
                shutdown_complete: false,
            });
            let WebSocketServerShutdown::Nonquiescent(retained) = retained else {
                return Err("forced WebSocket retained work did not report Nonquiescent".to_owned());
            };
            if retained.remaining_connections() != 1 {
                return Err(
                    "WebSocket abort race did not retain exactly one live caller-owned child"
                        .to_owned(),
                );
            }
            let mut retained = retained;
            if retained
                .settle_for(Duration::ZERO)
                .await
                .map_err(|error| format!("WebSocket retained-child probe failed: {error}"))?
            {
                return Err(
                    "WebSocket settle_for falsely reported an abort-race child as settled"
                        .to_owned(),
                );
            }
            if retained.remaining_connections() != 1 {
                return Err("WebSocket settle_for detached or lost the abort-race child".to_owned());
            }
            release_live_child.store(true, Ordering::Release);
            let error = retained
                .settle_for(Duration::from_secs(1))
                .await
                .expect_err("a real child failure must be returned after all children drain");
            if !error
                .message
                .contains("WebSocket connection child settlement failure")
                || shutdown_calls.load(Ordering::Acquire) != 1
            {
                return Err(
                    "WebSocket settlement skipped cleanup or hid its recorded child failure"
                        .to_owned(),
                );
            }
            Ok(())
        });
    }

    #[cfg(feature = "websocket")]
    #[test]
    fn websocket_settle_for_returns_listener_failure_after_cleanup() {
        run_live_http_test(|_cx| async move {
            let shutdown_calls = Arc::new(AtomicUsize::new(0));
            let shutdown_observer = Arc::clone(&shutdown_calls);
            let server = Arc::new(
                Server::new("websocket-settle-for-listener-error", "1.0.0")
                    .on_shutdown(move || {
                        shutdown_observer.fetch_add(1, Ordering::AcqRel);
                    })
                    .build(),
            );
            let mut retained = WebSocketNonquiescentShutdown {
                children: WebSocketConnectionChildren::default(),
                server,
                listener_error: Some(McpError::internal_error("forced accept-loop failure")),
                shutdown_complete: false,
            };
            let error = retained
                .settle_for(Duration::ZERO)
                .await
                .expect_err("settle_for must not hide a recorded listener failure");
            if !error.message.contains("forced accept-loop failure")
                || shutdown_calls.load(Ordering::Acquire) != 1
            {
                return Err(
                    "WebSocket settle_for did not preserve listener error after cleanup".to_owned(),
                );
            }
            Ok(())
        });
    }

