    #[test]
    fn boxed_extension_settings_resolver_preserves_inactive_disposition() {
        struct InactiveResolver;

        impl ExtensionSettingsCompatibilityResolver for InactiveResolver {
            fn resolve(
                &mut self,
                descriptor: &ExtensionDescriptor,
                _client: &ExtensionSettings,
                _server: &ExtensionSettings,
            ) -> Result<ExtensionSettings, ExtensionNegotiationError> {
                Err(ExtensionNegotiationError::SettingsCompatibilityRejected(
                    descriptor.id.to_string(),
                ))
            }

            fn resolve_with_disposition(
                &mut self,
                _descriptor: &ExtensionDescriptor,
                _client: &ExtensionSettings,
                _server: &ExtensionSettings,
            ) -> Result<ExtensionSettingsResolution, ExtensionNegotiationError> {
                Ok(ExtensionSettingsResolution::Inactive)
            }
        }

        let settings = ExtensionSettings::new(serde_json::json!({}))
            .expect("empty extension settings must be valid");
        let mut resolver = BoxedExtensionSettingsResolver(Box::new(InactiveResolver));
        let disposition = resolver
            .resolve_with_disposition(
                &fastmcp_protocol::extensions::official_mcp_apps_descriptor(),
                &settings,
                &settings,
            )
            .expect("boxed resolver must retain an inactive disposition");

        assert_eq!(disposition, ExtensionSettingsResolution::Inactive);
    }

    #[cfg(all(feature = "apps", feature = "tasks"))]
    #[test]
    fn builder_mcp_apps_composes_with_final_tasks_and_preserves_inactive_apps() {
        let delivered = Arc::new(Mutex::new(Vec::new()));
        let server = Server::new("apps-and-tasks-server", "1.0.0")
            .mcp_apps()
            .expect("official Apps installs before final Tasks")
            .final_tasks(final_tasks_test_runtime(Arc::clone(&delivered)))
            .expect("final Tasks composes with official Apps")
            .build();
        let apps_id = fastmcp_protocol::official_mcp_apps_extension_id();
        let tasks_id = fastmcp_protocol::official_tasks_extension_id();

        assert_eq!(
            server
                .extension_registry_receipt()
                .expect("Apps and Tasks registry is frozen")
                .descriptor_count(),
            2
        );
        let discovery = serde_json::to_value(
            server
                .server_discovery()
                .expect("Apps and Tasks discovery is available"),
        )
        .expect("Apps and Tasks discovery serializes");
        assert_eq!(
            discovery.pointer("/capabilities/extensions/io.modelcontextprotocol~1ui"),
            Some(&serde_json::json!({}))
        );
        assert_eq!(
            discovery.pointer("/capabilities/extensions/io.modelcontextprotocol~1tasks"),
            Some(&serde_json::json!({}))
        );

        let client = ClientExtensionDiscovery {
            extensions: BTreeMap::from([
                (
                    apps_id.clone(),
                    McpAppsClientSettings::new(vec!["text/plain".to_owned()])
                        .expect("another bounded MIME type is valid Apps settings")
                        .to_extension_settings(),
                ),
                (tasks_id.clone(), official_tasks_empty_settings()),
            ]),
        };
        let negotiated = server
            .negotiate_extensions(&client)
            .expect("valid inactive Apps settings do not reject Tasks negotiation");
        assert_eq!(
            negotiated.inactive_reason(&apps_id),
            Some(ExtensionInactiveReason::SettingsInactiveFallback)
        );
        assert!(negotiated.active(&tasks_id).is_some());
    }

    #[cfg(feature = "apps")]
    #[test]
    fn builder_mcp_apps_ui_resource_binds_a_final_only_ui_catalog_entry() {
        let resource = crate::providers::McpAppsUiResource::try_new(
            fastmcp_protocol::common_types::AbsoluteUri::parse("ui://weather/dashboard")
                .expect("valid ui URI"),
            "weather-dashboard",
            "<main>weather</main>",
        )
        .expect("valid Apps UI resource");
        let server = Server::new("apps-ui-resource", "1.0")
            .mcp_apps()
            .expect("Apps capability installs")
            .mcp_apps_ui_resource(resource)
            .expect("Apps UI resource binds after Apps opt-in")
            .build();

        let inbound =
            InboundRequestContext::new(Cx::for_testing(), 901, InboundRequestTransport::Memory);
        let response = block_on(server.dispatch_stateless(
            &inbound,
            &JsonRpcRequest::new(
                "resources/list",
                Some(serde_json::json!({
                    "_meta": {
                        "io.modelcontextprotocol/protocolVersion": "2026-07-28",
                        "io.modelcontextprotocol/clientCapabilities": {},
                    },
                })),
                901_i64,
            ),
        ))
        .expect("modern resource catalog dispatch succeeds");
        let resources = response.result.expect("modern resource list has a result");
        assert_eq!(resources["resources"][0]["uri"], "ui://weather/dashboard");
        assert_eq!(
            resources["resources"][0]["mimeType"],
            fastmcp_protocol::MCP_APPS_HTML_MIME_TYPE
        );
        let read_inbound =
            InboundRequestContext::new(Cx::for_testing(), 902, InboundRequestTransport::Memory);
        let read_request = JsonRpcRequest::new(
            "resources/read",
            Some(serde_json::json!({
                "uri": "ui://weather/dashboard",
                "_meta": {
                    "io.modelcontextprotocol/protocolVersion": "2026-07-28",
                    "io.modelcontextprotocol/clientCapabilities": {},
                },
            })),
            902_i64,
        );
        let read = block_on(server.dispatch_stateless(&read_inbound, &read_request))
            .expect("modern Apps UI read reaches its final-only resource");
        assert!(
            read.error.is_none(),
            "modern Apps UI read must succeed: {:?}",
            read.error
        );
        let contents = read.result.expect("modern UI read has a result");
        assert_eq!(contents["contents"][0]["text"], "<main>weather</main>");
        assert_eq!(
            contents["contents"][0]["mimeType"],
            fastmcp_protocol::MCP_APPS_HTML_MIME_TYPE
        );
        assert!(
            server.resources().is_empty(),
            "the Apps UI document must remain absent from the exact-2024 catalog"
        );
    }

    #[cfg(feature = "apps")]
    #[test]
    fn builder_mcp_apps_ui_resource_rejects_only_missing_apps_opt_in_without_mutation() {
        let resource = crate::providers::McpAppsUiResource::try_new(
            fastmcp_protocol::common_types::AbsoluteUri::parse("ui://weather/dashboard")
                .expect("valid ui URI"),
            "weather-dashboard",
            "<main>weather</main>",
        )
        .expect("valid Apps UI resource");
        let error = match Server::new("apps-ui-resource", "1.0").mcp_apps_ui_resource(resource) {
            Ok(_) => panic!("changing only the missing Apps opt-in must reject the UI resource"),
            Err(error) => error,
        };
        assert_eq!(error.code, McpErrorCode::InvalidRequest);
    }

    #[cfg(all(feature = "apps", feature = "tasks"))]
    #[test]
    fn builder_final_tasks_then_mcp_apps_preserves_both_discovery_markers() {
        let server = Server::new("tasks-then-apps-server", "1.0.0")
            .final_tasks(final_tasks_test_runtime(Arc::new(Mutex::new(Vec::new()))))
            .expect("final Tasks configures before official Apps")
            .mcp_apps()
            .expect("official Apps composes after final Tasks")
            .build();
        let discovery = serde_json::to_value(
            server
                .server_discovery()
                .expect("Apps and Tasks discovery is available"),
        )
        .expect("Apps and Tasks discovery serializes");

        assert_eq!(
            discovery.pointer("/capabilities/extensions/io.modelcontextprotocol~1ui"),
            Some(&serde_json::json!({}))
        );
        assert_eq!(
            discovery.pointer("/capabilities/extensions/io.modelcontextprotocol~1tasks"),
            Some(&serde_json::json!({}))
        );
    }

    #[derive(Debug, Default)]
    struct HttpOverlapControlState {
        enabled: bool,
        entries: usize,
        permits: usize,
    }

    #[derive(Debug, Default)]
    struct HttpOverlapControl {
        state: Mutex<HttpOverlapControlState>,
        changed: Condvar,
    }

    impl HttpOverlapControl {
        fn begin(&self) -> HttpOverlapControlGuard<'_> {
            let mut state = self.state.lock().expect("HTTP overlap control poisoned");
            state.enabled = true;
            state.entries = 0;
            state.permits = 0;
            HttpOverlapControlGuard { control: self }
        }

        fn enter_and_wait(&self) {
            let mut state = self.state.lock().expect("HTTP overlap control poisoned");
            if !state.enabled {
                return;
            }
            state.entries += 1;
            self.changed.notify_all();
            while state.enabled && state.permits == 0 {
                state = self
                    .changed
                    .wait(state)
                    .expect("HTTP overlap control poisoned while waiting");
            }
            state.permits = state.permits.saturating_sub(1);
        }

        fn wait_for_entries(&self, target: usize, timeout: Duration) -> bool {
            let state = self.state.lock().expect("HTTP overlap control poisoned");
            let (state, _) = self
                .changed
                .wait_timeout_while(state, timeout, |state| state.entries < target)
                .expect("HTTP overlap control poisoned while observing entries");
            state.entries >= target
        }

        fn release_one(&self) {
            let mut state = self.state.lock().expect("HTTP overlap control poisoned");
            state.permits = state.permits.saturating_add(1);
            self.changed.notify_all();
        }

        fn disable(&self) {
            let mut state = self.state.lock().expect("HTTP overlap control poisoned");
            state.enabled = false;
            state.permits = 0;
            self.changed.notify_all();
        }
    }

    struct HttpOverlapControlGuard<'a> {
        control: &'a HttpOverlapControl,
    }

    impl Drop for HttpOverlapControlGuard<'_> {
        fn drop(&mut self) {
            self.control.disable();
        }
    }

    fn http_overlap_metrics() -> &'static HttpOverlapMetrics {
        HTTP_OVERLAP_METRICS.get_or_init(HttpOverlapMetrics::default)
    }

    fn http_overlap_lock() -> &'static Mutex<()> {
        HTTP_OVERLAP_LOCK.get_or_init(|| Mutex::new(()))
    }

    fn http_overlap_control() -> &'static HttpOverlapControl {
        HTTP_OVERLAP_CONTROL.get_or_init(HttpOverlapControl::default)
    }

    pub(super) fn record_live_http_listener_wait() {
        LIVE_HTTP_LISTENER_WAITS.fetch_add(1, Ordering::AcqRel);
    }

    pub(super) fn record_live_http_connection_read_wait() {
        LIVE_HTTP_CONNECTION_READ_WAITS.fetch_add(1, Ordering::AcqRel);
    }

    fn live_http_listener_wait_count() -> usize {
        LIVE_HTTP_LISTENER_WAITS.load(Ordering::Acquire)
    }

    fn live_http_connection_read_wait_count() -> usize {
        LIVE_HTTP_CONNECTION_READ_WAITS.load(Ordering::Acquire)
    }

    async fn wait_for_live_http_probe(
        cx: &Cx,
        before: usize,
        probe: fn() -> usize,
    ) -> Result<(), String> {
        let deadline = cx.now().saturating_add_nanos(LIVE_HTTP_TEST_TIMEOUT_NANOS);
        while probe() <= before {
            cx.checkpoint()
                .map_err(|error| format!("live HTTP probe caller stopped: {error}"))?;
            asupersync::time::timeout_at(
                deadline,
                asupersync::time::sleep(cx.now(), Duration::from_millis(1)),
            )
            .await
            .map_err(|_| live_http_test_timeout("live HTTP probe"))?;
        }
        Ok(())
    }

    async fn wait_for_live_http_flag(
        cx: &Cx,
        flag: &AtomicBool,
        operation: &str,
    ) -> Result<(), String> {
        let deadline = cx.now().saturating_add_nanos(LIVE_HTTP_TEST_TIMEOUT_NANOS);
        while !flag.load(Ordering::Acquire) {
            cx.checkpoint()
                .map_err(|error| format!("{operation} caller stopped: {error}"))?;
            asupersync::time::timeout_at(
                deadline,
                asupersync::time::sleep(cx.now(), Duration::from_millis(1)),
            )
            .await
            .map_err(|_| live_http_test_timeout(operation))?;
        }
        Ok(())
    }

    async fn wait_for_live_http_test_result<T>(receiver: Receiver<T>) -> Result<T, String> {
        let cx = Cx::current().expect("the test runtime must install an ambient Cx while polling");
        let deadline = cx.now().saturating_add_nanos(LIVE_HTTP_TEST_TIMEOUT_NANOS);
        loop {
            match receiver.try_recv() {
                Ok(result) => return Ok(result),
                Err(TryRecvError::Disconnected) => {
                    panic!("live HTTP test task exited without reporting its result");
                }
                Err(TryRecvError::Empty) => {
                    asupersync::time::timeout_at(
                        deadline,
                        asupersync::time::sleep(cx.now(), Duration::from_millis(1)),
                    )
                    .await
                    .map_err(|_| live_http_test_timeout("live HTTP test result"))?;
                }
            }
        }
    }

    fn run_live_http_test<F, Fut>(operation: F)
    where
        F: FnOnce(Cx) -> Fut + Send + 'static,
        Fut: Future<Output = Result<(), String>> + Send + 'static,
    {
        let runtime = RuntimeBuilder::current_thread()
            .with_reactor(create_reactor().expect("live HTTP test reactor must initialize"))
            .blocking_threads(4, MAX_DISPATCH_QUEUE_DEPTH)
            .build()
            .expect("live HTTP test runtime must initialize");
        let result = runtime.block_on(async move {
            let cx = Cx::current().expect("the live HTTP test runtime must install an ambient Cx");
            operation(cx).await
        });
        result.unwrap();
    }

    async fn require_quiescent_http_shutdown(
        shutdown: HttpServerShutdown,
        probe: &str,
    ) -> Result<(), String> {
        match shutdown {
            HttpServerShutdown::Quiescent => Ok(()),
            HttpServerShutdown::Nonquiescent(mut shutdown) => {
                let initial = shutdown.poll_settlement();
                let settled = shutdown.settle_for(Duration::from_secs(1)).await;
                Err(format!(
                    "{probe} unexpectedly retained caller-owned HTTP children; initial={initial:?}, after bounded settlement={settled:?}"
                ))
            }
        }
    }

    fn run_live_modern_pump<R>(server: Server, recv: R, responses: Arc<LiveModernResponses>) -> i32
    where
        R: FnMut(&Cx, &AtomicBool) -> Result<JsonRpcMessage, TransportError> + Send + 'static,
    {
        let runtime = RuntimeBuilder::current_thread()
            .with_reactor(create_reactor().expect("live modern test reactor must initialize"))
            .blocking_threads(4, MAX_DISPATCH_QUEUE_DEPTH)
            .build()
            .expect("live modern test runtime must initialize");
        let (sender, receiver) = sync_channel(1);
        runtime
            .block_on(async move {
                let cx =
                    Cx::current().expect("the live modern test runtime must install an ambient Cx");
                let dispatch_cx = cx.clone();
                match cx.spawn_blocking(move |pump_cx| {
                    let result = Arc::new(server).run_loop_pump_with_policy(
                        &pump_cx,
                        &dispatch_cx,
                        recv,
                        move |_send_cx, message| {
                            responses.record(message.clone());
                            Ok(())
                        },
                        Arc::new(|_| {}),
                        "live-modern-test",
                        false,
                        None,
                        true,
                        true,
                        None,
                        None,
                        None,
                        PumpIoMode::Split,
                    );
                    let _ = sender.send(result);
                }) {
                    // The blocking closure owns the product return value.
                    // Joining its cancellation-dominant wrapper can instead
                    // report shutdown when the pump closes the server region
                    // immediately after producing that value.
                    Ok(_pump) => wait_for_live_http_test_result(receiver).await,
                    Err(error) => Err(format!("live modern pump admission failed: {error}")),
                }
            })
            .expect("live modern pump must complete")
    }

    fn run_live_split_transport<R, S>(
        completion_timeout: Duration,
        server: Server,
        recv: R,
        send: S,
    ) -> Result<(), String>
    where
        R: TransportRecvHalf + Send + 'static,
        S: TransportSendHalf + 'static,
    {
        let runtime = RuntimeBuilder::current_thread()
            .with_reactor(create_reactor().expect("live split transport reactor must initialize"))
            .blocking_threads(4, MAX_DISPATCH_QUEUE_DEPTH)
            .build()
            .expect("live split transport runtime must initialize");
        let (sender, receiver) = sync_channel(1);
        runtime.block_on(async move {
            let cx =
                Cx::current().expect("the live split transport runtime must install an ambient Cx");
            let dispatch_cx = cx.clone();
            match cx.spawn_blocking(move |pump_cx| {
                let result = server.run_split_transport_returning_with_dispatch_cx(
                    &pump_cx,
                    &dispatch_cx,
                    recv,
                    send,
                );
                let _ = sender.send(result);
            }) {
                // Read the value from the completed blocking closure itself;
                // the wrapper join is cancellation-dominant during shutdown.
                Ok(_pump) => {
                    let deadline = cx.now().saturating_add_nanos(
                        u64::try_from(completion_timeout.as_nanos())
                            .expect("split transport completion timeout must fit in nanoseconds"),
                    );
                    loop {
                        match receiver.try_recv() {
                            Ok(result) => break result.map_err(|error| error.to_string()),
                            Err(TryRecvError::Disconnected) => {
                                panic!(
                                    "live split transport task exited without reporting its result"
                                );
                            }
                            Err(TryRecvError::Empty) => {
                                asupersync::time::timeout_at(
                                    deadline,
                                    asupersync::time::sleep(cx.now(), Duration::from_millis(1)),
                                )
                                .await
                                .map_err(|_| {
                                    live_http_test_timeout("live split transport result")
                                })?;
                            }
                        }
                    }
                }
                Err(error) => Err(format!("live split transport admission failed: {error}")),
            }
        })
    }

    async fn live_http_exchange(address: SocketAddr, request: Vec<u8>) -> Result<Vec<u8>, String> {
        let cx = Cx::current()
            .expect("the test runtime must install an ambient Cx for live HTTP exchange");
        let deadline = cx.now().saturating_add_nanos(LIVE_HTTP_TEST_TIMEOUT_NANOS);
        let mut stream = asupersync::time::timeout_at(deadline, AsyncTcpStream::connect(address))
            .await
            .map_err(|_| live_http_test_timeout("live HTTP client connection"))?
            .map_err(|error| format!("live HTTP client connect failed: {error}"))?;
        asupersync::time::timeout_at(deadline, stream.write_all(&request))
            .await
            .map_err(|_| live_http_test_timeout("live HTTP client request write"))?
            .map_err(|error| format!("live HTTP client write failed: {error}"))?;
        asupersync::time::timeout_at(deadline, stream.flush())
            .await
            .map_err(|_| live_http_test_timeout("live HTTP client request flush"))?
            .map_err(|error| format!("live HTTP client flush failed: {error}"))?;
        let mut response = Vec::new();
        read_live_http_to_end(&mut stream, &mut response, "live HTTP client response EOF").await?;
        Ok(response)
    }

    fn live_http_post(
        path_and_query: &str,
        body: &[u8],
        extra_headers: &[(&str, &str)],
    ) -> Vec<u8> {
        let mut request = format!(
            "POST {path_and_query} HTTP/1.1\r\nHost: loopback\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n",
            body.len()
        );
        for (name, value) in extra_headers {
            request.push_str(name);
            request.push_str(": ");
            request.push_str(value);
            request.push_str("\r\n");
        }
        request.push_str("\r\n");
        let mut request = request.into_bytes();
        request.extend_from_slice(body);
        request
    }

    async fn live_http_strict_admission_exchange(
        cx: &Cx,
        mirrored_method_header: &'static str,
    ) -> Result<Vec<u8>, String> {
        live_http_admission_exchange(
            cx,
            vec![
                ("Accept", "application/json"),
                ("MCP-Protocol-Version", MODERN_PROTOCOL_VERSION),
                ("Mcp-Method", mirrored_method_header),
            ],
        )
        .await
    }

    async fn live_http_admission_exchange(
        cx: &Cx,
        headers: Vec<(&'static str, &'static str)>,
    ) -> Result<Vec<u8>, String> {
        let bound = Server::new("live-http-strict-admission", "1.0.0")
            .protocol_policy(ProtocolPolicy::ModernOnly)
            .expect("ModernOnly must be available to this test build")
            .build()
            .bind_http(cx, "127.0.0.1:0")
            .await
            .map_err(|error| format!("strict admission HTTP bind failed: {error}"))?;
        let address = bound
            .local_addr()
            .map_err(|error| format!("strict admission HTTP address failed: {error}"))?;
        let caller_cx = cx.clone();
        let mut client = cx
            .spawn(move |_client_cx| async move {
                let request = JsonRpcRequest::new(
                    SERVER_DISCOVER_METHOD,
                    Some(serde_json::json!({
                        "_meta": {
                            MODERN_PROTOCOL_VERSION_METADATA_KEY: MODERN_PROTOCOL_VERSION,
                            FINAL_CLIENT_CAPABILITIES_META_KEY: {},
                        },
                    })),
                    803_i64,
                );
                let body = serde_json::to_vec(&request).map_err(|error| {
                    format!("strict admission request did not serialize: {error}")
                })?;
                let response =
                    live_http_exchange(address, live_http_post("/mcp", &body, &headers)).await;
                caller_cx.cancel_with(CancelKind::User, Some("strict admission exchange complete"));
                response
            })
            .map_err(|error| format!("strict admission client admission failed: {error}"))?;

        let serve = bound.serve(cx).await;
        let response = client
            .join(cx)
            .await
            .map_err(|error| format!("strict admission client failed: {error:?}"))??;
        let shutdown = serve.map_err(|error| format!("strict admission server failed: {error}"))?;
        require_quiescent_http_shutdown(shutdown, "strict admission").await?;
        Ok(response)
    }

    fn live_http_response_body(response: &[u8]) -> Result<&[u8], String> {
        response
            .windows(4)
            .position(|window| window == b"\r\n\r\n")
            .map(|offset| &response[offset + 4..])
            .ok_or_else(|| "live HTTP response omitted its header terminator".to_string())
    }

    fn live_http_sse_jsonrpc_response(response: &[u8]) -> Result<JsonRpcResponse, String> {
        let body = std::str::from_utf8(live_http_response_body(response)?)
            .map_err(|error| format!("live SSE body was not UTF-8: {error}"))?;
        let data = body
            .rsplit_once("data: ")
            .map(|(_, data)| data)
            .and_then(|data| data.split_once("\n\n").map(|(data, _)| data))
            .ok_or_else(|| "live SSE body omitted a JSON-RPC event".to_owned())?;
        serde_json::from_str(data)
            .map_err(|error| format!("live SSE JSON-RPC event was invalid: {error}"))
    }

    /// Parses the full chunked H1 body rather than searching its text. This
    /// keeps live SSE assertions honest about frame boundaries, ordering, and
    /// terminal EOF: an extra notification after the response is a fourth
    /// parsed frame, not an overlooked substring.
    fn live_http_chunked_sse_messages(response: &[u8]) -> Result<Vec<JsonRpcMessage>, String> {
        let mut remaining = live_http_response_body(response)?;
        let mut messages = Vec::new();
        loop {
            let Some(line_end) = remaining.windows(2).position(|window| window == b"\r\n") else {
                return Err("live SSE chunk omitted its size terminator".to_owned());
            };
            let chunk_size = std::str::from_utf8(&remaining[..line_end])
                .map_err(|error| format!("live SSE chunk size was not UTF-8: {error}"))?;
            let chunk_size = usize::from_str_radix(chunk_size, 16)
                .map_err(|error| format!("live SSE chunk size was invalid: {error}"))?;
            remaining = &remaining[line_end + 2..];
            if chunk_size == 0 {
                if remaining != b"\r\n" {
                    return Err("live SSE terminal chunk had trailing bytes".to_owned());
                }
                return Ok(messages);
            }
            if remaining.len() < chunk_size + 2 {
                return Err("live SSE chunk was truncated".to_owned());
            }
            let (chunk, suffix) = remaining.split_at(chunk_size);
            if &suffix[..2] != b"\r\n" {
                return Err("live SSE chunk omitted its data terminator".to_owned());
            }
            remaining = &suffix[2..];
            let event = std::str::from_utf8(chunk)
                .map_err(|error| format!("live SSE event was not UTF-8: {error}"))?;
            if !event.starts_with("event: message\n") || !event.ends_with("\n\n") {
                return Err(format!(
                    "live SSE chunk was not one message event: {event:?}"
                ));
            }
            let data = event
                .lines()
                .filter_map(|line| line.strip_prefix("data: "))
                .collect::<Vec<_>>();
            if data.len() != 1 {
                return Err(
                    "live SSE message event did not carry one JSON-RPC data line".to_owned(),
                );
            }
            messages.push(
                Codec::new()
                    .decode_complete_message(data[0].as_bytes())
                    .map_err(|error| format!("live SSE JSON-RPC event was invalid: {error}"))?,
            );
        }
    }

    fn live_http_response_header(response: &[u8], name: &str) -> Result<String, String> {
        let headers = std::str::from_utf8(
            response
                .windows(4)
                .position(|window| window == b"\r\n\r\n")
                .map(|offset| &response[..offset])
                .ok_or_else(|| "live HTTP response omitted its header terminator".to_string())?,
        )
        .map_err(|error| format!("live HTTP response headers were not UTF-8: {error}"))?;
        headers
            .split("\r\n")
            .skip(1)
            .find_map(|header| {
                let (header_name, value) = header.split_once(':')?;
                header_name
                    .eq_ignore_ascii_case(name)
                    .then(|| value.trim().to_owned())
            })
            .ok_or_else(|| format!("live HTTP response omitted {name} header"))
    }

    fn live_http_response_has_header(response: &[u8], name: &str) -> Result<bool, String> {
        let headers = std::str::from_utf8(
            response
                .windows(4)
                .position(|window| window == b"\r\n\r\n")
                .map(|offset| &response[..offset])
                .ok_or_else(|| "live HTTP response omitted its header terminator".to_string())?,
        )
        .map_err(|error| format!("live HTTP response headers were not UTF-8: {error}"))?;
        Ok(headers.split("\r\n").skip(1).any(|header| {
            header
                .split_once(':')
                .is_some_and(|(header_name, _)| header_name.eq_ignore_ascii_case(name))
        }))
    }

    async fn read_live_http_until(
        stream: &mut AsyncTcpStream,
        received: &mut Vec<u8>,
        needle: &[u8],
    ) -> Result<(), String> {
        let cx = Cx::current()
            .expect("the test runtime must install an ambient Cx for live HTTP SSE reads");
        let deadline = cx.now().saturating_add_nanos(LIVE_HTTP_TEST_TIMEOUT_NANOS);
        while !received
            .windows(needle.len())
            .any(|window| window == needle)
        {
            if received.len() > 64 * 1024 {
                return Err("live HTTP SSE response exceeded the test bound".to_string());
            }
            let mut chunk = [0_u8; 2048];
            let read = asupersync::time::timeout_at(deadline, stream.read(&mut chunk))
                .await
                .map_err(|_| live_http_test_timeout("live HTTP SSE response"))?
                .map_err(|error| format!("live HTTP SSE read failed: {error}"))?;
            if read == 0 {
                return Err("live HTTP SSE connection closed before expected event".to_string());
            }
            received.extend_from_slice(&chunk[..read]);
        }
        Ok(())
    }

    async fn read_live_http_to_end(
        stream: &mut AsyncTcpStream,
        received: &mut Vec<u8>,
        operation: &str,
    ) -> Result<(), String> {
        let cx = Cx::current()
            .expect("the test runtime must install an ambient Cx for live HTTP EOF reads");
        let deadline = cx.now().saturating_add_nanos(LIVE_HTTP_TEST_TIMEOUT_NANOS);
        asupersync::time::timeout_at(deadline, stream.read_to_end(received))
            .await
            .map_err(|_| live_http_test_timeout(operation))?
            .map_err(|error| format!("{operation} failed: {error}"))?;
        Ok(())
    }

    async fn open_live_legacy_http_session(
        address: SocketAddr,
        headers: &[(&str, &str)],
    ) -> Result<(AsyncTcpStream, String, Vec<u8>), String> {
        let cx = Cx::current()
            .expect("the test runtime must install an ambient Cx for legacy HTTP SSE setup");
        let deadline = cx.now().saturating_add_nanos(LIVE_HTTP_TEST_TIMEOUT_NANOS);
        let mut stream = asupersync::time::timeout_at(deadline, AsyncTcpStream::connect(address))
            .await
            .map_err(|_| live_http_test_timeout("legacy HTTP SSE connection"))?
            .map_err(|error| format!("legacy HTTP SSE connect failed: {error}"))?;
        let mut extra_headers = String::new();
        for (name, value) in headers {
            extra_headers.push_str(name);
            extra_headers.push_str(": ");
            extra_headers.push_str(value);
            extra_headers.push_str("\r\n");
        }
        let request = format!(
            "GET /sse HTTP/1.1\r\nHost: {address}\r\nAccept: text/event-stream\r\nConnection: keep-alive\r\n{extra_headers}\r\n"
        );
        asupersync::time::timeout_at(deadline, stream.write_all(request.as_bytes()))
            .await
            .map_err(|_| live_http_test_timeout("legacy HTTP SSE request write"))?
            .map_err(|error| format!("legacy HTTP SSE write failed: {error}"))?;
        asupersync::time::timeout_at(deadline, stream.flush())
            .await
            .map_err(|_| live_http_test_timeout("legacy HTTP SSE request flush"))?
            .map_err(|error| format!("legacy HTTP SSE flush failed: {error}"))?;

        let mut received = Vec::new();
        let endpoint_prefix = format!("data: http://{address}/messages?session_id=");
        read_live_http_until(&mut stream, &mut received, endpoint_prefix.as_bytes()).await?;
        let received_text = std::str::from_utf8(&received)
            .map_err(|error| format!("legacy HTTP SSE endpoint was not UTF-8: {error}"))?;
        let session_id = received_text
            .split_once(&endpoint_prefix)
            .and_then(|(_, remainder)| remainder.split_whitespace().next())
            .ok_or_else(|| "legacy HTTP SSE endpoint omitted its session identifier".to_string())?
            .to_owned();
        Ok((stream, session_id, received))
    }

    async fn wait_for_live_http_legacy_admission(
        cx: &Cx,
        session: &LiveHttpSession,
        request_id: &RequestId,
    ) -> Result<(), String> {
        let deadline = cx.now().saturating_add_nanos(LIVE_HTTP_TEST_TIMEOUT_NANOS);
        while !session.cancellation.admissions.contains(request_id) {
            cx.checkpoint()
                .map_err(|error| format!("legacy HTTP admission wait stopped: {error}"))?;
            asupersync::time::timeout_at(
                deadline,
                asupersync::time::sleep(cx.now(), Duration::from_millis(1)),
            )
            .await
            .map_err(|_| live_http_test_timeout("legacy HTTP request admission"))?;
        }
        Ok(())
    }

    fn reset_http_overlap_metrics() {
        let metrics = http_overlap_metrics();
        metrics.current.store(0, Ordering::SeqCst);
        metrics.max.store(0, Ordering::SeqCst);
    }

    fn test_request_sender() -> RequestSender {
        let pending = Arc::new(PendingRequests::new());
        let send_fn: bidirectional::TransportSendFn =
            Arc::new(|message| Err(format!("unexpected outbound message in test: {message:?}")));
        RequestSender::new(pending, send_fn)
    }

