    #[cfg(feature = "tasks")]
    #[test]
    fn configured_final_tasks_route_methods_and_typed_notifications() {
        let delivered = Arc::new(Mutex::new(Vec::new()));
        let (server, _service) = final_tasks_test_server(Arc::clone(&delivered));
        let runtime = server
            .final_task_runtime()
            .expect("configured final Tasks runtime must be retained");
        let task_id = runtime
            .create_task_with_work(
                final_tasks_test_work_descriptor(),
                Some("accepted".to_owned()),
            )
            .expect("application store must accept task before reply")
            .task
            .base()
            .task_id
            .clone();
        let notification = delivered
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .first()
            .cloned()
            .expect("durable task creation must route a typed notification");
        assert_eq!(
            serde_json::to_value(notification).expect("notification must serialize")["method"],
            fastmcp_protocol::TASK_STATUS_NOTIFICATION
        );

        let inbound =
            InboundRequestContext::new(Cx::for_testing(), 71, InboundRequestTransport::Memory);
        let get = block_on(server.dispatch_stateless(
            &inbound,
            &JsonRpcRequest::new(
                fastmcp_protocol::TASK_GET,
                Some(final_tasks_get_params(&task_id, serde_json::json!({}))),
                71_i64,
            ),
        ))
        .expect("tasks/get must respond");
        assert_eq!(
            get.result.as_ref().map(|result| &result["resultType"]),
            Some(&serde_json::json!("complete"))
        );
        assert_eq!(
            get.result.as_ref().map(|result| &result["taskId"]),
            Some(&serde_json::json!(task_id.as_str()))
        );

        let mut session = initialized_test_session(&server);
        let notification_sender: NotificationSender = Arc::new(|_| {});
        let session_get = block_on(server.dispatch_request(
            &Cx::for_testing(),
            &mut session,
            JsonRpcRequest::new(
                fastmcp_protocol::TASK_GET,
                Some(final_tasks_get_params(&task_id, serde_json::json!({}))),
                72_i64,
            ),
            &notification_sender,
            &test_request_sender(),
        ))
        .expect("session tasks/get must produce a JSON-RPC response");
        assert_eq!(
            session_get.result.as_ref().map(|result| &result["taskId"]),
            Some(&serde_json::json!(task_id.as_str())),
            "stdio/session dispatch must serve official tasks/get"
        );
        let missing = fastmcp_protocol::FinalTaskId::parse("missing-task-id-0001")
            .expect("planted missing task id");
        let session_missing = block_on(server.dispatch_request(
            &Cx::for_testing(),
            &mut session,
            JsonRpcRequest::new(
                fastmcp_protocol::TASK_GET,
                Some(final_tasks_get_params(&missing, serde_json::json!({}))),
                73_i64,
            ),
            &notification_sender,
            &test_request_sender(),
        ))
        .expect("session tasks/get of an unknown id must respond");
        let missing_error = session_missing
            .error
            .as_ref()
            .expect("unknown task id must fail");
        assert_ne!(
            missing_error.code,
            i32::from(McpErrorCode::MethodNotFound).into(),
            "unknown task id is not MethodNotFound after official Tasks is installed"
        );

        let mut requests = fastmcp_protocol::TaskInputRequests::new();
        requests.insert(
            "roots".to_owned(),
            serde_json::from_value(serde_json::json!({ "method": "roots/list" }))
                .expect("typed roots request"),
        );
        runtime
            .require_input(&task_id, requests, Some("awaiting roots".to_owned()))
            .expect("caller-owned supervisor can enter input_required");
        let mut update_params = final_tasks_params(&task_id, serde_json::json!({}));
        update_params
            .as_object_mut()
            .expect("final Tasks parameters are an object")
            .insert(
                "inputResponses".to_owned(),
                serde_json::json!({ "roots": { "roots": [] } }),
            );
        let update = block_on(server.dispatch_stateless(
            &inbound,
            &JsonRpcRequest::new(
                fastmcp_protocol::tasks_extension::TASK_UPDATE,
                Some(update_params),
                71_i64,
            ),
        ))
        .expect("tasks/update must respond");
        assert_eq!(
            update.result,
            Some(serde_json::json!({ "resultType": "complete" }))
        );

        let cancel = block_on(server.dispatch_stateless(
            &inbound,
            &JsonRpcRequest::new(
                fastmcp_protocol::TASK_CANCEL,
                Some(final_tasks_get_params(&task_id, serde_json::json!({}))),
                71_i64,
            ),
        ))
        .expect("tasks/cancel must respond");
        assert_eq!(
            cancel.result,
            Some(serde_json::json!({ "resultType": "complete" }))
        );
        assert!(matches!(
            runtime
                .get_task(&task_id)
                .expect("final cancellation must remain in application storage")
                .task,
            fastmcp_protocol::Task::Cancelled(_)
        ));
        assert!(
            !runtime
                .is_cancellation_requested(&task_id)
                .expect("terminal task has no outstanding cooperative intent")
        );
    }

