    // ── ActiveRequestGuard ──────────────────────────────────────────

    #[test]
    fn active_request_pending_activation_preserves_parent_and_sibling() {
        active_request_pending_case(None);
    }

    #[test]
    fn active_request_pending_cancel_before_activation_preserves_parent_and_sibling() {
        active_request_pending_case(Some(true));
    }

    #[test]
    fn active_request_pending_cancel_after_activation_preserves_parent_and_sibling() {
        active_request_pending_case(Some(false));
    }

    fn active_request_pending_case(cancel_before_activation: Option<bool>) {
        let runtime = RuntimeBuilder::current_thread()
            .build()
            .expect("ownership test runtime must initialize");
        let parent = runtime.request_cx_with_budget(Budget::INFINITE);
        let child = runtime.request_cx_with_budget(Budget::INFINITE);
        let sibling = runtime.request_cx_with_budget(Budget::INFINITE);
        let server = Server::new("pending-request-owner", "1.0.0").build();
        let cancellation = McpRequestCancellation::new();
        let guard = ActiveRequestGuard::try_reserve(
            Arc::clone(&server.active_requests),
            11,
            RequestId::Number(7),
            parent.region_id(),
            cancellation.clone(),
        )
        .expect("pending request should reserve its wire ID");
        let completion = Arc::clone(&guard.completion);
        assert_eq!(server.active_requests.lock().unwrap().len(), 1);
        assert!(!completion.is_done());
        assert!(
            ActiveRequestGuard::try_new(
                Arc::clone(&server.active_requests),
                11,
                RequestId::Integer("7e0".to_owned()),
                sibling.clone(),
            )
            .is_err(),
            "queued ownership must reject an equivalent duplicate without replacement"
        );
        if cancel_before_activation == Some(true) {
            server.cancel_active_requests(CancelKind::Shutdown, false);
        }
        assert_eq!(
            guard.activate(child.clone()),
            cancel_before_activation != Some(true)
        );
        if cancel_before_activation == Some(false) {
            server.cancel_active_requests(CancelKind::Shutdown, false);
        }
        assert_eq!(
            child.is_cancel_requested(),
            cancel_before_activation.is_some()
        );
        assert_eq!(
            cancellation.is_cancel_requested(),
            cancel_before_activation.is_some()
        );
        assert!(!parent.is_cancel_requested());
        assert!(!sibling.is_cancel_requested());
        assert!(!completion.is_done());
        assert_eq!(server.active_requests.lock().unwrap().len(), 1);
        drop(guard);
        assert!(completion.is_done());
        assert!(server.active_requests.lock().unwrap().is_empty());
        let replacement = ActiveRequestGuard::try_new(
            Arc::clone(&server.active_requests),
            11,
            RequestId::Number(7),
            sibling.clone(),
        )
        .expect("retirement must permit exact ID reuse");
        assert!(!replacement.cancellation().is_cancel_requested());
        assert!(!sibling.is_cancel_requested());
        drop(replacement);
        assert!(server.active_requests.lock().unwrap().is_empty());
    }

    #[test]
    fn active_request_guard_removes_on_drop() {
        let map = Arc::new(Mutex::new(HashMap::new()));
        let cx = Cx::for_testing();
        let id = RequestId::Number(1);
        {
            let _guard = ActiveRequestGuard::try_new(Arc::clone(&map), 11, id.clone(), cx)
                .expect("insert guard");
            assert_eq!(map.lock().unwrap().len(), 1);
        }
        // After drop, the entry should be removed
        assert_eq!(map.lock().unwrap().len(), 0);
    }

    #[test]
    fn active_request_guard_rejects_duplicate_request_id() {
        let map = Arc::new(Mutex::new(HashMap::new()));
        let first = ActiveRequestGuard::try_new(
            Arc::clone(&map),
            11,
            RequestId::Number(7),
            Cx::for_testing(),
        )
        .expect("first request should register");
        let duplicate = ActiveRequestGuard::try_new(
            Arc::clone(&map),
            11,
            RequestId::Integer("7e0".to_owned()),
            Cx::for_testing(),
        );
        assert!(
            duplicate.is_err(),
            "equivalent numeric active request IDs must be rejected"
        );
        drop(first);
        assert!(map.lock().unwrap().is_empty());
    }

    #[test]
    fn active_request_guard_allows_same_request_id_in_distinct_sessions() {
        let map = Arc::new(Mutex::new(HashMap::new()));
        let first = ActiveRequestGuard::try_new(
            Arc::clone(&map),
            11,
            RequestId::Number(7),
            Cx::for_testing(),
        )
        .expect("first session should register");
        let second = ActiveRequestGuard::try_new(
            Arc::clone(&map),
            12,
            RequestId::Number(7),
            Cx::for_testing(),
        )
        .expect("second session may reuse the same wire request id");
        assert_eq!(map.lock().unwrap().len(), 2);
        drop((first, second));
        assert!(map.lock().unwrap().is_empty());
    }

    #[test]
    fn cancellation_notification_is_bound_to_originating_session() {
        let server = Server::new("cancel-owner-test", "1.0.0").build();
        let first_cx = Cx::for_testing();
        let second_cx = Cx::for_testing();
        let request_id = RequestId::Number(7);
        let first = ActiveRequestGuard::try_new(
            Arc::clone(&server.active_requests),
            11,
            request_id.clone(),
            first_cx.clone(),
        )
        .expect("first session should register");
        let second = ActiveRequestGuard::try_new(
            Arc::clone(&server.active_requests),
            12,
            request_id.clone(),
            second_cx.clone(),
        )
        .expect("second session should register");
        let first_cancellation = first.cancellation();
        let second_cancellation = second.cancellation();

        server.handle_cancelled_notification(
            11,
            CancelledParams {
                request_id,
                reason: Some("owner requested cancellation".to_string()),
                meta: None,
            },
        );

        assert!(first_cancellation.is_cancel_requested());
        assert!(!second_cancellation.is_cancel_requested());
        assert!(!first_cx.is_cancel_requested());
        assert!(!second_cx.is_cancel_requested());
        drop((first, second));
    }

    #[test]
    fn cancelled_notification_does_not_block_the_receive_path() {
        let server = Server::new("nonblocking-cancellation-test", "1.0.0").build();
        let request_id = RequestId::Number(41);
        let guard = ActiveRequestGuard::try_new(
            Arc::clone(&server.active_requests),
            11,
            request_id.clone(),
            Cx::for_testing(),
        )
        .expect("request should register");
        let cancellation = guard.cancellation();

        server.handle_cancelled_notification(
            11,
            CancelledParams {
                request_id,
                reason: None,
                meta: None,
            },
        );

        // bd-mvpne: an `assert!(start.elapsed() < Duration::from_secs(1))` stood here and was
        // removed, with its `Instant::now()` binding. It ran AFTER the call it bounded, so a
        // genuine block never reached it -- it could not detect the defect its own message
        // named -- while still being able to fail because the machine was merely slow. The
        // two assertions below carry everything recoverable. Do not re-add a wall-clock
        // bound here; the property is structural, not temporal.
        assert!(cancellation.is_cancel_requested());
        assert!(!guard.completion.is_done());
    }

