    fn wait_for_dispatch_worker_failure(worker_failed: &AtomicBool) -> TransportError {
        let deadline = Instant::now() + Duration::from_secs(2);
        while !worker_failed.load(Ordering::Acquire) && Instant::now() < deadline {
            std::thread::sleep(Duration::from_millis(1));
        }
        if worker_failed.load(Ordering::Acquire) {
            TransportError::Cancelled
        } else {
            // Let the pump perform its normal stop-and-join cleanup. The
            // callback-entry assertion then fails the test without detaching
            // its worker thread through an unwind from inside `recv`.
            TransportError::Timeout
        }
    }

    #[test]
    fn dispatch_worker_send_failure_returns_failure_status() {
        let emitted = Arc::new(AtomicBool::new(false));
        let emitted_for_receive = Arc::clone(&emitted);
        let send_attempted = Arc::new(AtomicBool::new(false));
        let send_attempted_by_worker = Arc::clone(&send_attempted);
        let cx = Cx::for_testing();
        let exit_code = Server::new("worker-send-failure-test", "1.0.0")
            .build()
            .run_loop_pump(
                &cx,
                move |_receive_cx, worker_failed| {
                    if !emitted_for_receive.swap(true, Ordering::AcqRel) {
                        return Ok(JsonRpcMessage::Request(JsonRpcRequest::new(
                            "ping", None, 701_i64,
                        )));
                    }
                    Err(wait_for_dispatch_worker_failure(worker_failed))
                },
                move |_send_cx, _message| {
                    send_attempted_by_worker.store(true, Ordering::Release);
                    Err(TransportError::Io(std::io::Error::new(
                        std::io::ErrorKind::BrokenPipe,
                        "test response send failure",
                    )))
                },
                Arc::new(|_| {}),
                "test",
            );

        assert_eq!(exit_code, 1);
        assert!(send_attempted.load(Ordering::Acquire));
        assert!(!cx.is_cancel_requested());
    }

    #[test]
    fn reality_check_regression_worker_io_failure_wins_concurrent_clean_eof() {
        let emitted = Arc::new(AtomicBool::new(false));
        let emitted_for_receive = Arc::clone(&emitted);
        let send_entered = Arc::new(AtomicBool::new(false));
        let send_entered_for_receive = Arc::clone(&send_entered);
        let send_entered_by_worker = Arc::clone(&send_entered);

        let exit_code = Server::new("worker-send-eof-race-test", "1.0.0")
            .build()
            .run_loop_pump(
                &Cx::for_testing(),
                move |_receive_cx, _worker_failed| {
                    if !emitted_for_receive.swap(true, Ordering::AcqRel) {
                        return Ok(JsonRpcMessage::Request(JsonRpcRequest::new(
                            "ping", None, 706_i64,
                        )));
                    }
                    let deadline = Instant::now() + Duration::from_secs(2);
                    while !send_entered_for_receive.load(Ordering::Acquire)
                        && Instant::now() < deadline
                    {
                        std::thread::sleep(Duration::from_millis(1));
                    }
                    Err(TransportError::Closed)
                },
                move |send_cx, _message| {
                    send_entered_by_worker.store(true, Ordering::Release);
                    let deadline = Instant::now() + Duration::from_secs(2);
                    while send_cx.checkpoint().is_ok() && Instant::now() < deadline {
                        std::thread::sleep(Duration::from_millis(1));
                    }
                    Err(TransportError::Io(std::io::Error::new(
                        std::io::ErrorKind::BrokenPipe,
                        "test response failure after concurrent EOF",
                    )))
                },
                Arc::new(|_| {}),
                "test",
            );

        assert!(send_entered.load(Ordering::Acquire));
        assert_eq!(exit_code, 1);
    }

    #[test]
    fn dispatch_worker_panic_trips_failure_latch_and_returns_failure_status() {
        let emitted = Arc::new(AtomicBool::new(false));
        let emitted_for_receive = Arc::clone(&emitted);
        let send_entered = Arc::new(AtomicBool::new(false));
        let send_entered_by_worker = Arc::clone(&send_entered);
        let cx = Cx::for_testing();
        let exit_code = Server::new("worker-panic-latch-test", "1.0.0")
            .build()
            .run_loop_pump(
                &cx,
                move |_receive_cx, worker_failed| {
                    if !emitted_for_receive.swap(true, Ordering::AcqRel) {
                        return Ok(JsonRpcMessage::Request(JsonRpcRequest::new(
                            "ping", None, 702_i64,
                        )));
                    }
                    Err(wait_for_dispatch_worker_failure(worker_failed))
                },
                move |_send_cx, _message| -> Result<(), TransportError> {
                    send_entered_by_worker.store(true, Ordering::Release);
                    panic!("dispatch worker send callback panic")
                },
                Arc::new(|_| {}),
                "test",
            );

        assert_eq!(exit_code, 1);
        assert!(send_entered.load(Ordering::Acquire));
        assert!(!cx.is_cancel_requested());
    }

    #[test]
    fn stdio_pump_returns_failure_and_skips_hooks_for_non_quiescent_legacy_handler() {
        let control = Arc::new(NonQuiescentLegacyControl::default());
        let control_for_receive = Arc::clone(&control);
        let phase = Arc::new(AtomicUsize::new(0));
        let phase_for_receive = Arc::clone(&phase);
        let shutdown_called = Arc::new(AtomicBool::new(false));
        let shutdown_observer = Arc::clone(&shutdown_called);

        let server = Server::new("bounded-legacy-worker-shutdown-test", "1.0.0")
            .protocol_policy(ProtocolPolicy::Auto)
            .expect("Auto must be available to this test build")
            .tool(NonQuiescentLegacyTool {
                control: Arc::clone(&control),
            })
            .on_shutdown(move || shutdown_observer.store(true, Ordering::Release))
            .build();
        // The legacy dispatch worker also requires the caller-owned runtime
        // to admit its request child. A detached testing Cx rejects admission
        // before the deliberately non-cooperative handler can start.
        let runtime = RuntimeBuilder::current_thread()
            .with_reactor(create_reactor().expect("stdio pump reactor must initialize"))
            .blocking_threads(4, MAX_DISPATCH_QUEUE_DEPTH)
            .build()
            .expect("stdio pump runtime must initialize");
        let (sender, receiver) = sync_channel(1);
        runtime
            .handle()
            .try_spawn_with_cx(move |cx| async move {
                let dispatch_cx = cx.clone();
                let pump_sender = sender.clone();
                if let Err(error) = cx.spawn_blocking(move |pump_cx| {
                    let code = Arc::new(server).run_loop_pump_with_policy(
                        &pump_cx,
                        &dispatch_cx,
                        move |_receive_cx, _worker_failed| match phase_for_receive
                            .fetch_add(1, Ordering::AcqRel)
                        {
                            0 => Ok(exact_legacy_initialize_request(
                                705,
                                serde_json::json!("1.0.0"),
                            )),
                            1 => Ok(JsonRpcMessage::Request(JsonRpcRequest::notification(
                                "notifications/initialized",
                                None,
                            ))),
                            2 => Ok(JsonRpcMessage::Request(JsonRpcRequest::new(
                                "tools/call",
                                Some(serde_json::json!({
                                    "name": "non_quiescent_legacy_tool",
                                    "arguments": {},
                                })),
                                706_i64,
                            ))),
                            3 if control_for_receive.wait_for_started(Duration::from_secs(2)) => {
                                Err(TransportError::Closed)
                            }
                            3 => Err(TransportError::Timeout),
                            _ => Err(TransportError::Closed),
                        },
                        move |_send_cx, _message| Ok(()),
                        Arc::new(|_| {}),
                        "stdio-test",
                        true,
                        None,
                        true,
                        true,
                        None,
                        None,
                        None,
                        PumpIoMode::Split,
                    );
                    let _ = pump_sender.send(Ok(code));
                }) {
                    let _ = sender.send(Err(format!("stdio pump admission failed: {error}")));
                }
            })
            .expect("stdio pump task must be admitted");
        // The pump waits through bounded worker-shutdown windows before
        // detaching the non-quiescent legacy worker; poll its result without
        // joining the task while the handler is intentionally parked.
        let pump_result: Result<Result<i32, String>, String> = runtime.block_on(async {
            let cx = Cx::current().expect("the test runtime installs an ambient Cx");
            let deadline = cx.now().saturating_add_nanos(30_000_000_000);
            loop {
                match receiver.try_recv() {
                    Ok(result) => break Ok(result),
                    Err(TryRecvError::Disconnected) => {
                        break Err("stdio pump task exited without reporting its result".to_owned());
                    }
                    Err(TryRecvError::Empty) => {
                        if asupersync::time::timeout_at(
                            deadline,
                            asupersync::time::sleep(cx.now(), Duration::from_millis(5)),
                        )
                        .await
                        .is_err()
                        {
                            break Err("stdio pump did not settle within its bound".to_owned());
                        }
                    }
                }
            }
        });

        // Capture observations before releasing the parked legacy handler so
        // an assertion failure cannot strand the worker during runtime drop.
        let started = control.has_started();
        let finished_before_release = control.has_finished();
        let shutdown_before_release = shutdown_called.load(Ordering::Acquire);
        control.release();
        let finished_after_release = control.wait_for_finished(Duration::from_secs(2));

        let exit_code = pump_result
            .expect("stdio pump must report a result")
            .expect("stdio pump must complete");

        assert_eq!(exit_code, 1);
        assert!(started);
        assert!(!finished_before_release);
        assert!(!shutdown_before_release);
        assert!(finished_after_release);
    }

    #[test]
    fn returning_split_waits_for_non_quiescent_legacy_handler_before_owned_cleanup() {
        let control = Arc::new(NonQuiescentLegacyControl::default());
        let shutdown_called = Arc::new(AtomicBool::new(false));
        let shutdown_observer = Arc::clone(&shutdown_called);
        let release_control = Arc::clone(&control);
        let release_thread = std::thread::spawn(move || {
            let started = release_control.wait_for_started(Duration::from_secs(2));
            if started {
                std::thread::sleep(DISPATCH_WORKER_SHUTDOWN_TIMEOUT + Duration::from_millis(500));
            }
            // Always release before reporting a failed start observation. A
            // panic in this helper would otherwise strand the intentionally
            // non-cooperative handler and hang the entire test process.
            release_control.release();
            started
        });
        let started = Instant::now();
        let run_result = run_live_split_transport(
            Duration::from_nanos(LIVE_HTTP_TEST_TIMEOUT_NANOS),
            Server::new("returning-legacy-worker-shutdown-test", "1.0.0")
                .protocol_policy(ProtocolPolicy::Auto)
                .expect("Auto must be available to this test build")
                .tool(NonQuiescentLegacyTool {
                    control: Arc::clone(&control),
                })
                .on_shutdown(move || shutdown_observer.store(true, Ordering::Release))
                .build(),
            NonQuiescentLegacySplitRecv {
                phase: 0,
                control: Arc::clone(&control),
            },
            NonQuiescentLegacySplitSend,
        );
        let elapsed = started.elapsed();
        let release_observed_start = release_thread.join().expect("release thread must finish");

        assert!(
            release_observed_start,
            "legacy handler must start before its delayed release"
        );
        assert!(control.has_started());
        assert!(control.has_finished());
        assert!(elapsed >= DISPATCH_WORKER_SHUTDOWN_TIMEOUT);
        assert!(shutdown_called.load(Ordering::Acquire));
        assert!(run_result.is_err(), "worker timeout must remain a failure");
    }

    #[test]
    fn returning_split_waits_for_non_quiescent_modern_child_before_cleanup() {
        let control = Arc::new(NonQuiescentLegacyControl::default());
        let shutdown_called = Arc::new(AtomicBool::new(false));
        let shutdown_observer = Arc::clone(&shutdown_called);
        let release_control = Arc::clone(&control);
        let release_thread = std::thread::spawn(move || {
            let started = release_control.wait_for_started(Duration::from_secs(2));
            if started {
                std::thread::sleep(
                    DISPATCH_WORKER_SHUTDOWN_TIMEOUT * 2 + Duration::from_millis(500),
                );
            }
            // Preserve teardown even when the start observation misses its
            // bound. The assertion belongs after release so a failed harness
            // precondition cannot leave the runtime joining a parked child.
            release_control.release();
            started
        });
        let started = Instant::now();
        // The handler deliberately outlives both five-second product drain
        // windows. Include its two-second start bound and two seconds for
        // joined cleanup instead of expiring the harness before release.
        let completion_timeout = DISPATCH_WORKER_SHUTDOWN_TIMEOUT * 2
            + Duration::from_millis(500)
            + Duration::from_secs(2)
            + Duration::from_secs(2);
        let run_result = run_live_split_transport(
            completion_timeout,
            Server::new("returning-modern-worker-shutdown-test", "1.0.0")
                .protocol_policy(ProtocolPolicy::Auto)
                .expect("Auto must be available to this test build")
                .tool(NonQuiescentModernTool {
                    control: Arc::clone(&control),
                })
                .on_shutdown(move || shutdown_observer.store(true, Ordering::Release))
                .build(),
            NonQuiescentModernSplitRecv { phase: 0 },
            NonQuiescentLegacySplitSend,
        );
        let elapsed = started.elapsed();
        let release_observed_start = release_thread.join().expect("release thread must finish");

        assert!(
            release_observed_start,
            "modern child must start before its delayed release"
        );
        assert!(control.has_started());
        assert!(control.has_finished());
        assert!(elapsed >= DISPATCH_WORKER_SHUTDOWN_TIMEOUT);
        assert!(shutdown_called.load(Ordering::Acquire));
        assert!(
            run_result.is_err(),
            "modern worker timeout must remain a failure"
        );
        assert_eq!(
            run_result.as_ref().map_err(String::as_str),
            Err("[-32603] Server transport loop failed"),
            "the product must report its drain failure after cleanup; a harness timeout is not that failure"
        );
    }

    #[test]
    fn stdio_pump_returns_failure_and_skips_hooks_for_non_quiescent_modern_child() {
        let control = Arc::new(NonQuiescentLegacyControl::default());
        let shutdown_called = Arc::new(AtomicBool::new(false));
        let shutdown_observer = Arc::clone(&shutdown_called);
        let phase = Arc::new(AtomicUsize::new(0));
        let phase_for_receive = Arc::clone(&phase);
        let control_for_receive = Arc::clone(&control);
        let server = Server::new("stdio-modern-worker-shutdown-test", "1.0.0")
            .protocol_policy(ProtocolPolicy::Auto)
            .expect("Auto must be available to this test build")
            .tool(NonQuiescentModernTool {
                control: Arc::clone(&control),
            })
            .on_shutdown(move || shutdown_observer.store(true, Ordering::Release))
            .build();
        // The modern dispatch arm admits requests through spawn_blocking, so
        // the pump must run under a runtime with blocking threads; a bare
        // testing Cx rejects every modern dispatch before the tool starts.
        let runtime = RuntimeBuilder::current_thread()
            .with_reactor(create_reactor().expect("stdio pump reactor must initialize"))
            .blocking_threads(4, MAX_DISPATCH_QUEUE_DEPTH)
            .build()
            .expect("stdio pump runtime must initialize");
        let (sender, receiver) = sync_channel(1);
        runtime
            .handle()
            .try_spawn_with_cx(move |cx| async move {
                let dispatch_cx = cx.clone();
                let pump_sender = sender.clone();
                // The pump reports its exit code through the channel from the
                // blocking closure itself rather than via join(): joining the
                // pump task can park forever while the deliberately
                // non-quiescent modern child still occupies its blocking
                // thread, and the harness only needs the exit code.
                if let Err(error) = cx.spawn_blocking(move |pump_cx| {
                    let code = Arc::new(server).run_loop_pump_with_policy(
                        &pump_cx,
                        &dispatch_cx,
                        move |_receive_cx, _worker_failed| match phase_for_receive
                            .fetch_add(1, Ordering::AcqRel)
                        {
                            0 => Ok(modern_discovery_opening_request()),
                            1 => Ok(JsonRpcMessage::Request(JsonRpcRequest::new(
                                "tools/call",
                                Some(serde_json::json!({
                                    "name": "non_quiescent_modern_tool",
                                    "arguments": {},
                                    "_meta": {
                                        MODERN_PROTOCOL_VERSION_METADATA_KEY: MODERN_PROTOCOL_VERSION,
                                        FINAL_CLIENT_CAPABILITIES_META_KEY: {},
                                    },
                                })),
                                710_i64,
                            ))),
                            2 if control_for_receive.wait_for_started(Duration::from_secs(2)) => {
                                Err(TransportError::Closed)
                            }
                            2 => Err(TransportError::Timeout),
                            _ => Err(TransportError::Closed),
                        },
                        move |_send_cx, _message| Ok(()),
                        Arc::new(|_| {}),
                        "stdio-modern-test",
                        true,
                        None,
                        true,
                        true,
                        None,
                        None,
                        None,
                        PumpIoMode::Split,
                    );
                    let _ = pump_sender.send(Ok(code));
                }) {
                    let _ = sender.send(Err(format!("stdio pump admission failed: {error}")));
                }
            })
            .expect("stdio pump task must be admitted");
        // The pump legitimately holds several bounded worker-shutdown windows
        // (5s each) before detaching the non-quiescent child, so the result
        // wait must exceed their sum; the shared live-HTTP helper's 2s bound
        // is far too tight here.
        let pump_result: Result<Result<i32, String>, String> = runtime.block_on(async {
            let cx = Cx::current().expect("the test runtime installs an ambient Cx");
            let deadline = cx.now().saturating_add_nanos(30_000_000_000);
            loop {
                match receiver.try_recv() {
                    Ok(result) => break Ok(result),
                    Err(TryRecvError::Disconnected) => {
                        break Err("stdio pump task exited without reporting its result".to_owned());
                    }
                    Err(TryRecvError::Empty) => {
                        if asupersync::time::timeout_at(
                            deadline,
                            asupersync::time::sleep(cx.now(), Duration::from_millis(5)),
                        )
                        .await
                        .is_err()
                        {
                            break Err("stdio pump did not settle within its bound".to_owned());
                        }
                    }
                }
            }
        });

        // Capture the pre-release observations, then release the parked tool
        // BEFORE any panic: a failed assert (or a pump timeout) would
        // otherwise unwind into the runtime drop, which joins the
        // still-parked blocking thread forever.
        let started = control.has_started();
        let finished_before_release = control.has_finished();
        let shutdown_before_release = shutdown_called.load(Ordering::Acquire);
        control.release();
        let finished_after_release = control.wait_for_finished(Duration::from_secs(2));

        let exit_code = pump_result
            .expect("stdio pump must report a result")
            .expect("stdio pump must complete");
        assert_eq!(exit_code, 1);
        assert!(started);
        assert!(!finished_before_release);
        assert!(!shutdown_before_release);
        assert!(finished_after_release);
    }

    #[test]
    fn reality_check_regression_notification_failure_wins_concurrent_clean_eof() {
        let notification_failure = Arc::new(AtomicBool::new(false));
        let failure_from_receive = Arc::clone(&notification_failure);

        let cx = Cx::for_testing();
        let exit_code = Arc::new(Server::new("notification-eof-race-test", "1.0.0").build())
            .run_loop_pump_with_policy(
                &cx,
                &cx,
                move |_receive_cx, _worker_failed| {
                    // Model notification output failing immediately after a
                    // stop-aware receiver's final predicate check but before
                    // it returns the concurrently observed EOF.
                    failure_from_receive.store(true, Ordering::Release);
                    Err(TransportError::Closed)
                },
                move |_send_cx, _message| Ok(()),
                Arc::new(|_| {}),
                "stdio-test",
                true,
                Some(Arc::clone(&notification_failure)),
                false,
                true,
                None,
                None,
                None,
                PumpIoMode::Split,
            );

        assert!(notification_failure.load(Ordering::Acquire));
        assert_eq!(exit_code, 1);
    }

    #[cfg(unix)]
    #[test]
    fn reality_check_regression_dispatch_worker_send_failure_wakes_unix_stdio_receive() {
        use std::os::unix::net::UnixStream;

        let (mut peer, server_stream) =
            UnixStream::pair().expect("Unix stream fixture must be available");
        peer.write_all(b"{\"jsonrpc\":\"2.0\",\"method\":\"ping\",\"id\":703}\n")
            .expect("request fixture must reach the server stream");
        peer.flush().expect("request fixture must be flushed");

        let receive_calls = Arc::new(AtomicUsize::new(0));
        let receive_count = Arc::clone(&receive_calls);
        let receive_count_for_worker = Arc::clone(&receive_calls);
        let send_attempted = Arc::new(AtomicBool::new(false));
        let send_attempted_by_worker = Arc::clone(&send_attempted);
        let mut transport = StdioTransport::new(server_stream, Vec::<u8>::new());
        let cx = Cx::for_testing();
        let exit_code = cx.masked(|| {
            Server::new("unix-stdio-worker-failure-test", "1.0.0")
                .build()
                .run_loop_pump(
                    &cx,
                    move |receive_cx, worker_failed| {
                        receive_count.fetch_add(1, Ordering::AcqRel);
                        transport.recv_until_or_stopped(receive_cx, None, || {
                            worker_failed.load(Ordering::Acquire)
                        })
                    },
                    move |_send_cx, _message| {
                        let deadline = Instant::now() + Duration::from_secs(2);
                        while receive_count_for_worker.load(Ordering::Acquire) < 2
                            && Instant::now() < deadline
                        {
                            std::thread::sleep(Duration::from_millis(1));
                        }
                        send_attempted_by_worker.store(true, Ordering::Release);
                        Err(TransportError::Io(std::io::Error::new(
                            std::io::ErrorKind::BrokenPipe,
                            "test response send failure",
                        )))
                    },
                    Arc::new(|_| {}),
                    "stdio-test",
                )
        });

        assert_eq!(exit_code, 1);
        assert!(send_attempted.load(Ordering::Acquire));
        assert_eq!(receive_calls.load(Ordering::Acquire), 2);
    }

    #[derive(Clone, Copy)]
    enum ReturningProbeReceive {
        Closed,
        Cancelled,
        Timeout,
        PingThenClosed,
    }

