    async fn run_live_http_mrtr_retry(
        cx: &Cx,
        request_state_suffix: &str,
    ) -> Result<(JsonRpcResponse, JsonRpcResponse, usize), String> {
        let calls = Arc::new(AtomicUsize::new(0));
        let bound = Server::new("live-http-mrtr-retry", "1.0.0")
            .protocol_policy(ProtocolPolicy::ModernOnly)
            .expect("ModernOnly must be available to this test build")
            .auth_provider(auth_00_mrtr_provider(true))
            .tool(LiveHttpMrtrTool {
                name: "live_http_mrtr",
                calls: Arc::clone(&calls),
            })
            .build()
            .bind_http(cx, "127.0.0.1:0")
            .await
            .map_err(|error| format!("live HTTP MRTR retry bind failed: {error}"))?;
        let address = bound
            .local_addr()
            .map_err(|error| format!("live HTTP MRTR retry address failed: {error}"))?;
        let request_state_suffix = request_state_suffix.to_owned();
        let caller_cx = cx.clone();
        let mut client = cx
            .spawn(move |_client_cx| async move {
                let result = async {
                    let initial = JsonRpcRequest::new(
                        "tools/call",
                        Some(serde_json::json!({
                            "name": "live_http_mrtr",
                            "arguments": {},
                            "_meta": {
                                MODERN_PROTOCOL_VERSION_METADATA_KEY: MODERN_PROTOCOL_VERSION,
                                FINAL_CLIENT_CAPABILITIES_META_KEY: {},
                                "progressToken": "live-http-mrtr-sse",
                            },
                        })),
                        922_i64,
                    );
                    let initial_body = serde_json::to_vec(&initial).map_err(|error| {
                        format!("MRTR initial request did not serialize: {error}")
                    })?;
                    let initial = live_http_exchange(
                        address,
                        live_http_post(
                            "/mcp",
                            &initial_body,
                            &[
                                ("Accept", "text/event-stream"),
                                ("MCP-Protocol-Version", MODERN_PROTOCOL_VERSION),
                                ("Mcp-Method", "tools/call"),
                                ("Mcp-Name", "live_http_mrtr"),
                                ("Authorization", "Bearer alpha"),
                            ],
                        ),
                    )
                    .await?;
                    let initial = live_http_sse_jsonrpc_response(&initial)?;
                    let request_state = initial
                        .result
                        .as_ref()
                        .and_then(|result| result.get("requestState"))
                        .and_then(serde_json::Value::as_str)
                        .ok_or_else(|| {
                            "MRTR input-required response omitted requestState".to_owned()
                        })?;
                    let roots = serde_json::to_value(
                        bidirectional::MrtrInputResponse::roots(
                            fastmcp_protocol::ListRootsResult::empty(),
                        )
                        .map_err(|error| format!("MRTR roots response failed: {error}"))?,
                    )
                    .map_err(|error| format!("MRTR roots response did not serialize: {error}"))?;
                    // The retry leg reads its result from an ordinary JSON
                    // response; a progress token would demand an owned SSE
                    // body and turn this Accept into a 406.
                    let retry = JsonRpcRequest::new(
                        "tools/call",
                        Some(serde_json::json!({
                            "name": "live_http_mrtr",
                            "arguments": {},
                            "inputResponses": {"roots": roots},
                            "requestState": format!("{request_state}{request_state_suffix}"),
                            "_meta": {
                                MODERN_PROTOCOL_VERSION_METADATA_KEY: MODERN_PROTOCOL_VERSION,
                                FINAL_CLIENT_CAPABILITIES_META_KEY: {},
                            },
                        })),
                        923_i64,
                    );
                    let retry_body = serde_json::to_vec(&retry).map_err(|error| {
                        format!("MRTR retry request did not serialize: {error}")
                    })?;
                    let retry = live_http_exchange(
                        address,
                        live_http_post(
                            "/mcp",
                            &retry_body,
                            &[
                                ("Accept", "application/json"),
                                ("MCP-Protocol-Version", MODERN_PROTOCOL_VERSION),
                                ("Mcp-Method", "tools/call"),
                                ("Mcp-Name", "live_http_mrtr"),
                                ("Authorization", "Bearer alpha"),
                            ],
                        ),
                    )
                    .await?;
                    let retry = serde_json::from_slice(live_http_response_body(&retry)?).map_err(
                        |error| format!("MRTR retry response was not valid JSON-RPC: {error}"),
                    )?;
                    Ok::<_, String>((initial, retry))
                }
                .await;
                caller_cx.cancel_with(
                    CancelKind::User,
                    Some("live HTTP cross-POST MRTR retry complete"),
                );
                result
            })
            .map_err(|error| format!("live HTTP MRTR retry client admission failed: {error}"))?;

        let serve = bound.serve(cx).await;
        let (initial, retry) = client
            .join(cx)
            .await
            .map_err(|error| format!("live HTTP MRTR retry client failed: {error:?}"))??;
        let shutdown =
            serve.map_err(|error| format!("live HTTP MRTR retry server failed: {error}"))?;
        require_quiescent_http_shutdown(shutdown, "live HTTP MRTR retry").await?;
        Ok((initial, retry, calls.load(Ordering::Acquire)))
    }

    async fn run_live_http_public_final_sampling_json(
        cx: &Cx,
    ) -> Result<(JsonRpcResponse, usize), String> {
        let calls = Arc::new(AtomicUsize::new(0));
        let bound = Server::new("live-http-public-final-sampling", "1.0.0")
            .protocol_policy(ProtocolPolicy::ModernOnly)
            .expect("ModernOnly must be available to this test build")
            .auth_provider(auth_00_mrtr_provider(true))
            .tool(PublicFinalSamplingTool {
                calls: Arc::clone(&calls),
            })
            .build()
            .bind_http(cx, "127.0.0.1:0")
            .await
            .map_err(|error| format!("live HTTP public final sampling bind failed: {error}"))?;
        let address = bound
            .local_addr()
            .map_err(|error| format!("live HTTP public final sampling address failed: {error}"))?;
        let caller_cx = cx.clone();
        let mut client = cx
            .spawn(move |_client_cx| async move {
                let result = async {
                    let request = JsonRpcRequest::new(
                        "tools/call",
                        Some(serde_json::json!({
                            "name": "public-final-sampling",
                            "arguments": {},
                            "_meta": {
                                MODERN_PROTOCOL_VERSION_METADATA_KEY: MODERN_PROTOCOL_VERSION,
                                FINAL_CLIENT_CAPABILITIES_META_KEY: {"sampling": {}},
                            },
                        })),
                        940_i64,
                    );
                    let body = serde_json::to_vec(&request).map_err(|error| {
                        format!("public final sampling request did not serialize: {error}")
                    })?;
                    let response = live_http_exchange(
                        address,
                        live_http_post(
                            "/mcp",
                            &body,
                            &[
                                ("Accept", "application/json"),
                                ("MCP-Protocol-Version", MODERN_PROTOCOL_VERSION),
                                ("Mcp-Method", "tools/call"),
                                ("Mcp-Name", "public-final-sampling"),
                                ("Authorization", "Bearer alpha"),
                            ],
                        ),
                    )
                    .await?;
                    let response = serde_json::from_slice(live_http_response_body(&response)?)
                        .map_err(|error| {
                            format!(
                                "public final sampling response was not valid JSON-RPC: {error}"
                            )
                        })?;
                    Ok::<_, String>(response)
                }
                .await;
                caller_cx.cancel_with(
                    CancelKind::User,
                    Some("live HTTP public final sampling complete"),
                );
                result
            })
            .map_err(|error| {
                format!("live HTTP public final sampling client admission failed: {error}")
            })?;

        let serve = bound.serve(cx).await;
        let response = client.join(cx).await.map_err(|error| {
            format!("live HTTP public final sampling client failed: {error:?}")
        })??;
        let shutdown = serve
            .map_err(|error| format!("live HTTP public final sampling server failed: {error}"))?;
        require_quiescent_http_shutdown(shutdown, "live HTTP public final sampling").await?;
        Ok((response, calls.load(Ordering::Acquire)))
    }

    struct LiveLegacyCompletionHandler;

    impl CompletionHandler for LiveLegacyCompletionHandler {
        fn complete_legacy(
            &self,
            _ctx: &McpContext,
            params: LegacyCompletionParams,
        ) -> McpResult<CompletionValues> {
            Ok(CompletionValues {
                values: vec![format!("legacy:{}", params.argument.value)],
                total: Some(1),
                has_more: Some(false),
            })
        }

        fn complete_final(
            &self,
            _ctx: &McpContext,
            _params: FinalCompletionParams,
        ) -> McpResult<fastmcp_protocol::FinalCompletionValues> {
            Err(McpError::method_not_found("completion/complete"))
        }
    }

    struct CountingLegacyCompletionHandler {
        calls: Arc<AtomicUsize>,
    }

    impl CompletionHandler for CountingLegacyCompletionHandler {
        fn complete_legacy(
            &self,
            _ctx: &McpContext,
            params: LegacyCompletionParams,
        ) -> McpResult<CompletionValues> {
            self.calls.fetch_add(1, Ordering::AcqRel);
            Ok(CompletionValues {
                values: vec![format!("legacy:{}", params.argument.value)],
                total: Some(1),
                has_more: Some(false),
            })
        }

        fn complete_final(
            &self,
            _ctx: &McpContext,
            _params: FinalCompletionParams,
        ) -> McpResult<fastmcp_protocol::FinalCompletionValues> {
            Err(McpError::method_not_found("completion/complete"))
        }
    }

    struct LiveLegacyCancellationTool {
        started: Arc<AtomicBool>,
        observed_cancellation: Arc<AtomicBool>,
    }

    impl ToolHandler for LiveLegacyCancellationTool {
        fn definition(&self) -> Tool {
            Tool {
                name: "live_legacy_cancellation_tool".to_owned(),
                description: Some(
                    "Proves exact legacy cancellation reaches the live handler".to_owned(),
                ),
                input_schema: serde_json::json!({"type": "object"}),
                output_schema: None,
                icon: None,
                version: None,
                tags: Vec::new(),
                annotations: None,
            }
        }

        fn call(&self, ctx: &McpContext, _arguments: serde_json::Value) -> McpResult<Vec<Content>> {
            self.started.store(true, Ordering::Release);
            let deadline = Instant::now() + Duration::from_nanos(LIVE_HTTP_STEP_TIMEOUT_NANOS);
            while !ctx.is_cancelled() && Instant::now() < deadline {
                std::thread::yield_now();
            }
            if ctx.is_cancelled() {
                self.observed_cancellation.store(true, Ordering::Release);
                return Err(McpError::request_cancelled());
            }
            Err(McpError::internal_error(
                "exact legacy cancellation did not reach the live handler",
            ))
        }
    }

    struct LiveModernHttpPeerCancellationTool {
        started: Arc<AtomicBool>,
        release: Arc<AtomicBool>,
        observed_cancellation: Arc<AtomicBool>,
    }

    impl ToolHandler for LiveModernHttpPeerCancellationTool {
        fn definition(&self) -> Tool {
            Tool {
                name: "live_modern_http_peer_cancellation_tool".to_owned(),
                description: Some(
                    "Proves ordinary modern JSON peer close reaches only its handler".to_owned(),
                ),
                input_schema: serde_json::json!({"type": "object"}),
                output_schema: None,
                icon: None,
                version: None,
                tags: Vec::new(),
                annotations: None,
            }
        }

        fn call(&self, ctx: &McpContext, _arguments: serde_json::Value) -> McpResult<Vec<Content>> {
            self.started.store(true, Ordering::Release);
            let deadline = Instant::now() + Duration::from_nanos(LIVE_HTTP_STEP_TIMEOUT_NANOS);
            while !self.release.load(Ordering::Acquire)
                && !ctx.is_cancelled()
                && Instant::now() < deadline
            {
                std::thread::yield_now();
            }
            if ctx.is_cancelled() {
                self.observed_cancellation.store(true, Ordering::Release);
                return Err(McpError::request_cancelled());
            }
            if !self.release.load(Ordering::Acquire) {
                return Err(McpError::internal_error(
                    "ordinary modern JSON peer cancellation did not reach the handler",
                ));
            }
            Ok(vec![Content::text(
                "ordinary modern JSON request completed",
            )])
        }
    }

    struct LiveHttpShutdownTool {
        name: &'static str,
        cooperate_with_cancellation: bool,
        started: Arc<AtomicBool>,
        cancellation_observed: Arc<AtomicBool>,
        release: Arc<AtomicBool>,
        finished: Arc<AtomicBool>,
    }

    impl ToolHandler for LiveHttpShutdownTool {
        fn definition(&self) -> Tool {
            Tool {
                name: self.name.to_owned(),
                description: Some(
                    "Proves live HTTP shutdown ownership for a synchronous handler".to_owned(),
                ),
                input_schema: serde_json::json!({"type": "object"}),
                output_schema: None,
                icon: None,
                version: None,
                tags: Vec::new(),
                annotations: None,
            }
        }

        fn call(&self, ctx: &McpContext, _arguments: serde_json::Value) -> McpResult<Vec<Content>> {
            self.started.store(true, Ordering::Release);
            loop {
                if ctx.is_cancelled() {
                    self.cancellation_observed.store(true, Ordering::Release);
                    if self.cooperate_with_cancellation {
                        self.finished.store(true, Ordering::Release);
                        return Err(McpError::request_cancelled());
                    }
                }
                if self.release.load(Ordering::Acquire) {
                    self.finished.store(true, Ordering::Release);
                    return Ok(Vec::new());
                }
                thread::yield_now();
                thread::sleep(Duration::from_millis(1));
            }
        }
    }

    #[derive(Default)]
    struct LiveLegacyRequestGate {
        entered: AtomicBool,
        released: AtomicBool,
    }

    impl LiveLegacyRequestGate {
        fn enter(&self, ctx: &McpContext) -> McpResult<()> {
            self.entered.store(true, Ordering::Release);
            let deadline = Instant::now() + Duration::from_nanos(LIVE_HTTP_STEP_TIMEOUT_NANOS);
            while !self.released.load(Ordering::Acquire) && Instant::now() < deadline {
                if ctx.is_cancelled() {
                    return Err(McpError::request_cancelled());
                }
                thread::yield_now();
                thread::sleep(Duration::from_millis(1));
            }
            if self.released.load(Ordering::Acquire) {
                Ok(())
            } else {
                Err(McpError::internal_error(
                    "bounded legacy HTTP request gate was not released",
                ))
            }
        }

        fn release(&self) {
            self.released.store(true, Ordering::Release);
        }
    }

