    #[derive(Default)]
    struct NonQuiescentLegacyState {
        started: bool,
        released: bool,
        finished: bool,
    }

    #[derive(Default)]
    struct NonQuiescentLegacyControl {
        state: Mutex<NonQuiescentLegacyState>,
        changed: Condvar,
    }

    impl NonQuiescentLegacyControl {
        fn wait_until_released(&self) {
            let state = self
                .state
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            let mut state = state;
            state.started = true;
            self.changed.notify_all();
            let mut state = self
                .changed
                .wait_while(state, |state| !state.released)
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            state.finished = true;
            self.changed.notify_all();
        }

        fn wait_for_started(&self, timeout: Duration) -> bool {
            let state = self
                .state
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            let (state, _) = self
                .changed
                .wait_timeout_while(state, timeout, |state| !state.started)
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            state.started
        }

        fn has_started(&self) -> bool {
            self.state
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .started
        }

        fn has_finished(&self) -> bool {
            self.state
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .finished
        }

        fn release(&self) {
            let mut state = self
                .state
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            state.released = true;
            self.changed.notify_all();
        }

        fn wait_for_finished(&self, timeout: Duration) -> bool {
            let state = self
                .state
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            let (state, _) = self
                .changed
                .wait_timeout_while(state, timeout, |state| !state.finished)
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            state.finished
        }
    }

