    #[derive(Default)]
    struct LiveModernControlState {
        active: usize,
        max_active: usize,
        started: HashSet<u64>,
        cancelled: HashSet<u64>,
        released: HashSet<u64>,
        release_all: bool,
    }

    #[derive(Default)]
    struct LiveModernControl {
        state: Mutex<LiveModernControlState>,
        changed: Condvar,
        shutdown_requested: AtomicBool,
        shutdown_cx: Mutex<Option<Cx>>,
    }

    impl LiveModernControl {
        fn call(&self, ctx: &McpContext) -> McpResult<Vec<Content>> {
            let request_id = ctx.request_id();
            let mut state = self
                .state
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            state.active += 1;
            state.max_active = state.max_active.max(state.active);
            state.started.insert(request_id);
            self.changed.notify_all();

            loop {
                if ctx.is_cancelled() {
                    state.active = state.active.saturating_sub(1);
                    state.cancelled.insert(request_id);
                    self.changed.notify_all();
                    return Err(McpError::request_cancelled());
                }
                if state.release_all || state.released.contains(&request_id) {
                    state.active = state.active.saturating_sub(1);
                    self.changed.notify_all();
                    return Ok(vec![Content::text(format!("modern request {request_id}"))]);
                }
                let (next, _) = self
                    .changed
                    .wait_timeout(state, Duration::from_millis(1))
                    .unwrap_or_else(std::sync::PoisonError::into_inner);
                state = next;
            }
        }

        fn wait_for_started(&self, count: usize, timeout: Duration) -> bool {
            let state = self
                .state
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            let (state, _) = self
                .changed
                .wait_timeout_while(state, timeout, |state| state.started.len() < count)
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            state.started.len() >= count
        }

        fn has_started(&self, request_id: u64) -> bool {
            self.state
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .started
                .contains(&request_id)
        }

        fn wait_for_cancellation(&self, request_id: u64, timeout: Duration) -> bool {
            let state = self
                .state
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            let (state, _) = self
                .changed
                .wait_timeout_while(state, timeout, |state| {
                    !state.cancelled.contains(&request_id)
                })
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            state.cancelled.contains(&request_id)
        }

        fn release(&self, request_id: u64) {
            let mut state = self
                .state
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            state.released.insert(request_id);
            self.changed.notify_all();
        }

        fn request_shutdown(&self) {
            self.shutdown_requested.store(true, Ordering::Release);
            self.changed.notify_all();
        }

        fn install_shutdown_cx(&self, cx: Cx) {
            *self
                .shutdown_cx
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner) = Some(cx);
        }

        fn apply_shutdown(&self) {
            if let Some(cx) = self
                .shutdown_cx
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .as_ref()
                .cloned()
            {
                cx.cancel_with(
                    CancelKind::Shutdown,
                    Some("controlled modern tool requested server shutdown"),
                );
            }
        }

        fn release_all(&self) {
            let mut state = self
                .state
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            state.release_all = true;
            self.changed.notify_all();
        }

        fn max_active(&self) -> usize {
            self.state
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .max_active
        }

        fn was_cancelled(&self, request_id: u64) -> bool {
            self.state
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .cancelled
                .contains(&request_id)
        }
    }

    struct LiveModernControlledTool {
        control: Arc<LiveModernControl>,
    }

    impl ToolHandler for LiveModernControlledTool {
        fn definition(&self) -> Tool {
            Tool {
                name: "live_modern_controlled_tool".to_owned(),
                description: Some("Deterministic live modern dispatcher probe".to_owned()),
                input_schema: serde_json::json!({"type": "object"}),
                output_schema: None,
                icon: None,
                version: None,
                tags: Vec::new(),
                annotations: None,
            }
        }

        fn call(&self, ctx: &McpContext, _arguments: serde_json::Value) -> McpResult<Vec<Content>> {
            report_final_progress_probe_updates(ctx);
            self.control.call(ctx)
        }

        // The request-owned modern dispatch polls this handler on the
        // runtime's async worker, so a controlled tool that parks must be
        // COOPERATIVE: a synchronous condvar wait inside poll would
        // monopolize the single current_thread worker and starve every other
        // request-owned task (the exact strand the overlap tests then
        // misreport as lost dispatches).
        fn call_final_outcome_async_in_request<'a>(
            &'a self,
            ctx: &'a McpContext,
            request_cx: &'a Cx,
            _arguments: serde_json::Value,
        ) -> BoxFuture<'a, fastmcp_core::McpOutcome<FinalToolOutcome>> {
            // Cancellation may drop the pending future before another body poll.
            struct ActiveCallGuard<'ctx> {
                control: &'ctx LiveModernControl,
                ctx: &'ctx McpContext,
                request_cx: &'ctx Cx,
                request_id: u64,
                cancellation_observed: bool,
            }

            impl Drop for ActiveCallGuard<'_> {
                fn drop(&mut self) {
                    let mut state = self
                        .control
                        .state
                        .lock()
                        .unwrap_or_else(std::sync::PoisonError::into_inner);
                    state.active = state.active.saturating_sub(1);
                    if self.cancellation_observed
                        || self.ctx.request_cancellation().is_cancel_requested()
                        || self.request_cx.is_cancel_requested()
                        || self.control.shutdown_requested.load(Ordering::Acquire)
                    {
                        state.cancelled.insert(self.request_id);
                    }
                    self.control.changed.notify_all();
                }
            }

            Box::pin(async move {
                report_final_progress_probe_updates(ctx);
                let request_id = ctx.request_id();
                {
                    let mut state = self
                        .control
                        .state
                        .lock()
                        .unwrap_or_else(std::sync::PoisonError::into_inner);
                    state.active += 1;
                    state.max_active = state.max_active.max(state.active);
                    state.started.insert(request_id);
                    self.control.changed.notify_all();
                }
                let mut active_call = ActiveCallGuard {
                    control: &self.control,
                    ctx,
                    request_cx,
                    request_id,
                    cancellation_observed: false,
                };
                loop {
                    if self.control.shutdown_requested.load(Ordering::Acquire) {
                        self.control.apply_shutdown();
                        return fastmcp_core::Outcome::Cancelled(asupersync::CancelReason::user(
                            "controlled modern tool released for server shutdown",
                        ));
                    }
                    if ctx.checkpoint().is_err() || request_cx.is_cancel_requested() {
                        active_call.cancellation_observed = true;
                        return fastmcp_core::Outcome::Cancelled(asupersync::CancelReason::user(
                            "request cancellation observed by controlled modern tool",
                        ));
                    }
                    {
                        let state = self
                            .control
                            .state
                            .lock()
                            .unwrap_or_else(std::sync::PoisonError::into_inner);
                        if state.release_all || state.released.contains(&request_id) {
                            drop(state);
                            return match crate::handler::promote_legacy_tool_content(vec![
                                Content::text(format!("modern request {request_id}")),
                            ]) {
                                Ok(result) => {
                                    fastmcp_core::Outcome::Ok(FinalToolOutcome::Complete(result))
                                }
                                Err(error) => fastmcp_core::Outcome::Err(error),
                            };
                        }
                    }
                    // A fair yield keeps this cooperative: spawned task
                    // timers do not fire while the harness main thread owns
                    // block_on (a timer park would freeze the tool forever),
                    // and a hand-rolled immediate self-wake can starve
                    // sibling tasks of the runtime.
                    asupersync::runtime::yield_now().await;
                }
            })
        }
    }

