    #[derive(Default)]
    struct LiveModernNotificationControl {
        started: Mutex<bool>,
        cancelled: AtomicBool,
        changed: Condvar,
    }

    impl LiveModernNotificationControl {
        fn wait_for_started(&self, timeout: Duration) -> bool {
            let started = self
                .started
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            let (started, _) = self
                .changed
                .wait_timeout_while(started, timeout, |started| !*started)
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            *started
        }

        fn was_cancelled(&self) -> bool {
            self.cancelled.load(Ordering::Acquire)
        }
    }

    struct LiveModernBlockingNotificationMiddleware {
        control: Arc<LiveModernNotificationControl>,
    }

    impl Middleware for LiveModernBlockingNotificationMiddleware {
        fn on_request(
            &self,
            ctx: &McpContext,
            request: &JsonRpcRequest,
        ) -> McpResult<MiddlewareDecision> {
            if request.method != "notifications/initialized" {
                return Ok(MiddlewareDecision::Continue);
            }
            {
                let mut started = self
                    .control
                    .started
                    .lock()
                    .unwrap_or_else(std::sync::PoisonError::into_inner);
                *started = true;
                self.control.changed.notify_all();
            }
            let deadline = Instant::now() + Duration::from_secs(1);
            while !ctx.is_cancelled() && Instant::now() < deadline {
                std::thread::yield_now();
            }
            if ctx.is_cancelled() {
                self.control.cancelled.store(true, Ordering::Release);
                return Err(McpError::request_cancelled());
            }
            Err(McpError::internal_error(
                "modern notification did not receive shutdown cancellation",
            ))
        }
    }

    #[derive(Default)]
    struct LiveModernResponses {
        messages: Mutex<Vec<JsonRpcMessage>>,
        changed: Condvar,
    }

    impl LiveModernResponses {
        fn record(&self, message: JsonRpcMessage) {
            let mut messages = self
                .messages
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            messages.push(message);
            self.changed.notify_all();
        }

        fn response_count(&self, id: i64) -> usize {
            self.messages
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .iter()
                .filter(|message| {
                    matches!(message, JsonRpcMessage::Response(response) if response.id == Some(id.into()))
                })
                .count()
        }

        fn response(&self, id: i64) -> Option<JsonRpcResponse> {
            self.messages
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .iter()
                .find_map(|message| match message {
                    JsonRpcMessage::Response(response) if response.id == Some(id.into()) => {
                        Some(response.clone())
                    }
                    _ => None,
                })
        }

        fn messages(&self) -> Vec<JsonRpcMessage> {
            self.messages
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .clone()
        }

        fn wait_for_notification(&self, method: &str, timeout: Duration) -> bool {
            let messages = self
                .messages
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            let (messages, _) = self
                .changed
                .wait_timeout_while(messages, timeout, |messages| {
                    !messages.iter().any(|message| {
                        matches!(message, JsonRpcMessage::Request(request) if request.method == method)
                    })
                })
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            messages.iter().any(|message| {
                matches!(message, JsonRpcMessage::Request(request) if request.method == method)
            })
        }

        fn wait_for_responses(&self, ids: &[i64], timeout: Duration) -> bool {
            let messages = self
                .messages
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            let (messages, _) = self
                .changed
                .wait_timeout_while(messages, timeout, |messages| {
                    ids.iter().any(|id| {
                        !messages.iter().any(|message| {
                            matches!(message, JsonRpcMessage::Response(response) if response.id == Some((*id).into()))
                        })
                    })
                })
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            ids.iter().all(|id| {
                messages.iter().any(|message| {
                    matches!(message, JsonRpcMessage::Response(response) if response.id == Some((*id).into()))
                })
            })
        }
    }

    #[derive(Default)]
    struct BoundedTestSignal {
        raised: Mutex<bool>,
        changed: Condvar,
    }

    impl BoundedTestSignal {
        fn raise(&self) {
            let mut raised = self
                .raised
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            *raised = true;
            self.changed.notify_all();
        }

        fn wait(&self, timeout: Duration) -> bool {
            let raised = self
                .raised
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            let (raised, _) = self
                .changed
                .wait_timeout_while(raised, timeout, |raised| !*raised)
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            *raised
        }
    }

    struct LiveModernSplitRecv {
        phase: usize,
        control: Arc<LiveModernControl>,
        responses: Arc<LiveModernResponses>,
    }

    impl TransportRecvHalf for LiveModernSplitRecv {
        fn recv(&mut self, _cx: &Cx) -> Result<JsonRpcMessage, TransportError> {
            let phase = self.phase;
            self.phase = self.phase.saturating_add(1);
            match phase {
                0 => Ok(modern_discovery_opening_request()),
                1 => Ok(modern_controlled_tool_request(1200)),
                2 => {
                    if self.control.wait_for_started(1, Duration::from_secs(2)) {
                        Ok(modern_controlled_tool_request(1201))
                    } else {
                        Err(TransportError::Timeout)
                    }
                }
                3 => {
                    if !self.control.wait_for_started(2, Duration::from_secs(2)) {
                        return Err(TransportError::Timeout);
                    }
                    self.control.release(1200);
                    self.control.release(1201);
                    if self
                        .responses
                        .wait_for_responses(&[1200, 1201], Duration::from_secs(2))
                    {
                        Err(TransportError::Closed)
                    } else {
                        Err(TransportError::Timeout)
                    }
                }
                _ => Err(TransportError::Closed),
            }
        }

        fn close(&mut self, _cx: &Cx) -> Result<(), TransportError> {
            Ok(())
        }
    }

