    impl Transport for ReturningProbeTransport {
        fn send(&mut self, _cx: &Cx, _message: &JsonRpcMessage) -> Result<(), TransportError> {
            if self.fail_send {
                Err(TransportError::Io(std::io::Error::new(
                    std::io::ErrorKind::BrokenPipe,
                    "test returning-transport send failure",
                )))
            } else {
                Ok(())
            }
        }

        fn recv(&mut self, _cx: &Cx) -> Result<JsonRpcMessage, TransportError> {
            match self.receive {
                ReturningProbeReceive::Closed => Err(TransportError::Closed),
                ReturningProbeReceive::Cancelled => Err(TransportError::Cancelled),
                ReturningProbeReceive::Timeout => Err(TransportError::Timeout),
                ReturningProbeReceive::PingThenClosed => {
                    self.receive = ReturningProbeReceive::Closed;
                    Ok(JsonRpcMessage::Request(JsonRpcRequest::new(
                        "ping", None, 704_i64,
                    )))
                }
            }
        }

        fn close(&mut self, _cx: &Cx) -> Result<(), TransportError> {
            self.close_calls.fetch_add(1, Ordering::AcqRel);
            if self.fail_close {
                Err(TransportError::Io(std::io::Error::new(
                    std::io::ErrorKind::BrokenPipe,
                    "test returning-transport close failure",
                )))
            } else {
                Ok(())
            }
        }
    }

    impl Transport for SharedTransportCountingTransport {
        fn send(&mut self, _cx: &Cx, _message: &JsonRpcMessage) -> Result<(), TransportError> {
            self.send_calls.fetch_add(1, Ordering::AcqRel);
            Ok(())
        }

        fn recv(&mut self, _cx: &Cx) -> Result<JsonRpcMessage, TransportError> {
            self.recv_calls.fetch_add(1, Ordering::AcqRel);
            Err(TransportError::Closed)
        }

        fn close(&mut self, _cx: &Cx) -> Result<(), TransportError> {
            self.close_calls.fetch_add(1, Ordering::AcqRel);
            if self.fail_close {
                Err(TransportError::Io(std::io::Error::other(
                    "counting transport close failure",
                )))
            } else {
                Ok(())
            }
        }
    }

    impl Transport for ProtocolPolicyProbeTransport {
        fn send(&mut self, _cx: &Cx, message: &JsonRpcMessage) -> Result<(), TransportError> {
            self.sent
                .lock()
                .expect("protocol-policy test sent-message mutex must not be poisoned")
                .push(message.clone());
            Ok(())
        }

        fn recv(&mut self, _cx: &Cx) -> Result<JsonRpcMessage, TransportError> {
            self.receive_calls.fetch_add(1, Ordering::AcqRel);
            self.next.take().ok_or(TransportError::Closed)
        }

        fn close(&mut self, _cx: &Cx) -> Result<(), TransportError> {
            Ok(())
        }
    }

    impl Transport for ProtocolPolicyScriptTransport {
        fn send(&mut self, _cx: &Cx, message: &JsonRpcMessage) -> Result<(), TransportError> {
            self.sent
                .lock()
                .expect("protocol-policy test sent-message mutex must not be poisoned")
                .push(message.clone());
            Ok(())
        }

        fn recv(&mut self, _cx: &Cx) -> Result<JsonRpcMessage, TransportError> {
            self.receive_calls.fetch_add(1, Ordering::AcqRel);
            self.inbound.pop_front().ok_or(TransportError::Closed)
        }

        fn close(&mut self, _cx: &Cx) -> Result<(), TransportError> {
            Ok(())
        }
    }

