    #[test]
    fn public_split_transport_legacy_runtime_rejects_sampling_when_only_capability_is_removed() {
        let sent = live_legacy_runtime_connection_transcript(false);

        assert!(
            !sent.iter().any(|message| {
                matches!(message, JsonRpcMessage::Request(request) if request.method == "sampling/createMessage")
            }),
            "removing only the advertised sampling capability must prevent a reverse request"
        );
        assert_eq!(
            sent.iter()
                .filter(|message| {
                    matches!(message, JsonRpcMessage::Request(request) if request.method == "notifications/progress")
                })
                .count(),
            2,
            "the negative must retain the same connection state and notification path"
        );

        let rejected = sent.iter().find_map(|message| match message {
            JsonRpcMessage::Response(response) if response.id == Some(703_i64.into()) => {
                Some(response)
            }
            _ => None,
        });
        let rejected_result = rejected
            .and_then(|response| response.result.as_ref())
            .expect("the tool-level sampling refusal must use a legacy tools/call result");
        assert_eq!(
            rejected_result.get("isError"),
            Some(&serde_json::json!(true))
        );
        assert!(
            rejected_result
                .get("content")
                .and_then(serde_json::Value::as_array)
                .and_then(|content| content.first())
                .and_then(|content| content.get("text"))
                .and_then(serde_json::Value::as_str)
                .is_some_and(|message| message.contains("Sampling not available")),
            "the otherwise identical handler call must fail at the advertised-capability gate"
        );

        let second = sent.iter().find_map(|message| match message {
            JsonRpcMessage::Response(response) if response.id == Some(704_i64.into()) => {
                response.result.as_ref()
            }
            _ => None,
        });
        assert_eq!(
            second
                .and_then(|result| result["content"].as_array())
                .and_then(|content| content.first())
                .and_then(|content| content["text"].as_str()),
            Some("legacy-runtime-2-without-sampling"),
            "removing only sampling capability must not replace the retained SessionState"
        );
    }

    #[test]
    fn live_runtime_rejects_only_non_object_legacy_tool_arguments_without_advancing_lifecycle() {
        let sent = Arc::new(Mutex::new(Vec::new()));

        run_returning_transport_with_test_runtime(
            Server::new("live-legacy-runtime-negative", "1.0.0")
                .protocol_policy(ProtocolPolicy::Auto)
                .expect("Auto must be available to this test build")
                .tool(LiveRuntimeListedTool)
                .build(),
            ProtocolPolicyScriptTransport {
                inbound: std::collections::VecDeque::from([
                    exact_legacy_initialize_request(51, serde_json::json!("1.0.0")),
                    JsonRpcMessage::Request(JsonRpcRequest::notification(
                        "notifications/initialized",
                        None,
                    )),
                    JsonRpcMessage::Request(JsonRpcRequest::new(
                        "tools/call",
                        Some(serde_json::json!({
                            "name": "live_runtime_listed_tool",
                            "arguments": [],
                        })),
                        52_i64,
                    )),
                    JsonRpcMessage::Request(JsonRpcRequest::new(
                        "tools/call",
                        Some(serde_json::json!({
                            "name": "live_runtime_listed_tool",
                            "arguments": {},
                        })),
                        53_i64,
                    )),
                ]),
                sent: Arc::clone(&sent),
                receive_calls: Arc::new(AtomicUsize::new(0)),
            },
        )
        .expect("only the changed invalid arguments field must be rejected");

        let sent = sent
            .lock()
            .expect("protocol-policy test sent-message mutex must not be poisoned");
        let [
            JsonRpcMessage::Response(initialize),
            JsonRpcMessage::Response(rejected),
            JsonRpcMessage::Response(call),
        ] = sent.as_slice()
        else {
            panic!(
                "a rejected tools/call must leave the exact lifecycle ready for the unchanged valid call"
            );
        };
        assert_eq!(initialize.id, Some(51_i64.into()));
        assert_eq!(
            initialize
                .result
                .as_ref()
                .and_then(|result| result["protocolVersion"].as_str()),
            Some(LEGACY_PROTOCOL_VERSION)
        );
        assert_eq!(rejected.id, Some(52_i64.into()));
        assert_eq!(
            rejected
                .error
                .as_ref()
                .and_then(|error| error.code.as_i32()),
            Some(-32602)
        );
        assert_eq!(call.id, Some(53_i64.into()));
        assert_eq!(
            call.result
                .as_ref()
                .and_then(|result| result["content"].as_array())
                .and_then(|content| content.first())
                .and_then(|content| content["text"].as_str()),
            Some("live runtime legacy adapter request 53")
        );
        assert!(
            call.result
                .as_ref()
                .is_some_and(|result| result.get("resultType").is_none())
        );
    }

