    #[test]
    fn live_http_loopback_dispatches_modern_json_over_a_real_socket() {
        run_live_http_test(|cx| async move {
            let bound = Server::new("live-modern-http", "1.0.0")
                .build()
                .bind_http(&cx, "127.0.0.1:0")
                .await
                .map_err(|error| format!("live modern HTTP bind failed: {error}"))?;
            let address = bound
                .local_addr()
                .map_err(|error| format!("live modern HTTP address failed: {error}"))?;
            let caller_cx = cx.clone();
            let request = JsonRpcRequest::new(
                SERVER_DISCOVER_METHOD,
                Some(serde_json::json!({
                    "_meta": {
                        MODERN_PROTOCOL_VERSION_METADATA_KEY: MODERN_PROTOCOL_VERSION,
                        FINAL_CLIENT_CAPABILITIES_META_KEY: {},
                    },
                })),
                801_i64,
            );
            let body = serde_json::to_vec(&request)
                .map_err(|error| format!("modern wire request did not serialize: {error}"))?;
            let request = live_http_post(
                "/mcp",
                &body,
                &[
                    ("Accept", "application/json"),
                    ("MCP-Protocol-Version", MODERN_PROTOCOL_VERSION),
                    ("Mcp-Method", SERVER_DISCOVER_METHOD),
                ],
            );
            let mut client = cx
                .spawn(move |_client_cx| async move {
                    let response = live_http_exchange(address, request).await;
                    caller_cx.cancel_with(CancelKind::User, Some("modern loopback complete"));
                    response
                })
                .map_err(|error| format!("modern loopback client admission failed: {error}"))?;

            let serve = bound.serve(&cx).await;
            let response = client
                .join(&cx)
                .await
                .map_err(|error| format!("modern loopback client failed: {error:?}"))??;
            let shutdown =
                serve.map_err(|error| format!("modern loopback server failed: {error}"))?;
            require_quiescent_http_shutdown(shutdown, "modern loopback").await?;

            let response = std::str::from_utf8(&response)
                .map_err(|error| format!("modern loopback response was not UTF-8: {error}"))?;
            if !response.starts_with("HTTP/1.1 200") {
                return Err(format!(
                    "modern loopback response status was unexpected: {response}"
                ));
            }
            if !response
                .to_ascii_lowercase()
                .contains("\r\nconnection: close\r\n")
            {
                return Err(format!(
                    "single-request HTTP response did not declare connection closure: {response}"
                ));
            }
            if live_http_response_header(response.as_bytes(), "mcp-session-id").is_ok() {
                return Err("modern discovery response issued MCP-Session-Id".to_owned());
            }
            let response: JsonRpcResponse = serde_json::from_slice(live_http_response_body(
                response.as_bytes(),
            )?)
            .map_err(|error| format!("modern loopback JSON-RPC response was invalid: {error}"))?;
            if response.id != Some(801_i64.into()) || response.error.is_some() {
                return Err(format!(
                    "modern loopback request was not dispatched: {response:?}"
                ));
            }
            if response.result.as_ref().and_then(|result| {
                result["_meta"][fastmcp_protocol::SERVER_DISCOVER_SERVER_INFO_META_KEY]["name"]
                    .as_str()
            }) != Some("live-modern-http")
            {
                return Err(format!(
                    "modern loopback discovery result was unexpected: {response:?}"
                ));
            }
            Ok(())
        });
    }

    /// Explicit test consent backend installed through the production API;
    /// native Basic tests do not depend on the cfg(test) default approval.
    struct NativeBasicConsent;

    impl oauth::AuthorizationApprovalBackend for NativeBasicConsent {
        fn generation(&self) -> oauth::AuthorizationApprovalGeneration {
            oauth::AuthorizationApprovalGeneration::from_bytes([0x42; 32])
        }

        fn approve(
            &self,
            request: &oauth::AuthorizationApprovalRequest,
        ) -> oauth::AuthorizationApprovalDisposition {
            oauth::AuthorizationApprovalDisposition::Approved(
                request
                    .approve(
                        "native-basic-owner".to_owned(),
                        request.scopes().to_vec(),
                        request.resource().map(str::to_owned),
                        self.generation(),
                    )
                    .expect("approve the exact bounded client request"),
            )
        }
    }

    fn native_oauth_basic_header(encoded_components: &str) -> String {
        use base64::Engine as _;
        format!(
            "Basic {}",
            base64::engine::general_purpose::STANDARD.encode(encoded_components),
        )
    }

    fn native_oauth_basic_fixture() -> (OAuthHttpRoutes, String, String) {
        let oauth = Arc::new(
            oauth::OAuthServer::try_with_approval_backend(
                oauth::OAuthServerConfig::default(),
                Arc::new(NativeBasicConsent),
            )
            .expect("valid explicit consent configuration"),
        );
        oauth
            .register_client(
                oauth::OAuthClient::builder("native:basic+client")
                    .secret("S3cret:+ &=%")
                    .redirect_uri("https://client.example.test/callback")
                    .scope("mcp")
                    .build()
                    .expect("bounded confidential client"),
            )
            .expect("register confidential client");
        let (code, _) = oauth
            .authorize(&oauth::AuthorizationRequest {
                response_type: "code".to_owned(),
                client_id: "native:basic+client".to_owned(),
                redirect_uri: "https://client.example.test/callback".to_owned(),
                scopes: vec!["mcp".to_owned()],
                resource: None,
                state: None,
                code_challenge: "E9Melhoa2OwvFrEMTJguCHaoeK1t8URWbuGJSstw-cM".to_owned(),
                code_challenge_method: oauth::CodeChallengeMethod::S256,
            })
            .expect("issue a code through the explicit consent backend");
        let form = format!(
            "grant_type=authorization_code&code={code}&redirect_uri=https%3A%2F%2Fclient.example.test%2Fcallback&code_verifier=dBjftJeZ4CVP-mB92K27uhbUJU1p1r_wW1gFWFOEjXk"
        );
        // These literal OAuth components exercise encoded colons, plus signs,
        // spaces, ampersands, equals signs and percent signs independently of
        // the production percent decoder.
        let basic = native_oauth_basic_header("native%3Abasic%2Bclient:S3cret%3A%2B+%26%3D%25");
        let routes = OAuthHttpRoutes::new(oauth, "https://fastmcp.invalid/oauth")
            .expect("native OAuth routes");
        (routes, form, basic)
    }

    fn native_oauth_form_request(
        path: &str,
        form: &str,
        authorization: Option<&str>,
    ) -> asupersync::http::h1::Request {
        let mut headers = vec![(
            "Content-Type".to_owned(),
            "application/x-www-form-urlencoded".to_owned(),
        )];
        if let Some(authorization) = authorization {
            headers.push(("Authorization".to_owned(), authorization.to_owned()));
        }
        asupersync::http::h1::Request {
            method: Http1Method::Post,
            uri: path.to_owned(),
            version: asupersync::http::h1::Version::Http11,
            headers,
            body: form.as_bytes().to_vec(),
            trailers: Vec::new(),
            peer_addr: None,
        }
    }

    fn assert_native_oauth_error(
        response: &HttpResponse,
        status: HttpStatus,
        error: &str,
        challenge: Option<&str>,
    ) {
        assert_eq!(response.status, status);
        assert_eq!(
            serde_json::from_slice::<serde_json::Value>(&response.body).expect("OAuth error JSON"),
            serde_json::json!({ "error": error }),
        );
        assert_eq!(
            response.headers.get("www-authenticate").map(String::as_str),
            challenge,
        );
        assert_eq!(
            response.headers.get("cache-control").map(String::as_str),
            Some("no-store"),
        );
        assert_eq!(
            response.headers.get("pragma").map(String::as_str),
            Some("no-cache"),
        );
    }

    #[test]
    fn native_oauth_basic_rejections_preserve_code_and_live_grant() {
        let (routes, form, basic) = native_oauth_basic_fixture();
        let token_path = routes.token_path();
        let bad_secret = native_oauth_basic_header("native%3Abasic%2Bclient:wrong-secret");
        let unknown_client = native_oauth_basic_header("unknown-client:wrong-secret");
        for authorization in [
            bad_secret.as_str(),
            unknown_client.as_str(),
            "Basic malformed!",
            "Basic",
            "Basic \tY2xpZW50OnNlY3JldA==",
        ] {
            let request = native_oauth_form_request(token_path, &form, Some(authorization));
            assert_native_oauth_error(
                &dispatch_oauth_h1_request(&routes, &request, token_path, ""),
                HttpStatus::UNAUTHORIZED,
                "invalid_client",
                Some("Basic realm=\"oauth\""),
            );
        }
        for extra in [
            "client_id=native%3Abasic%2Bclient",
            "client_id=",
            "client_secret=wrong-secret",
            "client_secret=",
            "client%5Fsecret=",
        ] {
            let mixed_form = format!("{form}&{extra}");
            let request = native_oauth_form_request(token_path, &mixed_form, Some(&basic));
            assert_native_oauth_error(
                &dispatch_oauth_h1_request(&routes, &request, token_path, ""),
                HttpStatus::BAD_REQUEST,
                "invalid_request",
                None,
            );
        }
        let mut duplicate_header = native_oauth_form_request(token_path, &form, Some(&basic));
        duplicate_header
            .headers
            .push(("authorization".to_owned(), basic.clone()));
        assert_native_oauth_error(
            &dispatch_oauth_h1_request(&routes, &duplicate_header, token_path, ""),
            HttpStatus::BAD_REQUEST,
            "invalid_request",
            None,
        );
        let request = native_oauth_form_request(token_path, &form, Some(&basic));
        let issued = dispatch_oauth_h1_request(&routes, &request, token_path, "");
        assert_eq!(
            issued.status,
            HttpStatus::OK,
            "rejections must preserve the code",
        );
        let issued: serde_json::Value = serde_json::from_slice(&issued.body).expect("token JSON");
        let access = issued["access_token"].as_str().expect("access token");
        let refresh = issued["refresh_token"].as_str().expect("refresh token");
        assert!(routes.server().validate_access_token(access).is_some());
        let refresh_form = format!("grant_type=refresh_token&refresh_token={refresh}");
        let request = native_oauth_form_request(token_path, &refresh_form, Some(&bad_secret));
        assert_native_oauth_error(
            &dispatch_oauth_h1_request(&routes, &request, token_path, ""),
            HttpStatus::UNAUTHORIZED,
            "invalid_client",
            Some("Basic realm=\"oauth\""),
        );
        let revoke_path = routes.revocation_path();
        let revoke_form = format!("token={refresh}");
        let request = native_oauth_form_request(revoke_path, &revoke_form, Some(&bad_secret));
        assert_native_oauth_error(
            &dispatch_oauth_h1_request(&routes, &request, revoke_path, ""),
            HttpStatus::UNAUTHORIZED,
            "invalid_client",
            Some("Basic realm=\"oauth\""),
        );
        let request = native_oauth_form_request(
            revoke_path,
            &format!("{revoke_form}&client_secret="),
            Some(&basic),
        );
        assert_native_oauth_error(
            &dispatch_oauth_h1_request(&routes, &request, revoke_path, ""),
            HttpStatus::BAD_REQUEST,
            "invalid_request",
            None,
        );
        assert!(routes.server().validate_access_token(access).is_some());
        let request = native_oauth_form_request(token_path, &refresh_form, Some(&basic));
        let refreshed = dispatch_oauth_h1_request(&routes, &request, token_path, "");
        assert_eq!(
            refreshed.status,
            HttpStatus::OK,
            "rejections must preserve refresh",
        );
        let refreshed: serde_json::Value =
            serde_json::from_slice(&refreshed.body).expect("refreshed token JSON");
        let successor = refreshed["access_token"].as_str().expect("successor token");
        assert!(routes.server().validate_access_token(successor).is_some());
        let request =
            native_oauth_form_request(revoke_path, &format!("token={successor}"), Some(&basic));
        assert_eq!(
            dispatch_oauth_h1_request(&routes, &request, revoke_path, "").status,
            HttpStatus::OK,
        );
        assert!(routes.server().validate_access_token(successor).is_none());
    }

    #[test]
    fn native_oauth_basic_decoding_is_bounded_and_preserves_empty_password_authentication() {
        let client_id = "%61".repeat(oauth::MAX_OAUTH_CLIENT_ID_BYTES);
        let secret = "%62".repeat(oauth::MAX_OAUTH_CLIENT_CREDENTIAL_BYTES);
        let basic = native_oauth_basic_header(&format!("{client_id}:{secret}"));
        let mut admission =
            OAuthParameterAdmission::admit(OAuthParameterEndpoint::TokenForm, b"").unwrap();
        let (id, password) = oauth_http_client_credentials(&mut admission, Some(&basic))
            .expect("exact maximum percent-expanded credentials");
        assert_eq!(id, "a".repeat(oauth::MAX_OAUTH_CLIENT_ID_BYTES));
        assert_eq!(
            password,
            Some("b".repeat(oauth::MAX_OAUTH_CLIENT_CREDENTIAL_BYTES)),
        );
        for components in [
            format!("{client_id}a:{secret}"),
            format!("{client_id}:{secret}b"),
            format!("{client_id}a:secret"),
            format!("client:{secret}b"),
            "client:%".to_owned(),
            "client:%GG".to_owned(),
            "client:%ff".to_owned(),
            "client:%0a".to_owned(),
            "client-without-colon".to_owned(),
            ":secret".to_owned(),
        ] {
            let basic = native_oauth_basic_header(&components);
            let mut admission =
                OAuthParameterAdmission::admit(OAuthParameterEndpoint::TokenForm, b"").unwrap();
            let error = oauth_http_client_credentials(&mut admission, Some(&basic))
                .expect_err("invalid Basic input must fail before authentication");
            assert_native_oauth_error(
                &error,
                HttpStatus::UNAUTHORIZED,
                "invalid_client",
                Some("Basic realm=\"oauth\""),
            );
        }
        let oauth = Arc::new(oauth::OAuthServer::with_defaults());
        oauth
            .register_client(
                oauth::OAuthClient::builder("public-client")
                    .redirect_uri("https://client.example.test/callback")
                    .build()
                    .expect("public client"),
            )
            .unwrap();
        let routes = OAuthHttpRoutes::new(oauth, "https://fastmcp.invalid/oauth").unwrap();
        let empty_password = native_oauth_basic_header("public-client:");
        let request = native_oauth_form_request(
            routes.revocation_path(),
            "token=unknown-token",
            Some(&empty_password),
        );
        assert_native_oauth_error(
            &dispatch_oauth_h1_request(&routes, &request, routes.revocation_path(), ""),
            HttpStatus::UNAUTHORIZED,
            "invalid_client",
            Some("Basic realm=\"oauth\""),
        );
        let request = native_oauth_form_request(
            routes.revocation_path(),
            "token=unknown-token&client_id=public-client",
            None,
        );
        assert_eq!(
            dispatch_oauth_h1_request(&routes, &request, routes.revocation_path(), "").status,
            HttpStatus::OK,
            "the same public client remains usable with none authentication",
        );
    }

    #[test]
    fn live_http_oauth_basic_authorization_code_refresh_and_revocation() {
        run_live_http_test(|cx| async move {
            let (routes, code_form, basic) = native_oauth_basic_fixture();
            let oauth = Arc::clone(routes.server());
            let bound = Server::new("live-oauth-basic", "1.0.0")
                .oauth_http_routes(routes)
                .build()
                .bind_http(&cx, "127.0.0.1:0")
                .await
                .map_err(|error| format!("Basic OAuth listener failed: {error}"))?;
            let address = bound
                .local_addr()
                .map_err(|error| format!("Basic OAuth address failed: {error}"))?;
            let caller_cx = cx.clone();
            let mut client = cx
                .spawn(move |_client_cx| async move {
                    let result = async {
                        let request = |path: &str, form: &str, authorization: &str| {
                            format!(
                                "POST {path} HTTP/1.1\r\nHost: loopback\r\nAuthorization: {authorization}\r\nContent-Type: application/x-www-form-urlencoded\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{form}",
                                form.len(),
                            )
                            .into_bytes()
                        };
                        let wrong_basic =
                            native_oauth_basic_header("native%3Abasic%2Bclient:wrong-secret");
                        // RH-5: only the Basic password differs from the
                        // succeeding wire request; its code must survive.
                        let rejected = live_http_exchange(
                            address,
                            request("/oauth/token", &code_form, &wrong_basic),
                        )
                        .await?;
                        if !rejected.starts_with(b"HTTP/1.1 401")
                            || live_http_response_header(&rejected, "www-authenticate")?
                                != "Basic realm=\"oauth\""
                            || serde_json::from_slice::<serde_json::Value>(
                                live_http_response_body(&rejected)?,
                            )
                            .map_err(|_| "Basic rejection was not JSON".to_owned())?
                                != serde_json::json!({ "error": "invalid_client" })
                        {
                            return Err(
                                "Basic wrong-secret rejection changed its contract".to_owned(),
                            );
                        }
                        let issued = live_http_exchange(
                            address,
                            request("/oauth/token", &code_form, &basic),
                        )
                        .await?;
                        if !issued.starts_with(b"HTTP/1.1 200")
                            || live_http_response_header(&issued, "cache-control")? != "no-store"
                            || live_http_response_header(&issued, "pragma")? != "no-cache"
                        {
                            return Err(
                                "Basic authorization-code exchange did not succeed".to_owned(),
                            );
                        }
                        let issued: serde_json::Value =
                            serde_json::from_slice(live_http_response_body(&issued)?)
                                .map_err(|_| "Basic token response was not JSON".to_owned())?;
                        let access = issued["access_token"]
                            .as_str()
                            .ok_or_else(|| "Basic token response omitted access token".to_owned())?;
                        if oauth.validate_access_token(access).is_none() {
                            return Err("Basic access token is not usable".to_owned());
                        }
                        let refresh = issued["refresh_token"]
                            .as_str()
                            .ok_or_else(|| "Basic token response omitted refresh token".to_owned())?;
                        let refreshed = live_http_exchange(
                            address,
                            request(
                                "/oauth/token",
                                &format!("grant_type=refresh_token&refresh_token={refresh}"),
                                &basic,
                            ),
                        )
                        .await?;
                        if !refreshed.starts_with(b"HTTP/1.1 200") {
                            return Err("Basic refresh exchange did not succeed".to_owned());
                        }
                        let refreshed: serde_json::Value =
                            serde_json::from_slice(live_http_response_body(&refreshed)?)
                                .map_err(|_| "Basic refresh response was not JSON".to_owned())?;
                        let successor = refreshed["access_token"]
                            .as_str()
                            .ok_or_else(|| "Basic refresh omitted access token".to_owned())?;
                        if successor == access || oauth.validate_access_token(successor).is_none() {
                            return Err("Basic refresh did not issue a usable successor".to_owned());
                        }
                        let revoked = live_http_exchange(
                            address,
                            request("/oauth/revoke", &format!("token={successor}"), &basic),
                        )
                        .await?;
                        if !revoked.starts_with(b"HTTP/1.1 200")
                            || oauth.validate_access_token(successor).is_some()
                        {
                            return Err("Basic revocation did not invalidate its token".to_owned());
                        }
                        Ok(())
                    }
                    .await;
                    caller_cx.cancel_with(CancelKind::User, Some("Basic OAuth lifecycle complete"));
                    result
                })
                .map_err(|error| format!("Basic OAuth client spawn failed: {error}"))?;
            let serve = bound.serve(&cx).await;
            client
                .join(&cx)
                .await
                .map_err(|error| format!("Basic OAuth client failed: {error:?}"))??;
            let shutdown = serve.map_err(|error| format!("Basic OAuth server failed: {error}"))?;
            require_quiescent_http_shutdown(shutdown, "Basic OAuth lifecycle").await
        });
    }

    /// Native OAuth routes with OIDC under `base`, plus an access token for a
    /// client registered and authorized with `scopes`. A Pending signer
    /// activation is all `with_oidc` needs to fix the OIDC paths.
    #[cfg(feature = "builtin-auth-server")]
    fn native_oidc_userinfo_fixture(scopes: &[&str], base: &str) -> (OAuthHttpRoutes, String) {
        const CLIENT_ID: &str = "native-userinfo-client";
        const REDIRECT_URI: &str = "http://127.0.0.1/userinfo-callback";
        // RFC 7636 appendix B.
        const CODE_VERIFIER: &str = "dBjftJeZ4CVP-mB92K27uhbUJU1p1r_wW1gFWFOEjXk";
        const CODE_CHALLENGE: &str = "E9Melhoa2OwvFrEMTJguCHaoeK1t8URWbuGJSstw-cM";

        let oauth = Arc::new(oauth::OAuthServer::with_defaults());
        oauth
            .register_client(
                oauth::OAuthClient::builder(CLIENT_ID)
                    .redirect_uri(REDIRECT_URI)
                    .scopes(scopes.iter().copied())
                    .build()
                    .expect("valid userinfo client"),
            )
            .expect("register userinfo client");
        let (code, _) = oauth
            .authorize(&oauth::AuthorizationRequest {
                response_type: "code".to_string(),
                client_id: CLIENT_ID.to_string(),
                redirect_uri: REDIRECT_URI.to_string(),
                scopes: scopes.iter().map(|scope| (*scope).to_string()).collect(),
                resource: None,
                state: Some("userinfo-state".to_string()),
                code_challenge: CODE_CHALLENGE.to_string(),
                code_challenge_method: oauth::CodeChallengeMethod::S256,
            })
            .expect("authorize userinfo client");
        let access_token = oauth
            .token(&oauth::TokenRequest {
                grant_type: "authorization_code".to_string(),
                code: Some(code),
                redirect_uri: Some(REDIRECT_URI.to_string()),
                client_id: CLIENT_ID.to_string(),
                client_secret: None,
                code_verifier: Some(CODE_VERIFIER.to_string()),
                refresh_token: None,
                scopes: None,
                resource: None,
            })
            .expect("exchange userinfo access token")
            .access_token;

        let provider = native_pending_oidc_provider(&oauth, "https://fastmcp.invalid/oidc/jwks");
        let routes = OAuthHttpRoutes::new(oauth, base)
            .expect("OAuth route base")
            .with_oidc(provider)
            .expect("OIDC routes");
        (routes, access_token)
    }

    /// An OIDC provider over `oauth` whose signer activation is Pending on
    /// `jwks_uri`, which fixes the JWKS route `with_oidc` will serve.
    #[cfg(feature = "builtin-auth-server")]
    fn native_pending_oidc_provider(
        oauth: &Arc<oauth::OAuthServer>,
        jwks_uri: &str,
    ) -> Arc<oidc::OidcProvider> {
        let signer = oidc_public_canary_signer();
        let provider = Arc::new(
            oidc::OidcProvider::with_defaults(Arc::clone(oauth)).expect("default OIDC provider"),
        );
        provider
            .set_id_token_signing_activation_dependencies(
                Arc::new(LiveLoopbackOidcReadBackVerifier {
                    address: Mutex::new(None),
                    generation: signer.binding().ring_generation(),
                }) as Arc<dyn oidc::OidcJwksReadBackVerifier>,
                Arc::new(LiveOidcActivationStore::default())
                    as Arc<dyn oidc::OidcSigningActivationStore>,
            )
            .expect("OIDC activation dependencies");
        provider
            .begin_id_token_signing_activation(signer, jwks_uri)
            .expect("OIDC Pending activation");
        provider
    }

    /// The UserInfo route shares the OAuth route prefix, so a JWKS URI that
    /// lands on it would make one path answer two documents. `with_oidc` must
    /// refuse that configuration; a JWKS path beside it is accepted.
    #[cfg(feature = "builtin-auth-server")]
    #[test]
    fn native_oidc_routes_refuse_a_jwks_path_on_the_userinfo_route() {
        for (jwks_uri, accepted) in [
            ("https://fastmcp.invalid/oauth/jwks", true),
            ("https://fastmcp.invalid/oauth/userinfo", false),
        ] {
            let oauth = Arc::new(oauth::OAuthServer::with_defaults());
            let provider = native_pending_oidc_provider(&oauth, jwks_uri);
            let routes = OAuthHttpRoutes::new(oauth, "https://fastmcp.invalid/oauth")
                .expect("OAuth route base")
                .with_oidc(provider);
            if accepted {
                let routes = routes.expect("a distinct JWKS path is accepted");
                let oidc = routes.oidc_routes().expect("OIDC routes configured");
                assert_eq!(oidc.jwks_path(), "/oauth/jwks");
                assert_eq!(oidc.userinfo_path(), "/oauth/userinfo");
            } else {
                assert_eq!(
                    routes.err(),
                    Some(oauth::OAuthHttpRouteConfigurationError::InvalidPublicEndpointBase)
                );
            }
        }
    }

    #[cfg(feature = "builtin-auth-server")]
    fn native_oidc_userinfo_request(
        routes: &OAuthHttpRoutes,
        method: Http1Method,
        authorization: Option<&str>,
    ) -> HttpResponse {
        let path = routes
            .oidc_routes()
            .expect("OIDC routes configured")
            .userinfo_path()
            .to_owned();
        let request = asupersync::http::h1::Request {
            method,
            uri: path.clone(),
            version: asupersync::http::h1::Version::Http11,
            headers: authorization
                .map(|value| vec![("Authorization".to_owned(), value.to_owned())])
                .unwrap_or_default(),
            body: Vec::new(),
            trailers: Vec::new(),
            peer_addr: None,
        };
        dispatch_oauth_h1_request(routes, &request, &path, "")
    }

    /// bd-vej30: discovery advertises `userinfo_endpoint`, so a native route
    /// must serve it, under either spelling of the endpoint base.
    #[cfg(feature = "builtin-auth-server")]
    #[test]
    fn native_oidc_userinfo_serves_claims_for_an_openid_token_positive() {
        for base in [
            "https://fastmcp.invalid/oauth",
            "https://fastmcp.invalid/oauth/",
        ] {
            let (routes, access_token) = native_oidc_userinfo_fixture(&["openid"], base);
            let oidc = routes.oidc_routes().expect("OIDC routes configured");
            let discovery = oidc
                .provider()
                .discovery_document(routes.public_endpoint_base());
            assert_eq!(
                discovery.userinfo_endpoint,
                Some(format!("https://fastmcp.invalid{}", oidc.userinfo_path())),
                "{base}"
            );
            assert!(routes.has_path(oidc.userinfo_path()), "{base}");

            for method in [Http1Method::Get, Http1Method::Post] {
                let response = native_oidc_userinfo_request(
                    &routes,
                    method,
                    Some(&format!("Bearer {access_token}")),
                );
                assert_eq!(response.status, HttpStatus::OK, "{base} {response:?}");
                assert_eq!(
                    response.headers.get("cache-control").map(String::as_str),
                    Some("no-store")
                );
                let claims: serde_json::Value =
                    serde_json::from_slice(&response.body).expect("userinfo JSON");
                assert!(
                    claims["sub"].as_str().is_some_and(|sub| !sub.is_empty()),
                    "{claims}"
                );
            }
        }
    }

    #[cfg(feature = "builtin-auth-server")]
    #[test]
    fn native_oidc_userinfo_refuses_a_token_without_openid_scope_negative() {
        let (routes, access_token) =
            native_oidc_userinfo_fixture(&["mcp"], "https://fastmcp.invalid/oauth");
        let response = native_oidc_userinfo_request(
            &routes,
            Http1Method::Get,
            Some(&format!("Bearer {access_token}")),
        );
        assert_eq!(response.status, HttpStatus::FORBIDDEN, "{response:?}");
        assert_eq!(
            response.headers.get("www-authenticate").map(String::as_str),
            Some("Bearer error=\"insufficient_scope\"")
        );
        let body: serde_json::Value = serde_json::from_slice(&response.body).expect("error JSON");
        assert_eq!(body, serde_json::json!({ "error": "insufficient_scope" }));
    }

    #[cfg(feature = "builtin-auth-server")]
    #[test]
    fn native_oidc_userinfo_challenges_missing_and_unknown_bearer_tokens() {
        let (routes, _) =
            native_oidc_userinfo_fixture(&["openid"], "https://fastmcp.invalid/oauth");
        for authorization in [None, Some("Basic dXNlcjpwYXNz"), Some("Bearer")] {
            let response = native_oidc_userinfo_request(&routes, Http1Method::Get, authorization);
            assert_eq!(
                response.status,
                HttpStatus::UNAUTHORIZED,
                "{authorization:?}"
            );
            assert_eq!(
                response.headers.get("www-authenticate").map(String::as_str),
                Some("Bearer"),
                "{authorization:?}"
            );
        }
        let response = native_oidc_userinfo_request(
            &routes,
            Http1Method::Get,
            Some("Bearer forged-opaque-credential"),
        );
        assert_eq!(response.status, HttpStatus::UNAUTHORIZED);
        assert_eq!(
            response.headers.get("www-authenticate").map(String::as_str),
            Some("Bearer error=\"invalid_token\"")
        );
        let response = native_oidc_userinfo_request(&routes, Http1Method::Put, None);
        assert_eq!(response.status, HttpStatus::METHOD_NOT_ALLOWED);
    }

    #[cfg(feature = "builtin-auth-server")]
    #[test]
    fn live_http_oidc_jwks_read_back_then_discovery_activate_exact_public_bytes() {
        run_live_http_test(|cx| async move {
            use fastmcp_protocol::jose::ExternalRs256SigningDeadline;

            let oauth = Arc::new(oauth::OAuthServer::with_defaults());
            let signer = oidc_public_canary_signer();
            let expected_jwks = signer
                .canonical_public_jwks()
                .map_err(|error| format!("OIDC canonical JWKS failed: {error}"))?
                .as_bytes()
                .to_vec();
            let provider = Arc::new(
                oidc::OidcProvider::with_defaults(Arc::clone(&oauth))
                    .map_err(|error| format!("OIDC provider construction failed: {error}"))?,
            );
            let verifier = Arc::new(LiveLoopbackOidcReadBackVerifier {
                address: Mutex::new(None),
                generation: signer.binding().ring_generation(),
            });
            let store = Arc::new(LiveOidcActivationStore::default());
            provider
                .set_id_token_signing_activation_dependencies(
                    Arc::clone(&verifier) as Arc<dyn oidc::OidcJwksReadBackVerifier>,
                    Arc::clone(&store) as Arc<dyn oidc::OidcSigningActivationStore>,
                )
                .map_err(|error| format!("OIDC external dependencies failed: {error}"))?;
            provider
                .begin_id_token_signing_activation(
                    Arc::clone(&signer),
                    "https://fastmcp.invalid/oidc/jwks",
                )
                .map_err(|error| format!("OIDC Pending admission failed: {error}"))?;
            provider
                .publish_id_token_signing_jwks(
                    signer.canonical_public_jwks().map_err(|error| {
                        format!("OIDC JWKS publication generation failed: {error}")
                    })?,
                )
                .map_err(|error| format!("OIDC canonical JWKS publication failed: {error}"))?;
            let routes = OAuthHttpRoutes::new(Arc::clone(&oauth), "https://fastmcp.invalid/oauth")
                .map_err(|error| format!("OIDC OAuth route base failed: {error}"))?
                .with_oidc(Arc::clone(&provider))
                .map_err(|error| format!("OIDC public route configuration failed: {error}"))?;
            let bound = Server::new("live-oidc-jwks", "1.0.0")
                .oauth_http_routes(routes)
                .build()
                .bind_http(&cx, "127.0.0.1:0")
                .await
                .map_err(|error| format!("OIDC public HTTP bind failed: {error}"))?;
            let address = bound
                .local_addr()
                .map_err(|error| format!("OIDC public HTTP address failed: {error}"))?;
            verifier.set_address(address);
            let provider_for_client = Arc::clone(&provider);
            let caller_cx = cx.clone();
            let expected_for_client = expected_jwks.clone();
            let mut client = cx
                .spawn(move |client_cx| async move {
                    let jwks = live_http_exchange(
                        address,
                        b"GET /oidc/jwks HTTP/1.1\r\nHost: loopback\r\nConnection: close\r\n\r\n"
                            .to_vec(),
                    )
                    .await?;
                    if !jwks.starts_with(b"HTTP/1.1 200")
                        || live_http_response_body(&jwks)? != expected_for_client.as_slice()
                    {
                        return Err(format!(
                            "OIDC public JWKS did not return exact canonical bytes: {}",
                            String::from_utf8_lossy(&jwks)
                        ));
                    }
                    let deadline = ExternalRs256SigningDeadline::new(Duration::from_secs(1))
                        .map_err(|error| format!("OIDC canary deadline invalid: {error}"))?;
                    provider_for_client
                        .activate_id_token_signing(&client_cx, deadline)
                        .await
                        .map_err(|error| format!("OIDC active admission failed: {error}"))?;
                    let discovery = live_http_exchange(
                        address,
                        b"GET /.well-known/openid-configuration HTTP/1.1\r\nHost: loopback\r\nConnection: close\r\n\r\n"
                            .to_vec(),
                    )
                    .await?;
                    caller_cx.cancel_with(CancelKind::User, Some("live OIDC publication complete"));
                    Ok::<_, String>(discovery)
                })
                .map_err(|error| format!("OIDC public client admission failed: {error}"))?;

            let serve = bound.serve(&cx).await;
            let discovery = client
                .join(&cx)
                .await
                .map_err(|error| format!("OIDC public client failed: {error:?}"))??;
            let shutdown = serve.map_err(|error| format!("OIDC public server failed: {error}"))?;
            require_quiescent_http_shutdown(shutdown, "live OIDC public JWKS").await?;
            if !discovery.starts_with(b"HTTP/1.1 200") {
                return Err(format!(
                    "OIDC discovery did not become publicly reachable: {}",
                    String::from_utf8_lossy(&discovery)
                ));
            }
            let discovery: serde_json::Value =
                serde_json::from_slice(live_http_response_body(&discovery)?)
                    .map_err(|error| format!("OIDC discovery was not JSON: {error}"))?;
            if discovery["issuer"] != "https://fastmcp.invalid/"
                || discovery["jwks_uri"] != "https://fastmcp.invalid/oidc/jwks"
            {
                return Err(format!(
                    "OIDC discovery mismatched active publication: {discovery}"
                ));
            }
            Ok(())
        });
    }

    #[test]
    fn live_http_oauth_pkce_authorize_then_token_is_publicly_reachable() {
        run_live_http_test(|cx| async move {
            let oauth = Arc::new(oauth::OAuthServer::with_defaults());
            oauth
                .register_client(
                    oauth::OAuthClient::builder("live-pkce-client")
                        .redirect_uri("https://client.example.test/callback")
                        .scope("mcp")
                        .build()
                        .map_err(|error| {
                            format!("live OAuth client registration failed: {error}")
                        })?,
                )
                .map_err(|error| format!("live OAuth client retention failed: {error}"))?;
            let routes = OAuthHttpRoutes::new(Arc::clone(&oauth), "https://fastmcp.invalid/oauth")
                .map_err(|error| format!("live OAuth HTTP routes were invalid: {error}"))?;
            let bound = Server::new("live-oauth-pkce", "1.0.0")
                .oauth_http_routes(routes)
                .build()
                .bind_http(&cx, "127.0.0.1:0")
                .await
                .map_err(|error| format!("live OAuth HTTP bind failed: {error}"))?;
            let address = bound
                .local_addr()
                .map_err(|error| format!("live OAuth HTTP address failed: {error}"))?;
            let caller_cx = cx.clone();
            let mut client = cx
                .spawn(move |_client_cx| async move {
                    let denied = "GET /oauth/authorize?response_type=code&client_id=live-pkce-client&redirect_uri=https%3A%2F%2Fclient.example.test%2Fcallback&scope=denied&state=opaque-state&code_challenge=E9Melhoa2OwvFrEMTJguCHaoeK1t8URWbuGJSstw-cM&code_challenge_method=S256 HTTP/1.1\r\nHost: loopback\r\nConnection: close\r\n\r\n".to_owned();
                    // RH-5: this differs from the successful request only in
                    // its requested scope. A valid redirect must carry the
                    // OAuth error and the original opaque state.
                    let denied = live_http_exchange(address, denied.into_bytes()).await?;
                    let authorize = "GET /oauth/authorize?response_type=code&client_id=live-pkce-client&redirect_uri=https%3A%2F%2Fclient.example.test%2Fcallback&scope=mcp&state=opaque-state&code_challenge=E9Melhoa2OwvFrEMTJguCHaoeK1t8URWbuGJSstw-cM&code_challenge_method=S256 HTTP/1.1\r\nHost: loopback\r\nConnection: close\r\n\r\n".to_owned();
                    let authorize = live_http_exchange(address, authorize.into_bytes()).await?;
                    let location = live_http_response_header(&authorize, "location")?;
                    let redirect = url::Url::parse(&location)
                        .map_err(|error| format!("OAuth authorization Location was invalid: {error}"))?;
                    let code = redirect
                        .query_pairs()
                        .find_map(|(name, value)| (name == "code").then(|| value.into_owned()))
                        .ok_or_else(|| "OAuth authorization Location omitted code".to_owned())?;
                    if redirect
                        .query_pairs()
                        .find_map(|(name, value)| (name == "state").then(|| value.into_owned()))
                        .as_deref()
                        != Some("opaque-state")
                    {
                        return Err("OAuth authorization Location changed state".to_owned());
                    }
                    let form = format!(
                        "grant_type=authorization_code&code={}&redirect_uri=https%3A%2F%2Fclient.example.test%2Fcallback&client_id=live-pkce-client&code_verifier=dBjftJeZ4CVP-mB92K27uhbUJU1p1r_wW1gFWFOEjXk",
                        url::form_urlencoded::byte_serialize(code.as_bytes()).collect::<String>(),
                    );
                    let token = format!(
                        "POST /oauth/token HTTP/1.1\r\nHost: loopback\r\nContent-Type: application/x-www-form-urlencoded\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{}",
                        form.len(), form,
                    );
                    let token = live_http_exchange(address, token.into_bytes()).await?;
                    caller_cx.cancel_with(CancelKind::User, Some("live OAuth PKCE complete"));
                    Ok::<_, String>((denied, authorize, token))
                })
                .map_err(|error| format!("live OAuth client admission failed: {error}"))?;

            let serve = bound.serve(&cx).await;
            let (denied, authorize, token) = client
                .join(&cx)
                .await
                .map_err(|error| format!("live OAuth client failed: {error:?}"))??;
            let shutdown = serve.map_err(|error| format!("live OAuth server failed: {error}"))?;
            require_quiescent_http_shutdown(shutdown, "live OAuth PKCE").await?;
            if !authorize.starts_with(b"HTTP/1.1 303") {
                return Err(format!(
                    "OAuth authorization did not redirect: {}",
                    String::from_utf8_lossy(&authorize)
                ));
            }
            if !denied.starts_with(b"HTTP/1.1 303") {
                return Err(format!(
                    "valid OAuth error did not redirect: {}",
                    String::from_utf8_lossy(&denied)
                ));
            }
            let denied_location = live_http_response_header(&denied, "location")?;
            let denied_redirect = url::Url::parse(&denied_location)
                .map_err(|error| format!("OAuth error Location was invalid: {error}"))?;
            if denied_redirect
                .query_pairs()
                .find_map(|(name, value)| (name == "error").then(|| value.into_owned()))
                .as_deref()
                != Some("invalid_scope")
                || denied_redirect
                    .query_pairs()
                    .find_map(|(name, value)| (name == "state").then(|| value.into_owned()))
                    .as_deref()
                    != Some("opaque-state")
                || denied_redirect
                    .query_pairs()
                    .find_map(|(name, value)| (name == "iss").then(|| value.into_owned()))
                    .as_deref()
                    != Some("https://fastmcp.invalid/")
                || denied_redirect
                    .query_pairs()
                    .any(|(name, _)| name == "code")
            {
                return Err(format!(
                    "OAuth error redirect did not preserve the safe client response: {denied_location}"
                ));
            }
            if !token.starts_with(b"HTTP/1.1 200")
                || live_http_response_header(&token, "cache-control")? != "no-store"
            {
                return Err(format!(
                    "OAuth token response was not a no-store success: {}",
                    String::from_utf8_lossy(&token)
                ));
            }
            let token: serde_json::Value = serde_json::from_slice(live_http_response_body(&token)?)
                .map_err(|error| format!("OAuth token response was not JSON: {error}"))?;
            if token["token_type"] != "bearer"
                || token["access_token"].as_str().is_none_or(str::is_empty)
            {
                return Err(format!("OAuth token response was incomplete: {token}"));
            }
            Ok(())
        });
    }

    #[test]
    fn live_http_oauth_redirect_uri_mismatch_preserves_authorization_code() {
        run_live_http_test(|cx| async move {
            let oauth = Arc::new(oauth::OAuthServer::with_defaults());
            oauth
                .register_client(
                    oauth::OAuthClient::builder("live-redirect-client")
                        .secret("correct-secret")
                        .redirect_uri("https://client.example.test/callback")
                        .scope("mcp")
                        .build()
                        .map_err(|error| {
                            format!("live redirect client registration failed: {error}")
                        })?,
                )
                .map_err(|error| format!("live redirect client retention failed: {error}"))?;
            let routes = OAuthHttpRoutes::new(Arc::clone(&oauth), "https://fastmcp.invalid/oauth")
                .map_err(|error| format!("live redirect OAuth routes were invalid: {error}"))?;
            let bound = Server::new("live-oauth-redirect-retry", "1.0.0")
                .oauth_http_routes(routes)
                .build()
                .bind_http(&cx, "127.0.0.1:0")
                .await
                .map_err(|error| format!("live redirect OAuth HTTP bind failed: {error}"))?;
            let address = bound
                .local_addr()
                .map_err(|error| format!("live redirect OAuth HTTP address failed: {error}"))?;
            let caller_cx = cx.clone();
            let mut client = cx
                .spawn(move |_client_cx| async move {
                    let authorize = "GET /oauth/authorize?response_type=code&client_id=live-redirect-client&redirect_uri=https%3A%2F%2Fclient.example.test%2Fcallback&scope=mcp&code_challenge=E9Melhoa2OwvFrEMTJguCHaoeK1t8URWbuGJSstw-cM&code_challenge_method=S256 HTTP/1.1\r\nHost: loopback\r\nConnection: close\r\n\r\n".to_owned();
                    let authorize = live_http_exchange(address, authorize.into_bytes()).await?;
                    let location = live_http_response_header(&authorize, "location")?;
                    let redirect = url::Url::parse(&location)
                        .map_err(|error| format!("OAuth redirect Location was invalid: {error}"))?;
                    let code = redirect
                        .query_pairs()
                        .find_map(|(name, value)| (name == "code").then(|| value.into_owned()))
                        .ok_or_else(|| "OAuth redirect Location omitted code".to_owned())?;
                    let encoded_code = url::form_urlencoded::byte_serialize(code.as_bytes())
                        .collect::<String>();
                    let original = format!(
                        "grant_type=authorization_code&code={encoded_code}&redirect_uri=https%3A%2F%2Fclient.example.test%2Fcallback&client_id=live-redirect-client&client_secret=correct-secret&code_verifier=dBjftJeZ4CVP-mB92K27uhbUJU1p1r_wW1gFWFOEjXk"
                    );
                    // RH-5: this form differs from `original` only at redirect_uri.
                    let mismatch = original.replace(
                        "redirect_uri=https%3A%2F%2Fclient.example.test%2Fcallback",
                        "redirect_uri=https%3A%2F%2Fclient.example.test%2Fother",
                    );
                    // RH-5: this form differs from `original` only at the
                    // confidential client credential. Its rejection must not
                    // consume the authorization code.
                    let wrong_secret = original.replace(
                        "client_secret=correct-secret",
                        "client_secret=wrong-secret",
                    );
                    let request = |path: &str, form: &str, authorization: Option<&str>| {
                        format!(
                            "POST {path} HTTP/1.1\r\nHost: loopback\r\nContent-Type: application/x-www-form-urlencoded\r\n{}Content-Length: {}\r\nConnection: close\r\n\r\n{}",
                            authorization.map_or_else(String::new, |value| format!("Authorization: {value}\r\n")),
                            form.len(),
                            form,
                        )
                        .into_bytes()
                    };
                    let rejected =
                        live_http_exchange(address, request("/oauth/token", &mismatch, None)).await?;
                    let wrong_secret_rejected = live_http_exchange(
                        address,
                        request("/oauth/token", &wrong_secret, None),
                    )
                    .await?;
                    // RH-5: compared with the eventual successful redemption,
                    // this adds a second client-credential location.
                    let header_rejected = live_http_exchange(
                        address,
                        request("/oauth/token", &original, Some("Basic ZmFzdG1jcDppbnZhbGlk")),
                    )
                    .await?;
                    // RH-5: this differs from `original` only in its
                    // unsupported Bearer Authorization header. It must not
                    // be converted into a Basic challenge or consume `code`.
                    let bearer_rejected = live_http_exchange(
                        address,
                        request("/oauth/token", &original, Some("Bearer unsupported-token")),
                    )
                    .await?;
                    let revocation =
                        "token=not-a-token&client_id=live-redirect-client&client_secret=wrong-secret";
                    let revoke_wrong_secret = live_http_exchange(
                        address,
                        request("/oauth/revoke", revocation, None),
                    )
                    .await?;
                    // A declared over-limit OAuth form must be rejected from
                    // its head alone; no body bytes follow this request.
                    let over_limit = format!(
                        "POST /oauth/token HTTP/1.1\r\nHost: loopback\r\nContent-Type: application/x-www-form-urlencoded\r\nContent-Length: {}\r\nConnection: close\r\n\r\n",
                        oauth::MAX_OAUTH_FORM_BODY_BYTES + 1,
                    )
                    .into_bytes();
                    let over_limit = live_http_exchange(address, over_limit).await?;
                    let retried =
                        live_http_exchange(address, request("/oauth/token", &original, None)).await?;
                    let access_token = serde_json::from_slice::<serde_json::Value>(
                        live_http_response_body(&retried)?,
                    )
                    .map_err(|error| {
                        format!("successful retry token response was not JSON: {error}")
                    })?["access_token"]
                        .as_str()
                        .filter(|token| !token.is_empty())
                        .ok_or_else(|| {
                            "successful retry token response omitted access_token".to_owned()
                        })?
                        .to_owned();
                    let bearer_revocation_form = format!(
                        "token={}&client_id=live-redirect-client&client_secret=correct-secret",
                        url::form_urlencoded::byte_serialize(access_token.as_bytes())
                            .collect::<String>(),
                    );
                    // RH-5: this differs only by an unsupported Bearer
                    // Authorization header from the form that would revoke
                    // the freshly issued access token.
                    let bearer_revoke_rejected = live_http_exchange(
                        address,
                        request(
                            "/oauth/revoke",
                            &bearer_revocation_form,
                            Some("Bearer unsupported-token"),
                        ),
                    )
                    .await?;
                    caller_cx.cancel_with(CancelKind::User, Some("live OAuth redirect retry complete"));
                    Ok::<_, String>((
                        rejected,
                        wrong_secret_rejected,
                        header_rejected,
                        bearer_rejected,
                        revoke_wrong_secret,
                        over_limit,
                        retried,
                        bearer_revoke_rejected,
                        access_token,
                    ))
                })
                .map_err(|error| format!("live redirect OAuth client admission failed: {error}"))?;

            let serve = bound.serve(&cx).await;
            let (
                rejected,
                wrong_secret_rejected,
                header_rejected,
                bearer_rejected,
                revoke_wrong_secret,
                over_limit,
                retried,
                bearer_revoke_rejected,
                access_token,
            ) = client
                .join(&cx)
                .await
                .map_err(|error| format!("live redirect OAuth client failed: {error:?}"))??;
            let shutdown =
                serve.map_err(|error| format!("live redirect OAuth server failed: {error}"))?;
            require_quiescent_http_shutdown(shutdown, "live OAuth redirect retry").await?;
            if !rejected.starts_with(b"HTTP/1.1 400")
                || serde_json::from_slice::<serde_json::Value>(live_http_response_body(&rejected)?)
                    .ok()
                    .and_then(|body| body["error"].as_str().map(str::to_owned))
                    .as_deref()
                    != Some("invalid_grant")
            {
                return Err(format!(
                    "redirect-only mismatch was not an invalid_grant rejection: {}",
                    String::from_utf8_lossy(&rejected)
                ));
            }
            if !retried.starts_with(b"HTTP/1.1 200") {
                return Err(format!(
                    "a rejected token request consumed the authorization code: {}",
                    String::from_utf8_lossy(&retried)
                ));
            }
            for (endpoint, response) in [
                ("token form", &wrong_secret_rejected),
                ("revocation form", &revoke_wrong_secret),
            ] {
                if !response.starts_with(b"HTTP/1.1 400")
                    || live_http_response_has_header(response, "www-authenticate")?
                    || serde_json::from_slice::<serde_json::Value>(live_http_response_body(
                        response,
                    )?)
                    .ok()
                    .and_then(|body| body["error"].as_str().map(str::to_owned))
                    .as_deref()
                        != Some("invalid_client")
                {
                    return Err(format!(
                        "{endpoint} wrong-secret rejection was not an unchallenged invalid_client 400: {}",
                        String::from_utf8_lossy(response)
                    ));
                }
            }
            if !header_rejected.starts_with(b"HTTP/1.1 400")
                || live_http_response_has_header(&header_rejected, "www-authenticate")?
                || serde_json::from_slice::<serde_json::Value>(live_http_response_body(
                    &header_rejected,
                )?)
                .ok()
                .and_then(|body| body["error"].as_str().map(str::to_owned))
                .as_deref()
                    != Some("invalid_request")
            {
                return Err(format!(
                    "mixed client credentials were not an unchallenged invalid_request 400: {}",
                    String::from_utf8_lossy(&header_rejected)
                ));
            }
            for (endpoint, response) in [
                ("token Bearer", &bearer_rejected),
                ("revocation Bearer", &bearer_revoke_rejected),
            ] {
                if !response.starts_with(b"HTTP/1.1 400")
                    || live_http_response_has_header(response, "www-authenticate")?
                    || serde_json::from_slice::<serde_json::Value>(live_http_response_body(
                        response,
                    )?)
                    .ok()
                    .and_then(|body| body["error"].as_str().map(str::to_owned))
                    .as_deref()
                        != Some("invalid_request")
                {
                    return Err(format!(
                        "{endpoint} rejection was not an unchallenged invalid_request: {}",
                        String::from_utf8_lossy(response)
                    ));
                }
            }
            if oauth.validate_access_token(&access_token).is_none() {
                return Err(
                    "Bearer rejection on /oauth/revoke changed the issued access-token state"
                        .to_owned(),
                );
            }
            if !over_limit.starts_with(b"HTTP/1.1 400") {
                return Err(format!(
                    "over-limit OAuth form was not rejected from its head: {}",
                    String::from_utf8_lossy(&over_limit)
                ));
            }
            Ok(())
        });
    }

    #[test]
    fn live_http_strict_admission_dispatches_a_canonical_modern_post() {
        run_live_http_test(|cx| async move {
            let response = live_http_strict_admission_exchange(&cx, SERVER_DISCOVER_METHOD).await?;
            if !response.starts_with(b"HTTP/1.1 200") {
                return Err(format!(
                    "canonical strict-admission POST used an unexpected response: {}",
                    String::from_utf8_lossy(&response)
                ));
            }
            let response: JsonRpcResponse =
                serde_json::from_slice(live_http_response_body(&response)?).map_err(|error| {
                    format!("canonical strict-admission response was invalid: {error}")
                })?;
            if response.id != Some(803_i64.into()) || response.error.is_some() {
                return Err(format!(
                    "canonical strict-admission POST was not dispatched: {response:?}"
                ));
            }
            Ok(())
        });
    }

    #[test]
    fn live_http_strict_admission_rejects_only_a_mismatched_method_mirror() {
        run_live_http_test(|cx| async move {
            // This is the canonical live POST above with only its Mcp-Method
            // header changed; the JSON body still names server/discover.
            let response =
                live_http_strict_admission_exchange(&cx, "server/discover-mismatch").await?;
            if !response.starts_with(b"HTTP/1.1 400") {
                return Err(format!(
                    "mismatched strict-admission mirror used an unexpected response: {}",
                    String::from_utf8_lossy(&response)
                ));
            }
            let response: JsonRpcResponse =
                serde_json::from_slice(live_http_response_body(&response)?).map_err(|error| {
                    format!("strict-admission rejection was not valid JSON-RPC: {error}")
                })?;
            if response.id != Some(803_i64.into())
                || response.result.is_some()
                || response
                    .error
                    .as_ref()
                    .and_then(|error| error.code.as_i32())
                    != Some(fastmcp_protocol::HEADER_MISMATCH_ERROR_CODE)
                || response
                    .error
                    .as_ref()
                    .and_then(|error| error.data.as_ref())
                    .is_some()
            {
                return Err(format!(
                    "strict-admission mirror did not retain its canonical pre-dispatch error: {response:?}"
                ));
            }
            Ok(())
        });
    }

    #[test]
    fn live_http_listener_merges_repeated_accept_but_rejects_a_duplicate_singleton() {
        run_live_http_test(|cx| async move {
            let bound = Server::new("live-http-repeated-admission", "1.0.0")
                .protocol_policy(ProtocolPolicy::ModernOnly)
                .expect("ModernOnly must be available to this test build")
                .build()
                .bind_http(&cx, "127.0.0.1:0")
                .await
                .map_err(|error| format!("repeated admission HTTP bind failed: {error}"))?;
            let address = bound
                .local_addr()
                .map_err(|error| format!("repeated admission HTTP address failed: {error}"))?;
            let caller_cx = cx.clone();
            let mut client = cx
                .spawn(move |_client_cx| async move {
                    struct CancelServerOnDrop(Cx);

                    impl Drop for CancelServerOnDrop {
                        fn drop(&mut self) {
                            self.0.cancel_with(
                                CancelKind::User,
                                Some("repeated admission client exited"),
                            );
                        }
                    }

                    let _server_cancellation = CancelServerOnDrop(caller_cx);
                    let request = JsonRpcRequest::new(
                        SERVER_DISCOVER_METHOD,
                        Some(serde_json::json!({
                            "_meta": {
                                MODERN_PROTOCOL_VERSION_METADATA_KEY: MODERN_PROTOCOL_VERSION,
                                FINAL_CLIENT_CAPABILITIES_META_KEY: {},
                            },
                        })),
                        803_i64,
                    );
                    let body = serde_json::to_vec(&request).map_err(|error| {
                        format!("repeated admission request did not serialize: {error}")
                    })?;
                    let later_member_required = live_http_exchange(
                        address,
                        live_http_post(
                            "/mcp",
                            &body,
                            &[
                                ("Accept", "text/plain"),
                                ("Accept", "application/json"),
                                ("MCP-Protocol-Version", MODERN_PROTOCOL_VERSION),
                                ("Mcp-Method", SERVER_DISCOVER_METHOD),
                            ],
                        ),
                    )
                    .await?;
                    let accepted = live_http_exchange(
                        address,
                        live_http_post(
                            "/mcp",
                            &body,
                            &[
                                ("Accept", "application/json"),
                                ("Accept", "text/event-stream; q=0"),
                                ("MCP-Protocol-Version", MODERN_PROTOCOL_VERSION),
                                ("Mcp-Method", SERVER_DISCOVER_METHOD),
                            ],
                        ),
                    )
                    .await?;
                    let rejected = live_http_exchange(
                        address,
                        live_http_post(
                            "/mcp",
                            &body,
                            &[
                                ("Accept", "application/json"),
                                ("Accept", "text/event-stream; q=0"),
                                ("MCP-Protocol-Version", MODERN_PROTOCOL_VERSION),
                                ("Mcp-Method", SERVER_DISCOVER_METHOD),
                                ("Mcp-Method", SERVER_DISCOVER_METHOD),
                            ],
                        ),
                    )
                    .await?;
                    Ok::<_, String>((later_member_required, accepted, rejected))
                })
                .map_err(|error| format!("repeated admission client was not admitted: {error}"))?;

            let serve = bound.serve(&cx).await;
            let (later_member_required, accepted, rejected) = client
                .join(&cx)
                .await
                .map_err(|error| format!("repeated admission client failed: {error:?}"))??;
            let shutdown =
                serve.map_err(|error| format!("repeated admission server failed: {error}"))?;
            require_quiescent_http_shutdown(shutdown, "repeated admission").await?;

            if !later_member_required.starts_with(b"HTTP/1.1 200") {
                return Err(format!(
                    "a later valid repeated Accept member was not retained: {}",
                    String::from_utf8_lossy(&later_member_required)
                ));
            }
            if !accepted.starts_with(b"HTTP/1.1 200") {
                return Err(format!(
                    "wire-ordered repeated Accept fields used an unexpected response: {}",
                    String::from_utf8_lossy(&accepted)
                ));
            }
            if !rejected.starts_with(b"HTTP/1.1 400") {
                return Err(format!(
                    "changing only the repeated header name to a singleton used an unexpected response: {}",
                    String::from_utf8_lossy(&rejected)
                ));
            }
            Ok(())
        });
    }

    #[test]
    fn live_http_modern_sse_post_dispatches_without_discovery_or_session_id() {
        run_live_http_test(|cx| async move {
            let calls = Arc::new(AtomicUsize::new(0));
            let bound = Server::new("live-http-stateless-sse", "1.0.0")
                .protocol_policy(ProtocolPolicy::ModernOnly)
                .expect("ModernOnly must be available to this test build")
                .auth_provider(auth_00_mrtr_provider(true))
                .tool(LiveHttpMrtrTool {
                    name: "live_http_mrtr",
                    calls: Arc::clone(&calls),
                })
                .build()
                .bind_http(&cx, "127.0.0.1:0")
                .await
                .map_err(|error| format!("live HTTP MRTR bind failed: {error}"))?;
            let address = bound
                .local_addr()
                .map_err(|error| format!("live HTTP MRTR address failed: {error}"))?;
            let caller_cx = cx.clone();
            let mut client = cx
                .spawn(move |_client_cx| async move {
                    let initial = JsonRpcRequest::new(
                        "tools/call",
                        Some(serde_json::json!({
                            "name": "live_http_mrtr",
                            "arguments": {},
                            "_meta": {
                                MODERN_PROTOCOL_VERSION_METADATA_KEY: MODERN_PROTOCOL_VERSION,
                                FINAL_CLIENT_CAPABILITIES_META_KEY: {},
                                "progressToken": "live-http-mrtr-sse",
                            },
                        })),
                        922_i64,
                    );
                    let initial_body = serde_json::to_vec(&initial).map_err(|error| {
                        format!("MRTR initial request did not serialize: {error}")
                    })?;
                    let initial = live_http_exchange(
                        address,
                        live_http_post(
                            "/mcp",
                            &initial_body,
                            &[
                                ("Accept", "text/event-stream"),
                                ("MCP-Protocol-Version", MODERN_PROTOCOL_VERSION),
                                ("Mcp-Method", "tools/call"),
                                ("Mcp-Name", "live_http_mrtr"),
                                ("Authorization", "Bearer alpha"),
                            ],
                        ),
                    )
                    .await?;
                    caller_cx.cancel_with(
                        CancelKind::User,
                        Some("live HTTP stateless SSE request complete"),
                    );
                    Ok::<_, String>(initial)
                })
                .map_err(|error| format!("live HTTP MRTR client admission failed: {error}"))?;

            let serve = bound.serve(&cx).await;
            let response = client
                .join(&cx)
                .await
                .map_err(|error| format!("live HTTP MRTR client failed: {error:?}"))??;
            let shutdown =
                serve.map_err(|error| format!("live HTTP MRTR server failed: {error}"))?;
            require_quiescent_http_shutdown(shutdown, "live HTTP MRTR").await?;
            let response = live_http_sse_jsonrpc_response(&response)?;
            if response.id != Some(922_i64.into())
                || response.error.is_some()
                || response
                    .result
                    .as_ref()
                    .and_then(|result| result.get("resultType"))
                    != Some(&serde_json::json!("input_required"))
            {
                return Err(format!(
                    "sessionless modern SSE POST did not dispatch: {response:?}"
                ));
            }
            if calls.load(Ordering::Acquire) != 1 {
                return Err(
                    "sessionless modern SSE POST did not invoke the handler once".to_owned(),
                );
            }
            Ok(())
        });
    }

    #[test]
    fn live_http_modern_authorization_allows_native_bearer_once() {
        run_live_http_test(|cx| async move {
            let calls = Arc::new(AtomicUsize::new(0));
            let bound = Server::new("live-http-modern-authorization", "1.0.0")
                .protocol_policy(ProtocolPolicy::ModernOnly)
                .expect("ModernOnly must be available to this test build")
                .auth_provider(ModernHttpAuthProvider)
                .tool(ModernHttpAuthCounterTool {
                    calls: Arc::clone(&calls),
                })
                .build()
                .bind_http(&cx, "127.0.0.1:0")
                .await
                .map_err(|error| format!("live HTTP authorization bind failed: {error}"))?;
            let address = bound
                .local_addr()
                .map_err(|error| format!("live HTTP authorization address failed: {error}"))?;
            let request = modern_http_json_tool_request("modern_http_auth_counter", 935);
            let caller_cx = cx.clone();
            let mut client = cx
                .spawn(move |_client_cx| async move {
                    let response = live_http_exchange(
                        address,
                        live_http_post(
                            "/mcp",
                            &request.body,
                            &[
                                ("Accept", "application/json"),
                                ("Authorization", "Bearer alpha"),
                                ("MCP-Protocol-Version", MODERN_PROTOCOL_VERSION),
                                ("Mcp-Method", "tools/call"),
                                ("Mcp-Name", "modern_http_auth_counter"),
                            ],
                        ),
                    )
                    .await;
                    caller_cx.cancel_with(
                        CancelKind::User,
                        Some("live HTTP native bearer proof complete"),
                    );
                    response
                })
                .map_err(|error| {
                    format!("live HTTP authorization client admission failed: {error}")
                })?;
            let serve = bound.serve(&cx).await;
            let response = client
                .join(&cx)
                .await
                .map_err(|error| format!("live HTTP authorization client failed: {error:?}"))??;
            let shutdown =
                serve.map_err(|error| format!("live HTTP authorization server failed: {error}"))?;
            require_quiescent_http_shutdown(shutdown, "live HTTP native bearer").await?;
            let response: JsonRpcResponse =
                serde_json::from_slice(live_http_response_body(&response)?).map_err(|error| {
                    format!("live HTTP authorization response was not JSON-RPC: {error}")
                })?;
            if response.id != Some(935_i64.into()) || response.error.is_some() {
                return Err(format!(
                    "allowed native bearer did not dispatch: {response:?}"
                ));
            }
            if calls.load(Ordering::Acquire) != 1 {
                return Err(
                    "allowed native bearer did not invoke the handler exactly once".to_owned(),
                );
            }
            Ok(())
        });
    }

    #[test]
    fn live_http_native_authorization_rejects_before_owned_state_and_strips_valid_bearer() {
        run_live_http_test(|cx| async move {
            let handler_calls = Arc::new(AtomicUsize::new(0));
            let middleware_calls = Arc::new(AtomicUsize::new(0));
            let saw_credential = Arc::new(AtomicBool::new(false));
            let bound = Server::new("live-http-native-auth-admission", "1.0.0")
                .protocol_policy(ProtocolPolicy::ModernOnly)
                .expect("ModernOnly must be available to this test build")
                .auth_provider(ModernHttpAuthProvider)
                .middleware(ModernHttpAuthMiddleware {
                    calls: Arc::clone(&middleware_calls),
                    saw_credential: Arc::clone(&saw_credential),
                })
                .tool(ModernHttpAuthCounterTool {
                    calls: Arc::clone(&handler_calls),
                })
                .build()
                .bind_http(&cx, "127.0.0.1:0")
                .await
                .map_err(|error| format!("native auth admission bind failed: {error}"))?;
            let address = bound
                .local_addr()
                .map_err(|error| format!("native auth admission address failed: {error}"))?;
            let request = modern_http_json_tool_request("modern_http_auth_counter", 936);
            let caller_cx = cx.clone();
            let mut client = cx
                .spawn(move |_client_cx| async move {
                    let common = [
                        ("Accept", "application/json"),
                        ("MCP-Protocol-Version", MODERN_PROTOCOL_VERSION),
                        ("Mcp-Method", "tools/call"),
                        ("Mcp-Name", "modern_http_auth_counter"),
                    ];
                    let result = async {
                        let missing = live_http_exchange(
                            address,
                            live_http_post("/mcp", &request.body, &common),
                        )
                        .await?;
                        let invalid = live_http_exchange(
                            address,
                            live_http_post(
                                "/mcp",
                                &request.body,
                                &[
                                    ("Authorization", "Bearer invalid-never-echo"),
                                    ("Accept", "application/json"),
                                    ("MCP-Protocol-Version", MODERN_PROTOCOL_VERSION),
                                    ("Mcp-Method", "tools/call"),
                                    ("Mcp-Name", "modern_http_auth_counter"),
                                ],
                            ),
                        )
                        .await?;
                        let malformed = live_http_exchange(
                            address,
                            live_http_post(
                                "/mcp",
                                &request.body,
                                &[
                                    ("Authorization", "Bearer"),
                                    ("Accept", "application/json"),
                                    ("MCP-Protocol-Version", MODERN_PROTOCOL_VERSION),
                                    ("Mcp-Method", "tools/call"),
                                    ("Mcp-Name", "modern_http_auth_counter"),
                                ],
                            ),
                        )
                        .await?;
                        let duplicate = live_http_exchange(
                            address,
                            live_http_post(
                                "/mcp",
                                &request.body,
                                &[
                                    ("Authorization", "Bearer alpha"),
                                    ("aUtHoRiZaTiOn", "Bearer beta"),
                                    ("Accept", "application/json"),
                                    ("MCP-Protocol-Version", MODERN_PROTOCOL_VERSION),
                                    ("Mcp-Method", "tools/call"),
                                    ("Mcp-Name", "modern_http_auth_counter"),
                                ],
                            ),
                        )
                        .await?;
                        let accepted = live_http_exchange(
                            address,
                            live_http_post(
                                "/mcp",
                                &request.body,
                                &[
                                    ("Authorization", "Bearer alpha"),
                                    ("Accept", "application/json"),
                                    ("MCP-Protocol-Version", MODERN_PROTOCOL_VERSION),
                                    ("Mcp-Method", "tools/call"),
                                    ("Mcp-Name", "modern_http_auth_counter"),
                                ],
                            ),
                        )
                        .await?;
                        Ok::<_, String>((missing, invalid, malformed, duplicate, accepted))
                    }
                    .await;
                    caller_cx.cancel_with(
                        CancelKind::User,
                        Some("native HTTP authorization admission proof complete"),
                    );
                    result
                })
                .map_err(|error| {
                    format!("native auth admission client admission failed: {error}")
                })?;
            let serve = bound.serve(&cx).await;
            let (missing, invalid, malformed, duplicate, accepted) = client
                .join(&cx)
                .await
                .map_err(|error| format!("native auth admission client failed: {error:?}"))??;
            let shutdown =
                serve.map_err(|error| format!("native auth admission server failed: {error}"))?;
            require_quiescent_http_shutdown(shutdown, "native HTTP authorization admission")
                .await?;
            for (label, response) in [
                ("missing", missing),
                ("invalid", invalid),
                ("malformed", malformed),
                ("duplicate", duplicate),
            ] {
                if !response.starts_with(b"HTTP/1.1 401")
                    || live_http_response_header(&response, "www-authenticate")? != "Bearer"
                    || std::str::from_utf8(&response)
                        .map_err(|error| format!("{label} auth response was not UTF-8: {error}"))?
                        .contains("invalid-never-echo")
                {
                    return Err(format!(
                        "{label} native Authorization was not a bounded pre-dispatch 401"
                    ));
                }
            }
            let accepted: JsonRpcResponse =
                serde_json::from_slice(live_http_response_body(&accepted)?).map_err(|error| {
                    format!("valid native Authorization did not return JSON-RPC: {error}")
                })?;
            if accepted.error.is_some()
                || handler_calls.load(Ordering::Acquire) != 1
                || middleware_calls.load(Ordering::Acquire) != 1
                || saw_credential.load(Ordering::Acquire)
            {
                return Err(
                    "native Authorization admission mutated owned state or leaked bearer"
                        .to_owned(),
                );
            }
            Ok(())
        });
    }

    #[derive(Clone)]
    struct HttpHeaderAuthProbe {
        provider: Arc<auth::TokenAuthProvider>,
        provider_calls: Arc<AtomicUsize>,
        middleware_calls: Arc<AtomicUsize>,
        handler_calls: Arc<AtomicUsize>,
        token: String,
        subject: String,
    }

    impl HttpHeaderAuthProbe {
        fn new() -> Self {
            let nonce = std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .expect("test clock must follow the Unix epoch")
                .as_nanos();
            let token = format!("auth01-{}-{nonce}", std::process::id());
            let subject = format!("http-principal-{nonce}");
            let verifier = auth::StaticTokenVerifier::new([(
                token.clone(),
                AuthContext::with_subject(subject.clone()),
            )])
            .expect("runtime-selected static credential must be admissible");
            Self {
                provider: Arc::new(auth::TokenAuthProvider::new(verifier)),
                provider_calls: Arc::new(AtomicUsize::new(0)),
                middleware_calls: Arc::new(AtomicUsize::new(0)),
                handler_calls: Arc::new(AtomicUsize::new(0)),
                token,
                subject,
            }
        }

        fn effects(&self) -> (usize, usize, usize) {
            (
                self.provider_calls.load(Ordering::Acquire),
                self.middleware_calls.load(Ordering::Acquire),
                self.handler_calls.load(Ordering::Acquire),
            )
        }
    }

    impl AuthProvider for HttpHeaderAuthProbe {
        fn authenticate(
            &self,
            ctx: &McpContext,
            request: AuthRequest<'_>,
        ) -> McpResult<AuthContext> {
            self.provider_calls.fetch_add(1, Ordering::AcqRel);
            self.provider.authenticate(ctx, request)
        }
    }

    impl Middleware for HttpHeaderAuthProbe {
        fn on_request(
            &self,
            ctx: &McpContext,
            request: &JsonRpcRequest,
        ) -> McpResult<MiddlewareDecision> {
            self.middleware_calls.fetch_add(1, Ordering::AcqRel);
            let serialized = serde_json::to_string(request)
                .map_err(|error| McpError::internal_error(error.to_string()))?;
            if serialized.contains(&self.token)
                || ctx.auth().and_then(|auth| auth.subject).as_deref() != Some(&self.subject)
            {
                return Err(McpError::internal_error(
                    "HTTP credential custody or principal changed",
                ));
            }
            Ok(MiddlewareDecision::Continue)
        }
    }

    impl ToolHandler for HttpHeaderAuthProbe {
        fn definition(&self) -> Tool {
            Tool {
                name: "http_header_auth_probe".to_owned(),
                description: None,
                input_schema: serde_json::json!({"type": "object"}),
                output_schema: None,
                icon: None,
                version: None,
                tags: Vec::new(),
                annotations: None,
            }
        }

        fn call(&self, ctx: &McpContext, arguments: serde_json::Value) -> McpResult<Vec<Content>> {
            self.handler_calls.fetch_add(1, Ordering::AcqRel);
            if arguments
                != serde_json::json!({"token": "application-data", "access_token": "application-data"})
            {
                return Err(McpError::internal_error(
                    "application arguments changed during authentication",
                ));
            }
            Ok(vec![Content::text(
                ctx.auth().and_then(|auth| auth.subject).unwrap_or_default(),
            )])
        }
    }

    fn require_http_credential_location_rejection(
        response: &[u8],
        token: &str,
    ) -> Result<(), String> {
        if !response.starts_with(b"HTTP/1.1 401")
            || live_http_response_header(response, "www-authenticate")? != "Bearer"
            || response
                .windows(token.len())
                .any(|window| window == token.as_bytes())
        {
            return Err("credential location did not produce a secret-free HTTP 401".to_owned());
        }
        let body: serde_json::Value = serde_json::from_slice(live_http_response_body(response)?)
            .map_err(|error| error.to_string())?;
        if body
            != serde_json::json!({
                "error": "invalid_request",
                "message": "HTTP credentials must use the Authorization header",
            })
        {
            return Err(
                "credential location rejection lost its fixed migration message".to_owned(),
            );
        }
        Ok(())
    }

    #[cfg(feature = "tasks")]
    struct AuthTaskSupervisor;

    #[cfg(feature = "tasks")]
    impl ApplicationTaskSupervisor for AuthTaskSupervisor {
        fn resume<'a>(
            &'a self,
            _cx: &'a Cx,
            handoff: FinalTaskSupervisorHandoff,
        ) -> FinalTaskSupervisorFuture<'a> {
            Box::pin(async move {
                match handoff {
                    FinalTaskSupervisorHandoff::Initial(initial) => {
                        initial.require_input(
                            serde_json::from_value(
                                serde_json::json!({"roots": {"method": "roots/list"}}),
                            )
                            .unwrap(),
                            None,
                        )?;
                    }
                    FinalTaskSupervisorHandoff::Resumed(accepted) => {
                        accepted.complete_task(serde_json::from_value(serde_json::json!({"content": [{"type": "text", "text": "owner input consumed"}]})).unwrap(), None)?;
                    }
                }
                Ok(())
            })
        }
    }

    #[cfg(feature = "tasks")]
    fn auth_task_http_frame(request: &JsonRpcRequest, authorization: &str) -> Vec<u8> {
        let mut headers = vec![
            (
                "Accept",
                if request.method == SUBSCRIPTIONS_LISTEN {
                    "text/event-stream"
                } else {
                    "application/json"
                },
            ),
            ("Authorization", authorization),
            ("MCP-Protocol-Version", MODERN_PROTOCOL_VERSION),
            ("Mcp-Method", request.method.as_str()),
        ];
        if request.method == "tools/call" {
            headers.push(("Mcp-Name", "durable_final_task"));
        } else if let Some(task_id) = request
            .params
            .as_ref()
            .and_then(|params| params.get("taskId"))
            .and_then(serde_json::Value::as_str)
        {
            headers.push(("Mcp-Name", task_id));
        }
        live_http_post("/mcp", &serde_json::to_vec(request).unwrap(), &headers)
    }

    #[cfg(feature = "tasks")]
    async fn auth_task_http_rpc(
        address: SocketAddr,
        request: &JsonRpcRequest,
        authorization: &str,
    ) -> Result<JsonRpcResponse, String> {
        let frame =
            live_http_exchange(address, auth_task_http_frame(request, authorization)).await?;
        let response = if live_http_response_header(&frame, "content-type")?
            .starts_with("text/event-stream")
        {
            live_http_sse_jsonrpc_response(&frame)?
        } else {
            serde_json::from_slice(live_http_response_body(&frame)?)
                .map_err(|error| error.to_string())?
        };
        eprintln!(
            "{}",
            serde_json::json!({"proof": "auth_00_local_task_owner", "method": request.method, "response": response, "frame_sha256": sha256_bounded(&frame, 65_536).unwrap().as_bytes()})
        );
        Ok(response)
    }

    #[cfg(feature = "tasks")]
    fn auth_00_local_task_owner_probe(plant_foreign_caller: bool) {
        run_live_http_test(move |cx| async move {
            let subject = format!(
                "task-owner-{}",
                std::time::SystemTime::now()
                    .duration_since(std::time::UNIX_EPOCH)
                    .unwrap()
                    .as_nanos()
            );
            let mut refreshed = AuthContext::with_subject(subject.clone());
            refreshed.scopes = vec!["tasks".to_owned()];
            let verifier = StaticTokenVerifier::new([
                ("owner-first", AuthContext::with_subject(subject.clone())),
                ("owner-refreshed", refreshed),
                (
                    "foreign-valid",
                    AuthContext::with_subject(format!("foreign-{subject}")),
                ),
            ])
            .map_err(|error| error.to_string())?;
            let store = Arc::new(tasks::InMemoryFinalTaskStore::default());
            let task_runtime = FinalTaskRuntime::new(
                store.clone(),
                FinalTaskRuntimeConfig::new(60_000, Some(5_000)).unwrap(),
                Arc::new(|_| {}),
            );
            let runner = task_runtime
                .install_task_service(1, Arc::new(AuthTaskSupervisor))
                .map_err(|error| error.to_string())?;
            let scope = cx.scope();
            let mut service = cx
                .spawn_in(&scope, move |service_cx| async move {
                    runner.run(&service_cx).await
                })
                .map_err(|error| error.to_string())?;
            let ready_deadline = cx.now().saturating_add_nanos(LIVE_HTTP_TEST_TIMEOUT_NANOS);
            while !task_runtime.is_task_service_ready() {
                if cx.now() >= ready_deadline {
                    return Err("task service did not become ready".to_owned());
                }
                asupersync::runtime::yield_now().await;
            }
            let bound = Server::new("auth-task-owner", "1.0.0")
                .protocol_policy(ProtocolPolicy::ModernOnly)
                .unwrap()
                .auth_provider(TokenAuthProvider::new(verifier))
                .tool(FinalTaskCreatingTool)
                .final_tasks(task_runtime.clone())
                .unwrap()
                .build()
                .bind_http(&cx, "127.0.0.1:0")
                .await
                .map_err(|error| error.to_string())?;
            let address = bound.local_addr().map_err(|error| error.to_string())?;
            let task_server = Arc::clone(&bound.endpoint.server);
            let caller_cx = cx.clone();
            let mut client = cx.spawn(move |client_cx| async move {
                struct CancelServerOnDrop(Cx);
                impl Drop for CancelServerOnDrop {
                    fn drop(&mut self) {
                        self.0.cancel_with(CancelKind::User, Some("task owner probe exited"));
                    }
                }
                let _shutdown = CancelServerOnDrop(caller_cx.clone());
                let result = async {
                    let mut streams = Vec::new();
                    for method in [fastmcp_protocol::tasks_extension::TASK_UPDATE, fastmcp_protocol::TASK_CANCEL] {
                        let created = auth_task_http_rpc(address, &final_task_creating_tool_request(true), "Bearer owner-first").await?;
                        let created = created.result.ok_or_else(|| format!("authenticated task creation failed: {:?}", created.error))?;
                        let task_id = fastmcp_protocol::FinalTaskId::parse(created["taskId"].as_str().ok_or("task handle missing")?).map_err(|error| error.to_string())?;
                        let deadline = client_cx.now().saturating_add_nanos(LIVE_HTTP_TEST_TIMEOUT_NANOS);
                        loop {
                            if matches!(task_runtime.get_task(&task_id).unwrap().task, fastmcp_protocol::Task::InputRequired { .. }) { break; }
                            if client_cx.now() >= deadline { return Err("application did not request task input".to_owned()); }
                            asupersync::time::sleep(client_cx.now(), Duration::from_millis(5)).await;
                        }
                        let params = final_tasks_params(&task_id, serde_json::json!({}));
                        let get = JsonRpcRequest::new(fastmcp_protocol::TASK_GET, Some(params.clone()), 951_i64);
                        let mut update_params = params.clone();
                        update_params["inputResponses"] = serde_json::json!({"roots": {"roots": []}});
                        let update = JsonRpcRequest::new(fastmcp_protocol::tasks_extension::TASK_UPDATE, Some(update_params), 952_i64);
                        let cancel = JsonRpcRequest::new(fastmcp_protocol::TASK_CANCEL, Some(params.clone()), 953_i64);
                        let mut notifications = SubscriptionFilter::default();
                        set_task_subscription_ids(&mut notifications, vec![task_id.clone()]).unwrap();
                        let listen = JsonRpcRequest::new(SUBSCRIPTIONS_LISTEN, Some(serde_json::json!({"_meta": params["_meta"], "notifications": notifications})), 954_i64);
                        if plant_foreign_caller {
                            let before = store.get_task_snapshot(&task_id).unwrap().unwrap();
                            let notification_before = serde_json::to_value(store.latest_notification(&task_id)).unwrap();
                            for request in [&get, &update, &cancel, &listen] {
                                let foreign = auth_task_http_rpc(address, request, "Bearer foreign-valid").await?;
                                let mut missing = request.clone();
                                if request.method == SUBSCRIPTIONS_LISTEN {
                                    let mut absent_filter = SubscriptionFilter::default();
                                    set_task_subscription_ids(&mut absent_filter, vec![fastmcp_protocol::FinalTaskId::parse("absent-task").unwrap()]).unwrap();
                                    missing.params.as_mut().unwrap()["notifications"] = serde_json::to_value(absent_filter).unwrap();
                                } else {
                                    missing.params.as_mut().unwrap()["taskId"] = serde_json::json!("absent-task");
                                }
                                let absent = auth_task_http_rpc(address, &missing, "Bearer foreign-valid").await?;
                                assert!(foreign.result.is_none());
                                assert_eq!(serde_json::to_value(&foreign.error).unwrap(), serde_json::to_value(&absent.error).unwrap());
                                assert_eq!(foreign.error.unwrap().message, "Task not found");
                                let after = store.get_task_snapshot(&task_id).unwrap().unwrap();
                                assert_eq!(after.generation(), before.generation());
                                assert_eq!(serde_json::to_value(after.task()).unwrap(), serde_json::to_value(before.task()).unwrap());
                                assert_eq!(after.authenticated_principal(), before.authenticated_principal());
                                assert_eq!(serde_json::to_value(store.latest_notification(&task_id)).unwrap(), notification_before);
                                assert!(!store.is_cancellation_requested(&task_id).unwrap());
                                assert!(store.next_accepted_input_snapshot().unwrap().is_none());
                            }
                        }
                        let read = auth_task_http_rpc(address, &get, "Bearer owner-refreshed").await?;
                        assert!(read.error.is_none());
                        assert_eq!(read.result.unwrap()["taskId"], serde_json::json!(task_id));
                        let mut stream = AsyncTcpStream::connect(address).await.map_err(|error| error.to_string())?;
                        stream.write_all(&auth_task_http_frame(&listen, "Bearer owner-refreshed")).await.map_err(|error| error.to_string())?;
                        stream.flush().await.map_err(|error| error.to_string())?;
                        let mut received = Vec::new();
                        read_live_http_until(&mut stream, &mut received, b"notifications/subscriptions/acknowledged").await?;
                        let control = if method == fastmcp_protocol::tasks_extension::TASK_UPDATE { &update } else { &cancel };
                        let controlled = auth_task_http_rpc(address, control, "Bearer owner-refreshed").await?;
                        assert!(controlled.error.is_none());
                        assert_eq!(controlled.result.unwrap()["resultType"], "complete");
                        let terminal = if method == fastmcp_protocol::tasks_extension::TASK_UPDATE { "completed" } else { "cancelled" };
                        read_live_http_until(&mut stream, &mut received, format!("\"status\":\"{terminal}\"").as_bytes()).await?;
                        streams.push((stream, received, task_id, terminal));
                    }
                    assert_eq!(task_server.terminate_subscription_streams(), 2);
                    for (mut stream, mut received, task_id, terminal) in streams {
                        read_live_http_to_end(&mut stream, &mut received, "owner subscription terminal EOF").await?;
                        let messages = live_http_chunked_sse_messages(&received)?;
                        let Some(JsonRpcMessage::Request(acknowledgement)) = messages.first() else { panic!("missing subscription acknowledgement"); };
                        let ServerNotification::SubscriptionsAcknowledged(acknowledgement) = ServerNotification::decode(acknowledgement).unwrap() else { panic!("first event must acknowledge subscription"); };
                        assert_eq!(task_subscription_ids(&acknowledgement.notifications).unwrap().unwrap(), vec![task_id.clone()]);
                        let events = messages.iter().filter_map(|message| {
                            let JsonRpcMessage::Request(request) = message else { return None; };
                            (request.method == fastmcp_protocol::TASK_STATUS_NOTIFICATION).then(|| serde_json::from_value::<FinalTaskStatusNotification>(serde_json::to_value(request).unwrap()).unwrap())
                        }).collect::<Vec<_>>();
                        assert!(!events.is_empty());
                        assert!(events.iter().all(|event| event.params.task.base().task_id == task_id));
                        let terminal_events = events.iter().filter(|event| serde_json::to_value(&event.params.task).unwrap()["status"] == terminal).collect::<Vec<_>>();
                        assert_eq!(terminal_events.len(), 1);
                        if terminal == "completed" {
                            let task = serde_json::to_value(&terminal_events[0].params.task).unwrap();
                            assert_eq!(task["result"]["content"][0]["text"], "owner input consumed");
                        }
                        eprintln!("{}", serde_json::json!({"proof": "auth_00_local_task_owner", "subject": subject, "task_id": task_id, "terminal": terminal, "subscription_events": events.len(), "subscription_frame_sha256": sha256_bounded(&received, 65_536).unwrap().as_bytes(), "negative": plant_foreign_caller}));
                    }
                    Ok::<_, String>(())
                }.await;
                caller_cx.cancel_with(CancelKind::User, Some("task owner probe complete"));
                result
            }).map_err(|error| error.to_string())?;
            let serve = bound.serve(&cx).await;
            // The application service has its own context. Cancelling the
            // HTTP caller does not stop that context or its idle receiver.
            service.abort();
            let client_result = client
                .join(&cx)
                .await
                .map_err(|error| format!("task owner client failed: {error:?}"));
            let mut service_shutdown = Box::pin(asupersync::time::timeout_at(
                cx.now().saturating_add_nanos(LIVE_HTTP_TEST_TIMEOUT_NANOS),
                service.join(&cx),
            ));
            // Keep the real cleanup deadline while shielding its timer from
            // the caller's cancellation. The service's own abort stays active.
            let service_result = std::future::poll_fn(|task_context| {
                cx.masked(|| service_shutdown.as_mut().poll(task_context))
            })
            .await
            .map_err(|_| live_http_test_timeout("task owner service shutdown"))?;
            match service_result {
                Ok(Ok(())) | Err(asupersync::runtime::JoinError::Cancelled(_)) => {}
                other => return Err(format!("task service failed during owner probe: {other:?}")),
            }
            client_result??;
            require_quiescent_http_shutdown(serve.map_err(|error| error.to_string())?, "task owner")
                .await
        });
    }

