    #[test]
    fn live_http_loopback_preserves_exact_legacy_sse_and_post_lifecycle() {
        run_live_http_test(|cx| async move {
            let bound = Server::new("live-legacy-http", "1.0.0")
                .tool(LiveRuntimeListedTool)
                .http_config(
                    HttpServerConfig::new()
                        .mcp_path("/bridge")
                        .legacy_sse_path("/bridge"),
                )
                .build()
                .bind_http(&cx, "127.0.0.1:0")
                .await
                .map_err(|error| format!("live legacy HTTP bind failed: {error}"))?;
            let address = bound
                .local_addr()
                .map_err(|error| format!("live legacy HTTP address failed: {error}"))?;
            let caller_cx = cx.clone();
            let mut client = cx
                .spawn(move |_client_cx| async move {
                    let modern = JsonRpcRequest::new(
                        SERVER_DISCOVER_METHOD,
                        Some(serde_json::json!({
                            "_meta": {
                                MODERN_PROTOCOL_VERSION_METADATA_KEY: MODERN_PROTOCOL_VERSION,
                                FINAL_CLIENT_CAPABILITIES_META_KEY: {},
                            },
                        })),
                        810_i64,
                    );
                    let modern_body = serde_json::to_vec(&modern)
                        .map_err(|error| format!("shared-target modern request failed: {error}"))?;
                    let modern = live_http_exchange(
                        address,
                        live_http_post(
                            "/bridge",
                            &modern_body,
                            &[
                                ("Accept", "application/json"),
                                ("MCP-Protocol-Version", MODERN_PROTOCOL_VERSION),
                                ("MCP-Method", SERVER_DISCOVER_METHOD),
                            ],
                        ),
                    )
                    .await?;
                    if !modern.starts_with(b"HTTP/1.1 200") {
                        return Err(format!(
                            "shared-target modern POST did not select final HTTP: {modern:?}"
                        ));
                    }

                    let mut stream = AsyncTcpStream::connect(address)
                        .await
                        .map_err(|error| format!("legacy SSE connect failed: {error}"))?;
                    stream
                        .write_all(
                            format!(
                                "GET /bridge HTTP/1.1\r\nHost: {address}\r\nAccept: text/event-stream\r\nConnection: keep-alive\r\n\r\n"
                            )
                            .as_bytes(),
                        )
                        .await
                        .map_err(|error| format!("legacy SSE request write failed: {error}"))?;
                    stream
                        .flush()
                        .await
                        .map_err(|error| format!("legacy SSE request flush failed: {error}"))?;

                    let mut received = Vec::new();
                    let endpoint_prefix = format!(
                        "data: http://{address}/messages?session_id="
                    );
                    read_live_http_until(&mut stream, &mut received, endpoint_prefix.as_bytes())
                        .await?;
                    let received_text = std::str::from_utf8(&received)
                        .map_err(|error| format!("legacy SSE endpoint was not UTF-8: {error}"))?;
                    let session_id = received_text
                        .split_once(&endpoint_prefix)
                        .and_then(|(_, remainder)| remainder.split_whitespace().next())
                        .ok_or_else(|| "legacy SSE endpoint omitted its session identifier".to_string())?
                        .to_owned();

                    let initialize = JsonRpcRequest::new(
                        "initialize",
                        Some(serde_json::json!({
                            "protocolVersion": LEGACY_PROTOCOL_VERSION,
                            "capabilities": {},
                            "clientInfo": {"name": "loopback-legacy-client", "version": "1.0.0"},
                        })),
                        811_i64,
                    );
                    let initialized = JsonRpcRequest::notification("notifications/initialized", None);
                    let call = JsonRpcRequest::new(
                        "tools/call",
                        Some(serde_json::json!({
                            "name": "live_runtime_listed_tool",
                            "arguments": {},
                        })),
                        812_i64,
                    );
                    for message in [initialize, initialized] {
                        let body = serde_json::to_vec(&message).map_err(|error| {
                            format!("legacy loopback request did not serialize: {error}")
                        })?;
                        let response = live_http_exchange(
                            address,
                            live_http_post(
                                &format!("/messages?session_id={session_id}"),
                                &body,
                                &[],
                            ),
                        )
                        .await?;
                        let response = std::str::from_utf8(&response).map_err(|error| {
                            format!("legacy POST response was not UTF-8: {error}")
                        })?;
                        if !response.starts_with("HTTP/1.1 202") {
                            return Err(format!("legacy POST was not accepted: {response}"));
                        }
                    }

                    let call_body = serde_json::to_vec(&call).map_err(|error| {
                        format!("legacy loopback tool request did not serialize: {error}")
                    })?;
                    let wrong_session = live_http_exchange(
                        address,
                        live_http_post(
                            "/messages?session_id=wrong-session",
                            &call_body,
                            &[],
                        ),
                    )
                    .await?;
                    let wrong_session = std::str::from_utf8(&wrong_session).map_err(|error| {
                        format!("wrong-session legacy response was not UTF-8: {error}")
                    })?;
                    if !wrong_session.starts_with("HTTP/1.1 404") {
                        return Err(format!(
                            "changing only the legacy session ID was not rejected: {wrong_session}"
                        ));
                    }

                    let accepted = live_http_exchange(
                        address,
                        live_http_post(
                            &format!("/messages?session_id={session_id}"),
                            &call_body,
                            &[],
                        ),
                    )
                    .await?;
                    let accepted = std::str::from_utf8(&accepted).map_err(|error| {
                        format!("correct-session legacy response was not UTF-8: {error}")
                    })?;
                    if !accepted.starts_with("HTTP/1.1 202") {
                        return Err(format!(
                            "the unchanged exact legacy session did not accept the valid request: {accepted}"
                        ));
                    }

                    read_live_http_until(&mut stream, &mut received, br#""id":812"#).await?;
                    let received = std::str::from_utf8(&received)
                        .map_err(|error| format!("legacy SSE response was not UTF-8: {error}"))?;
                    if !received.contains(LEGACY_PROTOCOL_VERSION)
                        || !received.contains("live runtime legacy adapter request 812")
                        || received.contains("\"resultType\"")
                    {
                        return Err(format!("legacy SSE lifecycle was not exact: {received}"));
                    }
                    caller_cx.cancel_with(CancelKind::User, Some("legacy loopback complete"));
                    Ok(())
                })
                .map_err(|error| format!("legacy loopback client admission failed: {error}"))?;

            let serve = bound.serve(&cx).await;
            let client = client
                .join(&cx)
                .await
                .map_err(|error| format!("legacy loopback client failed: {error:?}"))?;
            let shutdown =
                serve.map_err(|error| format!("legacy loopback server failed: {error}"))?;
            require_quiescent_http_shutdown(shutdown, "legacy loopback").await?;
            client
        });
    }

    async fn live_http_legacy_reverse_response_post_probe(
        cx: &Cx,
        wrong_reverse_response_id: bool,
        plant_exact_admission_negatives: bool,
        reverse_response_token: Option<&'static str>,
        async_handler: bool,
    ) -> Result<(), String> {
        const INITIALIZE_ID: i64 = 842;
        const TOOL_CALL_ID: i64 = 843;

        // The synchronous tool bridges `ctx.sample` with `block_on` from its
        // `call` method, which is the obvious user code (bd-6rfrg). The async
        // tool awaits it on the caller-owned path instead.
        let server = Server::new("live-http-legacy-reverse-response", "1.0.0");
        let server = if async_handler {
            server.tool(LiveLegacyReverseResponseAsyncTool)
        } else {
            server.tool(LiveLegacyRuntimeConnectionTool)
        };
        let server = if reverse_response_token.is_some() {
            let verifier = StaticTokenVerifier::new([
                ("alpha", AuthContext::with_subject("alice")),
                ("beta", AuthContext::with_subject("bob")),
            ])
            .map_err(|error| format!("legacy reverse-response verifier failed: {error}"))?
            .with_allowed_schemes(["Bearer"])
            .map_err(|error| format!("legacy reverse-response scheme failed: {error}"))?;
            server.auth_provider(TokenAuthProvider::new(verifier))
        } else {
            server
        };
        let bound = server
            .build()
            .bind_http(cx, "127.0.0.1:0")
            .await
            .map_err(|error| format!("legacy reverse-response HTTP bind failed: {error}"))?;
        let address = bound
            .local_addr()
            .map_err(|error| format!("legacy reverse-response address failed: {error}"))?;
        let caller_cx = cx.clone();
        let mut client = cx
            .spawn(move |client_cx| async move {
                let opener_headers = reverse_response_token
                    .map(|_| vec![("Authorization", "Bearer alpha")])
                    .unwrap_or_default();
                let (mut sse, session_id, mut received) =
                    open_live_legacy_http_session(address, &opener_headers).await?;
                for request in [
                    JsonRpcRequest::new(
                        "initialize",
                        Some(serde_json::json!({
                            "protocolVersion": LEGACY_PROTOCOL_VERSION,
                            "capabilities": {"sampling": {}},
                            "clientInfo": {
                                "name": "legacy-reverse-response-client",
                                "version": "1.0.0"
                            },
                        })),
                        INITIALIZE_ID,
                    ),
                    JsonRpcRequest::notification("notifications/initialized", None),
                ] {
                    let body = serde_json::to_vec(&request).map_err(|error| {
                        format!("legacy reverse-response setup did not serialize: {error}")
                    })?;
                    let response = live_http_exchange(
                        address,
                        live_http_post(
                            &format!("/messages?session_id={session_id}"),
                            &body,
                            &opener_headers,
                        ),
                    )
                    .await?;
                    if !response.starts_with(b"HTTP/1.1 202") {
                        return Err(format!(
                            "legacy reverse-response setup was not accepted: {response:?}"
                        ));
                    }
                }

                let tool_call = JsonRpcRequest::new(
                    "tools/call",
                    Some(serde_json::json!({
                        "name": "live_legacy_runtime_connection_tool",
                        "arguments": {"sample": true},
                    })),
                    TOOL_CALL_ID,
                );
                let tool_call_body = serde_json::to_vec(&tool_call).map_err(|error| {
                    format!("legacy sampling tool call did not serialize: {error}")
                })?;
                let tool_call_request = live_http_post(
                    &format!("/messages?session_id={session_id}"),
                    &tool_call_body,
                    &opener_headers,
                );
                let mut tool_call = client_cx
                    .spawn(move |_tool_call_cx| async move {
                        live_http_exchange(address, tool_call_request).await
                    })
                    .map_err(|error| {
                        format!("legacy sampling tool-call POST was not admitted: {error}")
                    })?;

                read_live_http_until(&mut sse, &mut received, b"\"method\":\"sampling/createMessage\"")
                    .await?;
                let received_text = std::str::from_utf8(&received).map_err(|error| {
                    format!("legacy sampling reverse request was not UTF-8: {error}")
                })?;
                let sampling_offset = received_text
                    .find("\"method\":\"sampling/createMessage\"")
                    .ok_or_else(|| "legacy sampling reverse request was not retained".to_string())?;
                let event_start = received_text[..sampling_offset]
                    .rfind("data: ")
                    .ok_or_else(|| "legacy sampling reverse request omitted SSE data".to_string())?;
                let event = &received_text[event_start + "data: ".len()..];
                let (event, _) = event
                    .split_once("\n\n")
                    .ok_or_else(|| "legacy sampling reverse request was not one SSE event".to_string())?;
                let JsonRpcMessage::Request(reverse_request) = Codec::new()
                    .decode_complete_message(event.as_bytes())
                    .map_err(|error| {
                        format!("legacy sampling reverse request was not JSON-RPC: {error}")
                    })?
                else {
                    return Err("legacy sampling reverse event was not a request".to_string());
                };
                let reverse_request_id = reverse_request
                    .id
                    .ok_or_else(|| "legacy sampling reverse request omitted its ID".to_string())?;
                let response_id = if wrong_reverse_response_id {
                    // The only behavioral change in the near-identical
                    // negative is this correlation ID.
                    RequestId::Number(-2)
                } else {
                    reverse_request_id
                };
                let mut sampling_result = serde_json::to_value(
                    fastmcp_protocol::CreateMessageResult::text(
                        "http-sampled-value",
                        "legacy-http-test-model",
                    ),
                )
                .map_err(|error| format!("legacy sampling response did not serialize: {error}"))?;
                sampling_result["_meta"] =
                    serde_json::json!({"com.example/application": true});

                if plant_exact_admission_negatives {
                    let accepted = serde_json::json!({
                        "jsonrpc": "2.0",
                        "id": response_id.clone(),
                        "result": sampling_result.clone(),
                    });
                    let mut result_type = accepted.clone();
                    result_type["result"]["resultType"] = serde_json::json!("complete");
                    let mut final_metadata = accepted.clone();
                    final_metadata["result"]["_meta"]
                        ["io.modelcontextprotocol/protocolVersion"] =
                        serde_json::json!(LEGACY_PROTOCOL_VERSION);
                    for (dimension, body, headers) in [
                        (
                            "final resultType",
                            serde_json::to_vec(&result_type).map_err(|error| error.to_string())?,
                            Vec::new(),
                        ),
                        (
                            "final reserved metadata",
                            serde_json::to_vec(&final_metadata)
                                .map_err(|error| error.to_string())?,
                            Vec::new(),
                        ),
                        (
                            "modern binding header",
                            serde_json::to_vec(&accepted).map_err(|error| error.to_string())?,
                            vec![("MCP-Protocol-Version", MODERN_PROTOCOL_VERSION)],
                        ),
                    ] {
                        let rejected = live_http_exchange(
                            address,
                            live_http_post(
                                &format!("/messages?session_id={session_id}"),
                                &body,
                                if opener_headers.is_empty() {
                                    &headers
                                } else {
                                    &opener_headers
                                },
                            ),
                        )
                        .await?;
                        if !rejected.starts_with(b"HTTP/1.1 400") {
                            return Err(format!(
                                "{dimension} reached the pending reverse waiter: {rejected:?}"
                            ));
                        }
                    }
                }
                let reverse_response = JsonRpcResponse::success(response_id, sampling_result);
                let reverse_body = serde_json::to_vec(&reverse_response).map_err(|error| {
                    format!("legacy sampling reverse response did not serialize: {error}")
                })?;
                let reverse_authorization = reverse_response_token
                    .map(|token| format!("Bearer {token}"));
                let reverse_headers = reverse_authorization
                    .as_deref()
                    .map(|authorization| vec![("Authorization", authorization)])
                    .unwrap_or_default();
                let reverse_post = live_http_post(
                    &format!("/messages?session_id={session_id}"),
                    &reverse_body,
                    &reverse_headers,
                );
                let mut reverse_post = client_cx
                    .spawn(move |_reverse_cx| async move { live_http_exchange(address, reverse_post).await })
                    .map_err(|error| {
                        format!("legacy sampling reverse-response POST was not admitted: {error}")
                    })?;

                if wrong_reverse_response_id {
                    // Observe the task without entering and then abandoning a
                    // join future. Cancellation of a timed join can itself
                    // alter the child task's authority, which would make this
                    // planted negative interfere with the settlement path it
                    // is meant to verify.
                    asupersync::time::sleep(client_cx.now(), Duration::from_millis(100)).await;
                    if !matches!(tool_call.try_join(), Ok(None)) {
                        caller_cx.cancel_with(
                            CancelKind::User,
                            Some("wrong-ID reverse response probe failed"),
                        );
                        return Err(
                            "wrong-ID reverse response settled the pending handler"
                                .to_string(),
                        );
                    }

                    let cancellation = JsonRpcRequest::notification(
                        "notifications/cancelled",
                        Some(serde_json::json!({
                            "requestId": TOOL_CALL_ID,
                            "reason": "settle wrong-ID reverse-response probe",
                        })),
                    );
                    let cancellation_body = serde_json::to_vec(&cancellation).map_err(|error| {
                        caller_cx.cancel_with(
                            CancelKind::User,
                            Some("cancellation serialization failed"),
                        );
                        format!("legacy sampling cancellation did not serialize: {error}")
                    })?;
                    let cancellation_response = live_http_exchange(
                        address,
                        live_http_post(
                            &format!("/messages?session_id={session_id}"),
                            &cancellation_body,
                            &opener_headers,
                        ),
                    )
                    .await;
                    let cancellation_response = match cancellation_response {
                        Ok(response) => response,
                        Err(error) => {
                            caller_cx.cancel_with(
                                CancelKind::User,
                                Some("cancellation exchange failed"),
                            );
                            return Err(error);
                        }
                    };
                    if !cancellation_response.starts_with(b"HTTP/1.1 202") {
                        caller_cx.cancel_with(
                            CancelKind::User,
                            Some("cancellation not accepted"),
                        );
                        return Err(format!(
                            "legacy sampling cancellation was not accepted: {cancellation_response:?}"
                        ));
                    }
                    let _ = tool_call.join(&client_cx).await.map_err(|error| {
                        caller_cx.cancel_with(
                            CancelKind::User,
                            Some("tool-call join failed"),
                        );
                        format!("legacy sampling cancelled tool-call POST failed: {error:?}")
                    })??;
                    let _ = reverse_post.join(&client_cx).await.map_err(|error| {
                        caller_cx.cancel_with(
                            CancelKind::User,
                            Some("reverse-post join failed"),
                        );
                        format!("wrong-ID reverse-response POST failed after settlement: {error:?}")
                    })??;
                } else {
                    let reverse_response = reverse_post.join(&client_cx).await.map_err(|error| {
                        format!("legacy sampling reverse-response POST failed: {error:?}")
                    })??;
                    if reverse_response_token == Some("beta") {
                        if !reverse_response.starts_with(b"HTTP/1.1 401") {
                            return Err(format!(
                                "foreign-principal reverse response was not rejected before mutation: {reverse_response:?}"
                            ));
                        }
                        asupersync::time::sleep(
                            client_cx.now(),
                            Duration::from_millis(100),
                        )
                        .await;
                        if !matches!(tool_call.try_join(), Ok(None)) {
                            return Err(
                                "foreign-principal reverse response settled the pending handler"
                                    .to_string(),
                            );
                        }
                        let owned_retry = live_http_exchange(
                            address,
                            live_http_post(
                                &format!("/messages?session_id={session_id}"),
                                &reverse_body,
                                &opener_headers,
                            ),
                        )
                        .await?;
                        if !owned_retry.starts_with(b"HTTP/1.1 202") {
                            return Err(format!(
                                "opener-principal reverse-response retry was not accepted: {owned_retry:?}"
                            ));
                        }
                    } else if !reverse_response.starts_with(b"HTTP/1.1 202") {
                        return Err(format!(
                            "matching reverse-response POST was not accepted: {reverse_response:?}"
                        ));
                    }
                    let tool_call_response = tool_call.join(&client_cx).await.map_err(|error| {
                        format!("legacy sampling tool-call POST failed: {error:?}")
                    })??;
                    if !tool_call_response.starts_with(b"HTTP/1.1 202") {
                        return Err(format!(
                            "legacy sampling tool-call POST was not accepted: {tool_call_response:?}"
                        ));
                    }
                    read_live_http_until(
                        &mut sse,
                        &mut received,
                        b"legacy-runtime-1-http-sampled-value",
                    )
                    .await?;
                }

                caller_cx.cancel_with(
                    CancelKind::User,
                    Some("legacy reverse-response POST probe complete"),
                );
                Ok::<_, String>(())
            })
            .map_err(|error| format!("legacy reverse-response client task was not admitted: {error}"))?;

        // Bound only the two outermost awaits, so a stall fails the test by
        // name instead of freezing the binary. Inner joins stay unbounded: a
        // timed join cancels, which would change the authority under test.
        let serve_deadline = cx.now().saturating_add_nanos(LIVE_HTTP_TEST_TIMEOUT_NANOS);
        let serve = asupersync::time::timeout_at(serve_deadline, bound.serve(cx))
            .await
            .map_err(|_| {
                // `serve` returns only after the client cancels `caller_cx`, and
                // a client that fails early returns without cancelling. Report
                // its outcome so that failure is not misread as a server stall.
                let client_state = match client.try_join() {
                    Ok(None) => "the client is still pending".to_owned(),
                    Ok(Some(Ok(()))) => "the client completed and cancelled".to_owned(),
                    Ok(Some(Err(error))) => format!("the client failed first: {error}"),
                    Err(error) => format!("the client task could not be joined: {error:?}"),
                };
                format!("legacy reverse-response serve did not finish; {client_state}")
            })?;
        let join_deadline = cx.now().saturating_add_nanos(LIVE_HTTP_TEST_TIMEOUT_NANOS);
        asupersync::time::timeout_at(join_deadline, client.join(cx))
            .await
            .map_err(|_| "legacy reverse-response client did not finish".to_owned())?
            .map_err(|error| format!("legacy reverse-response client failed: {error:?}"))??;
        let shutdown =
            serve.map_err(|error| format!("legacy reverse-response server failed: {error}"))?;
        require_quiescent_http_shutdown(shutdown, "legacy reverse-response").await
    }

