    #[test]
    fn live_http_legacy_unmatched_response_uses_one_auth_provider_evaluation() {
        run_live_http_test(|cx| async move {
            let provider_calls = Arc::new(AtomicUsize::new(0));
            let bound = Server::new("legacy-response-auth-receipt", "1.0.0")
                .auth_provider(CountingLegacyHttpAuthProvider {
                    calls: Arc::clone(&provider_calls),
                })
                .build()
                .bind_http(&cx, "127.0.0.1:0")
                .await
                .map_err(|error| format!("legacy auth-receipt bind failed: {error}"))?;
            let address = bound
                .local_addr()
                .map_err(|error| format!("legacy auth-receipt address failed: {error}"))?;
            let caller_cx = cx.clone();
            let client_provider_calls = Arc::clone(&provider_calls);
            let mut client = cx
                .spawn(move |_client_cx| async move {
                    let (stream, session_id, _) = open_live_legacy_http_session(
                        address,
                        &[("Authorization", "Bearer alpha")],
                    )
                    .await?;
                    if client_provider_calls.load(Ordering::Acquire) != 1 {
                        return Err(
                            "legacy SSE opener did not evaluate its provider exactly once"
                                .to_owned(),
                        );
                    }
                    let unmatched = JsonRpcResponse::success(
                        RequestId::Number(9_999),
                        serde_json::json!({"ignored": true}),
                    );
                    let body = serde_json::to_vec(&unmatched).map_err(|error| {
                        format!("unmatched legacy response did not serialize: {error}")
                    })?;
                    let response = live_http_exchange(
                        address,
                        live_http_post(
                            &format!("/messages?session_id={session_id}"),
                            &body,
                            &[("Authorization", "Bearer alpha")],
                        ),
                    )
                    .await?;
                    if !response.starts_with(b"HTTP/1.1 400") {
                        return Err(format!(
                            "unmatched legacy response did not reach its serialized rejection: {response:?}"
                        ));
                    }
                    if client_provider_calls.load(Ordering::Acquire) != 2 {
                        return Err(
                            "serialized unmatched-response fallback re-evaluated authentication"
                                .to_owned(),
                        );
                    }
                    drop(stream);
                    caller_cx.cancel_with(
                        CancelKind::User,
                        Some("legacy unmatched auth-receipt probe complete"),
                    );
                    Ok::<(), String>(())
                })
                .map_err(|error| format!("legacy auth-receipt client admission failed: {error}"))?;

            let serve = bound.serve(&cx).await;
            client
                .join(&cx)
                .await
                .map_err(|error| format!("legacy auth-receipt client failed: {error:?}"))??;
            let shutdown =
                serve.map_err(|error| format!("legacy auth-receipt server failed: {error}"))?;
            require_quiescent_http_shutdown(shutdown, "legacy unmatched auth receipt").await
        });
    }

    async fn live_http_legacy_blocking_bridge_probe(
        cx: &Cx,
        plant_dispatch_panic: bool,
    ) -> Result<(), String> {
        let endpoint = Server::new("legacy-panic-quarantine", "1.0.0")
            .build_http_endpoint("http://legacy.test")
            .map_err(|error| format!("dual-era endpoint did not build: {error}"))?;
        let mut owned = endpoint
            .open_session(cx)
            .map_err(|error| format!("legacy HTTP session did not open: {error}"))?;
        let ServerHttpEndpointResponse::LegacySse(mut stream) = owned
            .handle_async(cx, HttpRequest::new(HttpMethod::Get, "/sse"))
            .await
            .map_err(|error| format!("legacy SSE admission failed: {error}"))?
        else {
            return Err("legacy GET did not return an SSE response body".to_owned());
        };
        let _ = stream
            .recv_event(cx)
            .map_err(|error| format!("legacy SSE endpoint advertisement failed: {error}"))?;
        let session_id = owned.legacy_session_id().to_owned();
        let shell = Arc::new(LiveHttpSession {
            cancellation: owned.cancellation_control(),
            legacy_pending_requests: Arc::clone(&owned.legacy_pending_requests),
            session: Mutex::new(Some(owned)),
            session_available: Condvar::new(),
            closing: AtomicBool::new(false),
        });
        let sessions = Arc::new(Mutex::new(HashMap::from([(
            session_id.clone(),
            Arc::clone(&shell),
        )])));
        let permit = try_reserve_blocking_dispatch()
            .ok_or_else(|| "legacy blocking bridge test could not reserve capacity".to_owned())?;

        let response = run_live_http_legacy_blocking_dispatch(
            cx,
            &sessions,
            Some(session_id.clone()),
            permit,
            move |_blocking_cx| {
                assert!(
                    !plant_dispatch_panic,
                    "planted legacy HTTP blocking-dispatch panic"
                );
                HttpResponse::ok()
            },
        )
        .await
        .map_err(|()| "legacy blocking bridge region did not settle".to_owned())?;

        let remains_routable = sessions
            .lock()
            .map_err(|_| "quarantine registry lock was poisoned".to_owned())?
            .contains_key(&session_id);
        if plant_dispatch_panic {
            if response.status != HttpStatus::INTERNAL_SERVER_ERROR
                || remains_routable
                || !shell.closing.load(Ordering::Acquire)
                || shell.cancellation.legacy_lifecycle.is_live()
                || stream.try_recv_event(cx).is_ok()
                || !matches!(
                    take_live_http_session(cx, &shell, None),
                    LiveHttpSessionTake::Unavailable
                )
            {
                return Err(
                    "panicked bridge did not map to 500 and quarantine only its session shell"
                        .to_owned(),
                );
            }
        } else if response.status != HttpStatus::OK
            || !remains_routable
            || shell.closing.load(Ordering::Acquire)
        {
            return Err("successful bridge dispatch mutated session admission state".to_owned());
        }
        drop(stream);
        Ok(())
    }

    #[test]
    fn live_http_legacy_blocking_bridge_returns_dispatch_response() {
        run_live_http_test(
            |cx| async move { live_http_legacy_blocking_bridge_probe(&cx, false).await },
        );
    }

    #[test]
    fn live_http_legacy_blocking_bridge_maps_panic_and_quarantines_session_shell() {
        run_live_http_test(|cx| async move {
            // This differs from the positive only in the closure's planted
            // panic, exercising the production pool/catch/settlement path.
            live_http_legacy_blocking_bridge_probe(&cx, true).await
        });
    }

    async fn live_bound_http_cross_era_transcript(
        cx: &Cx,
        policy: ProtocolPolicy,
    ) -> Result<(Vec<u8>, Vec<u8>), String> {
        let bound = Server::new("live-http-cross-era", "1.0.0")
            .protocol_policy(policy)
            .map_err(|error| format!("cross-era HTTP policy rejected: {error}"))?
            .build()
            .bind_http(cx, "127.0.0.1:0")
            .await
            .map_err(|error| format!("cross-era HTTP bind failed: {error}"))?;
        let address = bound
            .local_addr()
            .map_err(|error| format!("cross-era HTTP address failed: {error}"))?;
        let caller_cx = cx.clone();
        let mut client = cx
            .spawn(move |client_cx| async move {
                let legacy_request = format!(
                    "GET /sse HTTP/1.1\r\nHost: {address}\r\nAccept: text/event-stream\r\nConnection: close\r\n\r\n"
                )
                .into_bytes();
                let deadline = client_cx
                    .now()
                    .saturating_add_nanos(LIVE_HTTP_TEST_TIMEOUT_NANOS);
                let mut legacy = asupersync::time::timeout_at(
                    deadline,
                    AsyncTcpStream::connect(address),
                )
                    .await
                    .map_err(|_| live_http_test_timeout("cross-era legacy connection"))?
                    .map_err(|error| format!("cross-era legacy connect failed: {error}"))?;
                asupersync::time::timeout_at(deadline, legacy.write_all(&legacy_request))
                    .await
                    .map_err(|_| live_http_test_timeout("cross-era legacy request write"))?
                    .map_err(|error| format!("cross-era legacy write failed: {error}"))?;
                asupersync::time::timeout_at(deadline, legacy.flush())
                    .await
                    .map_err(|_| live_http_test_timeout("cross-era legacy request flush"))?
                    .map_err(|error| format!("cross-era legacy flush failed: {error}"))?;

                let modern = JsonRpcRequest::new(
                    SERVER_DISCOVER_METHOD,
                    Some(serde_json::json!({
                        "_meta": {
                            MODERN_PROTOCOL_VERSION_METADATA_KEY: MODERN_PROTOCOL_VERSION,
                            FINAL_CLIENT_CAPABILITIES_META_KEY: {},
                        },
                    })),
                    891_i64,
                );
                let modern_body = serde_json::to_vec(&modern)
                    .map_err(|error| format!("cross-era modern request did not serialize: {error}"))?;
                let modern_request = live_http_post(
                    "/mcp",
                    &modern_body,
                    &[
                        ("Accept", "application/json"),
                        ("MCP-Protocol-Version", MODERN_PROTOCOL_VERSION),
                        ("Mcp-Method", SERVER_DISCOVER_METHOD),
                    ],
                );

                let mut legacy_bytes = Vec::new();
                if matches!(policy, ProtocolPolicy::Auto) {
                    let endpoint_prefix = format!("data: http://{address}/messages?session_id=");
                    read_live_http_until(&mut legacy, &mut legacy_bytes, endpoint_prefix.as_bytes())
                        .await?;
                } else {
                    read_live_http_to_end(
                        &mut legacy,
                        &mut legacy_bytes,
                        "cross-era legacy rejection EOF",
                    )
                    .await?;
                }

                let modern_response = live_http_exchange(address, modern_request).await?;
                caller_cx.cancel_with(CancelKind::User, Some("cross-era HTTP transcript complete"));
                Ok::<_, String>((legacy_bytes, modern_response))
            })
            .map_err(|error| format!("cross-era HTTP client admission failed: {error}"))?;

        let serve = bound.serve(cx).await;
        let transcript = client
            .join(cx)
            .await
            .map_err(|error| format!("cross-era HTTP client failed: {error:?}"))??;
        let shutdown = serve.map_err(|error| format!("cross-era HTTP server failed: {error}"))?;
        require_quiescent_http_shutdown(shutdown, "cross-era HTTP").await?;
        Ok(transcript)
    }

    fn assert_cross_era_modern_discovery(response: &[u8]) -> Result<(), String> {
        if !response.starts_with(b"HTTP/1.1 200") {
            return Err(format!(
                "cross-era modern request did not receive HTTP 200: {response:?}"
            ));
        }
        let response: JsonRpcResponse = serde_json::from_slice(live_http_response_body(response)?)
            .map_err(|error| format!("cross-era modern response was invalid: {error}"))?;
        if response.id != Some(891_i64.into()) || response.error.is_some() {
            return Err(format!(
                "cross-era modern request was rejected: {response:?}"
            ));
        }
        if response.result.as_ref().and_then(|result| {
            result["_meta"][fastmcp_protocol::SERVER_DISCOVER_SERVER_INFO_META_KEY]["name"].as_str()
        }) != Some("live-http-cross-era")
        {
            return Err(format!(
                "cross-era modern discovery result changed its server identity: {response:?}"
            ));
        }
        Ok(())
    }

    async fn live_non_sse_shutdown_fence_transcript(
        cx: &Cx,
        cancel_before_response: bool,
    ) -> Result<Vec<u8>, String> {
        const REQUEST_ID: i64 = 892;

        let control = Arc::new(LiveModernControl::default());
        control.install_shutdown_cx(cx.clone());
        let bound = Server::new("live-http-shutdown-fence", "1.0.0")
            .tool(LiveModernControlledTool {
                control: Arc::clone(&control),
            })
            .build()
            .bind_http(cx, "127.0.0.1:0")
            .await
            .map_err(|error| format!("shutdown-fence HTTP bind failed: {error}"))?;
        let address = bound
            .local_addr()
            .map_err(|error| format!("shutdown-fence HTTP address failed: {error}"))?;
        let request = JsonRpcRequest::new(
            "tools/call",
            Some(serde_json::json!({
                "name": "live_modern_controlled_tool",
                "arguments": {},
                "_meta": {
                    MODERN_PROTOCOL_VERSION_METADATA_KEY: MODERN_PROTOCOL_VERSION,
                    FINAL_CLIENT_CAPABILITIES_META_KEY: {},
                },
            })),
            REQUEST_ID,
        );
        let request = live_http_post(
            "/mcp",
            &serde_json::to_vec(&request)
                .map_err(|error| format!("shutdown-fence request did not serialize: {error}"))?,
            &[
                // Streamable HTTP POSTs must accept both JSON and SSE; the
                // server still commits this exchange as an ordinary non-SSE
                // JSON response.
                ("Accept", "application/json, text/event-stream"),
                ("MCP-Protocol-Version", MODERN_PROTOCOL_VERSION),
                ("Mcp-Method", "tools/call"),
                ("Mcp-Name", "live_modern_controlled_tool"),
            ],
        );
        let shutdown_applied = Arc::new(AtomicBool::new(false));
        let relay_control = Arc::clone(&control);
        let relay_applied = Arc::clone(&shutdown_applied);
        let caller_cx = cx.clone();
        let mut cancellation_relay = cx
            .spawn(move |_relay_cx| async move {
                while !relay_control.shutdown_requested.load(Ordering::Acquire) {
                    asupersync::runtime::yield_now().await;
                }
                let reason = if cancel_before_response {
                    "shutdown-fence cancellation before H1 response"
                } else {
                    "shutdown-fence response committed"
                };
                caller_cx.cancel_with(CancelKind::Shutdown, Some(reason));
                // The parked accept only wakes on I/O; poke the listener so
                // the serve loop observes the shutdown cancellation.
                let _ = std::net::TcpStream::connect(address);
                relay_applied.store(true, Ordering::Release);
            })
            .map_err(|error| format!("shutdown-fence relay admission failed: {error}"))?;
        let controller = Arc::clone(&control);
        let client_shutdown_applied = Arc::clone(&shutdown_applied);
        let client = thread::spawn(move || -> Result<Vec<u8>, String> {
            struct SignalShutdownOnDrop(Arc<LiveModernControl>);

            impl Drop for SignalShutdownOnDrop {
                fn drop(&mut self) {
                    self.0.request_shutdown();
                }
            }

            let _shutdown_on_drop = SignalShutdownOnDrop(Arc::clone(&controller));
            let mut stream = std::net::TcpStream::connect(address)
                .map_err(|error| format!("shutdown-fence client connect failed: {error}"))?;
            stream
                .set_read_timeout(Some(Duration::from_secs(2)))
                .map_err(|error| format!("shutdown-fence client timeout setup failed: {error}"))?;
            std::io::Write::write_all(&mut stream, &request)
                .map_err(|error| format!("shutdown-fence client write failed: {error}"))?;
            std::io::Write::flush(&mut stream)
                .map_err(|error| format!("shutdown-fence client flush failed: {error}"))?;
            if !controller.wait_for_started(1, Duration::from_secs(2)) {
                return Err("shutdown-fence tool did not enter before its deadline".to_owned());
            }
            if cancel_before_response {
                controller.request_shutdown();
                let deadline = Instant::now() + Duration::from_secs(2);
                while !client_shutdown_applied.load(Ordering::Acquire) {
                    if Instant::now() >= deadline {
                        return Err(
                            "shutdown-fence runtime relay did not apply cancellation".to_owned()
                        );
                    }
                    thread::yield_now();
                }
            } else {
                controller.release(REQUEST_ID as u64);
            }

            let mut response = Vec::new();
            match std::io::Read::read_to_end(&mut stream, &mut response) {
                Ok(_) => {}
                Err(error)
                    if cancel_before_response
                        && response.is_empty()
                        && matches!(
                            error.kind(),
                            std::io::ErrorKind::ConnectionAborted
                                | std::io::ErrorKind::ConnectionReset
                                | std::io::ErrorKind::UnexpectedEof
                                | std::io::ErrorKind::TimedOut
                                | std::io::ErrorKind::WouldBlock
                        ) => {}
                Err(error) => {
                    return Err(format!("shutdown-fence client read failed: {error}"));
                }
            }
            if !cancel_before_response {
                controller.request_shutdown();
            }
            Ok(response)
        });

        let serve = bound.serve(cx).await;
        cancellation_relay
            .join(cx)
            .await
            .map_err(|error| format!("shutdown-fence cancellation relay failed: {error:?}"))?;
        let response = client
            .join()
            .map_err(|_| "shutdown-fence client panicked".to_owned())??;
        let shutdown = serve.map_err(|error| format!("shutdown-fence server failed: {error}"))?;
        require_quiescent_http_shutdown(shutdown, "shutdown fence").await?;
        Ok(response)
    }

    #[test]
    fn live_bound_http_auto_coexists_with_exact_legacy_and_modern_requests() {
        run_live_http_test(|cx| async move {
            let (legacy, modern) =
                live_bound_http_cross_era_transcript(&cx, ProtocolPolicy::Auto).await?;
            if !legacy.starts_with(b"HTTP/1.1 200")
                || !legacy
                    .windows(b"/messages?session_id=".len())
                    .any(|window| window == b"/messages?session_id=")
            {
                return Err(format!(
                    "Auto did not retain the exact legacy SSE route: {legacy:?}"
                ));
            }
            assert_cross_era_modern_discovery(&modern)?;
            Ok(())
        });
    }

    #[test]
    fn live_bound_http_modern_only_rejects_the_identical_legacy_half() {
        run_live_http_test(|cx| async move {
            // This transcript differs from the Auto positive only in the
            // policy selected at server construction.
            let (legacy, modern) =
                live_bound_http_cross_era_transcript(&cx, ProtocolPolicy::ModernOnly).await?;
            if !legacy.starts_with(b"HTTP/1.1 400") {
                return Err(format!(
                    "ModernOnly admitted the legacy SSE route: {legacy:?}"
                ));
            }
            assert_cross_era_modern_discovery(&modern)?;
            Ok(())
        });
    }

    #[test]
    fn live_http_non_sse_response_commits_before_shutdown() {
        run_live_http_test(|cx| async move {
            let response = live_non_sse_shutdown_fence_transcript(&cx, false).await?;
            if !response.starts_with(b"HTTP/1.1 200")
                || !response
                    .windows(b"modern request 892".len())
                    .any(|window| window == b"modern request 892")
            {
                return Err(format!(
                    "a non-SSE response did not commit before shutdown: {response:?}"
                ));
            }
            Ok(())
        });
    }

    #[test]
    fn live_http_non_sse_shutdown_suppresses_the_pending_response() {
        run_live_http_test(|cx| async move {
            // This differs from the positive only by cancelling after the
            // handler enters and before the ordinary H1 response can commit.
            let response = live_non_sse_shutdown_fence_transcript(&cx, true).await?;
            if !response.is_empty() {
                return Err(format!(
                    "shutdown wrote a non-SSE response after cancellation: {response:?}"
                ));
            }
            Ok(())
        });
    }

    async fn live_http_legacy_admission_cancellation_probe(
        cx: &Cx,
        cancellation_request_id: i64,
    ) -> Result<usize, String> {
        const INITIALIZE_ID: i64 = 830;
        const BLOCKER_ID: i64 = 831;
        const TARGET_ID: i64 = 832;

        let gate = Arc::new(LiveLegacyRequestGate::default());
        let target_calls = Arc::new(AtomicUsize::new(0));
        let bound = Server::new("live-http-legacy-admission-cancellation", "1.0.0")
            .tool(LiveLegacyAdmissionBlocker {
                gate: Arc::clone(&gate),
            })
            .tool(LiveLegacyAdmissionTarget {
                calls: Arc::clone(&target_calls),
            })
            .build()
            .bind_http(cx, "127.0.0.1:0")
            .await
            .map_err(|error| format!("legacy admission HTTP bind failed: {error}"))?;
        let address = bound
            .local_addr()
            .map_err(|error| format!("legacy admission HTTP address failed: {error}"))?;
        let legacy_sessions = Arc::clone(&bound.legacy_sessions);
        let caller_cx = cx.clone();
        let gate_for_client = Arc::clone(&gate);
        let target_calls_for_client = Arc::clone(&target_calls);
        let mut client = cx
            .spawn(move |client_cx| async move {
                struct CancelServerOnDrop(Cx);

                impl Drop for CancelServerOnDrop {
                    fn drop(&mut self) {
                        self.0.cancel_with(
                            CancelKind::User,
                            Some("legacy admission client exited"),
                        );
                    }
                }

                let _server_cancellation = CancelServerOnDrop(caller_cx.clone());
                let (mut sse, session_id, mut received) =
                    open_live_legacy_http_session(address, &[]).await?;
                let session = legacy_sessions
                    .lock()
                    .unwrap_or_else(std::sync::PoisonError::into_inner)
                    .get(&session_id)
                    .cloned()
                    .ok_or_else(|| "legacy admission session was not registered".to_string())?;

                for request in [
                    JsonRpcRequest::new(
                        "initialize",
                        Some(serde_json::json!({
                            "protocolVersion": LEGACY_PROTOCOL_VERSION,
                            "capabilities": {},
                            "clientInfo": {"name": "legacy-admission-client", "version": "1.0.0"},
                        })),
                        INITIALIZE_ID,
                    ),
                    JsonRpcRequest::notification("notifications/initialized", None),
                ] {
                    let body = serde_json::to_vec(&request).map_err(|error| {
                        format!("legacy admission setup request did not serialize: {error}")
                    })?;
                    let response = live_http_exchange(
                        address,
                        live_http_post(&format!("/messages?session_id={session_id}"), &body, &[]),
                    )
                    .await?;
                    if !response.starts_with(b"HTTP/1.1 202") {
                        return Err(format!(
                            "legacy admission setup request was not accepted: {response:?}"
                        ));
                    }
                }

                let blocker = JsonRpcRequest::new(
                    "tools/call",
                    Some(serde_json::json!({
                        "name": "live_legacy_admission_blocker",
                        "arguments": {},
                    })),
                    BLOCKER_ID,
                );
                let blocker_body = serde_json::to_vec(&blocker).map_err(|error| {
                    format!("legacy admission blocker request did not serialize: {error}")
                })?;
                let blocker_request = live_http_post(
                    &format!("/messages?session_id={session_id}"),
                    &blocker_body,
                    &[],
                );
                let mut blocker = client_cx
                    .spawn(move |_blocker_cx| async move {
                        live_http_exchange(address, blocker_request).await
                    })
                    .map_err(|error| {
                        format!("legacy admission blocker task was not admitted: {error}")
                    })?;
                let _release_blocker = LiveLegacyRequestGateRelease {
                    gate: Arc::clone(&gate_for_client),
                };

                let blocker_deadline = client_cx
                    .now()
                    .saturating_add_nanos(LIVE_HTTP_TEST_TIMEOUT_NANOS);
                while !gate_for_client.entered.load(Ordering::Acquire) {
                    client_cx
                        .checkpoint()
                        .map_err(|error| format!("legacy admission client stopped: {error}"))?;
                    asupersync::time::timeout_at(
                        blocker_deadline,
                        asupersync::time::sleep(client_cx.now(), Duration::from_millis(1)),
                    )
                    .await
                    .map_err(|_| live_http_test_timeout("legacy admission blocker entry"))?;
                }

                let target_id = RequestId::Number(TARGET_ID);
                let target = JsonRpcRequest::new(
                    "tools/call",
                    Some(serde_json::json!({
                        "name": "live_legacy_admission_target",
                        "arguments": {},
                    })),
                    TARGET_ID,
                );
                let target_body = serde_json::to_vec(&target).map_err(|error| {
                    format!("legacy admission target request did not serialize: {error}")
                })?;
                let target_request = live_http_post(
                    &format!("/messages?session_id={session_id}"),
                    &target_body,
                    &[],
                );
                let mut target = client_cx
                    .spawn(move |_target_cx| async move {
                        live_http_exchange(address, target_request).await
                    })
                    .map_err(|error| {
                        format!("legacy admission target task was not admitted: {error}")
                    })?;
                wait_for_live_http_legacy_admission(&client_cx, &session, &target_id).await?;

                let cancellation = JsonRpcRequest::notification(
                    "notifications/cancelled",
                    Some(serde_json::json!({
                        "requestId": cancellation_request_id,
                        "reason": "legacy HTTP admission cancellation",
                    })),
                );
                let cancellation_body = serde_json::to_vec(&cancellation).map_err(|error| {
                    format!("legacy admission cancellation did not serialize: {error}")
                })?;
                let cancellation_response = live_http_exchange(
                    address,
                    live_http_post(
                        &format!("/messages?session_id={session_id}"),
                        &cancellation_body,
                        &[],
                    ),
                )
                .await?;
                if !cancellation_response.starts_with(b"HTTP/1.1 202") {
                    return Err(format!(
                        "legacy admission cancellation control POST was not accepted: {cancellation_response:?}"
                    ));
                }

                gate_for_client.release();
                let blocker_response = blocker
                    .join(&client_cx)
                    .await
                    .map_err(|error| format!("legacy admission blocker task failed: {error:?}"))??;
                if !blocker_response.starts_with(b"HTTP/1.1 202") {
                    return Err(format!(
                        "legacy admission blocker acknowledgement was unexpected: {blocker_response:?}"
                    ));
                }
                let target_response = target
                    .join(&client_cx)
                    .await
                    .map_err(|error| format!("legacy admission target task failed: {error:?}"))??;
                if !target_response.starts_with(b"HTTP/1.1 202") {
                    return Err(format!(
                        "legacy admission target acknowledgement was unexpected: {target_response:?}"
                    ));
                }

                let blocker_marker = format!("\"id\":{BLOCKER_ID}");
                read_live_http_until(&mut sse, &mut received, blocker_marker.as_bytes()).await?;
                let target_marker = format!("\"id\":{TARGET_ID}");
                if cancellation_request_id == TARGET_ID {
                    if target_calls_for_client.load(Ordering::Acquire) != 0
                        || received
                            .windows(target_marker.len())
                            .any(|window| window == target_marker.as_bytes())
                    {
                        return Err(
                            "a cancellation admitted before the session mutex still entered its target"
                                .to_string(),
                        );
                    }
                    let probe_deadline = client_cx
                        .now()
                        .saturating_add_nanos(100_000_000);
                    let mut chunk = [0_u8; 1024];
                    match asupersync::time::timeout_at(probe_deadline, sse.read(&mut chunk)).await {
                        Err(_) => {}
                        Ok(Ok(0)) => {
                            return Err(
                                "legacy admission SSE stream closed before the bounded silence probe"
                                    .to_string(),
                            );
                        }
                        Ok(Ok(read)) => {
                            received.extend_from_slice(&chunk[..read]);
                            return Err(format!(
                                "cancelled queued legacy request emitted an SSE frame: {received:?}"
                            ));
                        }
                        Ok(Err(error)) => {
                            return Err(format!(
                                "legacy admission SSE silence probe failed: {error}"
                            ));
                        }
                    }
                } else {
                    read_live_http_until(&mut sse, &mut received, target_marker.as_bytes()).await?;
                    if target_calls_for_client.load(Ordering::Acquire) != 1 {
                        return Err(
                            "one-ID-negative cancellation altered the exact target request"
                                .to_string(),
                        );
                    }
                }

                caller_cx.cancel_with(CancelKind::User, Some("legacy admission probe complete"));
                Ok::<_, String>(())
            })
            .map_err(|error| format!("legacy admission client task was not admitted: {error}"))?;

        let serve = bound.serve(cx).await;
        client
            .join(cx)
            .await
            .map_err(|error| format!("legacy admission client task failed: {error:?}"))??;
        let shutdown =
            serve.map_err(|error| format!("legacy admission HTTP server failed: {error}"))?;
        require_quiescent_http_shutdown(shutdown, "legacy admission HTTP").await?;
        Ok(target_calls.load(Ordering::Acquire))
    }

    #[test]
    fn live_http_legacy_cancellation_survives_admission_to_active_transition() {
        run_live_http_test(|cx| async move {
            let calls = live_http_legacy_admission_cancellation_probe(&cx, 832).await?;
            if calls != 0 {
                return Err(format!(
                    "cancelled queued legacy HTTP request entered its handler {calls} time(s)"
                ));
            }
            Ok(())
        });
    }

    #[test]
    fn live_http_legacy_cancellation_rejects_the_one_id_negative() {
        run_live_http_test(|cx| async move {
            // This differs from the positive only in the cancellation request
            // ID. It must not affect the queued request with ID 832.
            let calls = live_http_legacy_admission_cancellation_probe(&cx, 833).await?;
            if calls != 1 {
                return Err(format!(
                    "one-ID-negative cancellation changed target handler calls to {calls}"
                ));
            }
            Ok(())
        });
    }

    #[test]
    fn live_http_legacy_initialize_is_peer_cancellation_protected() {
        run_live_http_test(|cx| async move {
            const INITIALIZE_ID: i64 = 834;

            let bound = Server::new("live-http-legacy-initialize-protection", "1.0.0")
                .build()
                .bind_http(&cx, "127.0.0.1:0")
                .await
                .map_err(|error| format!("legacy initialize HTTP bind failed: {error}"))?;
            let address = bound
                .local_addr()
                .map_err(|error| format!("legacy initialize HTTP address failed: {error}"))?;
            let legacy_sessions = Arc::clone(&bound.legacy_sessions);
            let caller_cx = cx.clone();
            let mut client = cx
                .spawn(move |client_cx| async move {
                    let (mut sse, session_id, mut received) =
                        open_live_legacy_http_session(address, &[]).await?;
                    let session = legacy_sessions
                        .lock()
                        .unwrap_or_else(std::sync::PoisonError::into_inner)
                        .get(&session_id)
                        .cloned()
                        .ok_or_else(|| "legacy initialize session was not registered".to_string())?;
                    let mut session_hold = LiveHttpSessionMutexHold::new(Arc::clone(&session))?;
                    let initialize = JsonRpcRequest::new(
                        "initialize",
                        Some(serde_json::json!({
                            "protocolVersion": LEGACY_PROTOCOL_VERSION,
                            "capabilities": {},
                            "clientInfo": {"name": "legacy-initialize-client", "version": "1.0.0"},
                        })),
                        INITIALIZE_ID,
                    );
                    let initialize_body = serde_json::to_vec(&initialize).map_err(|error| {
                        format!("legacy initialize request did not serialize: {error}")
                    })?;
                    let initialize_request = live_http_post(
                        &format!("/messages?session_id={session_id}"),
                        &initialize_body,
                        &[],
                    );
                    let mut initialize = client_cx
                        .spawn(move |_initialize_cx| async move {
                            live_http_exchange(address, initialize_request).await
                        })
                        .map_err(|error| {
                            format!("legacy initialize task was not admitted: {error}")
                        })?;
                    let initialize_id = RequestId::Number(INITIALIZE_ID);
                    wait_for_live_http_legacy_admission(&client_cx, &session, &initialize_id).await?;

                    let cancellation = JsonRpcRequest::notification(
                        "notifications/cancelled",
                        Some(serde_json::json!({
                            "requestId": INITIALIZE_ID,
                            "reason": "initialize must be peer-cancellation protected",
                        })),
                    );
                    let cancellation_body = serde_json::to_vec(&cancellation).map_err(|error| {
                        format!("legacy initialize cancellation did not serialize: {error}")
                    })?;
                    let cancellation_response = live_http_exchange(
                        address,
                        live_http_post(
                            &format!("/messages?session_id={session_id}"),
                            &cancellation_body,
                            &[],
                        ),
                    )
                    .await?;
                    if !cancellation_response.starts_with(b"HTTP/1.1 202") {
                        return Err(format!(
                            "legacy initialize cancellation control POST was not accepted: {cancellation_response:?}"
                        ));
                    }

                    session_hold.release()?;
                    let initialize_response = initialize
                        .join(&client_cx)
                        .await
                        .map_err(|error| format!("legacy initialize task failed: {error:?}"))??;
                    if !initialize_response.starts_with(b"HTTP/1.1 202") {
                        return Err(format!(
                            "legacy initialize acknowledgement was unexpected: {initialize_response:?}"
                        ));
                    }
                    let initialize_marker = format!("\"id\":{INITIALIZE_ID}");
                    read_live_http_until(&mut sse, &mut received, initialize_marker.as_bytes())
                        .await?;
                    let received = std::str::from_utf8(&received).map_err(|error| {
                        format!("legacy initialize SSE response was not UTF-8: {error}")
                    })?;
                    if !received.contains(LEGACY_PROTOCOL_VERSION) {
                        return Err(
                            "peer cancellation suppressed the exact legacy initialize response"
                                .to_string(),
                        );
                    }
                    caller_cx.cancel_with(
                        CancelKind::User,
                        Some("legacy initialize protection probe complete"),
                    );
                    Ok::<_, String>(())
                })
                .map_err(|error| {
                    format!("legacy initialize client task was not admitted: {error}")
                })?;

            let serve = bound.serve(&cx).await;
            client
                .join(&cx)
                .await
                .map_err(|error| format!("legacy initialize client task failed: {error:?}"))??;
            let shutdown =
                serve.map_err(|error| format!("legacy initialize HTTP server failed: {error}"))?;
            require_quiescent_http_shutdown(shutdown, "legacy initialize HTTP").await?;
            Ok(())
        });
    }

    #[test]
    fn live_http_legacy_cancellation_bypasses_the_busy_session_lock() {
        run_live_http_test(|cx| async move {
            let started = Arc::new(AtomicBool::new(false));
            let observed_cancellation = Arc::new(AtomicBool::new(false));
            let observed_by_server = Arc::clone(&observed_cancellation);
            let bound = Server::new("live-http-legacy-cancellation", "1.0.0")
                .tool(LiveLegacyCancellationTool {
                    started: Arc::clone(&started),
                    observed_cancellation: Arc::clone(&observed_cancellation),
                })
                .build()
                .bind_http(&cx, "127.0.0.1:0")
                .await
                .map_err(|error| format!("legacy cancellation HTTP bind failed: {error}"))?;
            let address = bound
                .local_addr()
                .map_err(|error| format!("legacy cancellation HTTP address failed: {error}"))?;
            let legacy_sessions = Arc::clone(&bound.legacy_sessions);
            let caller_cx = cx.clone();
            let mut client = cx
                .spawn(move |client_cx| async move {
                    struct CancelServerOnDrop(Cx);

                    impl Drop for CancelServerOnDrop {
                        fn drop(&mut self) {
                            self.0.cancel_with(
                                CancelKind::User,
                                Some("legacy cancellation client exited"),
                            );
                        }
                    }

                    let _server_cancellation = CancelServerOnDrop(caller_cx.clone());
                    let mut stream = AsyncTcpStream::connect(address)
                        .await
                        .map_err(|error| format!("legacy cancellation SSE connect failed: {error}"))?;
                    stream
                        .write_all(
                            format!(
                                "GET /sse HTTP/1.1\r\nHost: {address}\r\nAccept: text/event-stream\r\nConnection: keep-alive\r\n\r\n"
                            )
                            .as_bytes(),
                        )
                        .await
                        .map_err(|error| format!("legacy cancellation SSE write failed: {error}"))?;
                    stream
                        .flush()
                        .await
                        .map_err(|error| format!("legacy cancellation SSE flush failed: {error}"))?;

                    let mut received = Vec::new();
                    let endpoint_prefix = format!("data: http://{address}/messages?session_id=");
                    read_live_http_until(&mut stream, &mut received, endpoint_prefix.as_bytes())
                        .await?;
                    let received_text = std::str::from_utf8(&received).map_err(|error| {
                        format!("legacy cancellation SSE endpoint was not UTF-8: {error}")
                    })?;
                    let session_id = received_text
                        .split_once(&endpoint_prefix)
                        .and_then(|(_, remainder)| remainder.split_whitespace().next())
                        .ok_or_else(|| {
                            "legacy cancellation SSE endpoint omitted its session identifier"
                                .to_string()
                        })?
                        .to_owned();
                    let live_session = legacy_sessions
                        .lock()
                        .unwrap_or_else(std::sync::PoisonError::into_inner)
                        .get(&session_id)
                        .cloned()
                        .ok_or_else(|| {
                            "legacy cancellation session was not registered".to_string()
                        })?;

                    for request in [
                        JsonRpcRequest::new(
                            "initialize",
                            Some(serde_json::json!({
                                "protocolVersion": LEGACY_PROTOCOL_VERSION,
                                "capabilities": {},
                                "clientInfo": {"name": "legacy-cancellation-client", "version": "1.0.0"},
                            })),
                            821_i64,
                        ),
                        JsonRpcRequest::notification("notifications/initialized", None),
                    ] {
                        let body = serde_json::to_vec(&request).map_err(|error| {
                            format!("legacy cancellation setup request did not serialize: {error}")
                        })?;
                        let response = live_http_exchange(
                            address,
                            live_http_post(
                                &format!("/messages?session_id={session_id}"),
                                &body,
                                &[],
                            ),
                        )
                        .await?;
                        if !response.starts_with(b"HTTP/1.1 202") {
                            return Err(format!(
                                "legacy cancellation setup request was not accepted: {response:?}"
                            ));
                        }
                    }

                    let call = JsonRpcRequest::new(
                        "tools/call",
                        Some(serde_json::json!({
                            "name": "live_legacy_cancellation_tool",
                            "arguments": {},
                        })),
                        822_i64,
                    );
                    let call_body = serde_json::to_vec(&call).map_err(|error| {
                        format!("legacy cancellation call did not serialize: {error}")
                    })?;
                    let call_request = live_http_post(
                        &format!("/messages?session_id={session_id}"),
                        &call_body,
                        &[],
                    );
                    let mut call = client_cx
                        .spawn(move |_call_cx| async move {
                            live_http_exchange(address, call_request).await
                        })
                        .map_err(|error| {
                            format!("legacy cancellation call admission failed: {error}")
                        })?;

                    let deadline =
                        Instant::now() + Duration::from_nanos(LIVE_HTTP_TEST_TIMEOUT_NANOS);
                    while !started.load(Ordering::Acquire) && Instant::now() < deadline {
                        client_cx
                            .checkpoint()
                            .map_err(|error| format!("legacy cancellation client stopped: {error}"))?;
                        asupersync::time::sleep(client_cx.now(), Duration::from_millis(1)).await;
                    }
                    if !started.load(Ordering::Acquire) {
                        return Err("legacy cancellation handler did not start".to_string());
                    }
                    if !live_session
                        .cancellation
                        .admissions
                        .contains(&RequestId::Number(822))
                    {
                        return Err(
                            "running legacy cancellation target lost its admission authority"
                                .to_string(),
                        );
                    }

                    let cancelled = JsonRpcRequest::notification(
                        "notifications/cancelled",
                        Some(serde_json::json!({
                            "requestId": 822,
                            "reason": "live HTTP cancellation",
                            "_meta": {"com.example/application": true},
                        })),
                    );
                    let mut final_metadata = serde_json::to_value(&cancelled).map_err(|error| {
                        format!("legacy cancellation negative did not serialize: {error}")
                    })?;
                    final_metadata["params"]["_meta"]
                        ["io.modelcontextprotocol/subscriptionId"] = serde_json::json!("final");
                    for (dimension, body, headers) in [
                        (
                            "final reserved metadata",
                            serde_json::to_vec(&final_metadata)
                                .map_err(|error| error.to_string())?,
                            Vec::new(),
                        ),
                        (
                            "modern binding header",
                            serde_json::to_vec(&cancelled)
                                .map_err(|error| error.to_string())?,
                            vec![("MCP-Protocol-Version", MODERN_PROTOCOL_VERSION)],
                        ),
                    ] {
                        let rejected = live_http_exchange(
                            address,
                            live_http_post(
                                &format!("/messages?session_id={session_id}"),
                                &body,
                                &headers,
                            ),
                        )
                        .await?;
                        if !rejected.starts_with(b"HTTP/1.1 400") {
                            return Err(format!(
                                "{dimension} cancellation reached mutable state: {rejected:?}"
                            ));
                        }
                        if observed_by_server.load(Ordering::Acquire) {
                            return Err(format!(
                                "{dimension} cancellation reached the running handler"
                            ));
                        }
                        if !matches!(call.try_join(), Ok(None)) {
                            return Err(format!(
                                "{dimension} cancellation settled the target request"
                            ));
                        }
                    }
                    let cancelled_body = serde_json::to_vec(&cancelled).map_err(|error| {
                        format!("legacy cancellation notification did not serialize: {error}")
                    })?;
                    let cancelled = live_http_exchange(
                        address,
                        live_http_post(
                            &format!("/messages?session_id={session_id}"),
                            &cancelled_body,
                            &[],
                        ),
                    )
                    .await?;
                    if !cancelled.starts_with(b"HTTP/1.1 202") {
                        return Err(format!(
                            "legacy cancellation control POST was not accepted while request ran: {cancelled:?}"
                        ));
                    }
                    let call_response = call
                        .join(&client_cx)
                        .await
                        .map_err(|error| {
                            format!("legacy cancellation call task failed: {error:?}")
                        })??;
                    if !call_response.starts_with(b"HTTP/1.1 202") {
                        return Err(format!(
                            "legacy cancellation call acknowledgement was unexpected: {call_response:?}"
                        ));
                    }
                    if !observed_by_server.load(Ordering::Acquire) {
                        return Err(
                            "legacy cancellation notification did not reach the running handler"
                                .to_string(),
                        );
                    }
                    caller_cx.cancel_with(CancelKind::User, Some("legacy cancellation complete"));
                    Ok(())
                })
                .map_err(|error| format!("legacy cancellation client admission failed: {error}"))?;

            let serve = bound.serve(&cx).await;
            client
                .join(&cx)
                .await
                .map_err(|error| format!("legacy cancellation client failed: {error:?}"))??;
            let shutdown =
                serve.map_err(|error| format!("legacy cancellation server failed: {error}"))?;
            require_quiescent_http_shutdown(shutdown, "legacy cancellation").await?;
            if !observed_cancellation.load(Ordering::Acquire) {
                return Err("live HTTP legacy handler did not observe cancellation".to_string());
            }
            Ok(())
        });
    }

    async fn live_http_legacy_sse_peer_close_probe(
        cx: &Cx,
        close_originating_peer: bool,
    ) -> Result<(), String> {
        const INITIALIZE_ID: i64 = 835;
        const TOOL_CALL_ID: i64 = 836;

        let started = Arc::new(AtomicBool::new(false));
        let observed_cancellation = Arc::new(AtomicBool::new(false));
        let observed_by_handler = Arc::clone(&observed_cancellation);
        let bound = Server::new("live-http-legacy-peer-close", "1.0.0")
            .tool(LiveLegacyCancellationTool {
                started: Arc::clone(&started),
                observed_cancellation: Arc::clone(&observed_cancellation),
            })
            .build()
            .bind_http(cx, "127.0.0.1:0")
            .await
            .map_err(|error| format!("legacy peer-close HTTP bind failed: {error}"))?;
        let address = bound
            .local_addr()
            .map_err(|error| format!("legacy peer-close HTTP address failed: {error}"))?;
        let caller_cx = cx.clone();
        let mut client = cx
            .spawn(move |client_cx| async move {
                let (originating_sse, session_id, _) =
                    open_live_legacy_http_session(address, &[]).await?;
                let (other_sse, _, _) = open_live_legacy_http_session(address, &[]).await?;
                for request in [
                    JsonRpcRequest::new(
                        "initialize",
                        Some(serde_json::json!({
                            "protocolVersion": LEGACY_PROTOCOL_VERSION,
                            "capabilities": {},
                            "clientInfo": {
                                "name": "legacy-peer-close-client",
                                "version": "1.0.0"
                            },
                        })),
                        INITIALIZE_ID,
                    ),
                    JsonRpcRequest::notification("notifications/initialized", None),
                ] {
                    let body = serde_json::to_vec(&request).map_err(|error| {
                        format!("legacy peer-close setup request did not serialize: {error}")
                    })?;
                    let response = live_http_exchange(
                        address,
                        live_http_post(&format!("/messages?session_id={session_id}"), &body, &[]),
                    )
                    .await?;
                    if !response.starts_with(b"HTTP/1.1 202") {
                        return Err(format!(
                            "legacy peer-close setup request was not accepted: {response:?}"
                        ));
                    }
                }

                let call = JsonRpcRequest::new(
                    "tools/call",
                    Some(serde_json::json!({
                        "name": "live_legacy_cancellation_tool",
                        "arguments": {},
                    })),
                    TOOL_CALL_ID,
                );
                let call_body = serde_json::to_vec(&call).map_err(|error| {
                    format!("legacy peer-close tool call did not serialize: {error}")
                })?;
                let mut call = client_cx
                    .spawn(move |_call_cx| async move {
                        live_http_exchange(
                            address,
                            live_http_post(
                                &format!("/messages?session_id={session_id}"),
                                &call_body,
                                &[],
                            ),
                        )
                        .await
                    })
                    .map_err(|error| {
                        format!("legacy peer-close tool call was not admitted: {error}")
                    })?;
                wait_for_live_http_flag(&client_cx, &started, "legacy peer-close handler start")
                    .await?;

                let mut originating_sse = Some(originating_sse);
                if close_originating_peer {
                    drop(originating_sse.take());
                    wait_for_live_http_flag(
                        &client_cx,
                        &observed_by_handler,
                        "originating legacy SSE peer close cancellation",
                    )
                    .await?;
                    drop(other_sse);
                } else {
                    // The near-identical negative closes only the unrelated
                    // SSE peer.  Its deadline proves cancellation remains
                    // isolated to the originating exact-2024 session.
                    drop(other_sse);
                    let deadline = client_cx.now().saturating_add_nanos(100_000_000);
                    if asupersync::time::timeout_at(
                        deadline,
                        wait_for_live_http_flag(
                            &client_cx,
                            &observed_by_handler,
                            "unrelated legacy SSE peer close",
                        ),
                    )
                    .await
                    .is_ok()
                    {
                        return Err(
                            "unrelated legacy SSE peer close cancelled the active request"
                                .to_string(),
                        );
                    }
                    drop(originating_sse.take());
                    wait_for_live_http_flag(
                        &client_cx,
                        &observed_by_handler,
                        "originating legacy SSE peer close after isolation check",
                    )
                    .await?;
                }

                let call_response = call
                    .join(&client_cx)
                    .await
                    .map_err(|error| format!("legacy peer-close tool call failed: {error:?}"))??;
                if !call_response.starts_with(b"HTTP/1.1 202") {
                    return Err(format!(
                        "legacy peer-close tool acknowledgement was unexpected: {call_response:?}"
                    ));
                }
                caller_cx.cancel_with(CancelKind::User, Some("legacy peer-close probe complete"));
                Ok::<_, String>(())
            })
            .map_err(|error| format!("legacy peer-close client was not admitted: {error}"))?;

        let serve = bound.serve(cx).await;
        let client_result = client
            .join(cx)
            .await
            .map_err(|error| format!("legacy peer-close client failed: {error:?}"));
        client_result??;
        let shutdown =
            serve.map_err(|error| format!("legacy peer-close server failed: {error}"))?;
        require_quiescent_http_shutdown(shutdown, "legacy peer-close").await?;
        if !observed_cancellation.load(Ordering::Acquire) {
            return Err("originating legacy peer close did not cancel its request".to_string());
        }
        Ok(())
    }

    #[test]
    fn live_http_legacy_sse_peer_close_cancels_its_busy_request() {
        run_live_http_test(
            |cx| async move { live_http_legacy_sse_peer_close_probe(&cx, true).await },
        );
    }

    #[test]
    fn live_http_legacy_sse_peer_close_does_not_cancel_another_session() {
        run_live_http_test(|cx| async move {
            // This differs from the positive only in the SSE peer that closes.
            live_http_legacy_sse_peer_close_probe(&cx, false).await
        });
    }

    async fn live_http_shutdown_ownership_probe(
        cx: &Cx,
        cooperate_with_cancellation: bool,
    ) -> Result<(), String> {
        struct ReleaseOnExit(Arc<AtomicBool>);

        impl Drop for ReleaseOnExit {
            fn drop(&mut self) {
                self.0.store(true, Ordering::Release);
            }
        }

        let started = Arc::new(AtomicBool::new(false));
        let cancellation_observed = Arc::new(AtomicBool::new(false));
        let release = Arc::new(AtomicBool::new(false));
        // A failed observation must release the deliberately parked handler
        // before runtime teardown joins its blocking thread.
        let _release_on_exit = ReleaseOnExit(Arc::clone(&release));
        let finished = Arc::new(AtomicBool::new(false));
        let tool_name = if cooperate_with_cancellation {
            "live_http_cooperative_shutdown_tool"
        } else {
            "live_http_noncooperative_shutdown_tool"
        };
        let bound = Server::new("live-http-shutdown-ownership", "1.0.0")
            .tool(LiveHttpShutdownTool {
                name: tool_name,
                cooperate_with_cancellation,
                started: Arc::clone(&started),
                cancellation_observed: Arc::clone(&cancellation_observed),
                release: Arc::clone(&release),
                finished: Arc::clone(&finished),
            })
            .build()
            .bind_http(cx, "127.0.0.1:0")
            .await
            .map_err(|error| format!("shutdown-ownership HTTP bind failed: {error}"))?;
        let address = bound
            .local_addr()
            .map_err(|error| format!("shutdown-ownership HTTP address failed: {error}"))?;
        let caller_cx = cx.clone();
        let started_by_client = Arc::clone(&started);
        let mut client = cx
            .spawn(move |client_cx| async move {
                let (sse, session_id, _) = open_live_legacy_http_session(address, &[]).await?;
                for request in [
                    JsonRpcRequest::new(
                        "initialize",
                        Some(serde_json::json!({
                            "protocolVersion": LEGACY_PROTOCOL_VERSION,
                            "capabilities": {},
                            "clientInfo": {
                                "name": "shutdown-ownership-client",
                                "version": "1.0.0"
                            },
                        })),
                        841_i64,
                    ),
                    JsonRpcRequest::notification("notifications/initialized", None),
                ] {
                    let body = serde_json::to_vec(&request).map_err(|error| {
                        format!("shutdown-ownership setup request did not serialize: {error}")
                    })?;
                    let response = live_http_exchange(
                        address,
                        live_http_post(&format!("/messages?session_id={session_id}"), &body, &[]),
                    )
                    .await?;
                    if !response.starts_with(b"HTTP/1.1 202") {
                        return Err(format!(
                            "shutdown-ownership setup request was not accepted: {response:?}"
                        ));
                    }
                }
                let call = JsonRpcRequest::new(
                    "tools/call",
                    Some(serde_json::json!({"name": tool_name, "arguments": {}})),
                    842_i64,
                );
                let call_body = serde_json::to_vec(&call).map_err(|error| {
                    format!("shutdown-ownership tool call did not serialize: {error}")
                })?;
                let call = client_cx
                    .spawn(move |_call_cx| async move {
                        live_http_exchange(
                            address,
                            live_http_post(
                                &format!("/messages?session_id={session_id}"),
                                &call_body,
                                &[],
                            ),
                        )
                        .await
                    })
                    .map_err(|error| {
                        format!("shutdown-ownership tool call was not admitted: {error}")
                    })?;
                wait_for_live_http_flag(
                    &client_cx,
                    &started_by_client,
                    "shutdown-ownership handler start",
                )
                .await?;
                caller_cx.cancel_with(
                    CancelKind::User,
                    Some("live HTTP shutdown ownership probe complete"),
                );
                Ok::<_, String>((sse, call))
            })
            .map_err(|error| format!("shutdown-ownership client was not admitted: {error}"))?;

        // This probe deliberately cancels the caller. A timeout_at wrapper
        // would mistake its cancellation-aware timer's early completion for
        // deadline expiry while the server is still settling its children.
        let shutdown = bound
            .serve(cx)
            .await
            .map_err(|error| format!("shutdown-ownership server failed: {error}"))?;
        let (_sse, _call) = client
            .join(cx)
            .await
            .map_err(|error| format!("shutdown-ownership client failed: {error:?}"))??;
        if !cancellation_observed.load(Ordering::Acquire) {
            return Err("live HTTP shutdown did not reach the busy handler".to_owned());
        }

        match (cooperate_with_cancellation, shutdown) {
            (true, HttpServerShutdown::Quiescent) if finished.load(Ordering::Acquire) => Ok(()),
            (true, HttpServerShutdown::Quiescent) => {
                Err("cooperative HTTP handler was joined before recording completion".to_owned())
            }
            (true, HttpServerShutdown::Nonquiescent(mut shutdown)) => {
                let initial = shutdown.poll_settlement();
                let settled = shutdown.settle_for(Duration::from_secs(1)).await;
                Err(format!(
                    "cooperative HTTP shutdown unexpectedly retained children: initial={initial:?}, after bounded settlement={settled:?}"
                ))
            }
            (false, HttpServerShutdown::Quiescent) => {
                Err("non-cooperative HTTP handler was falsely reported as quiescent".to_owned())
            }
            (false, HttpServerShutdown::Nonquiescent(mut shutdown)) => {
                if finished.load(Ordering::Acquire) {
                    return Err(
                        "non-cooperative HTTP handler completed before its retained outcome"
                            .to_owned(),
                    );
                }
                if !matches!(
                    shutdown.poll_settlement(),
                    HttpShutdownSettlement::Pending { remaining } if remaining > 0
                ) {
                    return Err(
                        "non-cooperative HTTP shutdown did not return its live child handle"
                            .to_owned(),
                    );
                }
                release.store(true, Ordering::Release);
                let deadline = Instant::now() + Duration::from_secs(1);
                while !finished.load(Ordering::Acquire) {
                    if Instant::now() >= deadline {
                        return Err(
                            "released non-cooperative HTTP handler did not complete".to_owned()
                        );
                    }
                    asupersync::runtime::yield_now().await;
                }
                shutdown
                    .settle(cx)
                    .await
                    .map_err(|error| format!("caller-owned HTTP child join failed: {error}"))
            }
        }
    }

    #[test]
    fn live_http_shutdown_joins_a_cooperative_child() {
        run_live_http_test(|cx| async move { live_http_shutdown_ownership_probe(&cx, true).await });
    }

    #[test]
    fn live_http_shutdown_returns_caller_owned_noncooperative_child_for_later_join() {
        run_live_http_test(|cx| async move {
            // This differs from the positive only in the handler's
            // cancellation cooperation, preserving the same live HTTP path.
            live_http_shutdown_ownership_probe(&cx, false).await
        });
    }

    #[test]
    fn live_http_cancellation_wakes_idle_listener_and_connection_read() {
        run_live_http_test(|cx| async move {
            let listener_wait_before = live_http_listener_wait_count();
            let listener = Server::new("idle-listener-http", "1.0.0")
                .build()
                .bind_http(&cx, "127.0.0.1:0")
                .await
                .map_err(|error| format!("idle listener bind failed: {error}"))?;
            let caller_cx = cx.clone();
            let mut canceller = cx
                .spawn(move |canceller_cx| async move {
                    if let Err(error) = wait_for_live_http_probe(
                        &canceller_cx,
                        listener_wait_before,
                        live_http_listener_wait_count,
                    )
                    .await
                    {
                        caller_cx
                            .cancel_with(CancelKind::User, Some("idle listener probe timed out"));
                        return Err(error);
                    }
                    caller_cx.cancel_with(CancelKind::User, Some("idle listener cancellation"));
                    Ok(())
                })
                .map_err(|error| format!("idle listener canceller admission failed: {error}"))?;
            let shutdown = listener
                .serve(&cx)
                .await
                .map_err(|error| format!("idle listener serve failed: {error}"))?;
            require_quiescent_http_shutdown(shutdown, "idle listener").await?;
            canceller
                .join(&cx)
                .await
                .map_err(|error| format!("idle listener canceller failed: {error:?}"))??;
            Ok(())
        });

        run_live_http_test(|cx| async move {
            let read_wait_before = live_http_connection_read_wait_count();
            let listener = Server::new("idle-connection-http", "1.0.0")
                .build()
                .bind_http(&cx, "127.0.0.1:0")
                .await
                .map_err(|error| format!("idle connection bind failed: {error}"))?;
            let address = listener
                .local_addr()
                .map_err(|error| format!("idle connection address failed: {error}"))?;
            let caller_cx = cx.clone();
            let mut client = cx
                .spawn(move |client_cx| async move {
                    let mut stream = AsyncTcpStream::connect(address)
                        .await
                        .map_err(|error| format!("idle client connect failed: {error}"))?;
                    stream
                        .write_all(b"POST /mcp HTTP/1.1\r\nHost: loopback\r\n")
                        .await
                        .map_err(|error| format!("idle client partial write failed: {error}"))?;
                    stream
                        .flush()
                        .await
                        .map_err(|error| format!("idle client partial flush failed: {error}"))?;
                    if let Err(error) = wait_for_live_http_probe(
                        &client_cx,
                        read_wait_before,
                        live_http_connection_read_wait_count,
                    )
                    .await
                    {
                        caller_cx.cancel_with(
                            CancelKind::User,
                            Some("idle connection probe timed out"),
                        );
                        return Err(error);
                    }
                    caller_cx.cancel_with(CancelKind::User, Some("idle connection cancellation"));

                    let mut byte = [0_u8; 1];
                    match stream.read(&mut byte).await {
                        Ok(0) | Err(_) => Ok(()),
                        Ok(read) => Err(format!(
                            "idle connection remained live after server cancellation ({read} byte response)"
                        )),
                    }
                })
                .map_err(|error| format!("idle connection client admission failed: {error}"))?;
            let shutdown = listener
                .serve(&cx)
                .await
                .map_err(|error| format!("idle connection serve failed: {error}"))?;
            require_quiescent_http_shutdown(shutdown, "idle connection").await?;
            client
                .join(&cx)
                .await
                .map_err(|error| format!("idle connection client failed: {error:?}"))??;
            Ok(())
        });
    }

