    #[test]
    fn public_http_legacy_sse_binds_opener_principal_before_post() {
        let cx = Cx::for_testing();
        let verifier = StaticTokenVerifier::new([
            ("alpha", AuthContext::with_subject("alice")),
            ("beta", AuthContext::with_subject("bob")),
        ])
        .expect("valid verifier configuration")
        .with_allowed_schemes(["Bearer"])
        .expect("valid scheme configuration");
        let alice = crate::auth::principal_fingerprint(Some(&AuthContext::with_subject("alice")))
            .expect("alice fingerprint");
        let bob = crate::auth::principal_fingerprint(Some(&AuthContext::with_subject("bob")))
            .expect("bob fingerprint");
        let endpoint = Server::new("legacy-sse-owner", "1.0.0")
            .tool(LiveRuntimeListedTool)
            .auth_provider(TokenAuthProvider::new(verifier))
            .build_http_endpoint("http://legacy.test")
            .expect("dual-era endpoint must build");
        let mut session = endpoint
            .open_session(&cx)
            .expect("endpoint must open a bounded live session");

        let denied = block_on(session.handle_async(&cx, HttpRequest::new(HttpMethod::Get, "/sse")))
            .expect("unauthenticated GET must be answered");
        assert!(
            matches!(
                denied,
                ServerHttpEndpointResponse::Immediate(response)
                    if response.status == HttpStatus::UNAUTHORIZED
            ),
            "GET /sse without a token must fail closed when a verifier is installed"
        );

        let stream = block_on(session.handle_async(
            &cx,
            HttpRequest::new(HttpMethod::Get, "/sse").with_header("Authorization", "Bearer alpha"),
        ))
        .expect("authenticated GET must open");
        let ServerHttpEndpointResponse::LegacySse(mut stream) = stream else {
            panic!("authenticated GET must open an exact SSE stream");
        };
        assert!(
            session
                .legacy_session
                .principal_binding()
                .verify_existing(alice),
            "GET /sse must bind the opener before any POST"
        );
        assert!(
            !session
                .legacy_session
                .principal_binding()
                .verify_existing(bob),
            "GET /sse must not bind a different principal"
        );

        let _ = stream
            .recv_event(&cx)
            .expect("legacy stream must advertise its exact POST endpoint");
        let legacy_session_id = session.legacy_session_id().to_owned();
        let post = |message: JsonRpcRequest, token: &str| {
            HttpRequest::new(HttpMethod::Post, "/messages")
                .with_header("content-type", "application/json")
                .with_header("Authorization", format!("Bearer {token}"))
                .with_query("session_id", legacy_session_id.clone())
                .with_body(serde_json::to_vec(&message).expect("legacy request must serialize"))
        };
        let initialize = JsonRpcRequest::new(
            "initialize",
            Some(serde_json::json!({
                "protocolVersion": LEGACY_PROTOCOL_VERSION,
                "capabilities": {},
                "clientInfo": {"name": "legacy-http-client", "version": "1.0.0"},
            })),
            311_i64,
        );
        let initialized = JsonRpcRequest::notification("notifications/initialized", None);
        let foreign_call = JsonRpcRequest::new(
            "tools/call",
            Some(serde_json::json!({
                "name": "live_runtime_listed_tool",
                "arguments": {},
            })),
            312_i64,
        );
        let owned_call = JsonRpcRequest::new(
            "tools/call",
            Some(serde_json::json!({
                "name": "live_runtime_listed_tool",
                "arguments": {},
            })),
            313_i64,
        );

        for request in [initialize, initialized] {
            let response = block_on(session.handle_async(&cx, post(request, "alpha")))
                .expect("opener POST must be dispatched");
            let ServerHttpEndpointResponse::Immediate(response) = response else {
                panic!("legacy POST acknowledgement must be immediate");
            };
            assert_eq!(response.status, HttpStatus::ACCEPTED);
        }
        let codec = Codec::new();
        let initialize_event = stream
            .recv_event(&cx)
            .expect("opener initialize response must stream");
        assert!(matches!(
            codec
                .decode_complete_message(initialize_event.data.as_bytes())
                .expect("initialize event must remain JSON-RPC"),
            JsonRpcMessage::Response(response)
                if response.id == Some(311_i64.into()) && response.error.is_none()
        ));

        let foreign = block_on(session.handle_async(&cx, post(foreign_call, "beta")))
            .expect("foreign POST must be answered");
        let ServerHttpEndpointResponse::Immediate(foreign) = foreign else {
            panic!("foreign legacy POST acknowledgement must be immediate");
        };
        assert_eq!(foreign.status, HttpStatus::ACCEPTED);
        let foreign_event = stream
            .recv_event(&cx)
            .expect("foreign tool response must stream");
        assert!(matches!(
            codec
                .decode_complete_message(foreign_event.data.as_bytes())
                .expect("foreign tool event must remain JSON-RPC"),
            JsonRpcMessage::Response(response)
                if response.id == Some(312_i64.into()) && response.error.is_some()
        ));

        let owned = block_on(session.handle_async(&cx, post(owned_call, "alpha")))
            .expect("opener tool call must be dispatched");
        let ServerHttpEndpointResponse::Immediate(owned) = owned else {
            panic!("opener tool call acknowledgement must be immediate");
        };
        assert_eq!(owned.status, HttpStatus::ACCEPTED);
        let owned_event = stream
            .recv_event(&cx)
            .expect("opener tool response must stream");
        assert!(matches!(
            codec
                .decode_complete_message(owned_event.data.as_bytes())
                .expect("opener tool event must remain JSON-RPC"),
            JsonRpcMessage::Response(response)
                if response.id == Some(313_i64.into())
                    && response.error.is_none()
                    && response
                        .result
                        .as_ref()
                        .is_some_and(|result| result.get("resultType").is_none())
        ));
    }

    #[test]
    fn legacy_http_runtime_retains_session_state_progress_and_log_level() {
        let cx = Cx::for_testing();
        let endpoint = Server::new("legacy-http-runtime", "1.0.0")
            .log_level(Level::Debug)
            .tool(LiveLegacyRuntimeConnectionTool)
            .build_http_endpoint("http://legacy.test")
            .expect("builder must construct the configured dual-era endpoint");
        let mut session = endpoint
            .open_session(&cx)
            .expect("endpoint must open a bounded live session");
        let ServerHttpEndpointResponse::LegacySse(mut stream) =
            block_on(session.handle_async(&cx, HttpRequest::new(HttpMethod::Get, "/sse")))
                .expect("legacy SSE route must open")
        else {
            panic!("legacy GET must open an exact SSE stream");
        };
        let _endpoint = stream
            .recv_event(&cx)
            .expect("legacy stream must advertise its POST endpoint");
        let session_id = session.legacy_session_id().to_owned();
        let post = |message: JsonRpcRequest| {
            HttpRequest::new(HttpMethod::Post, "/messages")
                .with_header("content-type", "application/json")
                .with_query("session_id", session_id.clone())
                .with_body(serde_json::to_vec(&message).expect("message must serialize"))
        };

        for request in [
            JsonRpcRequest::new(
                "initialize",
                Some(serde_json::json!({
                    "protocolVersion": LEGACY_PROTOCOL_VERSION,
                    "capabilities": {},
                    "clientInfo": {"name": "legacy-http-client", "version": "1.0.0"},
                })),
                231_i64,
            ),
            JsonRpcRequest::notification("notifications/initialized", None),
            JsonRpcRequest::new(
                "logging/setLevel",
                Some(serde_json::json!({"level": "debug"})),
                232_i64,
            ),
        ] {
            assert!(matches!(
                block_on(session.handle_async(&cx, post(request))),
                Ok(ServerHttpEndpointResponse::Immediate(response)) if response.status == HttpStatus::ACCEPTED
            ));
        }
        let codec = Codec::new();
        let _initialize = stream
            .recv_event(&cx)
            .expect("initialize response must be delivered");
        let _set_level = stream
            .recv_event(&cx)
            .expect("logging response must be delivered");

        for id in [233_i64, 234_i64] {
            let call = JsonRpcRequest::new(
                "tools/call",
                Some(serde_json::json!({
                    "name": "live_legacy_runtime_connection_tool",
                    "arguments": {"sample": false},
                    "_meta": {"progressToken": "legacy-http-runtime-progress"},
                })),
                id,
            );
            assert!(matches!(
                block_on(session.handle_async(&cx, post(call))),
                Ok(ServerHttpEndpointResponse::Immediate(response)) if response.status == HttpStatus::ACCEPTED
            ));
        }

        let mut progress_count = 0;
        let mut log_count = 0;
        let mut results = Vec::new();
        for _ in 0..6 {
            let event = stream
                .recv_event(&cx)
                .expect("each legacy handler output must reach the same SSE stream");
            match codec
                .decode_complete_message(event.data.as_bytes())
                .expect("legacy runtime output must remain JSON-RPC")
            {
                JsonRpcMessage::Request(notification)
                    if notification.method == "notifications/progress" =>
                {
                    progress_count += 1;
                }
                JsonRpcMessage::Request(notification)
                    if notification.method == "notifications/message" =>
                {
                    log_count += 1;
                }
                JsonRpcMessage::Response(response) => {
                    results.push(
                        response
                            .result
                            .and_then(|result| {
                                result["content"][0]["text"].as_str().map(str::to_owned)
                            })
                            .expect("tool response must preserve the runtime counter text"),
                    );
                }
                message => panic!("unexpected legacy HTTP runtime message: {message:?}"),
            }
        }
        assert_eq!(progress_count, 2);
        assert_eq!(log_count, 2);
        assert_eq!(
            results,
            [
                "legacy-runtime-1-without-sampling".to_owned(),
                "legacy-runtime-2-without-sampling".to_owned(),
            ]
        );
        assert_eq!(session.legacy_session.log_level(), Some(LogLevel::Debug));
    }

    #[test]
    fn legacy_http_delivers_resource_updates_only_to_the_subscribed_uri() {
        // resources/subscribe admits only URIs the router can resolve, so the
        // subscribed target must exist as a registered resource.
        struct SubscribedFileResource;

        impl crate::ResourceHandler for SubscribedFileResource {
            fn definition(&self) -> Resource {
                Resource {
                    uri: "file:///subscribed.txt".to_string(),
                    name: "subscribed".to_string(),
                    description: None,
                    mime_type: Some("text/plain".to_string()),
                    icon: None,
                    version: None,
                    tags: vec![],
                }
            }

            fn read(&self, _ctx: &McpContext) -> McpResult<Vec<fastmcp_protocol::ResourceContent>> {
                Ok(vec![fastmcp_protocol::ResourceContent {
                    uri: "file:///subscribed.txt".to_string(),
                    mime_type: Some("text/plain".to_string()),
                    text: Some("subscribed".to_string()),
                    blob: None,
                }])
            }
        }

        let cx = Cx::for_testing();
        let endpoint = Server::new("legacy-http-resource-update", "1.0.0")
            .resource(SubscribedFileResource)
            .resource_subscriptions()
            .build_http_endpoint("http://legacy.test")
            .expect("builder must construct the configured dual-era endpoint");
        let mut session = endpoint
            .open_session(&cx)
            .expect("endpoint must open a bounded live session");
        let ServerHttpEndpointResponse::LegacySse(mut stream) =
            block_on(session.handle_async(&cx, HttpRequest::new(HttpMethod::Get, "/sse")))
                .expect("legacy SSE route must open")
        else {
            panic!("legacy GET must open an exact SSE stream");
        };
        let _endpoint = stream.recv_event(&cx).expect("legacy endpoint event");
        let session_id = session.legacy_session_id().to_owned();
        let post = |message: JsonRpcRequest| {
            HttpRequest::new(HttpMethod::Post, "/messages")
                .with_header("content-type", "application/json")
                .with_query("session_id", session_id.clone())
                .with_body(serde_json::to_vec(&message).expect("message must serialize"))
        };
        for request in [
            JsonRpcRequest::new(
                "initialize",
                Some(serde_json::json!({
                    "protocolVersion": LEGACY_PROTOCOL_VERSION,
                    "capabilities": {},
                    "clientInfo": {"name": "legacy-http-client", "version": "1.0.0"},
                })),
                241_i64,
            ),
            JsonRpcRequest::notification("notifications/initialized", None),
            JsonRpcRequest::new(
                "resources/subscribe",
                Some(serde_json::json!({"uri": "file:///subscribed.txt"})),
                242_i64,
            ),
        ] {
            assert!(matches!(
                block_on(session.handle_async(&cx, post(request))),
                Ok(ServerHttpEndpointResponse::Immediate(response)) if response.status == HttpStatus::ACCEPTED
            ));
        }
        let _initialize = stream.recv_event(&cx).expect("initialize response");
        let _subscribe = stream.recv_event(&cx).expect("subscribe response");

        assert!(session.notify_legacy_resource_updated("file:///subscribed.txt"));
        let update = stream
            .recv_event(&cx)
            .expect("subscribed update must stream");
        assert!(matches!(
            Codec::new()
                .decode_complete_message(update.data.as_bytes())
                .expect("resource update must remain JSON-RPC"),
            JsonRpcMessage::Request(notification)
                if notification.method == "notifications/resources/updated"
                    && notification.params == Some(serde_json::json!({"uri": "file:///subscribed.txt"}))
        ));

        let before = session
            .legacy_adapter
            .as_ref()
            .expect("subscription retains the exact adapter")
            .snapshot();
        assert!(
            !session.notify_legacy_resource_updated("file:///other.txt"),
            "changing only the URI must not emit a resource update"
        );
        assert_eq!(
            session
                .legacy_adapter
                .as_ref()
                .expect("negative must retain the exact adapter")
                .snapshot(),
            before,
            "the rejected URI must leave subscription state unchanged"
        );
        assert!(
            stream
                .try_recv_event(&cx)
                .expect("unsubscribed update check must not fail")
                .is_none()
        );
    }

    /// The live exact-2024 HTTP handler serves requests only through its async
    /// hook; its synchronous hook refuses instead of blocking on the request.
    #[test]
    fn legacy_http_runtime_handler_serves_requests_only_through_the_async_hook() {
        struct ListedResource;

        impl crate::ResourceHandler for ListedResource {
            fn definition(&self) -> Resource {
                Resource {
                    uri: "file:///listed.txt".to_string(),
                    name: "listed".to_string(),
                    description: None,
                    mime_type: Some("text/plain".to_string()),
                    icon: None,
                    version: None,
                    tags: vec![],
                }
            }

            fn read(&self, _ctx: &McpContext) -> McpResult<Vec<fastmcp_protocol::ResourceContent>> {
                Ok(vec![])
            }
        }

        let cx = Cx::for_testing();
        let endpoint = Server::new("legacy-http-async-hook", "1.0.0")
            .resource(ListedResource)
            .build_http_endpoint("http://legacy.test")
            .expect("builder must construct the configured dual-era endpoint");
        let mut session = endpoint
            .open_session(&cx)
            .expect("endpoint must open a bounded live session");
        let ServerHttpEndpointResponse::LegacySse(mut stream) =
            block_on(session.handle_async(&cx, HttpRequest::new(HttpMethod::Get, "/sse")))
                .expect("legacy SSE route must open")
        else {
            panic!("legacy GET must open an exact SSE stream");
        };
        let _endpoint = stream.recv_event(&cx).expect("legacy endpoint event");
        let session_id = session.legacy_session_id().to_owned();
        let post = |message: JsonRpcRequest| {
            HttpRequest::new(HttpMethod::Post, "/messages")
                .with_header("content-type", "application/json")
                .with_query("session_id", session_id.clone())
                .with_body(serde_json::to_vec(&message).expect("message must serialize"))
        };
        let list = |id: i64| JsonRpcRequest::new("resources/list", Some(serde_json::json!({})), id);
        for request in [
            JsonRpcRequest::new(
                "initialize",
                Some(serde_json::json!({
                    "protocolVersion": LEGACY_PROTOCOL_VERSION,
                    "capabilities": {},
                    "clientInfo": {"name": "legacy-http-client", "version": "1.0.0"},
                })),
                251_i64,
            ),
            JsonRpcRequest::notification("notifications/initialized", None),
            list(252),
        ] {
            assert!(matches!(
                block_on(session.handle_async(&cx, post(request))),
                Ok(ServerHttpEndpointResponse::Immediate(response)) if response.status == HttpStatus::ACCEPTED
            ));
        }
        let _initialize = stream.recv_event(&cx).expect("initialize response");
        let listed = stream.recv_event(&cx).expect("resources/list response");
        let JsonRpcMessage::Response(listed) = Codec::new()
            .decode_complete_message(listed.data.as_bytes())
            .expect("the listing must remain JSON-RPC")
        else {
            panic!("resources/list must answer with a response");
        };
        assert!(listed.error.is_none(), "{listed:?}");
        assert_eq!(
            listed.result.as_ref().expect("listing result")["resources"][0]["uri"],
            "file:///listed.txt"
        );

        // Near-identical negative: the same request on the same adapter's
        // synchronous entry point is refused instead of being dispatched.
        let binding = session.legacy_binding;
        let wire = serde_json::to_value(list(253)).expect("request must serialize");
        let refused = session
            .legacy_adapter
            .as_mut()
            .expect("the session installed its exact adapter")
            .receive(binding, wire)
            .expect("a handler refusal is answered on the wire");
        let Legacy2024Outbound::Response(refused) = refused else {
            panic!("a request must be answered: {refused:?}");
        };
        assert_eq!(refused["error"]["code"], -32603, "{refused}");
        assert_eq!(
            refused["error"]["message"], LIVE_LEGACY_SYNC_DISPATCH_REFUSED,
            "{refused}"
        );
    }

    #[test]
    fn legacy_http_roots_provider_requires_only_the_roots_capability() {
        let cx = Cx::for_testing();
        let endpoint = Server::new("legacy-http-roots", "1.0.0")
            .build_http_endpoint("http://legacy.test")
            .expect("builder must construct the configured dual-era endpoint");
        let mut session = endpoint
            .open_session(&cx)
            .expect("endpoint must open a bounded live session");
        let ServerHttpEndpointResponse::LegacySse(mut stream) =
            block_on(session.handle_async(&cx, HttpRequest::new(HttpMethod::Get, "/sse")))
                .expect("legacy SSE route must open")
        else {
            panic!("legacy GET must open an exact SSE stream");
        };
        let _endpoint = stream.recv_event(&cx).expect("legacy endpoint event");
        let session_id = session.legacy_session_id().to_owned();
        let post = |message: JsonRpcRequest| {
            HttpRequest::new(HttpMethod::Post, "/messages")
                .with_header("content-type", "application/json")
                .with_query("session_id", session_id.clone())
                .with_body(serde_json::to_vec(&message).expect("message must serialize"))
        };
        for request in [
            JsonRpcRequest::new(
                "initialize",
                Some(serde_json::json!({
                    "protocolVersion": LEGACY_PROTOCOL_VERSION,
                    "capabilities": {"roots": {}},
                    "clientInfo": {"name": "legacy-http-client", "version": "1.0.0"},
                })),
                251_i64,
            ),
            JsonRpcRequest::notification("notifications/initialized", None),
        ] {
            assert!(matches!(
                block_on(session.handle_async(&cx, post(request))),
                Ok(ServerHttpEndpointResponse::Immediate(response)) if response.status == HttpStatus::ACCEPTED
            ));
        }
        let _initialize = stream.recv_event(&cx).expect("initialize response");

        let provider = session
            .legacy_roots_provider()
            .expect("roots capability must expose the shipped provider");
        let roots_task = std::thread::spawn(move || block_on(provider.list_roots()));
        let request = stream
            .recv_event(&cx)
            .expect("roots provider must emit a reverse request");
        let JsonRpcMessage::Request(request) = Codec::new()
            .decode_complete_message(request.data.as_bytes())
            .expect("roots reverse request must remain JSON-RPC")
        else {
            panic!("roots provider must emit a request");
        };
        assert_eq!(request.method, "roots/list");
        let response = JsonRpcResponse::success(
            request.id.expect("roots request must have an ID"),
            serde_json::json!({"roots": [{"uri": "file:///work", "name": "work"}]}),
        );
        let response_post = HttpRequest::new(HttpMethod::Post, "/messages")
            .with_header("content-type", "application/json")
            .with_query("session_id", session.legacy_session_id())
            .with_body(serde_json::to_vec(&response).expect("response must serialize"));
        assert!(matches!(
            block_on(session.handle_async(&cx, response_post)),
            Ok(ServerHttpEndpointResponse::Immediate(response)) if response.status == HttpStatus::ACCEPTED
        ));
        let roots = roots_task
            .join()
            .expect("roots task must not panic")
            .expect("routed roots response must complete the provider");
        assert_eq!(roots.len(), 1);
        assert_eq!(roots[0].uri, "file:///work");
    }

    #[test]
    fn legacy_http_roots_provider_is_absent_without_roots_capability() {
        let cx = Cx::for_testing();
        let endpoint = Server::new("legacy-http-roots", "1.0.0")
            .build_http_endpoint("http://legacy.test")
            .expect("builder must construct the configured dual-era endpoint");
        let mut session = endpoint
            .open_session(&cx)
            .expect("endpoint must open a bounded live session");
        let ServerHttpEndpointResponse::LegacySse(mut stream) =
            block_on(session.handle_async(&cx, HttpRequest::new(HttpMethod::Get, "/sse")))
                .expect("legacy SSE route must open")
        else {
            panic!("legacy GET must open an exact SSE stream");
        };
        let _endpoint = stream.recv_event(&cx).expect("legacy endpoint event");
        let session_id = session.legacy_session_id().to_owned();
        let post = |message: JsonRpcRequest| {
            HttpRequest::new(HttpMethod::Post, "/messages")
                .with_header("content-type", "application/json")
                .with_query("session_id", session_id.clone())
                .with_body(serde_json::to_vec(&message).expect("message must serialize"))
        };
        for request in [
            JsonRpcRequest::new(
                "initialize",
                Some(serde_json::json!({
                    "protocolVersion": LEGACY_PROTOCOL_VERSION,
                    "capabilities": {},
                    "clientInfo": {"name": "legacy-http-client", "version": "1.0.0"},
                })),
                251_i64,
            ),
            JsonRpcRequest::notification("notifications/initialized", None),
        ] {
            assert!(matches!(
                block_on(session.handle_async(&cx, post(request))),
                Ok(ServerHttpEndpointResponse::Immediate(response)) if response.status == HttpStatus::ACCEPTED
            ));
        }
        let _initialize = stream.recv_event(&cx).expect("initialize response");
        assert!(
            session.legacy_roots_provider().is_none(),
            "changing only the negotiated roots capability must withhold the provider"
        );
        assert!(
            stream
                .try_recv_event(&cx)
                .expect("capability negative check must not fail")
                .is_none()
        );
    }

    #[test]
    fn legacy_http_wrong_session_rejection_leaves_the_live_lifecycle_unchanged() {
        let cx = Cx::for_testing();
        let endpoint = Server::new("legacy-http-wrong-session", "1.0.0")
            .tool(LiveRuntimeListedTool)
            .build_http_endpoint("http://legacy.test")
            .expect("builder must construct the configured dual-era endpoint");
        let mut session = endpoint
            .open_session(&cx)
            .expect("endpoint must open a bounded live session");
        let stream = block_on(session.handle_async(&cx, HttpRequest::new(HttpMethod::Get, "/sse")))
            .expect("legacy SSE route must open");
        let ServerHttpEndpointResponse::LegacySse(mut stream) = stream else {
            panic!("legacy GET must open an exact SSE stream");
        };
        let _endpoint = stream
            .recv_event(&cx)
            .expect("legacy stream must advertise its exact POST endpoint");

        let initialize = JsonRpcRequest::new(
            "initialize",
            Some(serde_json::json!({
                "protocolVersion": LEGACY_PROTOCOL_VERSION,
                "capabilities": {},
                "clientInfo": {"name": "legacy-http-client", "version": "1.0.0"},
            })),
            221_i64,
        );
        let initialize_response = block_on(
            session.handle_async(
                &cx,
                HttpRequest::new(HttpMethod::Post, "/messages")
                    .with_header("content-type", "application/json")
                    .with_query("session_id", session.legacy_session_id())
                    .with_body(
                        serde_json::to_vec(&initialize)
                            .expect("legacy initialize request must serialize"),
                    ),
            ),
        )
        .expect("correct-session initialize must dispatch");
        assert!(matches!(
            initialize_response,
            ServerHttpEndpointResponse::Immediate(response) if response.status == HttpStatus::ACCEPTED
        ));
        let _initialize = stream
            .recv_event(&cx)
            .expect("initialize response must be streamed before lifecycle advance");
        let initialized = JsonRpcRequest::notification("notifications/initialized", None);
        let initialized_response = block_on(
            session.handle_async(
                &cx,
                HttpRequest::new(HttpMethod::Post, "/messages")
                    .with_header("content-type", "application/json")
                    .with_query("session_id", session.legacy_session_id())
                    .with_body(
                        serde_json::to_vec(&initialized)
                            .expect("legacy initialized notification must serialize"),
                    ),
            ),
        )
        .expect("correct-session initialized notification must dispatch");
        assert!(matches!(
            initialized_response,
            ServerHttpEndpointResponse::Immediate(response) if response.status == HttpStatus::ACCEPTED
        ));

        let valid = JsonRpcRequest::new(
            "tools/call",
            Some(serde_json::json!({
                "name": "live_runtime_listed_tool",
                "arguments": {},
            })),
            222_i64,
        );
        let mut wrong_session = HttpRequest::new(HttpMethod::Post, "/messages")
            .with_header("content-type", "application/json")
            .with_query("session_id", session.legacy_session_id())
            .with_body(serde_json::to_vec(&valid).expect("legacy tool request must serialize"));
        wrong_session
            .query
            .insert("session_id".to_string(), "wrong-session".to_string());
        let before = session
            .legacy_adapter
            .as_ref()
            .expect("initialize installs the exact legacy adapter")
            .snapshot();
        let rejected = block_on(session.handle_async(&cx, wrong_session))
            .expect("wrong session must become an HTTP rejection");
        assert!(matches!(
            rejected,
            ServerHttpEndpointResponse::Immediate(response) if response.status == HttpStatus::NOT_FOUND
        ));
        assert_eq!(
            session
                .legacy_adapter
                .as_ref()
                .expect("wrong session must not remove the adapter")
                .snapshot(),
            before,
            "changing only the session ID must not mutate the live exact lifecycle"
        );

        let accepted = block_on(
            session.handle_async(
                &cx,
                HttpRequest::new(HttpMethod::Post, "/messages")
                    .with_header("content-type", "application/json")
                    .with_query("session_id", session.legacy_session_id())
                    .with_body(
                        serde_json::to_vec(&valid).expect("legacy tool request must serialize"),
                    ),
            ),
        )
        .expect("the otherwise identical correct-session request must dispatch");
        assert!(matches!(
            accepted,
            ServerHttpEndpointResponse::Immediate(response) if response.status == HttpStatus::ACCEPTED
        ));
        let call = stream
            .recv_event(&cx)
            .expect("the unchanged lifecycle must still dispatch the valid call");
        assert!(matches!(
            Codec::new()
                .decode_complete_message(call.data.as_bytes())
                .expect("valid call event must remain JSON-RPC"),
            JsonRpcMessage::Response(response) if response.id == Some(222_i64.into())
        ));
    }

    #[test]
    fn legacy_http_closed_stream_rejects_cancellation_before_authority_mutation() {
        let cx = Cx::for_testing();
        let endpoint = Server::new("legacy-http-closed-cancellation", "1.0.0")
            .build_http_endpoint("http://legacy.test")
            .expect("dual-era endpoint must build");
        let mut session = endpoint
            .open_session(&cx)
            .expect("endpoint must open a bounded session");
        let ServerHttpEndpointResponse::LegacySse(stream) =
            block_on(session.handle_async(&cx, HttpRequest::new(HttpMethod::Get, "/sse")))
                .expect("legacy SSE route must open")
        else {
            panic!("legacy GET must return a live body");
        };

        let request_id = RequestId::Number(2_223);
        let target = JsonRpcRequest::new("tools/list", None, request_id.clone());
        let _admission = session
            .legacy_admissions
            .admit(
                &target,
                &session.legacy_session.principal_binding(),
                auth::principal_fingerprint(None).expect("anonymous principal is admissible"),
            )
            .expect("target request admission must remain structurally valid")
            .expect("correlated target must allocate cancellation authority");
        let target_cancellation = session
            .legacy_admissions
            .admitted_request_cancellation(&request_id)
            .expect("target authority must be observable before peer close");
        let control = session.cancellation_control();
        drop(stream);

        let cancellation = JsonRpcRequest::notification(
            "notifications/cancelled",
            Some(serde_json::json!({
                "requestId": request_id,
                "_meta": {"com.example/application": true},
            })),
        );
        let rejected = control
            .handle(
                &cx,
                &HttpRequest::new(HttpMethod::Post, "/messages")
                    .with_header("content-type", "application/json")
                    .with_query("session_id", session.legacy_session_id())
                    .with_body(
                        serde_json::to_vec(&cancellation)
                            .expect("legacy cancellation must serialize"),
                    ),
            )
            .expect("the exact cancellation route owns the HTTP response");
        assert_eq!(rejected.status, HttpStatus::SERVICE_UNAVAILABLE);
        assert!(!target_cancellation.is_cancel_requested());
        assert!(
            session
                .legacy_admissions
                .contains(&RequestId::Number(2_223))
        );
        assert!(
            session
                .endpoint_session
                .lock()
                .expect("transport session lock must remain healthy")
                .take_legacy_request()
                .is_none(),
            "closed-stream cancellation rejection cannot enqueue work"
        );
    }

    struct LiveLegacyActiveCancellationRecv {
        phase: usize,
        started: Arc<AtomicBool>,
        observed_cancellation: Arc<AtomicBool>,
        responses: Arc<LiveModernResponses>,
    }

    impl TransportRecvHalf for LiveLegacyActiveCancellationRecv {
        fn recv(&mut self, _cx: &Cx) -> Result<JsonRpcMessage, TransportError> {
            let phase = self.phase;
            self.phase = self.phase.saturating_add(1);
            match phase {
                0 => Ok(exact_legacy_initialize_request(
                    71,
                    serde_json::json!("1.0.0"),
                )),
                1 => Ok(JsonRpcMessage::Request(JsonRpcRequest::notification(
                    "notifications/initialized",
                    None,
                ))),
                2 => Ok(JsonRpcMessage::Request(JsonRpcRequest::new(
                    "tools/call",
                    Some(serde_json::json!({
                        "name": "live_legacy_cancellation_tool",
                        "arguments": {},
                    })),
                    72_i64,
                ))),
                3 => {
                    let deadline = Instant::now() + Duration::from_secs(1);
                    while !self.started.load(Ordering::Acquire) && Instant::now() < deadline {
                        std::thread::yield_now();
                    }
                    if !self.started.load(Ordering::Acquire) {
                        return Err(TransportError::Timeout);
                    }
                    Ok(JsonRpcMessage::Request(JsonRpcRequest::notification(
                        "notifications/cancelled",
                        Some(serde_json::json!({
                            "requestId": 72,
                            "reason": "test cancellation",
                        })),
                    )))
                }
                4 => {
                    let deadline = Instant::now() + Duration::from_secs(1);
                    while !self.observed_cancellation.load(Ordering::Acquire)
                        && Instant::now() < deadline
                    {
                        std::thread::yield_now();
                    }
                    if self.observed_cancellation.load(Ordering::Acquire) {
                        Ok(JsonRpcMessage::Request(JsonRpcRequest::new(
                            "ping", None, 73_i64,
                        )))
                    } else {
                        Err(TransportError::Timeout)
                    }
                }
                _ => {
                    if self
                        .responses
                        .wait_for_responses(&[73], Duration::from_secs(1))
                    {
                        Err(TransportError::Closed)
                    } else {
                        Err(TransportError::Timeout)
                    }
                }
            }
        }

        fn close(&mut self, _cx: &Cx) -> Result<(), TransportError> {
            Ok(())
        }
    }

    #[test]
    fn live_runtime_cancels_exact_legacy_tool_by_its_original_wire_id() {
        run_live_legacy_active_cancellation(false);
    }

    #[test]
    fn legacy_application_content_preserves_active_wire_cancellation() {
        run_live_legacy_active_cancellation(true);
    }

    fn run_live_legacy_active_cancellation(application_content: bool) {
        let started = Arc::new(AtomicBool::new(false));
        let observed_cancellation = Arc::new(AtomicBool::new(false));
        let responses = Arc::new(LiveModernResponses::default());

        run_live_split_transport(
            Duration::from_secs(20),
            Server::new("live-legacy-cancellation", "1.0.0")
                .legacy_application_tool_content(application_content)
                .protocol_policy(ProtocolPolicy::Auto)
                .expect("Auto must be available to this test build")
                .tool(LiveLegacyCancellationTool {
                    started: Arc::clone(&started),
                    observed_cancellation: Arc::clone(&observed_cancellation),
                })
                .build(),
            LiveLegacyActiveCancellationRecv {
                phase: 0,
                started: Arc::clone(&started),
                observed_cancellation: Arc::clone(&observed_cancellation),
                responses: Arc::clone(&responses),
            },
            LiveModernSplitSend {
                responses: Arc::clone(&responses),
            },
        )
        .expect("accepted active cancellation must close the public transport cleanly");

        assert!(observed_cancellation.load(Ordering::Acquire));
        assert_eq!(responses.response_count(71), 1);
        assert_eq!(responses.response_count(72), 0);
        assert_eq!(responses.response_count(73), 1);
        assert!(
            responses
                .response(73)
                .is_some_and(|response| response.error.is_none())
        );
    }

    struct LiveLegacyQueuedCancellationRecv {
        phase: usize,
        cancelled_request_id: i64,
        initialize_send_started: Arc<BoundedTestSignal>,
        initialize_send_release: Arc<BoundedTestSignal>,
        control: Arc<LiveModernControl>,
        responses: Arc<LiveModernResponses>,
    }

    impl TransportRecvHalf for LiveLegacyQueuedCancellationRecv {
        fn recv(&mut self, _cx: &Cx) -> Result<JsonRpcMessage, TransportError> {
            let phase = self.phase;
            self.phase = self.phase.saturating_add(1);
            match phase {
                0 => Ok(exact_legacy_initialize_request(
                    75,
                    serde_json::json!("1.0.0"),
                )),
                1 => Ok(JsonRpcMessage::Request(JsonRpcRequest::notification(
                    "notifications/initialized",
                    None,
                ))),
                2 => {
                    // Hold the initialization response attempt so request 80
                    // is certainly the first queued application request when
                    // its cancellation reaches the receive pump.
                    if self.initialize_send_started.wait(Duration::from_secs(2)) {
                        Ok(legacy_controlled_tool_request(80))
                    } else {
                        Err(TransportError::Timeout)
                    }
                }
                3 => Ok(JsonRpcMessage::Request(JsonRpcRequest::notification(
                    "notifications/cancelled",
                    Some(serde_json::json!({
                        "requestId": self.cancelled_request_id,
                        "reason": "queued cancellation",
                    })),
                ))),
                4 => {
                    // `recv` is called again only after the cancellation frame
                    // from phase 3 has been authenticated and applied.
                    self.initialize_send_release.raise();
                    Ok(JsonRpcMessage::Request(JsonRpcRequest::new(
                        "ping", None, 82_i64,
                    )))
                }
                5 => {
                    if self.cancelled_request_id == 80 {
                        if !self
                            .responses
                            .wait_for_responses(&[82], Duration::from_secs(2))
                        {
                            return Err(TransportError::Timeout);
                        }
                    } else {
                        if !self.control.wait_for_started(1, Duration::from_secs(2)) {
                            return Err(TransportError::Timeout);
                        }
                        self.control.release(80);
                        if !self
                            .responses
                            .wait_for_responses(&[80, 82], Duration::from_secs(2))
                        {
                            return Err(TransportError::Timeout);
                        }
                    }
                    Err(TransportError::Closed)
                }
                _ => Err(TransportError::Closed),
            }
        }

        fn close(&mut self, _cx: &Cx) -> Result<(), TransportError> {
            Ok(())
        }
    }

    struct LiveLegacyFirstQueuedSend {
        initialize_send_started: Arc<BoundedTestSignal>,
        initialize_send_release: Arc<BoundedTestSignal>,
        responses: Arc<LiveModernResponses>,
    }

    impl TransportSendHalf for LiveLegacyFirstQueuedSend {
        fn send(&mut self, _cx: &Cx, message: &JsonRpcMessage) -> Result<(), TransportError> {
            self.responses.record(message.clone());
            if matches!(
                message,
                JsonRpcMessage::Response(response) if response.id == Some(75_i64.into())
            ) {
                self.initialize_send_started.raise();
                if !self.initialize_send_release.wait(Duration::from_secs(2)) {
                    return Err(TransportError::Timeout);
                }
            }
            Ok(())
        }

        fn close(&mut self, _cx: &Cx) -> Result<(), TransportError> {
            Ok(())
        }
    }

    fn live_legacy_queued_cancellation_transcript(
        cancelled_request_id: i64,
    ) -> (
        McpResult<()>,
        Arc<LiveModernControl>,
        Arc<LiveModernResponses>,
    ) {
        let control = Arc::new(LiveModernControl::default());
        let responses = Arc::new(LiveModernResponses::default());
        let initialize_send_started = Arc::new(BoundedTestSignal::default());
        let initialize_send_release = Arc::new(BoundedTestSignal::default());

        let result = run_live_split_transport(
            Duration::from_secs(20),
            Server::new("live-legacy-queued-cancellation", "1.0.0")
                .protocol_policy(ProtocolPolicy::Auto)
                .expect("Auto must be available to this test build")
                .tool(LiveModernControlledTool {
                    control: Arc::clone(&control),
                })
                .build(),
            LiveLegacyQueuedCancellationRecv {
                phase: 0,
                cancelled_request_id,
                initialize_send_started: Arc::clone(&initialize_send_started),
                initialize_send_release: Arc::clone(&initialize_send_release),
                control: Arc::clone(&control),
                responses: Arc::clone(&responses),
            },
            LiveLegacyFirstQueuedSend {
                initialize_send_started,
                initialize_send_release,
                responses: Arc::clone(&responses),
            },
        )
        .map_err(McpError::internal_error);

        (result, control, responses)
    }

    #[test]
    fn live_exact_legacy_first_queued_cancellation_suppresses_only_the_target_response() {
        let (result, control, responses) = live_legacy_queued_cancellation_transcript(80);

        result.expect("accepted queued cancellation must close the public transport cleanly");
        assert_eq!(responses.response_count(75), 1);
        assert_eq!(responses.response_count(80), 0);
        assert_eq!(responses.response_count(82), 1);
        assert_eq!(control.max_active(), 0);
        assert!(!control.was_cancelled(80));
        assert!(
            responses
                .response(82)
                .is_some_and(|response| response.error.is_none())
        );
    }

