    #[test]
    fn split_returning_modern_progress_write_success_quiesces() {
        split_returning_modern_progress_write_case(false);
    }

    #[test]
    fn split_returning_modern_progress_write_failure_survives_successful_terminal_write() {
        split_returning_modern_progress_write_case(true);
    }

    fn split_returning_modern_progress_write_case(fail_progress_write: bool) {
        const REQUEST_ID: i64 = 1210;

        #[derive(Default)]
        struct Probe {
            control: Arc<LiveModernControl>,
            responses: Arc<LiveModernResponses>,
            receive_waiting: BoundedTestSignal,
            progress_attempted: BoundedTestSignal,
            progress_attempts: AtomicUsize,
            receive_calls: AtomicUsize,
            closed_after_terminal: AtomicUsize,
            timeout_returns: AtomicUsize,
            receive_closes: AtomicUsize,
            send_closes: AtomicUsize,
        }

        struct ProgressWriteRecv {
            probe: Arc<Probe>,
        }

        impl TransportRecvHalf for ProgressWriteRecv {
            fn recv(&mut self, _cx: &Cx) -> Result<JsonRpcMessage, TransportError> {
                match self.probe.receive_calls.fetch_add(1, Ordering::AcqRel) {
                    0 => Ok(modern_discovery_opening_request()),
                    1 => {
                        if !self
                            .probe
                            .responses
                            .wait_for_responses(&[905], Duration::from_secs(2))
                        {
                            self.probe.timeout_returns.fetch_add(1, Ordering::AcqRel);
                            return Err(TransportError::Timeout);
                        }
                        Ok(modern_controlled_tool_progress_request(REQUEST_ID))
                    }
                    2 => {
                        // Keep the receive operation open until both the progress
                        // attempt and the terminal write finish. This exercises
                        // the failure latch even when EOF wins the next observation.
                        self.probe.receive_waiting.raise();
                        if !self.probe.progress_attempted.wait(Duration::from_secs(2)) {
                            self.probe.control.release_all();
                            self.probe.timeout_returns.fetch_add(1, Ordering::AcqRel);
                            return Err(TransportError::Timeout);
                        }
                        self.probe.control.release(REQUEST_ID as u64);
                        if self
                            .probe
                            .responses
                            .wait_for_responses(&[REQUEST_ID], Duration::from_secs(2))
                        {
                            self.probe
                                .closed_after_terminal
                                .fetch_add(1, Ordering::AcqRel);
                            Err(TransportError::Closed)
                        } else {
                            self.probe.timeout_returns.fetch_add(1, Ordering::AcqRel);
                            Err(TransportError::Timeout)
                        }
                    }
                    _ => Err(TransportError::Closed),
                }
            }

            fn close(&mut self, _cx: &Cx) -> Result<(), TransportError> {
                self.probe.receive_closes.fetch_add(1, Ordering::AcqRel);
                Ok(())
            }
        }

        struct ProgressWriteSend {
            probe: Arc<Probe>,
            fail_progress_write: bool,
        }

        impl TransportSendHalf for ProgressWriteSend {
            fn send(&mut self, _cx: &Cx, message: &JsonRpcMessage) -> Result<(), TransportError> {
                if matches!(message, JsonRpcMessage::Request(notification)
                    if notification.method == "notifications/progress")
                {
                    if !self.probe.receive_waiting.wait(Duration::from_secs(2)) {
                        self.probe.timeout_returns.fetch_add(1, Ordering::AcqRel);
                        return Err(TransportError::Timeout);
                    }
                    self.probe.progress_attempts.fetch_add(1, Ordering::AcqRel);
                    self.probe.progress_attempted.raise();
                    // The sole changed input between the paired cases is the
                    // result of this progress write. All responses still succeed.
                    if self.fail_progress_write {
                        return Err(TransportError::Io(std::io::Error::other(
                            "progress write failed",
                        )));
                    }
                }
                self.probe.responses.record(message.clone());
                Ok(())
            }

            fn close(&mut self, _cx: &Cx) -> Result<(), TransportError> {
                self.probe.send_closes.fetch_add(1, Ordering::AcqRel);
                Ok(())
            }
        }

        let probe = Arc::new(Probe::default());
        let server = Server::new("split-progress-write", "1.0.0")
            .protocol_policy(ProtocolPolicy::Auto)
            .expect("Auto must be available to this test build")
            .tool(LiveModernControlledTool {
                control: Arc::clone(&probe.control),
            })
            .build();
        let active_requests = Arc::clone(&server.active_requests);
        let result = run_live_split_transport(
            Duration::from_nanos(LIVE_HTTP_TEST_TIMEOUT_NANOS),
            server,
            ProgressWriteRecv {
                probe: Arc::clone(&probe),
            },
            ProgressWriteSend {
                probe: Arc::clone(&probe),
                fail_progress_write,
            },
        );

        assert_eq!(probe.receive_calls.load(Ordering::Acquire), 3);
        assert_eq!(
            probe.closed_after_terminal.load(Ordering::Acquire),
            1,
            "receive must return clean EOF only after observing the terminal write"
        );
        assert_eq!(
            probe.timeout_returns.load(Ordering::Acquire),
            0,
            "a fixture timeout must never substitute for the notification failure"
        );
        assert_eq!(probe.progress_attempts.load(Ordering::Acquire), 1);
        assert_eq!(probe.responses.response_count(905), 1);
        assert_eq!(probe.responses.response_count(REQUEST_ID), 1);
        assert_eq!(probe.receive_closes.load(Ordering::Acquire), 1);
        assert_eq!(probe.send_closes.load(Ordering::Acquire), 1);
        assert!(probe.control.has_started(REQUEST_ID as u64));
        assert_eq!(
            probe
                .control
                .state
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .active,
            0,
            "handler cleanup must finish before the returning runner settles"
        );
        assert!(
            active_requests
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .is_empty(),
            "the runner must retire every request owner"
        );
        let progress_writes = probe
            .responses
            .messages()
            .iter()
            .filter(|message| {
                matches!(message, JsonRpcMessage::Request(notification)
                if notification.method == "notifications/progress")
            })
            .count();
        let terminal = probe
            .responses
            .response(REQUEST_ID)
            .expect("the terminal response write succeeds in both cases");
        if fail_progress_write {
            assert_eq!(progress_writes, 0);
            assert!(terminal.result.is_none());
            assert_eq!(
                terminal.error.and_then(|error| error.code.as_i32()),
                Some(i32::from(McpErrorCode::RequestCancelled))
            );
            let error = result.expect_err(
                "a successful cancellation response cannot erase the progress-write failure",
            );
            assert!(error.contains("Server transport loop failed"), "{error}");
        } else {
            assert_eq!(progress_writes, 1);
            assert!(terminal.error.is_none());
            let result_body = terminal.result.expect("successful tool result");
            assert_eq!(result_body["resultType"], "complete");
            assert_eq!(result_body["content"][0]["text"], "modern request 1210");
            result.expect("successful progress and response writes must quiesce cleanly");
        }
    }

    #[test]
    fn live_modern_stdio_metadata_free_cancellation_isolated_to_the_matching_request() {
        let control = Arc::new(LiveModernControl::default());
        let responses = Arc::new(LiveModernResponses::default());
        let control_for_receive = Arc::clone(&control);
        let responses_for_receive = Arc::clone(&responses);
        let phase = Arc::new(AtomicUsize::new(0));
        let phase_for_receive = Arc::clone(&phase);

        let exit_code = run_live_modern_pump(
            Server::new("live-modern-cancellation", "1.0.0")
                .protocol_policy(ProtocolPolicy::Auto)
                .expect("Auto must be available to this test build")
                .tool(LiveModernControlledTool {
                    control: Arc::clone(&control),
                })
                .build(),
            move |_cx, _worker_failed| match phase_for_receive.fetch_add(1, Ordering::AcqRel) {
                0 => Ok(modern_discovery_opening_request()),
                1 => Ok(modern_controlled_tool_request(200)),
                2 => {
                    if control_for_receive.wait_for_started(1, Duration::from_secs(2)) {
                        Ok(modern_controlled_tool_request(201))
                    } else {
                        Err(TransportError::Timeout)
                    }
                }
                3 => {
                    if control_for_receive.wait_for_started(2, Duration::from_secs(2)) {
                        Ok(modern_cancelled_notification(200))
                    } else {
                        Err(TransportError::Timeout)
                    }
                }
                4 => {
                    if !control_for_receive.wait_for_cancellation(200, Duration::from_secs(2)) {
                        return Err(TransportError::Timeout);
                    }
                    control_for_receive.release(201);
                    if responses_for_receive.wait_for_responses(&[200, 201], Duration::from_secs(2))
                    {
                        Err(TransportError::Closed)
                    } else {
                        Err(TransportError::Timeout)
                    }
                }
                _ => Err(TransportError::Closed),
            },
            Arc::clone(&responses),
        );

        assert_eq!(
            exit_code,
            0,
            "modern cancellation pump failed: phase={}, started200={}, started201={}, \
             cancelled200={}, cancelled201={}, max_active={}, response200={:?}, response201={:?}",
            phase.load(Ordering::Acquire),
            control.has_started(200),
            control.has_started(201),
            control.was_cancelled(200),
            control.was_cancelled(201),
            control.max_active(),
            responses.response(200),
            responses.response(201),
        );
        assert!(control.was_cancelled(200));
        assert!(!control.was_cancelled(201));
        assert_eq!(
            control
                .state
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .active,
            0,
            "all controlled calls must finish cleanup before the pump returns"
        );
        assert_eq!(responses.response_count(200), 1);
        assert_eq!(responses.response_count(201), 1);
        assert_eq!(
            responses
                .response(200)
                .and_then(|response| response.error)
                .and_then(|error| error.code.as_i32()),
            Some(i32::from(McpErrorCode::RequestCancelled))
        );
        assert!(
            responses
                .response(201)
                .is_some_and(|response| response.error.is_none())
        );
    }

    #[test]
    fn public_stdio_final_progress_flushes_during_work_before_log_and_terminal_response() {
        const REQUEST_ID: i64 = 206;
        let control = Arc::new(LiveModernControl::default());
        let responses = Arc::new(LiveModernResponses::default());
        let control_for_receive = Arc::clone(&control);
        let responses_for_receive = Arc::clone(&responses);
        let phase = Arc::new(AtomicUsize::new(0));
        let phase_for_receive = Arc::clone(&phase);

        let exit_code = run_live_modern_pump(
            Server::new("public-stdio-final-progress", "1.0.0")
                .protocol_policy(ProtocolPolicy::Auto)
                .expect("Auto must be available to this test build")
                .log_level(Level::Debug)
                .tool(LiveModernControlledTool {
                    control: Arc::clone(&control),
                })
                .build(),
            move |_cx, _worker_failed| match phase_for_receive.fetch_add(1, Ordering::AcqRel) {
                0 => Ok(modern_discovery_opening_request()),
                1 => Ok(modern_controlled_tool_progress_request(REQUEST_ID)),
                2 => {
                    if !control_for_receive.wait_for_started(1, Duration::from_secs(2)) {
                        return Err(TransportError::Timeout);
                    }
                    if !responses_for_receive
                        .wait_for_notification("notifications/progress", Duration::from_secs(2))
                        || responses_for_receive.response_count(REQUEST_ID) != 0
                    {
                        return Err(TransportError::Timeout);
                    }
                    control_for_receive.release(REQUEST_ID as u64);
                    if responses_for_receive
                        .wait_for_responses(&[REQUEST_ID], Duration::from_secs(2))
                    {
                        Err(TransportError::Closed)
                    } else {
                        Err(TransportError::Timeout)
                    }
                }
                _ => Err(TransportError::Closed),
            },
            Arc::clone(&responses),
        );

        assert_eq!(exit_code, 0);
        let messages = responses.messages();
        let progress = messages
            .iter()
            .enumerate()
            .find_map(|(index, message)| match message {
                JsonRpcMessage::Request(notification)
                    if notification.method == "notifications/progress" =>
                {
                    Some((index, notification))
                }
                _ => None,
            })
            .expect("the public stdio request must emit its coalesced progress");
        assert_eq!(
            messages
                .iter()
                .filter(|message| matches!(
                    message,
                    JsonRpcMessage::Request(notification)
                        if notification.method == "notifications/progress"
                ))
                .count(),
            1,
            "the outer final-progress runtime must retain only its latest update"
        );
        let progress_wire = serde_json::to_string(
            progress
                .1
                .params
                .as_ref()
                .expect("coalesced progress must have parameters"),
        )
        .expect("coalesced progress parameters must serialize");
        assert!(progress_wire.contains("\"progressToken\":\"public-stdio-final-progress\""));
        assert!(progress_wire.contains("\"progress\":12000"));
        assert!(progress_wire.contains("\"total\":11999"));
        assert!(progress_wire.contains("\"message\":\"latest\""));
        let log_index = messages
            .iter()
            .position(|message| {
                matches!(message, JsonRpcMessage::Request(notification) if notification.method == "notifications/message")
            })
            .expect("the final log must be written after progress");
        let response_index = messages
            .iter()
            .position(|message| {
                matches!(
                    message,
                    JsonRpcMessage::Response(response)
                        if response.id == Some(REQUEST_ID.into()) && response.error.is_none()
                )
            })
            .expect("the terminal response must be written");
        assert!(
            progress.0 < log_index && log_index < response_index,
            "the rate-flushed progress must precede the final log and terminal response"
        );
    }

    #[test]
    fn public_stdio_final_progress_cancellation_suppresses_post_cancellation_frames() {
        const REQUEST_ID: i64 = 207;
        let control = Arc::new(LiveModernControl::default());
        let responses = Arc::new(LiveModernResponses::default());
        let control_for_receive = Arc::clone(&control);
        let responses_for_receive = Arc::clone(&responses);
        let phase = Arc::new(AtomicUsize::new(0));
        let phase_for_receive = Arc::clone(&phase);

        let exit_code = run_live_modern_pump(
            Server::new("public-stdio-final-progress-cancel", "1.0.0")
                .protocol_policy(ProtocolPolicy::Auto)
                .expect("Auto must be available to this test build")
                .log_level(Level::Debug)
                .tool(LiveModernControlledTool {
                    control: Arc::clone(&control),
                })
                .build(),
            move |_cx, _worker_failed| match phase_for_receive.fetch_add(1, Ordering::AcqRel) {
                0 => Ok(modern_discovery_opening_request()),
                1 => Ok(modern_controlled_tool_progress_request(REQUEST_ID)),
                2 => {
                    if control_for_receive.wait_for_started(1, Duration::from_secs(2)) {
                        if responses_for_receive
                            .wait_for_notification("notifications/progress", Duration::from_secs(2))
                        {
                            Ok(modern_cancelled_notification(REQUEST_ID as u64))
                        } else {
                            Err(TransportError::Timeout)
                        }
                    } else {
                        Err(TransportError::Timeout)
                    }
                }
                3 => {
                    if !control_for_receive
                        .wait_for_cancellation(REQUEST_ID as u64, Duration::from_secs(2))
                    {
                        return Err(TransportError::Timeout);
                    }
                    if responses_for_receive
                        .wait_for_responses(&[REQUEST_ID], Duration::from_secs(2))
                    {
                        Err(TransportError::Closed)
                    } else {
                        Err(TransportError::Timeout)
                    }
                }
                _ => Err(TransportError::Closed),
            },
            Arc::clone(&responses),
        );

        assert_eq!(exit_code, 0);
        assert!(control.was_cancelled(REQUEST_ID as u64));
        let messages = responses.messages();
        let progress_index = messages
            .iter()
            .position(|message| {
                matches!(message, JsonRpcMessage::Request(notification) if notification.method == "notifications/progress")
            })
            .expect("the rate timer must flush progress before the one-variable cancellation");
        assert_eq!(
            responses
                .response(REQUEST_ID)
                .and_then(|response| response.error)
                .and_then(|error| error.code.as_i32()),
            Some(i32::from(McpErrorCode::RequestCancelled))
        );
        assert!(
            !messages[progress_index.saturating_add(1)..]
                .iter()
                .any(|message| matches!(
                    message,
                    JsonRpcMessage::Request(notification)
                        if notification.method == "notifications/progress"
                            || notification.method == "notifications/message"
                )),
            "once cancellation wins, no final progress or log frame may follow it"
        );
    }

    #[test]
    fn public_stdio_cancellation_fence_drops_interleaved_progress_before_commit() {
        const REQUEST_ID: i64 = 208;
        let control = Arc::new(LiveModernControl::default());
        let responses = Arc::new(LiveModernResponses::default());
        let interlock = install_stdio_progress_commit_interlock(REQUEST_ID as u64);
        let control_for_receive = Arc::clone(&control);
        let responses_for_receive = Arc::clone(&responses);
        let interlock_for_receive = Arc::clone(&interlock);
        let phase = Arc::new(AtomicUsize::new(0));
        let phase_for_receive = Arc::clone(&phase);

        let exit_code = run_live_modern_pump(
            Server::new("public-stdio-progress-cancellation-fence", "1.0.0")
                .protocol_policy(ProtocolPolicy::Auto)
                .expect("Auto must be available to this test build")
                .log_level(Level::Debug)
                .tool(LiveModernControlledTool {
                    control: Arc::clone(&control),
                })
                .build(),
            move |_cx, _worker_failed| match phase_for_receive.fetch_add(1, Ordering::AcqRel) {
                0 => Ok(modern_discovery_opening_request()),
                1 => Ok(modern_controlled_tool_progress_request(REQUEST_ID)),
                2 => {
                    if interlock_for_receive.wait_until_entered(Duration::from_secs(2)) {
                        // The progress callback is now stopped immediately
                        // before acquiring the writer. The receiver commits
                        // this sole changed input under the same writer fence.
                        Ok(modern_cancelled_notification(REQUEST_ID as u64))
                    } else {
                        Err(TransportError::Timeout)
                    }
                }
                3 => {
                    release_stdio_progress_commit_interlock();
                    if !control_for_receive
                        .wait_for_cancellation(REQUEST_ID as u64, Duration::from_secs(2))
                    {
                        return Err(TransportError::Timeout);
                    }
                    if responses_for_receive
                        .wait_for_responses(&[REQUEST_ID], Duration::from_secs(2))
                    {
                        Err(TransportError::Closed)
                    } else {
                        Err(TransportError::Timeout)
                    }
                }
                _ => Err(TransportError::Closed),
            },
            Arc::clone(&responses),
        );
        release_stdio_progress_commit_interlock();

        assert_eq!(exit_code, 0);
        assert!(control.was_cancelled(REQUEST_ID as u64));
        assert_eq!(
            responses
                .response(REQUEST_ID)
                .and_then(|response| response.error)
                .and_then(|error| error.code.as_i32()),
            Some(i32::from(McpErrorCode::RequestCancelled))
        );
        assert!(
            !responses.messages().iter().any(|message| matches!(
                message,
                JsonRpcMessage::Request(notification)
                    if notification.method == "notifications/progress"
                        || notification.method == "notifications/message"
            )),
            "a cancellation that owns the writer fence must suppress interleaved progress and final logs"
        );
    }

