    fn returning_subscription_peer_cancel_case(matching: bool) {
        let runtime = RuntimeBuilder::current_thread()
            .with_reactor(create_reactor().expect("peer cancellation reactor"))
            .blocking_threads(2, MAX_DISPATCH_QUEUE_DEPTH)
            .build()
            .expect("peer cancellation runtime");
        let server = Server::new("returning-peer-cancellation", "1.0.0")
            .protocol_policy(ProtocolPolicy::Auto)
            .expect("Auto is available in this test profile")
            .build();
        let active = Arc::clone(&server.active_requests);
        let active_for_recv = Arc::clone(&active);
        let sent = Arc::new(Mutex::new(Vec::new()));
        let sent_for_send = Arc::clone(&sent);
        let (acknowledged, acknowledgement) = sync_channel(1);
        runtime
            .block_on(async move {
                let cx = Cx::current().expect("caller runtime Cx");
                let mut pump = cx
                    .spawn_blocking(move |pump_cx| {
                        let mut phase = 0;
                        server.run_loop_returning_legacy(
                            &pump_cx,
                            move |_| {
                                let current = phase;
                                phase += 1;
                                match current {
                                    0 => Ok(modern_discovery_opening_request()),
                                    1 => Ok(modern_subscriptions_listen_request(908)),
                                    2 => {
                                        acknowledgement
                                            .recv_timeout(Duration::from_secs(2))
                                            .expect("real subscription must acknowledge");
                                        assert_eq!(active_for_recv.lock().unwrap().len(), 1);
                                        Ok(JsonRpcMessage::Request(JsonRpcRequest::notification(
                                            "notifications/cancelled",
                                            Some(serde_json::json!({
                                                "requestId": if matching { 908 } else { 909 },
                                                "_meta": {
                                                    MODERN_PROTOCOL_VERSION_METADATA_KEY: MODERN_PROTOCOL_VERSION,
                                                    FINAL_CLIENT_CAPABILITIES_META_KEY: {},
                                                },
                                            })),
                                        )))
                                    }
                                    3 => {
                                        if matching {
                                            let deadline = Instant::now() + Duration::from_secs(2);
                                            while !active_for_recv.lock().unwrap().is_empty() {
                                                assert!(Instant::now() < deadline, "peer cancellation must retire its listener before EOF");
                                                std::thread::sleep(Duration::from_millis(1));
                                            }
                                        } else {
                                            let owners = active_for_recv.lock().unwrap();
                                            assert_eq!(owners.len(), 1);
                                            assert!(!owners.values().next().unwrap().cancellation.is_cancel_requested());
                                        }
                                        Err(TransportError::Closed)
                                    }
                                    _ => panic!("unexpected receive after EOF"),
                                }
                            },
                            move |_, message| {
                                sent_for_send.lock().unwrap().push(message.clone());
                                Ok(())
                            },
                            Arc::new(move |notification| {
                                if notification.method == "notifications/subscriptions/acknowledged" {
                                    acknowledged.send(()).expect("receive pump owns acknowledgement channel");
                                }
                            }),
                            None,
                            "test",
                        )
                    })
                    .expect("caller runtime admits receive pump");
                let result = asupersync::time::timeout(
                    cx.now(),
                    Duration::from_secs(3),
                    pump.join(&cx),
                )
                .await
                .expect("peer cancellation pump must settle")
                .expect("peer cancellation pump must not panic");
                assert!(!cx.is_cancel_requested(), "request cancellation must preserve the caller");
                result
            })
            .expect("peer cancellation followed by EOF is clean");
        assert!(active.lock().unwrap().is_empty());
        let sent = sent.lock().unwrap();
        let completions: Vec<_> = sent
            .iter()
            .filter_map(|message| match message {
                JsonRpcMessage::Response(response)
                    if response.id == Some(RequestId::Number(908)) =>
                {
                    Some(response)
                }
                _ => None,
            })
            .collect();
        if matching {
            assert!(
                completions.is_empty(),
                "peer cancellation suppresses the terminal response"
            );
        } else {
            assert_eq!(completions.len(), 1);
            assert!(final_subscription_completion_response(completions[0]));
        }
    }

    fn returning_subscription_background_write_case(fail_write: bool) {
        struct RejectListen;

        impl Middleware for RejectListen {
            fn on_request(
                &self,
                _ctx: &McpContext,
                request: &JsonRpcRequest,
            ) -> McpResult<MiddlewareDecision> {
                if request.method == SUBSCRIPTIONS_LISTEN {
                    return Err(McpError::invalid_params("listener rejected by application"));
                }
                Ok(MiddlewareDecision::Continue)
            }
        }

        let runtime = RuntimeBuilder::current_thread()
            .with_reactor(create_reactor().expect("background write test reactor"))
            .blocking_threads(2, MAX_DISPATCH_QUEUE_DEPTH)
            .build()
            .expect("background write test runtime");
        let attempts = Arc::new(AtomicUsize::new(0));
        let attempts_for_send = Arc::clone(&attempts);
        let shutdown_calls = Arc::new(AtomicUsize::new(0));
        let shutdown_calls_for_hook = Arc::clone(&shutdown_calls);
        let server = Server::new("background-response-write", "1.0.0")
            .protocol_policy(ProtocolPolicy::Auto)
            .expect("Auto is available in this test profile")
            .middleware(RejectListen)
            .on_shutdown(move || {
                shutdown_calls_for_hook.fetch_add(1, Ordering::AcqRel);
            })
            .build();
        let active = Arc::clone(&server.active_requests);
        let (attempted, attempt_received) = sync_channel(1);
        let result = runtime.block_on(async move {
            let cx = Cx::current().expect("caller runtime Cx");
            let mut pump = cx
                .spawn_blocking(move |pump_cx| {
                    let mut incoming = std::collections::VecDeque::from([
                        modern_discovery_opening_request(),
                        modern_subscriptions_listen_request(906),
                    ]);
                    server.run_loop_returning_legacy(
                        &pump_cx,
                        move |_| {
                            if let Some(request) = incoming.pop_front() {
                                return Ok(request);
                            }
                            attempt_received
                                .recv_timeout(Duration::from_secs(2))
                                .expect("worker must attempt its correlated response");
                            Err(TransportError::Closed)
                        },
                        move |_, message| {
                            if let JsonRpcMessage::Response(response) = message
                                && response.id == Some(RequestId::Number(906))
                            {
                                assert_eq!(
                                    response.error.as_ref().map(|error| error.message.as_str()),
                                    Some("listener rejected by application")
                                );
                                attempts_for_send.fetch_add(1, Ordering::AcqRel);
                                attempted
                                    .send(())
                                    .expect("receive pump still owns its channel");
                                if fail_write {
                                    return Err(TransportError::Io(std::io::Error::new(
                                        std::io::ErrorKind::BrokenPipe,
                                        "background response writer failed",
                                    )));
                                }
                            }
                            Ok(())
                        },
                        Arc::new(|_| {}),
                        None,
                        "test",
                    )
                })
                .expect("caller runtime admits the receive pump");
            asupersync::time::timeout(cx.now(), Duration::from_secs(3), pump.join(&cx))
                .await
                .expect("background response pump must settle")
                .expect("background response pump must not panic")
        });
        assert_eq!(attempts.load(Ordering::Acquire), 1);
        if fail_write {
            let error = result.expect_err("clean EOF cannot hide the failed response write");
            let data = error.data.expect("typed write failure");
            assert_eq!(data["stage"], "send");
            assert_eq!(data["kind"], "io");
        } else {
            result.expect("delivered response followed by EOF succeeds");
        }
        assert_eq!(shutdown_calls.load(Ordering::Acquire), 1);
        assert!(active.lock().unwrap().is_empty());
    }

    fn returning_subscription_cleanup_case(release_before_shutdown: bool, invalid_response: bool) {
        struct CloseAfterDrainTransport {
            control: Arc<NonQuiescentLegacyControl>,
            phase: usize,
            close_calls: Arc<AtomicUsize>,
            closed_before_drain: Arc<AtomicBool>,
            release_before_shutdown: bool,
            invalid_response: bool,
        }

        struct NonQuiescentSubscriptionMiddleware {
            control: Arc<NonQuiescentLegacyControl>,
        }

        impl Middleware for NonQuiescentSubscriptionMiddleware {
            fn on_request(
                &self,
                _ctx: &McpContext,
                request: &JsonRpcRequest,
            ) -> McpResult<MiddlewareDecision> {
                if request.method == SUBSCRIPTIONS_LISTEN {
                    self.control.wait_until_released();
                }
                Ok(MiddlewareDecision::Continue)
            }
        }

        impl Transport for CloseAfterDrainTransport {
            fn send(&mut self, _cx: &Cx, _message: &JsonRpcMessage) -> Result<(), TransportError> {
                Ok(())
            }

            fn recv(&mut self, _cx: &Cx) -> Result<JsonRpcMessage, TransportError> {
                let phase = self.phase;
                self.phase = self.phase.saturating_add(1);
                match phase {
                    0 => Ok(modern_discovery_opening_request()),
                    1 => Ok(modern_subscriptions_listen_request(903)),
                    2 if self.control.wait_for_started(Duration::from_secs(2)) => {
                        if self.release_before_shutdown {
                            self.control.release();
                            assert!(self.control.wait_for_finished(Duration::from_secs(2)));
                        }
                        if self.invalid_response {
                            let mut response = JsonRpcResponse::success(
                                RequestId::Number(904),
                                serde_json::json!({}),
                            );
                            response.jsonrpc = "1.0".into();
                            return Ok(JsonRpcMessage::Response(response));
                        }
                        Err(TransportError::Io(std::io::Error::new(
                            std::io::ErrorKind::BrokenPipe,
                            "receive while request remains active",
                        )))
                    }
                    _ => Err(TransportError::Timeout),
                }
            }

            fn close(&mut self, _cx: &Cx) -> Result<(), TransportError> {
                self.close_calls.fetch_add(1, Ordering::AcqRel);
                if !self.control.has_finished() {
                    self.closed_before_drain.store(true, Ordering::Release);
                }
                Err(TransportError::Io(std::io::Error::new(
                    std::io::ErrorKind::BrokenPipe,
                    "close after request drain",
                )))
            }
        }

        let control = Arc::new(NonQuiescentLegacyControl::default());
        let runtime = RuntimeBuilder::current_thread()
            .with_reactor(create_reactor().expect("bounded cleanup test reactor must initialize"))
            .blocking_threads(2, MAX_DISPATCH_QUEUE_DEPTH)
            .build()
            .expect("bounded cleanup test runtime must initialize");
        let closed_before_drain = Arc::new(AtomicBool::new(false));
        let shutdown_before_drain = Arc::new(AtomicBool::new(false));
        let shutdown_calls = Arc::new(AtomicUsize::new(0));
        let close_calls = Arc::new(AtomicUsize::new(0));
        let control_for_shutdown = Arc::clone(&control);
        let shutdown_before_drain_for_hook = Arc::clone(&shutdown_before_drain);
        let shutdown_calls_for_hook = Arc::clone(&shutdown_calls);
        let server = Server::new("legacy-returning-bounded-cleanup", "1.0.0")
            .protocol_policy(ProtocolPolicy::Auto)
            .expect("Auto must be available to this test build")
            .middleware(NonQuiescentSubscriptionMiddleware {
                control: Arc::clone(&control),
            })
            .on_shutdown(move || {
                shutdown_calls_for_hook.fetch_add(1, Ordering::AcqRel);
                if !control_for_shutdown.has_finished() {
                    shutdown_before_drain_for_hook.store(true, Ordering::Release);
                }
            })
            .build();
        let active_requests_for_assert = Arc::clone(&server.active_requests);

        struct ReleaseNonCooperativeOnDrop(Arc<NonQuiescentLegacyControl>);

        impl Drop for ReleaseNonCooperativeOnDrop {
            fn drop(&mut self) {
                self.0.release();
                let _ = self.0.wait_for_finished(Duration::from_secs(2));
            }
        }

        let _release_on_failure = ReleaseNonCooperativeOnDrop(Arc::clone(&control));

        runtime
            .block_on(async move {
                let cx = Cx::current().expect("bounded cleanup test runtime must install Cx");
                let (result_sender, result_receiver) = sync_channel(1);
                let control_for_transport = Arc::clone(&control);
                let close_calls_for_transport = Arc::clone(&close_calls);
                let closed_before_drain_for_transport = Arc::clone(&closed_before_drain);
                let mut pump = cx
                    .spawn_blocking(move |pump_cx| {
                        let result = server.run_transport_returning_with_cx(
                            &pump_cx,
                            CloseAfterDrainTransport {
                                control: control_for_transport,
                                phase: 0,
                                close_calls: close_calls_for_transport,
                                closed_before_drain: closed_before_drain_for_transport,
                                release_before_shutdown,
                                invalid_response,
                            },
                        );
                        let _ = result_sender.send(result);
                    })
                    .expect("returning bounded cleanup pump must be admitted");
                let started = Instant::now();
                let deadline = cx.now().saturating_add_nanos(8_000_000_000);
                let result = loop {
                    match result_receiver.try_recv() {
                        Ok(result) => break result,
                        Err(std::sync::mpsc::TryRecvError::Disconnected) => {
                            panic!(
                                "returning bounded cleanup pump exited without reporting its result"
                            );
                        }
                        Err(std::sync::mpsc::TryRecvError::Empty) => {
                            asupersync::time::timeout_at(
                                deadline,
                                asupersync::time::sleep(cx.now(), Duration::from_millis(1)),
                            )
                            .await
                            .expect("returning bounded cleanup pump must settle within its bound");
                        }
                    }
                };

                pump.join(&cx)
                    .await
                    .expect("returning bounded-failure pump task must finish");
                let error = result.expect_err("transport close failure must remain visible");
                assert_eq!(
                    error.data.as_ref().and_then(|data| data["stage"].as_str()),
                    Some("run_and_close")
                );
                let data = error
                    .data
                    .as_ref()
                    .expect("combined error must include data");
                assert_eq!(data["kind"], "multiple_failures");
                let receive_kind = if invalid_response {
                    "invalid_response"
                } else {
                    "io"
                };
                if release_before_shutdown {
                    // `stage == "receive"` already entails that the non-quiescent
                    // cleanup wait was not entered: entering it produces a
                    // `run_and_cleanup` combined error carrying a `cleanup` key,
                    // which is what the other branch asserts. The two are mutually
                    // exclusive by construction, so this branch needs no separate
                    // check that the cleanup timeout was skipped.
                    //
                    // An `assert!(started.elapsed() < SHUTDOWN_CLEANUP_TIMEOUT)`
                    // stood here and was removed. It added no information about the
                    // property above, and it was an UPPER bound on real wall time
                    // (`Instant::now()`) covering the whole pump lifecycle, so a
                    // loaded host failed it with no code change: this test passed
                    // 1926/0 and failed 1925/1 seventeen minutes apart on identical
                    // source. Note the sibling branch's `>= SHUTDOWN_CLEANUP_TIMEOUT`
                    // is a LOWER bound and is load-monotone, so it is sound and stays.
                    // Do not reinstate an upper bound on wall time here.
                    assert_eq!(data["run"]["data"]["stage"], "receive");
                    assert_eq!(data["run"]["data"]["kind"], receive_kind);
                } else {
                    assert_eq!(data["run"]["data"]["stage"], "run_and_cleanup");
                    assert_eq!(data["run"]["data"]["kind"], "multiple_failures");
                    assert_eq!(data["run"]["data"]["run"]["data"]["stage"], "receive");
                    assert_eq!(data["run"]["data"]["run"]["data"]["kind"], receive_kind);
                    assert_eq!(data["run"]["data"]["cleanup"]["data"]["stage"], "shutdown");
                    assert_eq!(
                        data["run"]["data"]["cleanup"]["data"]["kind"],
                        "non_quiescent"
                    );
                    assert!(
                        data["run"]["data"]["cleanup"]["data"]["remaining"]
                            .as_u64()
                            .unwrap_or(0)
                            >= 1
                    );
                    assert!(started.elapsed() >= SHUTDOWN_CLEANUP_TIMEOUT);
                }
                assert_eq!(data["close"]["data"]["stage"], "close");
                assert_eq!(data["close"]["data"]["kind"], "io");
                assert_eq!(close_calls.load(Ordering::Acquire), 1);
                assert_eq!(
                    closed_before_drain.load(Ordering::Acquire),
                    !release_before_shutdown
                );
                assert!(!shutdown_before_drain.load(Ordering::Acquire));
                assert_eq!(
                    shutdown_calls.load(Ordering::Acquire),
                    usize::from(release_before_shutdown)
                );
                assert_eq!(
                    active_requests_for_assert
                        .lock()
                        .unwrap_or_else(std::sync::PoisonError::into_inner)
                        .is_empty(),
                    release_before_shutdown
                );
                control.release();
                assert!(control.wait_for_finished(Duration::from_secs(2)));
                let cleanup_deadline = cx.now().saturating_add_nanos(2_000_000_000);
                while !active_requests_for_assert
                    .lock()
                    .unwrap_or_else(std::sync::PoisonError::into_inner)
                    .is_empty()
                {
                    asupersync::time::timeout_at(
                        cleanup_deadline,
                        asupersync::time::sleep(cx.now(), Duration::from_millis(1)),
                    )
                    .await
                    .expect("released request region must retire before fixture teardown");
                }
                assert!(control.has_finished());
                assert!(
                    active_requests_for_assert
                        .lock()
                        .unwrap_or_else(std::sync::PoisonError::into_inner)
                        .is_empty()
                );
                Ok::<(), McpError>(())
            })
            .expect("returning bounded cleanup failure must preserve ownership and errors");
    }

    // bd-gl2we: the `returning_subscription_*` family fails intermittently
    // through two races around a stdio listen's acknowledgement (comment 5403).
    // These pairs FORCE each interleaving instead of waiting for load to find
    // it. Each pair differs only in the ordering it forces, and each records
    // that the ordering was actually reached, so a pass on an unforced run
    // cannot pass silently. They are deliberately outside the family's
    // `returning_subscription_*` prefix and its denominator.
    //
    // Both pairs now assert the contract. The pump-first test was bd-gl2we
    // finding F1: stdio shutdown lost a pending graceful election. bd-81cct
    // fixed it by having shutdown wait for the owner of a won election before
    // generic cancellation. The under-recv-lock test was F2: an
    // acknowledgement sent during an unsplit transport's `recv` failed the
    // connection. bd-8bcfq fixed it by queueing such output until `recv`
    // returns.

    #[test]
    fn forced_subscription_ack_order_pump_first_keeps_graceful_completion() {
        forced_subscription_shutdown_order_case(true);
    }

    #[test]
    fn forced_subscription_ack_order_active_first_keeps_graceful_completion() {
        forced_subscription_shutdown_order_case(false);
    }

    #[test]
    fn forced_subscription_ack_order_under_recv_lock_is_written_when_recv_returns() {
        forced_subscription_recv_lock_order_case(true);
    }

    #[test]
    fn forced_subscription_ack_order_outside_recv_lock_reports_receive_stage() {
        forced_subscription_recv_lock_order_case(false);
    }

    /// Election phases of every live final-subscription lease. The entry list
    /// is copied out before any phase lock is taken, so this never holds the
    /// registry mutex and an election mutex at once.
    fn final_subscription_phases(
        registry: &FinalSubscriptionRegistry,
    ) -> Vec<FinalSubscriptionPhase> {
        let elections: Vec<_> = registry
            .inner
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .entries
            .values()
            .map(|entry| Arc::clone(&entry.election))
            .collect();
        elections
            .iter()
            .map(|election| {
                *election
                    .phase
                    .lock()
                    .unwrap_or_else(std::sync::PoisonError::into_inner)
            })
            .collect()
    }

    /// `Active` is published by the opener only after its acknowledgement
    /// callback has returned, so reaching it proves the acknowledgement was
    /// already attempted.
    fn wait_for_single_active_final_subscription(
        registry: &FinalSubscriptionRegistry,
        timeout: Duration,
    ) -> bool {
        let deadline = Instant::now() + timeout;
        loop {
            if final_subscription_phases(registry) == [FinalSubscriptionPhase::Active] {
                return true;
            }
            if Instant::now() >= deadline {
                return false;
            }
            std::thread::sleep(Duration::from_millis(1));
        }
    }

    /// EOF shutdown against a listen whose acknowledgement callback has run.
    /// `pump_first` holds the opener inside that callback, before it can
    /// publish `Active`, until shutdown's `terminate` has recorded
    /// `ServerTerminationPending(0)`. It then keeps holding for a grace window
    /// in which a generic shutdown cancellation, had it been issued, would
    /// defeat the opener's deferred election. Otherwise the pump holds EOF
    /// until the opener has published `Active`, and shutdown elects the
    /// graceful completion directly. Either order must deliver exactly one
    /// graceful completion.
    fn forced_subscription_shutdown_order_case(pump_first: bool) {
        let runtime = RuntimeBuilder::current_thread()
            .with_reactor(create_reactor().expect("forced shutdown-order reactor"))
            .blocking_threads(2, MAX_DISPATCH_QUEUE_DEPTH)
            .build()
            .expect("forced shutdown-order runtime");
        let server = Server::new("forced-subscription-shutdown-order", "1.0.0")
            .protocol_policy(ProtocolPolicy::Auto)
            .expect("Auto is available in this test profile")
            .build();
        let active = Arc::clone(&server.active_requests);
        let active_for_callback = Arc::clone(&active);
        let registry = Arc::clone(&server.final_subscriptions);
        let registry_for_callback = Arc::clone(&registry);
        let sent = Arc::new(Mutex::new(Vec::new()));
        let sent_for_send = Arc::clone(&sent);
        let forced = Arc::new(AtomicBool::new(false));
        let forced_by_callback = Arc::clone(&forced);
        let forced_by_recv = Arc::clone(&forced);
        let cancelled_during_callback = Arc::new(AtomicBool::new(false));
        let cancelled_by_callback = Arc::clone(&cancelled_during_callback);
        let (acknowledged, acknowledgement) = sync_channel(1);
        runtime
            .block_on(async move {
                let cx = Cx::current().expect("caller runtime Cx");
                let mut pump = cx
                    .spawn_blocking(move |pump_cx| {
                        let mut phase = 0;
                        server.run_loop_returning_legacy(
                            &pump_cx,
                            move |_| {
                                let current = phase;
                                phase += 1;
                                match current {
                                    0 => Ok(modern_discovery_opening_request()),
                                    1 => Ok(modern_subscriptions_listen_request(910)),
                                    2 => {
                                        acknowledgement
                                            .recv_timeout(Duration::from_secs(2))
                                            .expect("real subscription must acknowledge");
                                        if !pump_first
                                            && wait_for_single_active_final_subscription(
                                                &registry,
                                                Duration::from_secs(2),
                                            )
                                        {
                                            forced_by_recv.store(true, Ordering::Release);
                                        }
                                        Err(TransportError::Closed)
                                    }
                                    _ => panic!("unexpected receive after EOF"),
                                }
                            },
                            move |_, message| {
                                sent_for_send.lock().unwrap().push(message.clone());
                                Ok(())
                            },
                            Arc::new(move |notification| {
                                if notification.method != "notifications/subscriptions/acknowledged"
                                {
                                    return;
                                }
                                // The lease is registered before its
                                // acknowledgement is sent; keep its election
                                // so the phase stays observable after
                                // `terminate` removes the registry entry.
                                let elections: Vec<_> = registry_for_callback
                                    .inner
                                    .lock()
                                    .unwrap_or_else(std::sync::PoisonError::into_inner)
                                    .entries
                                    .values()
                                    .map(|entry| Arc::clone(&entry.election))
                                    .collect();
                                acknowledged
                                    .send(())
                                    .expect("receive pump owns acknowledgement channel");
                                if !pump_first {
                                    return;
                                }
                                let deadline = Instant::now() + Duration::from_secs(2);
                                let server_won_during_callback = loop {
                                    if elections.iter().any(|election| {
                                        *election
                                            .phase
                                            .lock()
                                            .unwrap_or_else(std::sync::PoisonError::into_inner)
                                            == FinalSubscriptionPhase::ServerTerminationPending(0)
                                    }) {
                                        break true;
                                    }
                                    if Instant::now() >= deadline {
                                        break false;
                                    }
                                    std::thread::sleep(Duration::from_millis(1));
                                };
                                if !server_won_during_callback {
                                    return;
                                }
                                forced_by_callback.store(true, Ordering::Release);
                                // Shutdown must not cancel the request while
                                // this callback still owns the won election.
                                let grace = Instant::now() + Duration::from_millis(500);
                                while Instant::now() < grace {
                                    if active_for_callback
                                        .lock()
                                        .unwrap()
                                        .values()
                                        .any(|owner| owner.cancellation.is_cancel_requested())
                                    {
                                        cancelled_by_callback.store(true, Ordering::Release);
                                        return;
                                    }
                                    std::thread::sleep(Duration::from_millis(1));
                                }
                            }),
                            None,
                            "test",
                        )
                    })
                    .expect("caller runtime admits receive pump");
                asupersync::time::timeout(cx.now(), Duration::from_secs(3), pump.join(&cx))
                    .await
                    .expect("forced shutdown-order pump must settle")
                    .expect("forced shutdown-order pump must not panic")
            })
            .expect("EOF after an acknowledged listen is a clean close");
        assert!(
            forced.load(Ordering::Acquire),
            "the {} interleaving was not forced",
            if pump_first {
                "pump-first"
            } else {
                "active-first"
            }
        );
        assert!(active.lock().unwrap().is_empty());
        let sent = sent.lock().unwrap();
        let responses: Vec<_> = sent
            .iter()
            .filter_map(|message| match message {
                JsonRpcMessage::Response(response)
                    if response.id == Some(RequestId::Number(910)) =>
                {
                    Some(response)
                }
                _ => None,
            })
            .collect();
        assert!(
            !cancelled_during_callback.load(Ordering::Acquire),
            "shutdown cancelled the request while its won election was still pending"
        );
        assert_eq!(responses.len(), 1, "{responses:?}");
        assert!(final_subscription_completion_response(responses[0]));
    }

    /// An invalid response frame after an acknowledged listen, on an unsplit
    /// transport. Both variants send the same frames and run the same
    /// release-then-wait-for-`Active` step; only its location differs.
    /// `ack_under_recv_lock` runs it inside `recv`, while `SharedTransport`'s
    /// pump owns the I/O handle, so the acknowledgement is queued and written
    /// when that `recv` returns (receive phase 4). Otherwise it runs in
    /// middleware for an inline request, after `recv` has released the handle,
    /// and is written directly (receive phase 3).
    fn forced_subscription_recv_lock_order_case(ack_under_recv_lock: bool) {
        struct ForcedAckOrderTransport {
            control: Arc<NonQuiescentLegacyControl>,
            registry: Arc<FinalSubscriptionRegistry>,
            forced: Arc<AtomicBool>,
            acknowledgement_phases: Arc<Mutex<Vec<usize>>>,
            phase: usize,
            ack_under_recv_lock: bool,
        }

        struct ForcedAckOrderMiddleware {
            control: Arc<NonQuiescentLegacyControl>,
            registry: Arc<std::sync::OnceLock<Arc<FinalSubscriptionRegistry>>>,
            forced: Arc<AtomicBool>,
            ack_under_recv_lock: bool,
        }

        impl Middleware for ForcedAckOrderMiddleware {
            fn on_request(
                &self,
                _ctx: &McpContext,
                request: &JsonRpcRequest,
            ) -> McpResult<MiddlewareDecision> {
                if request.method == SUBSCRIPTIONS_LISTEN {
                    self.control.wait_until_released();
                } else if !self.ack_under_recv_lock && request.id == Some(RequestId::Number(907)) {
                    self.control.release();
                    let registry = self
                        .registry
                        .get()
                        .expect("registry is published before the pump starts");
                    if wait_for_single_active_final_subscription(registry, Duration::from_secs(2)) {
                        self.forced.store(true, Ordering::Release);
                    }
                }
                Ok(MiddlewareDecision::Continue)
            }
        }

        impl Transport for ForcedAckOrderTransport {
            fn send(&mut self, _cx: &Cx, message: &JsonRpcMessage) -> Result<(), TransportError> {
                if let JsonRpcMessage::Request(request) = message
                    && request.method == "notifications/subscriptions/acknowledged"
                {
                    self.acknowledgement_phases
                        .lock()
                        .unwrap_or_else(std::sync::PoisonError::into_inner)
                        .push(self.phase);
                }
                Ok(())
            }

            fn recv(&mut self, _cx: &Cx) -> Result<JsonRpcMessage, TransportError> {
                let phase = self.phase;
                self.phase = self.phase.saturating_add(1);
                match phase {
                    0 => Ok(modern_discovery_opening_request()),
                    1 => Ok(modern_subscriptions_listen_request(911)),
                    2 => Ok(modern_discovery_request(907)),
                    3 => {
                        if self.ack_under_recv_lock {
                            self.control.release();
                            if wait_for_single_active_final_subscription(
                                &self.registry,
                                Duration::from_secs(2),
                            ) {
                                self.forced.store(true, Ordering::Release);
                            }
                        }
                        let mut response =
                            JsonRpcResponse::success(RequestId::Number(912), serde_json::json!({}));
                        response.jsonrpc = "1.0".into();
                        Ok(JsonRpcMessage::Response(response))
                    }
                    _ => Err(TransportError::Timeout),
                }
            }

            fn close(&mut self, _cx: &Cx) -> Result<(), TransportError> {
                Ok(())
            }
        }

        let control = Arc::new(NonQuiescentLegacyControl::default());
        let forced = Arc::new(AtomicBool::new(false));
        let acknowledgement_phases = Arc::new(Mutex::new(Vec::new()));
        let registry_cell = Arc::new(std::sync::OnceLock::new());
        let runtime = RuntimeBuilder::current_thread()
            .with_reactor(create_reactor().expect("forced recv-lock reactor"))
            .blocking_threads(2, MAX_DISPATCH_QUEUE_DEPTH)
            .build()
            .expect("forced recv-lock runtime");
        let server = Server::new("forced-subscription-recv-lock-order", "1.0.0")
            .protocol_policy(ProtocolPolicy::Auto)
            .expect("Auto is available in this test profile")
            .middleware(ForcedAckOrderMiddleware {
                control: Arc::clone(&control),
                registry: Arc::clone(&registry_cell),
                forced: Arc::clone(&forced),
                ack_under_recv_lock,
            })
            .build();
        let registry = Arc::clone(&server.final_subscriptions);
        assert!(registry_cell.set(Arc::clone(&registry)).is_ok());
        let active = Arc::clone(&server.active_requests);
        let transport = ForcedAckOrderTransport {
            control: Arc::clone(&control),
            registry,
            forced: Arc::clone(&forced),
            acknowledgement_phases: Arc::clone(&acknowledgement_phases),
            phase: 0,
            ack_under_recv_lock,
        };
        let result = runtime.block_on(async move {
            let cx = Cx::current().expect("caller runtime Cx");
            let mut pump = cx
                .spawn_blocking(move |pump_cx| {
                    server.run_transport_returning_with_cx(&pump_cx, transport)
                })
                .expect("caller runtime admits receive pump");
            asupersync::time::timeout(cx.now(), Duration::from_secs(5), pump.join(&cx))
                .await
                .expect("forced recv-lock pump must settle")
                .expect("forced recv-lock pump must not panic")
        });
        control.release();
        assert!(
            forced.load(Ordering::Acquire),
            "the {} interleaving was not forced",
            if ack_under_recv_lock {
                "under-recv-lock"
            } else {
                "outside-recv-lock"
            }
        );
        let error = result.expect_err("an invalid response frame terminates the connection");
        let data = error.data.as_ref().expect("typed run failure");
        // Exactly one acknowledgement reaches the wire either way. Under the
        // receive lock it is queued and written right after the fourth `recv`
        // returns, before the pump classifies that frame; otherwise it is
        // written directly while the pump dispatches the third frame.
        let expected_phase = if ack_under_recv_lock { 4 } else { 3 };
        assert_eq!(
            *acknowledgement_phases
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner),
            [expected_phase],
            "{error:?}"
        );
        assert_eq!(data["stage"], "receive", "{error:?}");
        assert_eq!(data["kind"], "invalid_response", "{error:?}");
        assert!(active.lock().unwrap().is_empty());
    }

    #[test]
    fn returning_loop_replies_to_bounded_codec_error_then_reads_next_frame() {
        use std::collections::VecDeque;
        use std::sync::atomic::AtomicUsize;

        // A malformed OPENING frame is a fatal era-security rejection under
        // Auto, so the recoverable-parse-error contract is probed on an
        // already negotiated connection.
        let steps = Arc::new(Mutex::new(VecDeque::from([
            Ok(exact_legacy_initialize_request(
                32,
                serde_json::json!("1.0.0"),
            )),
            Ok(JsonRpcMessage::Request(JsonRpcRequest::notification(
                "notifications/initialized",
                None,
            ))),
            Err(TransportError::Codec(fastmcp_transport::CodecError::Json(
                serde_json::from_str::<serde_json::Value>("{")
                    .expect_err("fixture must be invalid JSON"),
            ))),
            Err(TransportError::Closed),
        ])));
        let receive_calls = Arc::new(AtomicUsize::new(0));
        let sent = Arc::new(Mutex::new(Vec::<JsonRpcMessage>::new()));
        let receive_steps = Arc::clone(&steps);
        let receive_count = Arc::clone(&receive_calls);
        let sent_messages = Arc::clone(&sent);

        Server::new("recoverable-codec-error-test", "1.0.0")
            .build()
            .run_loop_returning(
                &Cx::for_testing(),
                move |_, _worker_failed| {
                    receive_count.fetch_add(1, Ordering::Relaxed);
                    receive_steps
                        .lock()
                        .unwrap_or_else(std::sync::PoisonError::into_inner)
                        .pop_front()
                        .unwrap_or(Err(TransportError::Closed))
                },
                move |_, message| {
                    sent_messages
                        .lock()
                        .unwrap_or_else(std::sync::PoisonError::into_inner)
                        .push(message.clone());
                    Ok(())
                },
                Arc::new(|_| {}),
                None,
                "test",
            )
            .expect("clean transport closure after a recoverable codec error must succeed");

        assert_eq!(receive_calls.load(Ordering::Relaxed), 4);
        let sent = sent
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        // The initialize response races worker shutdown and is incidental;
        // the contract is exactly one uncorrelated parse-error reply.
        let parse_errors: Vec<&JsonRpcResponse> = sent
            .iter()
            .filter_map(|message| match message {
                JsonRpcMessage::Response(response) if response.id.is_none() => Some(response),
                _ => None,
            })
            .collect();
        let [response] = parse_errors.as_slice() else {
            panic!("expected exactly one uncorrelated parse-error response");
        };
        assert_eq!(
            response
                .error
                .as_ref()
                .and_then(|error| error.code.as_i32()),
            Some(-32700)
        );
        let wire = serde_json::to_value(response).expect("parse error response must serialize");
        assert!(wire.get("id").is_none());
    }

    #[test]
    fn returning_loop_correlates_invalid_request_only_when_codec_proves_unique_id() {
        use std::collections::VecDeque;

        let invalid = fastmcp_transport::Codec::new()
            .decode_complete_message(br#"{"jsonrpc":"2.1","method":"tools/list","id":"safe-id"}"#)
            .expect_err("wrong JSON-RPC version must be invalid");
        // A malformed OPENING frame is a fatal era-security rejection under
        // Auto, so the correlation contract is probed on an already
        // negotiated connection.
        let steps = Arc::new(Mutex::new(VecDeque::from([
            Ok(exact_legacy_initialize_request(
                31,
                serde_json::json!("1.0.0"),
            )),
            Ok(JsonRpcMessage::Request(JsonRpcRequest::notification(
                "notifications/initialized",
                None,
            ))),
            Err(TransportError::Codec(invalid)),
            Err(TransportError::Closed),
        ])));
        let sent = Arc::new(Mutex::new(Vec::<JsonRpcMessage>::new()));
        let receive_steps = Arc::clone(&steps);
        let sent_messages = Arc::clone(&sent);

        Server::new("correlated-invalid-request-test", "1.0.0")
            .build()
            .run_loop_returning(
                &Cx::for_testing(),
                move |_, _worker_failed| {
                    receive_steps
                        .lock()
                        .unwrap_or_else(std::sync::PoisonError::into_inner)
                        .pop_front()
                        .unwrap_or(Err(TransportError::Closed))
                },
                move |_, message| {
                    sent_messages
                        .lock()
                        .unwrap_or_else(std::sync::PoisonError::into_inner)
                        .push(message.clone());
                    Ok(())
                },
                Arc::new(|_| {}),
                None,
                "test",
            )
            .expect("clean transport closure after an invalid-request reply must succeed");

        let sent = sent
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        // The initialize response races worker shutdown and is incidental;
        // the contract is exactly one reply correlated to the proven id.
        let correlated: Vec<&JsonRpcResponse> = sent
            .iter()
            .filter_map(|message| match message {
                JsonRpcMessage::Response(response)
                    if response.id == Some(RequestId::String("safe-id".to_string())) =>
                {
                    Some(response)
                }
                _ => None,
            })
            .collect();
        let [response] = correlated.as_slice() else {
            panic!("expected exactly one response correlated to the proven unique id");
        };
        assert_eq!(
            response
                .error
                .as_ref()
                .and_then(|error| error.code.as_i32()),
            Some(i32::from(McpErrorCode::InvalidRequest))
        );
    }

    #[test]
    fn returning_loop_terminates_after_fatal_framing_error_without_logging_payload() {
        use std::sync::atomic::AtomicUsize;

        let receive_calls = Arc::new(AtomicUsize::new(0));
        let receive_count = Arc::clone(&receive_calls);
        let sent = Arc::new(AtomicUsize::new(0));
        let sent_count = Arc::clone(&sent);

        let error = Server::new("fatal-framing-error-test", "1.0.0")
            .build()
            .run_loop_returning(
                &Cx::for_testing(),
                move |_, _worker_failed| {
                    receive_count.fetch_add(1, Ordering::Relaxed);
                    Err(TransportError::Io(std::io::Error::new(
                        std::io::ErrorKind::InvalidData,
                        "SECRET_FRAMING_CANARY\r\nforged-log-line",
                    )))
                },
                move |_, _| {
                    sent_count.fetch_add(1, Ordering::Relaxed);
                    Ok(())
                },
                Arc::new(|_| {}),
                None,
                "test",
            )
            .expect_err("fatal framing failure must propagate from the returning loop");

        assert_eq!(receive_calls.load(Ordering::Relaxed), 1);
        assert_eq!(sent.load(Ordering::Relaxed), 0);
        assert_eq!(error.code, McpErrorCode::InternalError);
        assert_eq!(
            error.data.as_ref().and_then(|data| data["kind"].as_str()),
            Some("pump_failure")
        );
        assert_eq!(
            classify_receive_error(&TransportError::Timeout),
            ReceiveErrorDisposition::Terminate
        );
        assert_eq!(
            classify_receive_error(&TransportError::ReceiveDeadlineExceeded),
            ReceiveErrorDisposition::Terminate
        );
        assert_eq!(
            classify_receive_error(&TransportError::ControlFrameTooLarge {
                size: 513,
                max: 512,
            }),
            ReceiveErrorDisposition::Terminate
        );
        assert_eq!(
            classify_receive_error(&TransportError::Codec(
                fastmcp_transport::CodecError::MessageTooLarge(42)
            )),
            ReceiveErrorDisposition::Terminate
        );
    }

    #[test]
    fn receive_pump_terminates_each_fatal_transport_failure_without_retrying() {
        use std::sync::atomic::AtomicUsize;

        for error in [
            TransportError::Timeout,
            TransportError::ReceiveDeadlineExceeded,
            TransportError::ControlFrameTooLarge {
                size: 513,
                max: 512,
            },
            TransportError::Codec(fastmcp_transport::CodecError::MessageTooLarge(42)),
        ] {
            let error_label = format!("{error:?}");
            let receive_calls = Arc::new(AtomicUsize::new(0));
            let receive_count = Arc::clone(&receive_calls);
            let sent = Arc::new(AtomicUsize::new(0));
            let sent_count = Arc::clone(&sent);
            let mut next_error = Some(error);

            let exit_code = Server::new("fatal-receive-error-test", "1.0.0")
                .build()
                .run_loop_pump(
                    &Cx::for_testing(),
                    move |_, _worker_failed| {
                        receive_count.fetch_add(1, Ordering::Relaxed);
                        Err(next_error.take().unwrap_or(TransportError::Closed))
                    },
                    move |_, _| {
                        sent_count.fetch_add(1, Ordering::Relaxed);
                        Ok(())
                    },
                    Arc::new(|_| {}),
                    "test",
                );

            assert_eq!(exit_code, 1, "fatal error must fail: {error_label}");
            assert_eq!(
                receive_calls.load(Ordering::Relaxed),
                1,
                "fatal error must not be retried: {error_label}"
            );
            assert_eq!(
                sent.load(Ordering::Relaxed),
                0,
                "fatal error must not emit a response: {error_label}"
            );
        }
    }

