    #[test]
    fn production_dispatch_wires_router_backed_nested_tool_calls() {
        #[derive(Debug, Clone, Copy)]
        struct InnerTool;

        impl ToolHandler for InnerTool {
            fn definition(&self) -> Tool {
                Tool {
                    name: "inner_tool".to_string(),
                    description: Some("Nested dispatch target".to_string()),
                    input_schema: serde_json::json!({"type": "object"}),
                    output_schema: None,
                    icon: None,
                    version: None,
                    tags: Vec::new(),
                    annotations: None,
                }
            }

            fn call(&self, _ctx: &McpContext, _args: serde_json::Value) -> McpResult<Vec<Content>> {
                Ok(vec![Content::text("inner-result")])
            }
        }

        #[derive(Debug, Clone, Copy)]
        struct OuterTool;

        impl ToolHandler for OuterTool {
            fn definition(&self) -> Tool {
                Tool {
                    name: "outer_tool".to_string(),
                    description: Some("Calls another registered tool".to_string()),
                    input_schema: serde_json::json!({"type": "object"}),
                    output_schema: None,
                    icon: None,
                    version: None,
                    tags: Vec::new(),
                    annotations: None,
                }
            }

            fn call(&self, _ctx: &McpContext, _args: serde_json::Value) -> McpResult<Vec<Content>> {
                Err(McpError::internal_error(
                    "outer_tool requires async dispatch",
                ))
            }

            fn call_async<'a>(
                &'a self,
                ctx: &'a McpContext,
                _args: serde_json::Value,
            ) -> BoxFuture<'a, fastmcp_core::McpOutcome<Vec<Content>>> {
                Box::pin(async move {
                    match ctx.call_tool("inner_tool", serde_json::json!({})).await {
                        Ok(result) => {
                            let text = result.first_text().unwrap_or("missing nested text");
                            asupersync::Outcome::Ok(vec![Content::text(text)])
                        }
                        Err(error) => asupersync::Outcome::Err(error),
                    }
                })
            }
        }

        let server = Server::new("nested-production-dispatch-test", "1.0.0")
            .tool(InnerTool)
            .tool(OuterTool)
            .build();
        let mut session = initialized_test_session(&server);
        let notification_sender: NotificationSender = Arc::new(|_| {});
        let request_sender = test_request_sender();
        let response = block_on(server.dispatch_request(
            &Cx::for_testing(),
            &mut session,
            JsonRpcRequest::new(
                "tools/call",
                Some(serde_json::json!({
                    "name": "outer_tool",
                    "arguments": {}
                })),
                1_i64,
            ),
            &notification_sender,
            &request_sender,
        ))
        .expect("nested tool request should produce a response");
        let result: CallToolResult = serde_json::from_value(
            response
                .result
                .expect("top-level tool should complete through nested router dispatch"),
        )
        .expect("decode nested tool result");

        match result.content.as_slice() {
            [LegacyContent::Text { text, .. }] => assert_eq!(text, "inner-result"),
            other => panic!("expected nested tool text result, got {other:?}"),
        }
    }

    #[test]
    fn escaped_request_context_is_revoked_and_does_not_retain_server_router() {
        #[derive(Clone)]
        struct CaptureContextTool {
            captured: Arc<Mutex<Option<McpContext>>>,
        }

        impl ToolHandler for CaptureContextTool {
            fn definition(&self) -> Tool {
                Tool {
                    name: "capture_context".to_string(),
                    description: Some(
                        "Captures a request context for revocation testing".to_string(),
                    ),
                    input_schema: serde_json::json!({"type": "object"}),
                    output_schema: None,
                    icon: None,
                    version: None,
                    tags: Vec::new(),
                    annotations: None,
                }
            }

            fn call(&self, ctx: &McpContext, _args: serde_json::Value) -> McpResult<Vec<Content>> {
                *self
                    .captured
                    .lock()
                    .unwrap_or_else(std::sync::PoisonError::into_inner) = Some(ctx.clone());
                Ok(vec![Content::text("captured")])
            }
        }

        let captured = Arc::new(Mutex::new(None));
        let server = Server::new("request-lease-test", "1.0.0")
            .tool(CaptureContextTool {
                captured: Arc::clone(&captured),
            })
            .build();
        let mut session = initialized_test_session(&server);
        let notification_sender: NotificationSender = Arc::new(|_| {});
        let request_sender = test_request_sender();
        let response = block_on(server.dispatch_request(
            &Cx::for_testing(),
            &mut session,
            JsonRpcRequest::new(
                "tools/call",
                Some(serde_json::json!({
                    "name": "capture_context",
                    "arguments": {}
                })),
                1_i64,
            ),
            &notification_sender,
            &request_sender,
        ))
        .expect("capture request should produce a response");
        assert!(
            response.error.is_none(),
            "unexpected response: {response:?}"
        );

        let escaped = captured
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .take()
            .expect("handler should capture its context");
        let error = block_on(escaped.call_tool("capture_context", serde_json::json!({})))
            .expect_err("nested authority must close when dispatch returns");
        assert_eq!(error.code, McpErrorCode::RequestCancelled);

        let router = server.into_router();
        assert!(
            router
                .tools()
                .iter()
                .any(|tool| tool.name == "capture_context")
        );
    }

    #[test]
    fn http_bind_rejects_an_invalid_address_without_running_lifecycle_hooks() {
        let startup_called = Arc::new(AtomicBool::new(false));
        let shutdown_called = Arc::new(AtomicBool::new(false));
        let startup_observer = Arc::clone(&startup_called);
        let shutdown_observer = Arc::clone(&shutdown_called);

        let cx = Cx::for_testing();
        let result = block_on(
            Server::new("http-bind-test", "1.0.0")
                .on_startup(move || {
                    startup_observer.store(true, Ordering::SeqCst);
                    Ok::<(), std::io::Error>(())
                })
                .on_shutdown(move || shutdown_observer.store(true, Ordering::SeqCst))
                .build()
                .bind_http(&cx, "not-a-bindable-socket-address"),
        );
        let Err(error) = result else {
            panic!("an invalid bind address must be rejected by the live listener");
        };

        assert!(!startup_called.load(Ordering::SeqCst));
        assert!(!shutdown_called.load(Ordering::SeqCst));
        assert!(
            error.message.contains("HTTP listener bind failed"),
            "the bind failure must report the live listener boundary: {error:?}"
        );
    }

    #[test]
    fn final_subscription_acknowledges_filters_tags_and_releases_request_owned_state() {
        let server = Server::new("final-subscription-stream-test", "1.0.0").build();
        let registry = Arc::clone(&server.final_subscriptions);
        let sent = Arc::new(Mutex::new(Vec::<JsonRpcRequest>::new()));
        let sent_for_sender = Arc::clone(&sent);
        let sender: NotificationSender = Arc::new(move |notification| {
            sent_for_sender
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .push(notification);
        });
        let subscription_id = RequestId::String("subscription-71".to_owned());
        let lease = registry
            .open(
                subscription_id.clone(),
                SubscriptionFilter {
                    tools_list_changed: Some(true),
                    resources_list_changed: Some(false),
                    ..SubscriptionFilter::default()
                },
                false,
                None,
                McpRequestCancellation::new(),
                None,
                sender,
            )
            .expect("final subscription should admit a bounded stream");

        let acknowledgement = sent
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .first()
            .cloned()
            .expect("acknowledgement must be the first stream frame");
        let ServerNotification::SubscriptionsAcknowledged(acknowledgement) =
            ServerNotification::decode(&acknowledgement)
                .expect("acknowledgement must use the exact final server union")
        else {
            panic!("first subscription frame must be an acknowledgement");
        };
        assert_eq!(acknowledgement.notifications.tools_list_changed, Some(true));
        assert_eq!(acknowledgement.notifications.resources_list_changed, None);
        let acknowledged_id: RequestId = serde_json::from_value(
            acknowledgement
                .meta
                .as_ref()
                .and_then(|metadata| metadata.get(FINAL_SUBSCRIPTION_ID_META_KEY))
                .cloned()
                .expect("acknowledgement must carry its subscription id"),
        )
        .expect("subscription id metadata must retain the JSON-RPC id");
        assert_eq!(acknowledged_id, subscription_id);

        assert_eq!(
            server
                .publish_subscription_notification(ServerNotification::ToolsListChanged(None))
                .expect("selected catalog event should publish"),
            1
        );
        assert_eq!(
            server
                .publish_subscription_notification(ServerNotification::ResourcesListChanged(None))
                .expect("unselected catalog event should be safely filtered"),
            0
        );
        let delivered = sent
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .get(1)
            .cloned()
            .expect("selected event must follow acknowledgement");
        let ServerNotification::ToolsListChanged(Some(delivered)) =
            ServerNotification::decode(&delivered)
                .expect("delivered event must use the exact final server union")
        else {
            panic!("selected event must remain a tools/list_changed notification");
        };
        let delivered_id: RequestId = serde_json::from_value(
            delivered
                .meta
                .as_ref()
                .and_then(|metadata| metadata.get(FINAL_SUBSCRIPTION_ID_META_KEY))
                .cloned()
                .expect("selected event must carry its subscription id"),
        )
        .expect("delivery metadata must retain the JSON-RPC id");
        assert_eq!(delivered_id, subscription_id);

        drop(lease);
        assert!(
            registry
                .inner
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .entries
                .is_empty(),
            "request completion or cancellation must release the subscription entry"
        );
    }

