    #[test]
    fn final_subscription_concurrent_publications_are_not_silently_dropped() {
        let registry = Arc::new(FinalSubscriptionRegistry::default());
        let sent = Arc::new(AtomicUsize::new(0));
        let sent_for_sender = Arc::clone(&sent);
        let (entered_sender, entered_receiver) = std::sync::mpsc::channel();
        let release = Arc::new((Mutex::new(false), Condvar::new()));
        let release_for_sender = Arc::clone(&release);
        let sender: NotificationSender = Arc::new(move |notification| {
            sent_for_sender.fetch_add(1, Ordering::AcqRel);
            if matches!(
                ServerNotification::decode(&notification),
                Ok(ServerNotification::SubscriptionsAcknowledged(_))
            ) {
                return;
            }
            entered_sender
                .send(())
                .expect("concurrent publication observer should remain live");
            let (lock, ready) = &*release_for_sender;
            let mut released = lock
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            while !*released {
                released = ready
                    .wait(released)
                    .unwrap_or_else(std::sync::PoisonError::into_inner);
            }
        });
        let _lease = registry
            .open(
                RequestId::Number(75),
                SubscriptionFilter {
                    tools_list_changed: Some(true),
                    ..SubscriptionFilter::default()
                },
                false,
                None,
                McpRequestCancellation::new(),
                None,
                sender,
            )
            .expect("concurrent publication stream should admit");

        let first_registry = Arc::clone(&registry);
        let first = thread::spawn(move || {
            first_registry.publish(ServerNotification::ToolsListChanged(None))
        });
        entered_receiver
            .recv_timeout(Duration::from_secs(2))
            .expect("first publication callback should start");
        let second_registry = Arc::clone(&registry);
        let second = thread::spawn(move || {
            second_registry.publish(ServerNotification::ToolsListChanged(None))
        });
        let second_entered = entered_receiver
            .recv_timeout(Duration::from_secs(2))
            .is_ok();

        let (lock, ready) = &*release;
        *lock
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner) = true;
        ready.notify_all();

        let first_result = first
            .join()
            .expect("first concurrent publisher should not panic")
            .expect("first concurrent publication should remain valid");
        let second_result = second
            .join()
            .expect("second concurrent publisher should not panic")
            .expect("second concurrent publication should remain valid");
        assert!(
            second_entered,
            "an in-flight callback must not make a concurrent accepted event disappear"
        );
        assert_eq!(first_result, 1);
        assert_eq!(second_result, 1);
        assert_eq!(
            sent.load(Ordering::Acquire),
            3,
            "one acknowledgement and both accepted events must reach the sender"
        );
    }

    #[test]
    fn final_subscription_terminal_result_is_complete_and_correlated() {
        use fastmcp_protocol::CoreRequest;

        let server = Server::new("final-subscriptions-test", "1.0.0").build();
        let subscription_id = RequestId::String("subscription-terminal".to_owned());
        let terminal = server
            .final_subscription_complete_result(&subscription_id)
            .expect("terminal result should encode through the final result algebra");
        assert_eq!(
            terminal.get("resultType"),
            Some(&serde_json::json!("complete"))
        );
        assert_eq!(
            terminal
                .get("_meta")
                .and_then(|metadata| metadata.get(FINAL_SUBSCRIPTION_ID_META_KEY)),
            Some(&serde_json::to_value(&subscription_id).expect("id must serialize"))
        );

        let request_metadata = OpenMetadata::try_from_entries([
            (
                "io.modelcontextprotocol/protocolVersion".to_owned(),
                serde_json::json!(MODERN_PROTOCOL_VERSION),
            ),
            (
                FINAL_CLIENT_CAPABILITIES_META_KEY.to_owned(),
                serde_json::json!({}),
            ),
        ])
        .expect("final request metadata must be valid");
        let params = serde_json::to_value(FinalSubscriptionsListenParams {
            meta: request_metadata,
            notifications: SubscriptionFilter::default(),
        })
        .expect("final listen parameters must serialize");
        let request =
            CoreRequest::decode(ProtocolEra::Modern2026, SUBSCRIPTIONS_LISTEN, Some(&params))
                .expect("final listen request must select the final result decoder");
        let response = JsonRpcResponse::success(subscription_id.clone(), terminal);
        let CoreResult::Final(FinalCoreResult::SubscriptionsListen {
            subscription_id: decoded_id,
            ..
        }) = request
            .decode_response(&response)
            .expect("terminal complete result must round-trip with its response id")
        else {
            panic!("subscriptions/listen must decode only its terminal final result");
        };
        assert_eq!(decoded_id, subscription_id);
    }

    #[test]
    fn public_stdio_listen_teardown_emits_cancelled_before_correlated_completion() {
        let server = Arc::new(Server::new("final-listen-dispatch-test", "1.0.0").build());
        let wire = Arc::new(Mutex::new(Vec::<JsonRpcMessage>::new()));
        let wire_for_sender = Arc::clone(&wire);
        let notification_sender: NotificationSender = Arc::new(move |notification| {
            wire_for_sender
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .push(JsonRpcMessage::Request(notification));
        });
        let subscription_id = RequestId::Number(73);
        let metadata = OpenMetadata::try_from_entries([
            (
                "io.modelcontextprotocol/protocolVersion".to_owned(),
                serde_json::json!(MODERN_PROTOCOL_VERSION),
            ),
            (
                FINAL_CLIENT_CAPABILITIES_META_KEY.to_owned(),
                serde_json::json!({}),
            ),
        ])
        .expect("final request metadata must be valid");
        let params = serde_json::to_value(FinalSubscriptionsListenParams {
            meta: metadata,
            notifications: SubscriptionFilter {
                tools_list_changed: Some(true),
                ..SubscriptionFilter::default()
            },
        })
        .expect("final listen parameters must serialize");
        let request =
            JsonRpcRequest::new(SUBSCRIPTIONS_LISTEN, Some(params), subscription_id.clone());
        let inbound = InboundRequestContext::new(
            Cx::for_testing(),
            request_id_to_u64(Some(&subscription_id)),
            InboundRequestTransport::Stdio,
        );
        let terminator = {
            let server = Arc::clone(&server);
            let wire = Arc::clone(&wire);
            std::thread::spawn(move || {
                for _ in 0..100 {
                    if !wire
                        .lock()
                        .unwrap_or_else(std::sync::PoisonError::into_inner)
                        .is_empty()
                    {
                        return server.terminate_subscription_streams() == 1;
                    }
                    std::thread::sleep(Duration::from_millis(1));
                }
                false
            })
        };
        let response = block_on(Arc::clone(&server).dispatch_with_protocol_policy_owned(
            ProtocolPolicy::ModernOnly,
            &inbound,
            request,
            None,
            None,
            None,
            None,
            McpRequestCancellation::new(),
            None,
            notification_sender,
        ));

        assert!(
            terminator
                .join()
                .expect("subscription terminator must not panic"),
            "the listener must acknowledge before graceful termination"
        );
        let acknowledgement = wire
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .first()
            .cloned()
            .expect("listener must emit its acknowledgement before terminating");
        let JsonRpcMessage::Request(acknowledgement) = acknowledgement else {
            panic!("listener acknowledgement must be a JSON-RPC notification");
        };
        assert!(matches!(
            ServerNotification::decode(&acknowledgement),
            Ok(ServerNotification::SubscriptionsAcknowledged(_))
        ));
        let response = response.expect("server-owned stdio teardown must complete the listen");
        assert_eq!(response.id, Some(subscription_id.clone()));
        assert!(
            final_subscription_completion_response(&response),
            "server-owned teardown must complete the exact listen request; response={response:?}"
        );
        wire.lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .push(JsonRpcMessage::Response(response.clone()));
        let wire = wire
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        let terminal_position = wire
            .iter()
            .position(|message| {
                let JsonRpcMessage::Request(notification) = message else {
                    return false;
                };
                matches!(
                    ServerNotification::decode(notification),
                    Ok(ServerNotification::Cancelled(_))
                )
            })
            .expect("server teardown must emit one cancellation control after acknowledgement");
        let JsonRpcMessage::Request(terminal) = &wire[terminal_position] else {
            unreachable!("the terminal position above only selects requests");
        };
        let ServerNotification::Cancelled(terminal) = ServerNotification::decode(terminal)
            .expect("terminal control must use the final server notification union")
        else {
            panic!("server teardown must emit notifications/cancelled");
        };
        assert_eq!(terminal.request_id, subscription_id);
        assert_eq!(
            terminal
                .meta
                .as_ref()
                .and_then(|meta| meta.get(FINAL_SUBSCRIPTION_ID_META_KEY)),
            Some(&serde_json::json!(73)),
            "terminal metadata must correlate to exactly this listen request",
        );
        let completion_position = wire
            .iter()
            .position(|message| {
                matches!(
                    message,
                    JsonRpcMessage::Response(response)
                        if response.id == Some(subscription_id.clone())
                            && final_subscription_completion_response(response)
                )
            })
            .expect("server teardown must emit the correlated completion result");
        assert_eq!(
            wire.len(),
            3,
            "the acknowledgement, correlated cancellation control, and completion are exact",
        );
        assert!(
            terminal_position < completion_position,
            "stdio must emit notifications/cancelled before the correlated complete result"
        );
    }

    #[test]
    fn http_sse_accept_qvalue_admits_rfc_forms_and_rejects_four_fraction_digits() {
        let accepts = |value| {
            http_request_accepts_sse(
                &HttpRequest::new(HttpMethod::Post, "/mcp").with_header("accept", value),
            )
        };
        assert!(accepts("  */* ; Q=1. "));
        assert!(!accepts("  */* ; Q=0. "));
        assert!(!accepts("*/*; Q = 1."));
        assert!(!accepts("*/*; unrelated=value; Q=1."));
        assert!(!accepts("text/event-stream; q=1.0000"));
        assert!(!accepts("text/event-stream; q=0.0000"));
    }

    #[test]
    fn http_sse_accept_exclusions_override_wildcards_before_stream_allocation() {
        for value in [
            "text/event-stream;q=0, */*;q=1",
            "*/*;q=1, text/event-stream;q=0",
            "text/*;q=0, */*;q=1",
            "text/event-stream, text/event-stream;q=0, application/json",
            "application/json;profile=\"x, text/event-stream\"",
        ] {
            assert!(
                !http_request_accepts_sse(
                    &HttpRequest::new(HttpMethod::Post, "/mcp").with_header("accept", value),
                ),
                "a required SSE body must honor the full admitted preference: {value}",
            );
        }
        assert!(http_request_accepts_sse(
            &HttpRequest::new(HttpMethod::Post, "/mcp")
                .with_header("accept", "text/event-stream;q=0.1, */*;q=1"),
        ));
        assert!(!http_request_accepts_sse(&HttpRequest::new(
            HttpMethod::Post,
            "/mcp",
        )));
    }

    #[test]
    fn public_http_modern_disabled_components_are_isolated_between_sessions() {
        let cx = Cx::for_testing();
        let calls = Arc::new(AtomicUsize::new(0));
        let endpoint = Server::new("modern-http-session-isolation", "1.0.0")
            .protocol_policy(ProtocolPolicy::ModernOnly)
            .expect("ModernOnly must be available to this test build")
            .tool(HttpSessionDisablingTool {
                calls: Arc::clone(&calls),
            })
            .build_http_endpoint("http://final.test")
            .expect("modern endpoint must build");
        let mut first_client = endpoint
            .open_session(&cx)
            .expect("first modern HTTP session must open");
        let mut second_client = endpoint
            .open_session(&cx)
            .expect("second modern HTTP session must open");

        let request = modern_http_json_tool_request("http_session_disabling_tool", 901);
        for session in [&mut first_client, &mut second_client] {
            let response = block_on(session.handle_async(&cx, request.clone()))
                .expect("each independently admitted modern session must dispatch its first call");
            let ServerHttpEndpointResponse::Immediate(response) = response else {
                panic!("ordinary modern tool calls must return JSON responses");
            };
            let response: JsonRpcResponse = serde_json::from_slice(&response.body)
                .expect("modern tool response must remain JSON-RPC");
            assert_eq!(response.id, Some(901_i64.into()));
            assert!(response.error.is_none());
        }

        assert_eq!(
            calls.load(Ordering::Acquire),
            2,
            "disabling the tool for the first client must not prevent the second client entering it",
        );
    }

    #[test]
    fn public_http_modern_disabled_components_reject_only_the_same_session() {
        let cx = Cx::for_testing();
        let calls = Arc::new(AtomicUsize::new(0));
        let endpoint = Server::new("modern-http-session-disablement", "1.0.0")
            .protocol_policy(ProtocolPolicy::ModernOnly)
            .expect("ModernOnly must be available to this test build")
            .tool(HttpSessionDisablingTool {
                calls: Arc::clone(&calls),
            })
            .build_http_endpoint("http://final.test")
            .expect("modern endpoint must build");
        let mut first_client = endpoint
            .open_session(&cx)
            .expect("first modern HTTP session must open");
        let mut second_client = endpoint
            .open_session(&cx)
            .expect("second modern HTTP session must open");

        let first = block_on(first_client.handle_async(
            &cx,
            modern_http_json_tool_request("http_session_disabling_tool", 903),
        ))
        .expect("first session must dispatch the disabling call");
        assert!(matches!(
            first,
            ServerHttpEndpointResponse::Immediate(response)
                if serde_json::from_slice::<JsonRpcResponse>(&response.body)
                    .is_ok_and(|response| response.error.is_none())
        ));

        let comparison = modern_http_json_tool_request("http_session_disabling_tool", 904);
        let rejected = block_on(first_client.handle_async(&cx, comparison.clone()))
            .expect("same-session disablement must be represented as JSON-RPC");
        assert!(matches!(
            rejected,
            ServerHttpEndpointResponse::Immediate(response)
                if serde_json::from_slice::<JsonRpcResponse>(&response.body).is_ok_and(|response| {
                    response.id == Some(904_i64.into())
                        && response.error.is_some_and(|error| error.code.as_i32() == Some(-32601))
                })
        ));

        let independent = block_on(second_client.handle_async(&cx, comparison))
            .expect("changing only the client session must restore its independent state");
        assert!(matches!(
            independent,
            ServerHttpEndpointResponse::Immediate(response)
                if serde_json::from_slice::<JsonRpcResponse>(&response.body)
                    .is_ok_and(|response| response.id == Some(904_i64.into()) && response.error.is_none())
        ));
        assert_eq!(calls.load(Ordering::Acquire), 2);
    }

